  (49, 3, 'د. اختيار الوسط الصحيح', 'Picking the Right Medium', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (50, 0, 'ا. الإجتماع مع الشخص المعني بالمشروع لتفهم لماذا يحتاج إلى التواصل مع أعضاء فريقك.', 'Meet with the stakeholder to understand why he feels the need to communicate with your team members.', false),
