  (83, 0, 'التوجيه', 'Directive', true),
  (83, 1, 'المشاركة', 'Participative', false),
  (83, 2, 'الحزم', 'Assertive', false),
  (83, 3, 'الدعم', 'Supportive', false),
  (84, 0, 'يكمل أولاً المهمة الحرجة ثم يساعد عضو الفريق.', 'First complete the critical task then help the team member.', false),
  (84, 1, 'أولاً يساعد عضو الفريق ثم يكمل المهمة الحرجة.', 'First help the team member then complete the critical task.', true),
  (84, 2, 'يكمل المهمة الحرجة ويطلب من أحد كبار أعضاء الفريق مساعدة عضو الفريق.', 'Complete the critical task and ask another senior team member to help the team member.', false),
  (84, 3, 'يطلب من عضو الفريق الرجوع إلى مالك المنتج.', 'Ask the team member to refer to the product owner.', false),
