  (86, 0, 'تقديم مكافأة تتماشى مع أهدافه الشخصية.', 'Provide a reward that aligns with his personal goals.', true),
  (86, 1, 'تقديم شهادة تقدير في اجتماع الفريق القادم.', 'Provide a certificate of appreciation in the next team meeting.', false),
  (86, 2, 'ارسال رسالة شكر له بالبريد الإلكتروني وإرسال الى مديره الوظيفي نسخة.', 'Send him a thanks email and keep his functional manager in copy.', false),
  (86, 3, 'الطلب من مديره الوظيفي الموافقة على مكافأة له.', 'Ask his functional manager to approve a bonus for him.', false),
  (87, 0, 'الرسمية', 'Formal', false),
  (87, 1, 'الخبير', 'Expert', true),
  (87, 2, 'المرجعية', 'Referent', false),
  (87, 3, 'المكافأة', 'Reward', false),
  (88, 0, 'ا. التوجيه', 'Directing', false),
  (88, 1, 'ب. الدعم', 'Supporting', false),
  (88, 2, 'ج. التدريب', 'Coaching', true),
  (88, 3, 'د. التفويض', 'Delegating', false),
  (89, 0, 'ا. يجب على فريق التطوير تصعيد هذه المشكلة إلى مالك المنتج.', 'The development team should escalate this issue to the product owner.', false),
  (89, 1, 'ب. يجب على مدرب الفريق الرشيق التحدث إلى ممثل العميل وشرح كيفية عمل المشاريع الرشيقة.', 'The agile coach should talk to the customer representative and explain how agile projects work.', true),
  (89, 2, 'ج. يجب أن يطلب الفريق من ممثل العميل عدم إزعاجهم بعد الآن أثناء الإطلاق.', 'The team should ask the customer representative not to disturb them anymore during the sprint.', false),
  (89, 3, 'د. يجب على الفريق رفض طلب العميل لإضافة أي سمات جديدة أثناء الإطلاق.', 'The team should reject the customer request for adding any new features during the sprint.', false),
  (90, 0, 'ا. المرجع', 'Referent', false),
