  (200, 3, 'وضع خطة إدارة الجودة', 'Plan Quality Management', false),
  (201, 0, 'إضافة المشكلة إلى سجل المخاطر وتحديد خطة إستجابة.', 'Add the problem to the risk register and develop a response plan.', false),
  (201, 1, 'اقتراح إجراءات تصحيحية ورفعها إلى مجلس التحكم بالتغيير.', 'Suggest corrective actions and submit them to the change control board.', true),
  (201, 2, 'إضافة نتائج التدقيق إلى الدروس المستفادة.', 'Add the results of the audit to the lessons learned.', false),
  (201, 3, 'تلتقي مع مدير قسم ضمان الجودة لإيجاد حل للمشكلة.', 'You meet with the manager of the quality assurance department to find a solution of the problem.', false),
  (202, 0, 'إجراء التحكم المتكامل في التغيير، ضبط الجودة، التحقق من النطاق', 'Perform Integrated Change Control, Control Quality, Validate Scope', false),
  (202, 1, 'توجيه وإدارة أعمال المشروع، التحقق من النطاق، ضبط الجودة', 'Direct and manage project work, Validate Scope, Control Quality', false),
  (202, 2, 'توجيه وإدارة أعمال المشروع، ضبط الجودة، ضبط النطاق', 'Direct and Manage Project Work, Control Quality, Control Scope', false),
  (202, 3, 'توجيه وإدارة أعمال المشروع، ضبط الجودة، التحقق من النطاق', 'Direct and manage project work, Control Quality, Validate Scope', true),
  (203, 0, 'جعل أعضاء فريق العمل يقضون وقتاً إضافياً في مراجعة المتطلبات مع المعنيين بالمشروع.', 'Having team members spend extra time reviewing requirements with the stakeholders.', false),
  (203, 1, 'دفع العمل الإضافي للمساعدة في تلبية الموعد النهائي.', 'Paying extra labor to help meet a deadline.', true),
  (203, 2, 'التعاقد مع مفتشين إضافيين للبحث عن العيوب.', 'Hiring extra inspectors to look for defects.', false),
  (203, 3, 'إرسال فني لإصلاح المنتج المعيب الذي تم تسليمه إلى العميل.', 'Sending a technician to repair a defective product that was delivered to the client.', false),
  (204, 0, 'المخططات المصفوفية', 'Matrix diagrams', true),
  (204, 1, 'نموذج البيانات المنطقية', 'Logical data model', false),
