INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (550, 0, 'تم تنفيذ المشروع بميزانية أقل بنسبة 25٪، ولكن استغرق مدة أطول بنسبة 20٪ عن الخطة الأصلية.', 'The project was delivered under budget by 25%, and the overall duration was 20% longer than initially scheduled.', false),
  (550, 1, 'تم تنفيذ المشروع ضمن الميزانية، وتمت الموافقة على إغلاقه من قبل مكتب إدارة المشاريع (PMO).', 'The project was delivered on budget, and the project management office (PMO) approved the project closure.', false),
  (550, 2, 'تم تسليم المشروع مبكرًا، ودخل السوق قبل المنافسين، وتجاوز الميزانية بنسبة 10٪.', 'The project was delivered early, entered the market before the competition, and exceeded the budget by 10%.', false),
  (550, 3, 'تم تنفيذ المشروع في الوقت المحدد، وضمن الميزانية، وحقق زيادة بنسبة 5٪ في المبيعات المتوقعة للمنتج.', 'The project was delivered on schedule, within budget, and yielded a 5% increase in projected product sales.', true),
  (551, 0, 'بناء فريق مصفوفي لمراجعة العلاقات في جميع فرق المشروع.', 'Build a matrix team to review the relationships on all project teams.', false),
  (551, 1, 'طلب من جميع أعضاء الفريق التركيز أكثر على المشروع.', 'Ask all the team members to focus more on the project.', false),
  (551, 2, 'إعادة تعيين المهام غير المنجزة إلى عضو آخر في الفريق.', 'Reassign the uncompleted tasks to another team member.', false),
  (551, 3, 'التحدث مع عضو الفريق لمعرفة أسباب الأداء الضعيف.', 'Engage the team member to determine the reasons for poor performance.', true),
  (552, 0, 'تحديد مورد يمكنه توفير المكون ضمن قيمة الاحتياطي.', 'Identify a supplier that can provide the component within the amount of the reserve.', true),
  (552, 1, 'طلب المكوّن من مورد آخر وتقديم طلب تغيير إلى مجلس التحكم في التغيير (CCB).', 'Order the component from another supplier and submit a change request to the change control board (CCB).', false),
  (552, 2, 'مراجعة خطة الاستجابة للمخاطر وبيان العمل للخطوات التالية وبند الغرامة على التأخير.', 'Review the risk response plan and the statement of work for the next steps and a penalty clause for late delivery.', false),
  (552, 3, 'تحديث الجدول الزمني للمشروع ومستودع الدروس المستفادة.', 'Update the project schedule and the lessons learned repository.', false),
  (553, 0, 'طلب مزيد من المعلومات من عضو الفريق.', 'Request more information from the team member.', false),
  (553, 1, 'رفض اقتراح عضو الفريق.', 'Reject the team member''s proposal.', true),
  (553, 2, 'مناقشة الاقتراح مع فريق المشروع.', 'Discuss this proposal with the project team.', false),
  (553, 3, 'طلب من مدير الجودة دراسة الاقتراح.', 'Ask the quality manager to consider the proposal.', false),
  (554, 0, 'محافظ، معتدل، متحرر.', 'Conservative, moderate, and liberal', false),
  (554, 1, 'يتجنب المخاطر، محايد تجاه المخاطر، متسامح مع المخاطر، يسعى للمخاطر.', 'Risk-averse, risk-neutral, risk-tolerant, risk-seeking', true),
  (554, 2, 'يقلل من المخاطر، يتجنبها، ينقلها، يقبلها.', 'Risk-mitigating, risk-avoiding, risk-transferring, risk-accepting', false),
  (554, 3, 'مرتفع، متوسط، منخفض.', 'High, medium, and low', false),
  (554, 4, 'إيجابي، سلبي، غير مبالٍ.', 'Positive, negative, and indifferent', false),
  (555, 0, 'طلب من مالك الخطر التصعيد إلى أصحاب الموافقة للحصول عليها في أسرع وقت ممكن.', 'Asked the risk owner to escalate with approvers so that approvals are obtained as soon as possible.', false),
  (555, 1, 'تعديل خطط المشروع من خلال تقليل تقديرات إنجاز العمل ليتم الانتهاء منه في الوقت المحدد بالرغم من التأخير.', 'Adjusted the project plans by lowering work completion estimates so that the work can be completed on time despite the delay.', false),
  (555, 2, 'تطوير إجراءات محددة لتنفيذ استراتيجية الاستجابة للمخاطر المتفق عليها، بما في ذلك الخطط الأساسية والبديلة.', 'Developed specific actions to implement the agreed-upon risk response strategy, including primary and backup strategies.', true),
  (555, 3, 'استخدام تحليل الخيارات الحقيقية لإجراء تحليل اقتصادي لاستراتيجيات استجابة بديلة.', 'Used a real options analysis to perform an economic analysis of alternative risk response strategies.', false),
