INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (650, 3, 'تحديد استراتيجيات بناء الفريق.', 'Define the team-building strategies.', false),
  (651, 0, 'ضمان وجود خطة إدارة النطاق لتغطية جميع الأهداف ذات الصلة.', 'Ensuring that the scope management plan is in place to cover all related objectives.', false),
  (651, 1, 'ضمان أن الفريق يركز أيضًا على خطة إدارة التغيير الشاملة.', 'Ensuring that the team is also focused on the overall change management plan.', false),
  (651, 2, 'التخطيط لتحديثات دورية للمشروع لتغطية حالة التسليمات الحرجة.', 'Planning for regular project updates to cover the status of critical deliverables.', false),
  (651, 3, 'تحديد وتنسيق مؤشرات الأداء التي ستساعد في تقييم نجاح التسليم.', 'Determining and aligning performance indicators that will help in assessing successful delivery.', true),
  (652, 0, 'الاعتراف بمخاوف المحلل وإعادة تعيين المهمة لعضو آخر في الفريق.', 'Recognize the analyst''s concerns and reassign the task to another team member.', false),
  (652, 1, 'تسجيل المحلل في برنامج لبناء القدرات والإبقاء عليه في المهمة.', 'Enroll the analyst in a capacity-building program, and keep this analyst assigned to the task.', false),
  (652, 2, 'الطلب من المحلل استخدام مهاراته لتطوير الأداة، ثم نقل العمل إلى عضو آخر.', 'Ask the analyst to use skills to develop the tool, then move development to another team member.', false),
  (652, 3, 'ضمان عقد اجتماعات دورية بين المحلل والعضو الآخر طوال تنفيذ المهمة.', 'Make sure the analyst has regular pairing meetings with the other team member throughout task execution.', true),
  (653, 0, 'أجايل (Agile)', 'Agile', false),
  (653, 1, 'تقليدي (Traditional)', 'Traditional', true),
  (653, 2, 'خيط فولاذي (Steel Thread)', 'Steel Thread', false),
  (653, 3, 'موجة متدحرجة (Rolling Wave)', 'Rolling Wave', false),
  (654, 0, 'الاجتماع مع صاحب المصلحة لشرح أن المورد الجديد سيزيد المدة الزمنية ولكنه سيحقق أهداف المشروع.', 'Meet with the stakeholder to explain that using the new supplier will increase the timeline but will meet the overall project goals.', false),
  (654, 1, 'إبلاغ صاحب المصلحة بأن الجدول الزمني الحالي سيتطلب تحديثات، والاستمرار بمراجعات دورية لمناقشة هذه التحديثات.', 'Let the stakeholder know that the current schedule will require updates, and continue with periodic reviews to discuss the updates.', true),
  (654, 2, 'إبلاغ صاحب المصلحة بتأخير الجدول لمدة 10 أيام، ولكن سيتم تسريع المهام على المسار الحرج.', 'Inform the stakeholder that there will be a 10-day delay in the schedule to onboard the new supplier, but critical path tasks will be fast tracked.', false),
  (654, 3, 'إبلاغ صاحب المصلحة أن استخدام المورد الجديد سيتطلب إعادة البدء في بداية مرحلة التخطيط التالية.', 'Communicate to the stakeholder that using the new supplier will require a restart at the beginning of the next planning phase.', false),
