  (1097, 2, 'مصفوفة توزيع المسؤوليات (RAM)', 'Responsibility assignment matrix (RAM)', false),
  (1097, 3, 'مخطط هيكل تنظيم المشروع', 'Project organization chart', false),
  (1098, 0, 'مراقبة التغييرات', 'Change control', true),
