  (1105, 2, 'تحديد بيان نطاق المشروع.', 'Define the project scope statement.', false),
  (1105, 3, 'إنشاء هيكل تقسيم العمل (WBS).', 'Create the work breakdown structure (WBS).', false),
  (1106, 0, 'إضافة فجوة المعلومات إلى سجل المخاطر.', 'Add an information gap to the risk register.', false),
  (1106, 1, 'مراجعة بيان العمل (SOW) لإنشاء ميثاق المشروع.', 'Review the project statement of work (SOW) to create the project charter.', false),
  (1106, 2, 'تعديل دراسة الجدوى لتضييق نطاق المشروع وإنشاء ميثاق المشروع.', 'Revise the business case to narrow the project scope and create the project charter.', false),
  (1106, 3, 'مراجعة دراسة الجدوى مع الجهة الراعية للتأكد من توافق المشروع مع احتياجات العمل.', 'Review the business case with the sponsoring organization to confirm that the project aligns with business needs.', true),
  (1107, 0, 'بدء تدقيق للمخاطر.', 'Initiate a risk audit.', false),
