  (1183, 0, 'رضا العميل وعرض القيمة المقدمة.', 'Client satisfaction and value delivered demonstration.', false),
  (1183, 1, 'نمو ورفاهية الأفراد والمجتمعات التي ينتمون إليها.', 'Growth and well-being of people and communities they belong to.', true),
  (1183, 2, 'إدارة توقعات أصحاب المصلحة والتواصل معهم.', 'Stakeholders expectation management and communication.', false),
  (1183, 3, 'الإنتاجية والكفاءة لتحقيق الالتزامات.', 'Productivity and efficiency to achieve commitments made.', false),
  (1184, 0, 'رؤيوي، تحالفي، توجيهي، وتشاركي', 'Visionary, affiliative, coaching and participative', true),
  (1184, 1, 'رؤيوي، تحالفي، توجيهي، وسرعة التنفيذ', 'Visionary, affiliative, coaching and pace setting', false),
