  (1189, 3, 'وجود تواصل مفرط', 'Too much communication', false),
  (1190, 0, 'حل المشكلات', 'Problem solving', true),
  (1190, 1, 'التسوية', 'Compromising', false),
  (1190, 2, 'الاستيعاب', 'Accommodating', false),
  (1190, 3, 'التشاور', 'Consultation', false),
  (1191, 0, 'توزيع المهام ومراقبة جودة النتائج.', 'Distribute tasks and observe the quality of the deliverables.', false),
  (1191, 1, 'التحدث عن التفضيلات الشخصية والتأكد من أن الفريق يفهم أسلوبك.', 'Talk about personal preferences and make sure the team understands your approach.', false),
  (1191, 2, 'طلب بعض المعلومات عن الأعضاء من زملائهم للتعرف عليهم.', 'Ask some team members to share information about other members to become familiar with the team.', false),
  (1191, 3, 'سؤال أعضاء الفريق مباشرةً عن الأمور الشخصية والعملية.', 'Ask the team members directly about both personal and work-related matters.', true),
  (1192, 0, 'سؤال قسم الموارد البشرية عن الحوافز التي يجب تقديمها.', 'Ask Human Resources department which incentives should be provided.', false),
  (1192, 1, 'التحقق من توفر الميزانية لتحديد قيم المكافآت.', 'Check on budget availability in order to determine specific reward amounts.', false),
  (1192, 2, 'توفير فرصة لتقديم النتائج علنًا.', 'Provide an opportunity for publicly presenting the outcomes.', false),
  (1192, 3, 'تحديد احتياجات كل عضو من الفريق لتحديد الحوافز المناسبة.', 'Identify the specific needs for each team member to determine incentives.', true),
  (1193, 0, 'إشراك الفريق في عملية المشروع.', 'Engage the team in the project process.', true),
  (1193, 1, 'المشاركة النشطة في مهام المشروع.', 'Be actively involved in the project tasks.', true),
  (1193, 2, 'معاملة جميع أعضاء الفريق بنفس الطريقة.', 'Treat each team member the same way.', false),
  (1193, 3, 'طلب التعليقات وتحليل النتائج.', 'Ask for feedback and analyze the results.', true),
  (1193, 4, 'استخدام الديمقراطية في جميع قرارات الفريق.', 'Use democracy for all team decisions.', false),
  (1194, 0, 'إعداد جميع تقارير الحالة والعروض التوضيحية لإبقاء العميل مركزًا على تنفيذ المشروع الذي كان ناجحًا.', 'Prepare all status reports and demos to keep the client focused on the project execution that has been successful.', false),
  (1194, 1, 'إجراء مناقشة شفافة مع الراعي، مع عرض تقديم الدعم في تقييم الاستراتيجية إذا لزم الأمر.', 'Have a transparent discussion with the project sponsor, offering support on the strategy evaluation if needed.', true),
  (1194, 2, 'الاستمرار في تنفيذ المشروع، لأن الاستراتيجية التجارية ليست من مسؤوليات مدير المشروع.', 'Continue working on the project execution, as the business strategy is not responsibility of the project manager.', false),
  (1194, 3, 'إيقاف المشروع فورًا، لأن مدير المشروع يعلم أنه سيكون عديم الفائدة للعميل.', 'Halt the project immediately, as the project manager knows it will be useless to the client.', false),
  (1195, 0, 'مناقشة مع الفريق لتوضيح أن نجاح المنتج ليس نتيجة مباشرة للمشروع ولا  يعكس أدائهم.', 'Have a discussion with the team to explain that the product success is not a direct result of the project and it does not reflect their performance', true),
  (1195, 1, 'عقد اجتماع مع إدارة الأعمال للتأكد من فهمهم أن المشروع حقق أهدافه.', 'Have a meeting with the business to make sure they understand the project met its objectives', true),
  (1195, 2, 'لا يلزم اتخاذ أي إجراء، لأن مدير المشروع مسؤول فقط عن تسليمات المشروع.', 'No action is necessary, as the project manager is only responsible for the project deliverables.', false),
  (1195, 3, 'مناقشة مع الراعي التجاري للتحقق من الاستراتيجية للمشروع الجديد بناءً على هذه النتيجة.', 'Have a conversation with the business sponsor to validate the strategy for the new project based on this result.', false),
  (1196, 0, 'تعريف المشكلة', 'Problem Definition', false),
  (1196, 1, 'توليد حلول للمشكلة', 'Problem Solution Generation', false),
  (1196, 2, 'تحويل الأفكار إلى أفعال', 'Ideas to Action', true),
  (1196, 3, 'تخطيط تنفيذ الحل', 'Solution Action Planning', false),
  (1197, 0, 'المخاطر غير مؤكدة والمشكلات مؤكدة.', 'Risks are uncertain and issues are certain.', true),
  (1197, 1, 'المخاطر مؤكدة والمشكلات غير مؤكدة.', 'Risks are certain and issues are uncertain.', false),
  (1197, 2, 'وقعت المخاطر وقد لا تحدث المشكلات.', 'Risks have occurred and issues may not occur.', false),
  (1197, 3, 'قد لا تحدث المخاطر ولكن المشكلة قد حدثت.', 'Risks may not occur and an issue has occurred.', true),
  (1198, 0, 'فرض سياسات حوكمة صارمة مركزية داخل قسم تكنولوجيا المعلومات لضمان التوحيد والسيطرة.', 'Enforce stringent IT governance policies centralized within the IT department, ensuring uniformity and control over all IT endeavors.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1198, 1, 'فرض مقترحات مشاريع تكنولوجيا المعلومات الشاملة للتقييم والموافقة قبل بدء أي مشروع.', 'Mandate comprehensive IT project proposals to the IT department for assessment and approval before any project can commence.', false),
  (1198, 2, 'تمكين وحدات الأعمال من استخدام منصة مبسطة لإدارة مشاريع تكنولوجيا المعلومات لبدء المشاريع ومتابعتها بشكل مستقل.', 'Enable business units to use a simplified IT project management platform to initiate and monitor projects independently.', true),
  (1198, 3, 'التعاون مع فرق تكنولوجيا المعلومات متعددة الوظائف لتخطيط وتنفيذ المشاريع بشكل مشترك.', 'Collaborate with cross-functional IT business teams to jointly plan and execute IT projects, fostering cooperation between stakeholders.', false),
  (1199, 0, 'الإقناع', 'Persuasion', false),
  (1199, 1, 'النيابة', 'Deputation', false),
  (1199, 2, 'الأخذ والعطاء', 'Give and take', false),
  (1199, 3, 'الأوامر الصارمة', 'Strict orders', true),
  (1200, 0, 'التوظيف على أساس تعاقدي', 'Recruiting on a contractual basis', false),
  (1200, 1, 'توظيف المواهب الخبيرة', 'Recruiting expert talents', false),
  (1200, 2, 'التوظيف على أساس الإعارة', 'Recruitment on the basis of secondment', false),
  (1200, 3, 'التوظيف عبر التحكم المباشر', 'Recruitment via Direct Control', true),
  (1201, 0, 'متطلبات الامتثال هي متطلبات وظيفية ويجب تضمينها في وثيقة BRD.', 'Compliance requirements are functional requirements and must be included in the BRD.', false),
  (1201, 1, 'متطلبات الامتثال هي متطلبات غير وظيفية ويجب توثيقها في وثيقة BRD.', 'Compliance requirements are non-functional requirements and must be documented in the BRD.', true),
  (1201, 2, 'يجب أن تكون متطلبات الامتثال جزءًا من نطاق المشروع ويجب أن تُدار من قبل فريق المشروع.', 'Compliance requirements should be part of the project scope and should be managed by the project team.', true),
  (1201, 3, 'يمكن اعتبار متطلبات الامتثال أصولًا تنظيمية ولا تحتاج إلى تضمينها في وثيقة BRD.', 'Compliance requirements can be considered organization assets and do not need to be included in the BRD.', false),
  (1201, 4, 'لا يمكن اعتبار متطلبات الامتثال أصولًا تنظيمية ويجب تضمينها في وثيقة BRD.', 'Compliance requirements can not be considered organization assets and must be included in the BRD.', false),
  (1202, 0, 'جودة جيدة، يجب ألا تحتوي النسخة النهائية على أي أعطال حرجة.', 'Good quality, go-live should have zero critical defects.', false),
  (1202, 1, 'واجهة مستخدم جيدة تم تطويرها من قبل مصممين موهوبين.', 'Good user interface developed by talented graphical artists', false),
  (1202, 2, 'تخطيط وتنفيذ جيد لإدارة التغيير.', 'Good change management planning and execution', true),
  (1202, 3, 'عملية تحكم بالتغيير فعالة وسريعة.', 'Good change control process with fast approvals', false),
  (1203, 0, 'يمكن أن يحسن النهج المرن الجودة من خلال التسليم المتكرر والإصلاح الفعال للأعطال.', 'Agile delivery can improve quality through incremental delivery and efficient defect repair.', false),
  (1203, 1, 'توفر الفرق المرنة مرونة في استيعاب التغييرات المخططة مع تسريع عمليات الموافقة.', 'Agile teams offer flexibility in accommodating planned changes while streamlining the approval process.', false),
  (1203, 2, 'يستخدم مالك المنتج قائمة تُعرف باسم قائمة المهام (backlog) لتحديد أولويات العمل.', 'The product owner utilizes a list known as the backlog to prioritize work items, including planned changes.', false),
  (1203, 3, 'النهج المرن مناسب جدًا للتعامل مع التغييرات غير المتوقعة وتغير توقعات العمل.', 'Agile delivery is well-suited for handling unforeseen changes and shifting business expectations.', true),
  (1204, 0, 'قد تحتاج الموارد الخارجية إلى إشراف أكبر بسبب اختلافات التوقيت والثقافة.', 'Offshore resources may need more supervision due to time and cultural differences', true),
  (1204, 1, 'قد لا تمتلك الموارد الخارجية نفس المعرفة في مجال الأعمال مثل البائع السابق.', 'Offshore resources may not have the same business domain knowledge as the previous vendor', true),
  (1204, 2, 'قد تحتاج الموارد الخارجية إلى جهد أكبر في التخطيط وإدارة ميزانيات المشروع.', 'Offshore resources may need more effort in planning and managing project budgets', false),
  (1204, 3, 'قد تحتاج الموارد الخارجية إلى وقت أطول في التهيئة بسبب الفروقات الجيوسياسية.', 'Offshore resources may need longer onboarding due to geopolitical differences', true),
  (1204, 4, 'قد تحتاج الموارد الخارجية إلى توثيق مفصل بسبب الفروقات الزمنية والثقافية.', 'Offshore resources may need detailed documentation due to time and cultural differences', false),
  (1205, 0, 'المالية', 'Financial', false),
  (1205, 1, 'الجدول الزمني', 'Schedule', true),
  (1205, 2, 'الفنية', 'Technical', true),
  (1205, 3, 'السياسية', 'Political', false),
  (1205, 4, 'نطاق العمل', 'Scope', true),
  (1206, 0, 'إدارة التغيير', 'Change management', true),
  (1206, 1, 'إدارة المخاطر', 'Risk management', false),
  (1206, 2, 'إدارة أصحاب المصلحة', 'Stakeholder management', false),
  (1206, 3, 'إدارة الاتصالات', 'Communication management', false),
  (1207, 0, 'عقد اجتماع بدء المشروع مع جميع أصحاب المصلحة.', 'Hold a kick-off meeting with all stakeholders.', false),
  (1207, 1, 'إنشاء سجل أصحاب المصلحة وخطة الاتصال.', 'Create a stakeholder register and communication plan.', false),
  (1207, 2, 'تحديد احتياجات وتوقعات أصحاب المصلحة.', 'Identify the stakeholders'' needs and expectations.', true),
  (1207, 3, 'توثيق مخاوف ومخاطر أصحاب المصلحة.', 'Document the stakeholders'' concerns and risks.', false),
  (1208, 0, 'إلغاء اختبار المستخدم من خطة المشروع.', 'Eliminate the user testing from the project plan.', false),
  (1208, 1, 'استخدام الخادم الحالي لإجراء الاختبار.', 'Utilize the current server to complete user testing.', false),
  (1208, 2, 'طلب تسريع توريد الخادم الجديد من المورد.', 'Request to expedite the new server from the supplier.', false),
  (1208, 3, 'الانتظار لوصول الخادم الجديد وإعادة تقييم الجداول الزمنية لاختبار المستخدم.', 'Await the arrival of the new server and reevaluate timelines for user testing.', true),
  (1209, 0, 'يوصي بأن يتضمن الفريق القصص ذات المخاطر في التكرارات المبكرة بدلاً من المتأخرة.', 'Recommend that the team include risky stories in early iterations rather than later ones.', true),
  (1209, 1, 'يوصي بأن يختار الفريق القصص منخفضة المخاطر لإكمالها بسهولة والحفاظ على الحافز.', 'Recommend that the team choose stories with low risk for easy completion to keep team motivation high.', false),
  (1209, 2, 'يعمل مع مالك المنتج لتحديد القصص التي يجب تضمينها في التكرار.', 'Work with the product owner to decide on the stories that should go during the iteration.', false),
  (1209, 3, 'يستخدم تحليل باريتو لتحديد أي القصص يمكن إكمالها بشكل أسرع.', 'Use the Pareto analysis to decide which stories can be completed the fastest.', false),
  (1210, 0, 'التحقق من سبب رفض الاجتماعات.', 'Check why meetings are declined', true),
  (1210, 1, 'إعادة مشاركة خطة الاتصالات.', 'Re-share communications plan', false),
  (1210, 2, 'وضع قواعد سلوك للفريق في المشروع.', 'Set up a project team ground rules', false),
  (1210, 3, 'عقد اجتماع انطلاق المشروع.', 'Hold a project kick-off meeting', false),
  (1211, 0, 'بدء تطوير خطة إدارة المشروع باستخدام قالب مشروع سابق من مكتب إدارة المشاريع (PMO).', 'Start developing the project management plan based on a previous project template from the project management office (PMO).', false),
  (1211, 1, 'إجراء تحليل تأثير للمبادرة الجديدة لتحديد كيفية تنفيذ المشروع.', 'Conduct an impact analysis of the new initiative to determine how the project should be rolled out.', false),
  (1211, 2, 'تنظيم جلسة عمل تركز على النطاق والرؤية والرسالة للمبادرة.', 'Plan a working session focusing on the scope, vision, and mission of the initiative.', true),
  (1211, 3, 'إجراء دراسة مقارنة لتحديد جدوى المبادرة تجاريًا.', 'Conduct benchmarking to determine the business viability of the initiative.', false),
  (1212, 0, 'العمل على أساليب مختلفة في التقدير لإعطاء ثقة حول التكاليف لكل إصدار.', 'Worked on different approaches of estimating to give confidence of the cost spent in each product increment', false),
  (1212, 1, 'إعداد خطة لإدارة الاتصالات تتضمن تقارير عن الميزانية المنفقة في كل تكرار مقابل المخطط.', 'Worked on a communications management plan with reports of budget spent in each iteration versus planned to avoid these discussions during ceremonies', false),
  (1212, 2, 'العمل مع مالك المنتج لتوضيح دوره في مشروع أجايل ونطاق الاجتماعات الرسمية.', 'Worked with the product owner to clarify their role in an agile project and the scope of the agile ceremonies', true),
  (1212, 3, 'العمل بعقد بسعر ثابت لتحويل اهتمام مالك المنتج من التكلفة إلى القيمة.', 'Worked on a fixed-price contract to switch the product owner''s attention to value instead of money', false),
  (1213, 0, 'إنشاء ميثاق المشروع.', 'Create the project charter.', false),
  (1213, 1, 'عقد اجتماع انطلاق المشروع.', 'Conduct a kick-off meeting.', false),
  (1213, 2, 'تطوير خطة إدارة الاتصالات.', 'Develop the communications management plan.', true),
  (1213, 3, 'إعداد وتوزيع مصفوفة المسؤوليات (RACI).', 'Prepare and distribute the responsible, accountable, consult, and inform (RACI) matrix.', false),
  (1214, 0, 'مناقشة الأمر مع فريق المشروع لتحديد أنسب طريقة للاستجابة.', 'Discuss it with the project team to determine the most appropriate way to respond.', false),
  (1214, 1, 'إضافة التأخير إلى سجل القضايا وتضمينه في تقرير المشروع.', 'Add it to the issue log and include it in the project report.', true),
  (1214, 2, 'الاتصال بمدير المشتريات لتسريع تسليم المواد.', 'Contact the procurement manager to expedite delivery of the material.', false),
  (1214, 3, 'تصعيد المشكلة إلى مالك المشروع وطلب تغيير الجدول الزمني.', 'Escalate the issue to the project owner and request a schedule change.', false),
  (1215, 0, 'قيادة اجتماع للمشتريات.', 'Lead a procurement meeting.', false),
  (1215, 1, 'إنشاء هيكل تجزئة العمل (WBS).', 'Create a work breakdown structure (WBS).', false),
  (1215, 2, 'تكييف وتخصيص الأصول الحالية.', 'Adapt and tailor existing assets.', true),
  (1215, 3, 'الموافقة على دراسة الجدوى (business case).', 'Sign off on the business case.', false),
  (1216, 0, 'التنفيذ المتوازي (Fast tracking)', 'Fast tracking', false),
  (1216, 1, 'التسريع (Crashing)', 'Crashing', true),
  (1216, 2, 'تسوية الموارد (Resource leveling)', 'Resource leveling', false),
  (1216, 3, 'الفترة التمهيدية والتأخير (Lead and lag)', 'Lead and lag', false),
  (1217, 0, 'طلب من الراعي الانتظار حتى يتم الانتهاء من هيكل تجزئة العمل (WBS).', 'Ask the sponsor to wait until the Work breakdown structure (WBS) is done.', false),
  (1217, 1, 'مشاركة نسخة أولية من ورقة تقدير الميزانية (BES) مع الراعي.', 'Share a draft copy of the Budget Estimate Sheet (BES) with the sponsor.', false),
  (1217, 2, 'إعادة مشاركة بيان العمل (SOW) مع الراعي.', 'Re-share the Statement of Work (SOW) with the sponsor.', false),
  (1217, 3, 'مشاركة نسخة أولية من هيكل توزيع الموارد (RBS) مع الراعي.', 'Share a draft copy of the Resource Breakdown Structure (RBS) with the sponsor.', true),
  (1218, 0, 'طلب مورد جديد من قسم الموارد البشرية.', 'Request a new resource from HR.', false),
  (1218, 1, 'طلب مورد جديد من الراعي.', 'Request a new resource from the project sponsor.', false),
  (1218, 2, 'التفاوض بشأن توافر المورد.', 'Negotiate for the resource''s availability.', true),
  (1218, 3, 'إبلاغ العميل بعدم إمكانية تنفيذ التغيير الجديد.', 'Tell the customer that the new change is not possible.', false),
  (1219, 0, 'تنظيم أنشطة جماعية لمساعدة أعضاء الفريق على التعبير عن اهتماماتهم.', 'Organize team activities to help team members express their interests.', false),
  (1219, 1, 'إنشاء عملية لمشاركة المعلومات مع جميع أعضاء الفريق.', 'Establish a process of sharing information with all team members.', true),
  (1219, 2, 'استخدام تقييم واضح وفي الوقت المناسب للوضع مع أعضاء الفريق.', 'Use timely and clear assessment of the situation with team members.', false),
  (1219, 3, 'السماح بتبادل حر للأفكار والآراء بين أعضاء الفريق.', 'Allow free exchange of ideas and opinions between team members.', false),
  (1220, 0, 'مراقبة هؤلاء أصحاب المصلحة عن كثب.', 'Closely monitor these stakeholders', true),
  (1220, 1, 'تشجيع هؤلاء أصحاب المصلحة بشكل كبير.', 'Highly encourage these stakeholders', false),
  (1220, 2, 'التركيز بانتباه على هؤلاء أصحاب المصلحة.', 'Attentively focus on these stakeholders', false),
  (1220, 3, 'استغلال هؤلاء أصحاب المصلحة بشكل واضح.', 'Visibly harness these stakeholders', false),
  (1221, 0, 'طلب موافقة الإدارة.', 'Request management approval.', false),
  (1221, 1, 'استخدام المعدات المقدمة.', 'Use the equipment offered.', false),
  (1221, 2, 'تعديل جدول المشروع.', 'Revise the project schedule.', false),
  (1221, 3, 'تحديد ما إذا كانت هناك مخاطر.', 'Determine if there is a risk.', true),
