  (1223, 1, 'تعديل جدول المشروع والميزانية.', 'Revise the project schedule and the budget.', false),
  (1223, 2, 'تحديث الدروس المستفادة.', 'Update the lessons learned.', false),
  (1223, 3, 'تحديد مخاطر جديدة ومراقبة المخاطر المتبقية.', 'Identify new risks, and monitor residual risks.', true),
