INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1347, 1, 'إجراء اختبار المستخدم على الخادم الحالي.', 'Perform user testing on the current server.', false),
  (1347, 2, 'تخطي اختبار المستخدم والانتقال إلى المهمة التالية.', 'Bypass user testing and proceed to the next task.', false),
  (1347, 3, 'مطالبة المورد بتسريع تسليم الخادم الجديد.', 'Ask the supplier to rush the delivery of the new server.', false),
  (1348, 0, 'التواصل مع كل صاحب مصلحة بشكل فردي لفهم أسباب عدم الحضور.', 'Reach out to stakeholders individually to understand their reasons for non-attendance.', true),
  (1348, 1, 'الاستمرار في عقد الاجتماعات كما هو مخطط وانتظار انضمام أصحاب المصلحة.', 'Continue with the daily standup meetings as scheduled and wait for stakeholders to join.', false),
  (1348, 2, 'إلغاء الاجتماعات واستكشاف وسائل تواصل بديلة.', 'Cancel the daily standup meetings and explore alternative communication methods.', false),
  (1348, 3, 'تصعيد الأمر للإدارة العليا وطلب تدخلهم.', 'Escalate the issue to higher management and request their intervention.', false),
  (1349, 0, 'جدولة تمارين لبناء الفريق تركز على زيادة التفاعل.', 'Schedule team-building exercises focused on increasing engagement.', false),
  (1349, 1, 'العمل مع الفريق على تحديد أهداف أكثر تحديًا لرفع مستوى الأداء.', 'Work with the team to target higher levels of performance by providing more challenging goals.', true),
  (1349, 2, 'دعوة الراعي لحضور الاجتماع للتعامل مع السلوك المشتت.', 'Have the sponsor attend the standup to address the distracting behavior.', false),
  (1349, 3, 'العمل مع الراعي لتحديد ميزانية يمكن استخدامها لتحفيز الفريق.', 'Work with the sponsor to identify a budget that could be used to incentivize the team.', false),
  (1350, 0, 'إعادة تعيين عضو الفريق الذي يفتقر إلى المهارات إلى مهمة أخرى.', 'Reassign the team member who is missing the skills to another task.', false),
  (1350, 1, 'الاجتماع مع الفريق لمناقشة المشكلات ووضع خطة لمعالجتها.', 'Meet with the team to discuss the issues and develop a plan to address them.', true),
  (1350, 2, 'إبلاغ أصحاب المصلحة أن المشروع سيتأخر ولا يمكن فعل شيء.', 'Tell the stakeholders that the project will miss the deadline and nothing can be done.', false),
  (1350, 3, 'فصل عضو الفريق الذي يفتقر إلى المهارات وتوظيف شخص آخر.', 'Fire the team member who is missing the skills and hire someone else.', false),
  (1351, 0, 'استبعاد فريق التطوير من التدقيق حسب طلب العميل.', 'Exclude the project development team from the compliance audit as requested by the customer.', false),
  (1351, 1, 'بدء التدقيق دون إبلاغ العميل لأن الشركة ملزمة بالامتثال.', 'Initiate the audit without informing the customer because the company is required to comply.', false),
  (1351, 2, 'جدولة اجتماع مع اللجنة التوجيهية وجميع أصحاب المصلحة لمناقشة الأمر والتوصل إلى تفاهم مشترك.', 'Schedule a steering committee meeting with all stakeholders to discuss and come to a common understanding.', false),
  (1351, 3, 'الاجتماع مع العميل لشرح ضرورة الامتثال للمتطلبات والمضي قدمًا في التدقيق.', 'Meet with the customer to explain the need to meet the compliance requirements and proceed with the audit.', true),
  (1352, 0, 'مكتب إدارة المشاريع (PMO)', 'PMO', true),
  (1352, 1, 'مدير المشروع', 'Project Manager', false),
  (1352, 2, 'راعي المشروع', 'Project Sponsor', false),
  (1352, 3, 'العميل', 'Customer', false),
  (1353, 0, 'الاجتماع مع مالك المنتج لمناقشة كل من الفرصة والقلق المتعلق بالتعديل المقترح.', 'Meet with the product owner to discuss both the opportunity and concern about the proposed modification.', true),
  (1353, 1, 'إجراء تصويت بين الفريق لتحديد ما إذا كان سيتم تضمين التعديل.', 'Have the project team vote whether or not to include the modification.', false),
  (1353, 2, 'تسجيل الفرصة في السجل الاحتياطي وتأجيل النقاش وطلب من الفريق مناقشة الأمر في الاجتماع التالي.', 'Note the opportunity in the project backlog and table the discussion. Ask the project team to consider the modification and decide on how to proceed at the next scheduled meeting.', false),
  (1353, 3, 'الاجتماع مع أصحاب المصلحة والفريق لمناقشة كيفية المضي قدمًا بشأن التعديلات المقترحة.', 'Meet with stakeholders and the project team to discuss how to proceed regarding the proposed modifications.', false),
  (1354, 0, 'تنظيم اجتماع مع أصحاب المصلحة لضمان تعريف خطة التواصل بشكل واضح.', 'Set up a meeting with the project stakeholders to ensure the communication management plan is clearly defined.', false),
  (1354, 1, 'ضمان السماح للفريق باختيار أفضل الموارد التقنية لضمان نجاح المشروع.', 'Ensure the sponsor allows the project team to include the most technical resources to better ensure project success.', false),
  (1354, 2, 'العمل عن كثب مع الفريق لوضع وتحديد رؤية واضحة للمشروع.', 'Work closely with the project team to develop and clearly define the project vision.', true),
  (1354, 3, 'العمل مع أصحاب المصلحة لضمان تحديد ميثاق المشروع والمخرجات بشكل واضح.', 'Work with the project stakeholders to ensure that the project charter and deliverables are clearly defined.', false),
  (1355, 0, 'العمل مع القسم القانوني لتوثيق السياسات والإجراءات وجعل أعضاء الفريق يوقعون على هذا المستند.', 'Work with the legal department to document the policies and procedures and have the project team members sign this document.', false),
  (1355, 1, 'العمل مع راعي المشروع لاستبدال الأعضاء الذين لا يتبعون الإجراءات المحددة.', 'Work with the project sponsor to replace team members not following the established procedures.', false),
  (1355, 2, 'الاجتماع مع الفريق لمراجعة السياسات والإجراءات مجددًا والتأكيد على أهميتها.', 'Meet with the project team to review the policies and procedures again and stress their importance.', true),
  (1355, 3, 'تطوير برنامج حوافز لأولئك الذين يتبعون القواعد بشكل صحيح.', 'Develop an incentive program for those who correctly follow the ground rules.', false),
  (1356, 0, 'تحليل تخطيط البوكر (Planning Poker)', 'The planning poker analysis', false),
  (1356, 1, 'مخطط الانحدار للإصدار (Release Burndown Chart)', 'The release burndown chart', true),
  (1356, 2, 'عدد نقاط القصص للمستخدمين المتبقين', 'The count of story points for the remaining user stories', false),
  (1356, 3, 'هيكل تقسيم العمل (WBS)', 'The work breakdown structure', false),
  (1357, 0, 'التركيز يتحول إلى مناقشة المشكلات بدلاً من تحديد طرق التحسين للمشاريع المستقبلية.', 'The focus shifts towards discussing issues instead of identifying ways to improve for future projects.', true),
  (1357, 1, 'يتم فقدان فرصة تحسين عمليات الفريق استنادًا إلى ملاحظات المشروع المحددة.', 'The opportunity to improve team processes based on specific project observations is missed.', false),
  (1357, 2, 'يتم التركيز على ملاحظات أصحاب المصلحة حول أداء المشروع.', 'The emphasis is placed on stakeholder observations about project performance.', false),
  (1357, 3, 'لا يتم تحديث خطة إدارة الوقت بشكل صحيح.', 'The time management plan is not properly updated.', false),
  (1358, 0, 'دعوة المدراء التنفيذيين إلى الاجتماعات اليومية ليتعلموا أهمية المشروع.', 'Invite the executives to the project standups so they can learn the importance of the project.', false),
  (1358, 1, 'الاجتماع مع المدراء التنفيذيين لتدريبهم على فوائد ممارسات أجايل.', 'Meet with the executives to train them on the benefits of agile practices.', true),
  (1358, 2, 'إبلاغ مكتب إدارة المشاريع بأن المشروع يجب أن يستخدم النهج التقليدي لأنه لن ينجح دون قبول المدراء التنفيذيين.', 'Inform the PMO that the project needs to use waterfall as the project will not succeed without executive acceptance.', false),
  (1358, 3, 'استبدال أصحاب المصلحة الحاليين بالمدراء التنفيذيين.', 'Replace the current project stakeholders with the executives.', false),
  (1359, 0, 'يساعد مدير المشروع الفريق A في حل المشكلة، ويقوم الفريق A بتحديد كيفية تنفيذ الحل.', 'The project manager helps Team A solve the issue, and Team A decides how to implement the solution.', true),
  (1359, 1, 'يقدم الفريق B طلب تغيير للفريق A، ويتولى الفريق A اعتماد التغيير.', 'Team B submits a change request to Team A, and Team A validates the change.', false),
  (1359, 2, 'يحدد الفريق B كيف يقوم الفريق A بتنفيذ التغيير، ويشرف مدير المشروع.', 'Team B decides how Team A implements the change, project manager supervises.', false),
  (1359, 3, 'يقرر مدير المشروع كيف يقوم الفريق A بتنفيذ التغيير، ويحدد معايير القبول.', 'The project manager decides how Team A implements the change, and defines acceptance criteria.', false),
  (1360, 0, 'الثقة', 'Trust', true),
  (1360, 1, 'التركيز', 'Concentration', false),
  (1360, 2, 'السرعة', 'Speed', false),
  (1360, 3, 'الدقة', 'Accuracy', false),
  (1361, 0, 'يجب على الفريق حصر المنتجات التي أطلقها المنافسون ومحاولة تقليد أسلوبهم.', 'Team must list out products launched by the competitors and try to copy their style.', false),
  (1361, 1, 'يجب على الفريق سرد جميع التبعيات الخارجية وتقييم تأثيرها على تسليمات المشروع.', 'Team must list out all external dependencies and assess the impact of it on project deliveries.', true),
  (1361, 2, 'يجب على الفريق سرد تأثير دخول منافس جديد للسوق.', 'Team must list out impact of a new competitor in the market.', false),
  (1361, 3, 'يجب على الفريق التركيز على المهام المخصصة لهم ونسيان التبعيات الخارجية لأنها لن تؤثر على عملهم.', 'Team must concentrate on their assigned work and forget external dependencies. This will not affect their work.', false),
  (1362, 0, 'تقنية منخفضة ولكن عالية التفاعل (Low-tech, high-touch)', 'Low-tech, high-touch', true),
  (1362, 1, 'أداة مستخدمة في دورة PDCA', 'Tool used in PDCA', false),
  (1362, 2, 'تستخدم لإظهار الأعمال المنجزة', 'Used to show the work done', false),
  (1362, 3, 'لوحة لتقدير نقاط القصص', 'Board for story point estimates', false),
  (1363, 0, 'تحديث قاعدة المعرفة للدروس المستفادة.', 'Update the lessons learned knowledge base.', true),
  (1363, 1, 'تحديث سجل المخاطر قبل إبلاغ أعضاء الفريق.', 'Update the risk register before informing project team members.', false),
  (1363, 2, 'تحديث وأرشفة ملف المشتريات النهائي.', 'Update and archive the final procurement file.', false),
  (1363, 3, 'إغلاق وثائق تقييم أداء البائع.', 'Close out the seller performance evaluation documentation.', false),
  (1364, 0, 'طلب تأكيد رسمي على التغيير.', 'Request a formal confirmation of the change.', false),
  (1364, 1, 'الحصول على موافقة أصحاب المصلحة لتعديل الميزانية.', 'Get stakeholder approval to revise the budget.', false),
  (1364, 2, 'بدء عملية التحكم المتكاملة في التغيير.', 'Initiate integrated change control process.', true),
  (1364, 3, 'تحديث خطة إدارة المشروع.', 'Update project management plan.', false),
  (1365, 0, 'تطوير خطة لإشراك أصحاب المصلحة تتضمن استراتيجيات لمعالجة مخاوف هذا الطرف المقاوم.', 'Develop a stakeholder engagement plan that includes strategies to address the concerns of the resistant stakeholder.', true),
  (1365, 1, 'استبعاد صاحب المصلحة المقاوم من المشروع لتجنب الاضطرابات والتركيز على المشروع.', 'Exclude the resistant stakeholder from the project to prevent potential disruptions and maintain project focus.', false),
  (1365, 2, 'تعيين أحد أعضاء الفريق لإدارة صاحب المصلحة المقاوم والتركيز على إشراك الآخرين.', 'Assign the task of managing the resistant stakeholder to a team member and focus on engaging other stakeholders.', false),
  (1365, 3, 'طلب تدخل الإدارة العليا لإقناع صاحب المصلحة بأهمية المشروع.', 'Seek senior management''s intervention to convince the resistant stakeholder of the project''s importance.', false),
  (1366, 0, 'خطة إدارة النطاق.', 'Scope management plan.', false),
  (1366, 1, 'خطة إدارة المتطلبات.', 'Requirements management plan.', true),
  (1366, 2, 'خطة إدارة الجودة.', 'Quality management plan.', false),
  (1366, 3, 'تقارير أداء العمل.', 'Work performance reports.', false),
  (1367, 0, 'بيان العمل (SOW)', 'Statement of work (SOW)', false),
  (1367, 1, 'ميثاق المشروع', 'Project charter', true),
  (1367, 2, 'خطة إدارة المشروع', 'Project management plan', false),
  (1367, 3, 'نظام معلومات إدارة المشروع (PMIS)', 'Project management information system (PMIS)', false),
  (1368, 0, 'تفويض قرار أهمية التغيير إلى صاحب مصلحة أكثر خبرة.', 'Assign the decision regarding the critical nature of the change to a more knowledgeable stakeholder.', false),
  (1368, 1, 'تقديم طلب تغيير إلى لجنة التحكم في التغيير (CCB).', 'Submit a change request to the change control board (CCB).', true),
  (1368, 2, 'تعديل هيكل تقسيم العمل (WBS) وبيان نطاق المشروع لتضمين التغيير.', 'Revise the work breakdown structure (WBS) and the project scope statement to include the change.', false),
  (1368, 3, 'إبلاغ راعي المشروع بالتأثير على الميزانية والجدول الزمني.', 'Communicate the impact on the budget and schedule to the project sponsor.', false),
  (1369, 0, 'انخفاض ثقة المشروع.', 'Decreased project confidence.', true),
  (1369, 1, 'زيادة تكاليف المشروع.', 'Increased project costs.', false),
  (1369, 2, 'انخفاض جودة المشروع.', 'Decreased project quality.', false),
  (1369, 3, 'تأخر في الجدول الزمني للمشروع.', 'Delayed project schedule.', false),
  (1370, 0, 'تحديد الفجوات المعرفية لكل فرد ومعالجتها من خلال التدريب.', 'Identify each individual''s knowledge gaps and address those gaps through training.', true),
  (1370, 1, 'تسجيل ذلك في سجل المخاطر ومعالجة ذلك مع الفريق أثناء جلسة الاستعراض.', 'Note this in the risk register and address this with the team during a retrospective session.', false),
  (1370, 2, 'إبلاغ الراعي بأن التسليم لن يكون متاحًا في الوقت المحدد بسبب نقص الخبرة.', 'Inform the sponsor that the deliverable will not be available on time due to insufficient expertise.', false),
  (1370, 3, 'الاجتماع مع قسم الموارد البشرية لمعالجة الأفراد الذين يفتقرون إلى المهارات.', 'Meet with human resources to have them address the individuals that are missing skills.', false),
  (1371, 0, 'مراجعة الحالة التجارية للمشروع ونتائج دراسة الجدوى.', 'Review the project business case and the results of the feasibility study.', true),
  (1371, 1, 'تيسير اجتماع بين راعي المشروع وقائد الفريق لمناقشة المخاوف.', 'Facilitate a meeting between the project sponsor and the team lead to discuss the concerns.', false),
  (1371, 2, 'الاجتماع مع أصحاب المصلحة لمناقشة المخاوف وتسجيل استنتاجاتهم في خطة إشراك أصحاب المصلحة.', 'Meet with the stakeholders to discuss the concerns and record their conclusions in the stakeholder engagement plan.', false),
  (1371, 3, 'تحديد المخاطر والاستجابات المتفق عليها وتعديل سجل المخاطر وفقًا لذلك.', 'Identify the risks and agreed-upon risk responses and modify the risk register accordingly.', false),
  (1372, 0, 'بيان عمل المشتريات وتقارير أداء العمل', 'Procurement statement of work (SOW) and work performance report', false),
  (1372, 1, 'خطة إدارة المتطلبات وخطة إدارة التغيير', 'Requirements management plan and change management plan', false),
  (1372, 2, 'خطة إدارة المشتريات وميثاق المشروع', 'Procurement management plan and project charter', false),
  (1372, 3, 'التقرير النهائي وتحديثات وثائق المشروع', 'Final report and project document updates', true),
  (1373, 0, 'التأكد من فعالية استجابة المخاطر ومتابعة التقدم.', 'Confirmed the effectiveness of the risk response and monitored progress.', true),
  (1373, 1, 'تحديث سجل الافتراضات بتفاصيل حول المخاطر.', 'Updated the assumption log with details concerning the risk.', false),
  (1373, 2, 'إجراء تحليل للمخاطر لتحديد مدى التعرض لمخاطر المشروع.', 'Performed a risk analysis to quantify project risk exposure.', false),
  (1373, 3, 'تطوير مصفوفة الاحتمالية والأثر لتحديد أولوية المخاطر.', 'Developed a probability and impact matrix to determine the risk''s priority level.', false),
  (1374, 0, 'إرجاع الأداة إلى المورد الأصلي ورفض دفع الفاتورة لأن التسليم كان متأخرًا.', 'Return the tool to the original supplier and refuse to pay the invoice because delivery was late.', false),
  (1374, 1, 'الاحتفاظ بالأداة الإضافية كاحتياطي، ودفع الفاتورة من الاحتياطي المالي، وتحديث سجل الدروس المستفادة.', 'Keep the extra tool as a spare, pay the invoice from the contingency reserve, and update the lessons learned log.', false),
  (1374, 2, 'مراجعة اتفاقية الشراء مع المورد الأصلي لتطبيق شروط التأخير، وإبلاغ المستشار القانوني بالمشكلة.', 'Consult the original supplier''s procurement agreement to apply late delivery terms, and inform legal counsel of the issue.', true),
  (1374, 3, 'مقارنة جودة الأداتين، واختيار الأداة ذات القيمة الأفضل، وإرجاع الأخرى.', 'Compare the quality of both tools, select the tool that gives the best value, and return the other tool.', false),
  (1375, 0, 'مناقشة الخبير على انفراد حول تحفظاته أو تحيزاته والإصرار على تبني سلوك شامل للجميع.', 'Question the expert privately about their reluctance or biases and insist on an inclusive attitude.', true),
  (1375, 1, 'إصدار تحذير تأديبي للخبير وإبلاغ مديره الوظيفي لإرساله إلى تدريب على التنوع.', 'Issue a disciplinary warning to the expert and advise their functional manager to send them to diversity training.', false),
  (1375, 2, 'تجنّب التأخير والنزاعات من خلال توظيف مستشار يوافق الخبير على العمل معه.', 'Prevent delays and conflicts by hiring a consultant that the expert is willing to work with.', false),
  (1375, 3, 'تأنيب الخبير على سلوكه التمييزي خلال اجتماع الفريق لتقديم مثال يُحتذى به.', 'Reprimand the expert about their discriminatory behavior during a team meeting to set the right example.', false),
  (1376, 0, 'الاعتراف بعضو الفريق عالي الأداء كنموذج يجب أن يحتذي به الآخرون.', 'Recognize the high-performing team member as an example to be followed by the others.', false),
  (1376, 1, 'توفير تدريب إضافي للفريق حول العمليات الرشيقة (Agile).', 'Provide additional training to the team on agile processes.', false),
  (1376, 2, 'مناقشة المشكلة مع راعي المشروع والعودة إلى استخدام النهج التنبؤي فقط.', 'Discuss the issue with the project sponsor and revert the project to use only a predictive approach.', false),
  (1376, 3, 'الاجتماع مع الفريق لمناقشة المشكلات وتطوير خطة لمعالجتها.', 'Meet with the team to discuss the issues and develop a plan to address them.', true),
  (1377, 0, 'تخطيط جلسة عصف ذهني مع فريق المشروع لإيجاد حل للمشكلة.', 'Plan a brainstorming session with the project team to find a resolution to the problem.', false),
  (1377, 1, 'تحديد مصدر الصراع بين أصحاب المصلحة ومعالجة القضية.', 'Identify the source of the conflict between the stakeholders and address the issue.', true),
  (1377, 2, 'إعداد قائمة بالإيجابيات والسلبيات لتحديد تأثير هذا الصراع.', 'List the positives and negatives of the situation to determine the impact of this conflict.', false),
  (1377, 3, 'دعوة راعي المشروع للتدخل والعمل كوسيط بين أصحاب المصلحة.', 'Invite the project sponsor to intervene and act as a negotiator for the key stakeholders.', false),
  (1378, 0, 'طُلب من مدير المشروع تقديم نتيجة أعمال ضمن جدول زمني مضغوط؛ حيث كان الجدول الأصلي شهرًا، وأصبح المطلوب أسبوعين.', 'The project manager is being asked to deliver a business result in a compressed timeline; the original timeline was one month, but the new requested timeline is two weeks.', false),
  (1378, 1, 'علم مدير المشروع من عضو فريق آخر بعدم توفر أي موارد تقنية، ولكنه يعرف مدير الموارد التقنية من مشروع سابق.', 'In the resource planning activity, the project manager heard from another team member that no technical resources are available to join the team; however, the project manager knows the technical resource manager from a previous project.', false),
  (1378, 2, 'ضمان أن مالك المنتج على علم بوجود مشكلة في الحصول على مورد تقني.', 'Ensure the product owner knows that there is an issue with acquiring a technical resource.', true),
  (1378, 3, 'تصعيد مشكلة الموارد التقنية للإدارة العليا.', 'Escalate the technical resource issue to upper management.', false),
  (1378, 4, 'التحقق من توفر الموارد من خلال الاجتماع مع مدير الموارد التقنية المعروف سابقًا.', 'Verify the availability of resources by meeting with the previously known technical resource manager.', false),
  (1378, 5, 'الاتصال بمورد خارجي للحصول على مورد تقني.', 'Contact a third-party vendor to obtain a technical resource.', false),
  (1379, 0, 'في مراحله المبكرة.', 'It is in the early stages.', true),
  (1379, 1, 'لديه فريق جديد تمامًا.', 'It has a brand new team.', false),
  (1379, 2, 'سيكون مدير المشروع مشغولًا جدًا في تنفيذ مشاريع أخرى خلال الأسبوعين الأولين.', 'The project manager will be very busy executing other projects during the first two weeks of the project.', false),
  (1379, 3, 'ضمان فهم الفريق لمبادئ التنظيم الذاتي.', 'Ensure the team understands self-organizing principles.', false),
  (1379, 4, 'تخطيط واستضافة عدة فعاليات لبناء الفريق لتعزيز التعاون.', 'Plan and host several team-building events to normalize the team.', false),
  (1379, 5, 'توفير تحديثات يومية لحالة المشروع لإبقاء الفريق على اطلاع.', 'Provide daily project status updates to keep the team informed.', false),
  (1379, 6, 'التعرف على كل عضو من أعضاء الفريق من خلال محادثات فردية.', 'Get to know each team member through one-on-one conversations.', false),
  (1380, 0, 'تقييم هيكل تقسيم العمل (WBS) وإعادة التفاوض على النطاق مع راعي المشروع.', 'Assess the work breakdown structure (WBS) and renegotiate scope with the project sponsor.', false),
  (1380, 1, 'إشراك أصحاب المصلحة وأعضاء الفريق لتحديد الحد الأدنى من المنتج القابل للتسليم (MVP) اللازم للإطلاق.', 'Engage with the stakeholders and team members to determine the minimum viable product (MVP) necessary for the launch.', true),
  (1380, 2, 'حساب مؤشر أداء الجدول الزمني (SPI) وتصعيد خطر الجدول الزمني إلى راعي المشروع.', 'Calculate the schedule performance index (SPI) and escalate the schedule risk to the project sponsor.', false),
  (1380, 3, 'تعديل خط الأساس للجدول الزمني لتلبية احتياجات أصحاب المصلحة ومتابعة التقدم باستخدام مخطط الحرق.', 'Modify the schedule baseline to meet stakeholder needs and monitor progress using a burndown chart.', false),
  (1382, 0, 'اختيار أحد أعضاء الفريق لتحديث قالب خطة إدارة المشروع.', 'Select a team resource who can update the project management plan template.', false),
  (1382, 1, 'استنادًا إلى القيمة التجارية للتكرارات القادمة، اختيار أولوية للأنشطة.', 'Based on business value for the upcoming iterations, choose a priority for the activities.', false),
  (1382, 2, 'حل المشكلة بشكل مستقل حتى لا يتشتت أعضاء الفريق.', 'Resolve the issue independently so that team members do not become distracted.', true),
  (1382, 3, 'إضافة المشكلة كمخاطر جديدة في سجل المخاطر واقتراح إجراءات تصحيحية.', 'Add the problem as a new project risk in the risk register and suggest corrective actions.', false),
  (1383, 0, 'تصعيد مسألة المتطلبات غير الواضحة إلى الإدارة والانتظار للحصول على التفويض النهائي.', 'Escalate the issue of unclear requirements to the management team and wait for final authorization.', false),
  (1383, 1, 'تفصيل المتطلبات وتحديد أولوياتها إلى حزم عمل تكرارية.', 'Break down the requirements and prioritize the requirements into iterative work packages.', true),
  (1383, 2, 'تجاهل المتطلبات غير الواضحة والتركيز على خطة تسليم المشروع.', 'Ignore the unclear requirements and focus on the delivery plan of the project.', false),
  (1383, 3, 'الانتظار حتى تصبح المتطلبات أكثر وضوحًا قبل اتخاذ أي إجراء إضافي في المشروع.', 'Wait for the requirements to be more clear before any further action is taken on the project.', false),
  (1384, 0, 'إجراء مراجعات دورية لخطط المشروع وأهدافه وتسليماته لضمان تسجيل جميع البيانات.', 'Conduct periodic reviews of project plans, objectives, and deliverables to ensure all data is captured.', false),
  (1384, 1, 'طلب تمويل إضافي من الراعي لتوظيف موارد ماهرة وتحسين الجودة.', 'Request more funding from the sponsor to hire additional skilled resources and improve quality.', false),
  (1384, 2, 'مراجعة أهداف المشروع بشكل تعاوني مع الراعي للاتفاق على خطط وتسليمات قابلة للتحقيق.', 'Collaboratively review project objectives with the sponsor to agree on achievable plans and deliverables.', true),
  (1384, 3, 'إنشاء حالة عمل بعد مراجعة السوق لتعديل التسليمات بناءً على الأهداف الجديدة.', 'Create a business case after a market review to adjust project deliverables based on new objectives.', false),
  (1385, 0, 'خط الأساس للنطاق', 'Scope baseline', false),
  (1385, 1, 'خطة إدارة المشروع', 'Project management plan', false),
  (1385, 2, 'خط الأساس للتكلفة', 'Cost baseline', true),
  (1385, 3, 'خط الأساس للجدول الزمني', 'Schedule baseline', false),
  (1386, 0, 'العمل مع مكتب إدارة المشاريع (PMO) لتطوير جدول زمني مفصل للمشروع.', 'Work with the project management office (PMO) to develop a detailed project schedule.', false),
  (1386, 1, 'العمل مع فريق التسويق لإجراء تحليل تأثير لتحديد السوق المستهدف.', 'Work with the marketing team to conduct an impact analysis to identify the target market.', false),
  (1386, 2, 'العمل مع راعي المشروع لتحديد رؤية المشروع والمبادرة العامة.', 'Work with the project sponsor to define the project vision and overall initiative.', true),
  (1386, 3, 'العمل مع أصحاب المصلحة لتحديد أعضاء الفريق المناسبين للمشروع.', 'Work with the stakeholders to identify the appropriate project team members.', false),
  (1387, 0, 'تلبية المصالح الشخصية لأصحاب المصلحة.', 'Meeting the personal interests of stakeholders.', false),
  (1387, 1, 'تلبية المصالح المشتركة لجميع أصحاب المصلحة.', 'Meeting the mutual interests of all stakeholders.', true),
  (1387, 2, 'الحفاظ على العلاقات والانسجام مع أصحاب المصلحة.', 'Preserving the relationships and rapport with stakeholders.', false),
  (1387, 3, 'دفع أصحاب المصلحة لقبول وجهة نظر مدير المشروع.', 'Pushing stakeholders to accept the project manager''s viewpoint.', false),
  (1388, 0, 'مخطط باريتو', 'Pareto chart', false),
  (1388, 1, 'مخطط هيكل السمكة', 'Fishbone diagram', false),
  (1388, 2, 'دورة ديمنغ (PDCA)', 'Deming''s PDCA cycle', true),
  (1388, 3, 'مخطط السبب والأثر', 'Cause and effect diagram', false),
  (1389, 0, 'إنشاء بروتوكولات للتعامل مع السبرينت (sprints) خلال اجتماع الفريق.', 'Institute protocols for handling sprints in a team meeting.', false),
  (1389, 1, 'تيسير الاجتماعات مع كل عضو في الفريق لفهم أهداف المشروع.', 'Facilitate meetings with each member of the team to comprehend project goals.', true),
  (1389, 2, 'مناقشة تقدم المنتج مع أعضاء الفريق باستخدام مخطط الحرق (burndown chart).', 'Confer product progress with team members by utilizing a burndown chart.', false),
  (1389, 3, 'تحليل خريطة المشروع لإصدار المنتج مع أعضاء الفريق.', 'Analyze the project map for release of product with team members.', false),
  (1390, 0, 'مساعدة الفريق على صياغة اتفاقية فيما بينهم تتضمن المعايير السلوكية المرغوبة.', 'Aid the team to construct an agreement amongst them that details coveted behavioral norms.', true),
  (1390, 1, 'عقد اجتماع مع الفريق لمراجعة المشكلات وتفصيل الإجراءات لحلها.', 'Convene with the team to review the issues and detail actions to solve them.', false),
  (1390, 2, 'تولي دور قيادي أعلى وتقديم مثال للسلوك المطلوب.', 'Adopt a higher leadership role and set an example for the behavior needed.', false),
  (1390, 3, 'تنظيم تدريب للفريق حول أجايل وإدارة الوقت.', 'Assemble agile and time management training for the team to complete.', false),
  (1391, 0, 'مراجعة حضور مدير تكنولوجيا المعلومات في الاجتماعات السابقة للمشروع.', 'Review previous project meeting attendance to determine the IT director''s participation.', false),
  (1391, 1, 'تحليل المتطلبات التي تم الموافقة عليها للمشروع مع مدير تكنولوجيا المعلومات.', 'Analyze the requirements that were approved for the project with the IT director.', false),
  (1391, 2, 'مناقشة مخاوف مدير تكنولوجيا المعلومات مع فريق المشروع.', 'Discuss the IT director''s concerns with the project team.', false),
  (1391, 3, 'جمع ملاحظات مباشرة وصريحة من مدير تكنولوجيا المعلومات.', 'Collect forthright feedback from the IT director.', true),
  (1392, 0, 'إعداد وتنفيذ جلسات مع الفريق الكامل لمراجعة قائمة المهام المطلوبة ووصفها.', 'Prepare and execute sessions with the full project team to review the list of required tasks and descriptions.', true),
  (1392, 1, 'عقد اجتماع مع فريق ضمان الجودة والتعبير عن القلق بشأن ملاحظاتهم.', 'Create a meeting with the quality assurance team and voice concerns regarding the feedback they provided.', false),
  (1392, 2, 'طلب زيادة مالية من مجلس التحكم في التغيير (CCB) لتوظيف فريق ضمان جودة محلي بدلاً من الفريق عن بُعد.', 'Request a financial increase from the change control board (CCB) to employ a quality assurance team locally, as opposed to remote.', false),
  (1392, 3, 'دمج فريق ضمان الجودة مع فريق التطوير لإجراء الاختبارات في نهاية المشروع.', 'Combine the quality assurance team and the development team to complete testing at the conclusion of the project.', false),
  (1393, 0, 'مواصلة التطوير بناءً على خطة إدارة المشروع ومعالجة المشكلة بعد التسليم.', 'Continue developing based on the project management plan and address the issue post-delivery.', false),
  (1393, 1, 'مراجعة خطة إدارة النطاق وتسجيل ذلك كمخاطرة تؤثر على المشروع بأكمله.', 'Revisit the scope management plan and note this as a risk to the entire project.', false),
  (1393, 2, 'تحديد اجتماع مع مالك المنتج وفريق المالية للاتفاق على تصحيحات المسار.', 'Schedule a meeting with the product owner and finance team to agree on course corrections.', true),
  (1393, 3, 'مراجعة خطة إدارة التواصل وإجراء التعديلات اللازمة.', 'Revisit the communications management plan and make necessary adjustments.', false),
  (1394, 0, 'تقدير التأثير المالي للعوائق وطلب تمويل إضافي.', 'Estimate the financial impact of the impediments and request additional funding.', false),
  (1394, 1, 'تسجيل العوائق وإبلاغ الإدارة بالحاجة إلى مساعدتهم في حل هذه العوائق.', 'Capture the impediments and inform management that their assistance is needed in resolving the impediments.', false),
  (1394, 2, 'التأكد من تسجيل العوائق وترتيب أولوياتها بناءً على الميزات ذات القيمة الأعلى.', 'Ensure that the impediments are captured and prioritized based upon the highest valued features.', true),
  (1394, 3, 'البدء في إزالة العوائق بدءًا من الأسهل لتعزيز شعور الإنجاز لدى الفريق.', 'Begin to remove the impediments, starting with the easiest ones first, to foster team accomplishment.', false),
  (1395, 0, 'تدريب الفريق على عملية اتخاذ القرار مع افتراض استراتيجية متحفظة تجاه إطلاق المنتجات.', 'Coach the team on the decision-making process, assuming a risk-averse strategy towards product releasing.', false),
  (1395, 1, 'دعم قرار مالك المنتج والعمل على تحسين التوافق مع هذا صاحب المصلحة لتجنب مثل هذه القضايا مستقبلاً.', 'Support the product owner''s decision and seek better alignment with this stakeholder in order to avoid this type of issue in the future.', true),
  (1395, 2, 'تحمل المسؤولية عن قرارات الإطلاق واتخاذ القرار النهائي بشأن موعد الإطلاق للعملاء.', 'Assume the responsibility for product releases, making the final call on when something is ready for customer launch.', false),
  (1395, 3, 'تصعيد المسألة إلى الراعي وطرح تساؤلات حول صلاحيات صاحب المصلحة في اتخاذ قرارات الإطلاق.', 'Escalate the issue to the sponsor, questioning the authority of the key stakeholder regarding the product launch decision.', false),
  (1396, 0, 'وضع خطة لإدارة الاتصالات لإبلاغ الموظفين بنموذج العمل الجديد.', 'Develop a communications management plan to inform the employees about the new business model.', false),
  (1396, 1, 'تطوير خطة سباقات تفصيلية بأهداف واضحة.', 'Develop a detailed sprint plan with clear deliverables.', false),
  (1396, 2, 'اعتماد نهج تدريجي في التنفيذ يقدم أعلى قيمة تجارية في وقت مبكر.', 'Adopt an iterative rollout approach that delivers the highest business value earlier.', true),
  (1396, 3, 'إعداد دراسة جدوى مع افتراضات للنموذج الجديد.', 'Develop a business case with assumptions for the new model.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1397, 0, 'تطوير خطة مع مواعيد نهائية ومراقبتها لتقليل وقت إكمال المنتج.', 'Develop and monitor a plan with due dates to reduce the time of completing the product.', false),
  (1397, 1, 'العمل مع مالك المنتج لتعريف الحد الأدنى من المنتج القابل للتسويق (MVP).', 'Work with the product owner to define the minimum viable product(s).', true),
  (1397, 2, 'اتباع نهج توقعي للحصول على قبول رسمي لكل منتج.', 'Follow a predictive approach in order to obtain formal acceptance of each deliverable.', false),
  (1397, 3, 'تعزيز مهارات التفاوض والمهارات الشخصية لدى الفريق من خلال التدريب.', 'Reinforce the negotiation and soft skills of the team through training.', false),
  (1398, 0, 'مقابلة مع راعي المشروع.', 'Interview with the project champion', false),
  (1398, 1, 'مناقشات تعاونية.', 'Collaborative discussions', true),
  (1398, 2, 'تقييمات الاحتمالات.', 'Probability assessments', false),
  (1398, 3, 'ورش عمل لتفادي المخاطر.', 'Workshops for risk avoidance', false),
  (1399, 0, 'تعيين مورد أكثر مهارة.', 'Acquire a more skilled resource.', false),
  (1399, 1, 'إزالة عضو الفريق من المشروع.', 'Remove the team member from the project.', false),
  (1399, 2, 'توجيه عضو الفريق ومساعدته.', 'Mentor the team member.', true),
  (1399, 3, 'طلب من مدير الموظف تقديم تدريب له.', 'Ask the team member''s line manager to provide training.', false),
  (1400, 0, 'المنهجية الرشيقة (Agile)', 'Agile', true),
  (1400, 1, 'المنهجية الهجينة (Hybrid)', 'Hybrid', false),
  (1400, 2, 'المنهجية التنبؤية (Predictive)', 'Predictive', false),
  (1400, 3, 'منهجية الشلال (Waterfall)', 'Waterfall', false),
  (1401, 0, 'الرجوع إلى ميثاق المشروع.', 'Consult the project charter.', false),
  (1401, 1, 'إعادة تقييم أهداف المشروع التجاري.', 'Reevaluate the business venture''s objectives.', false),
  (1401, 2, 'البحث عن مدخلات محتملة من العملاء.', 'Seek potential customer input.', true),
  (1401, 3, 'إجراء دراسة جدوى.', 'Conduct a feasibility study.', false),
  (1402, 0, 'النقل.', 'Transfer', false),
  (1402, 1, 'التخفيف.', 'Mitigate', true),
  (1402, 2, 'القبول.', 'Accept', false),
  (1402, 3, 'التجنب.', 'Avoid', false),
  (1403, 0, 'عملية تقدير موارد النشاط.', 'Estimate Activity Resources process.', false),
  (1403, 1, 'إرشادات التصميم من أجل الجودة (DfX).', 'Design for X (DfX) guidelines.', false),
  (1403, 2, 'قوائم فحص الجودة.', 'Quality checklists.', true),
  (1403, 3, 'مقابلات مع خبراء المجال.', 'Subject matter expert (SME) interviews.', false),
  (1404, 0, 'الاجتماع مع المدير الوظيفي لمراجعة بيان العمل (SOW).', 'Meet with the functional manager to review the statement of work (SOW).', true),
  (1404, 1, 'طلب من راعي المشروع شرح مبررات التقييم من طرف ثالث للمدير الوظيفي.', 'Ask the project sponsor to explain the rationale for third-party evaluation to the functional manager.', false),
  (1404, 2, 'تقديم تحليل التكلفة/الفائدة لتقييم الطرف الثالث للمدير الوظيفي.', 'Provide a cost/benefit analysis of third-party evaluation to the functional manager.', false),
  (1404, 3, 'شرح هدف تقييم واجهة المستخدم للمدير الوظيفي.', 'Explain the intent of the UI evaluation to the functional manager.', false),
  (1405, 0, 'مقاطعة الجدال والتأكيد بقوة على سلطته للحفاظ على النظام والتحكم في الاجتماع.', 'Interrupt the argument and firmly assert their authority to maintain order and control over the meeting.', false),
  (1405, 1, 'تيسير مناقشة منظمة لفهم وجهة نظر كل صاحب مصلحة وإيجاد أرضية مشتركة.', 'Facilitate a structured discussion to understand each stakeholder''s perspective and find common ground.', true),
  (1405, 2, 'إنهاء الاجتماع مبكرًا للسماح لأصحاب المصلحة بتهدئة أعصابهم وإعادة جدولته لاحقًا.', 'Conclude the meeting prematurely to allow stakeholders to cool off and reschedule it at a later date.', false),
  (1405, 3, 'تجاهل الجدال والمضي قدمًا في جدول أعمال الاجتماع كما هو مخطط له، ومعالجة النزاع لاحقًا.', 'Ignore the argument and proceed with the meeting''s agenda as planned, addressing the conflict afterward.', false),
  (1406, 0, 'إبلاغ المورد بأنه تم الدفع مرة واحدة فقط، والبدء في عملية إغلاق المشروع، والبدء في العمل على المشروع الجديد.', 'Inform the supplier that payment was made only once, begin the close project process, and begin work on the new project.', false),
  (1406, 1, 'تأجيل إغلاق المشروع حتى تتمكن إدارة الحسابات الدائنة من توثيق أن الفاتورة تم دفعها بشكل صحيح.', 'Postpone project closure until the accounts payable department can document that the invoice was paid correctly.', true),
  (1406, 2, 'إكمال جميع وثائق المشروع النهائية، وتأجيل العمل على المشروع الجديد، وتحديث الوثائق بعد التحقق من الدفع.', 'Complete all final project documents, delay work on the new project, and update the documents after payment is verified.', false),
  (1406, 3, 'الاجتماع مع راعي المشروع الحالي للحصول على الموافقة لبدء المشروع الجديد قبل إغلاق المشروع الحالي.', 'Meet with the sponsor of the existing project to obtain approval to begin the new project before the existing project is closed.', false),
  (1407, 0, 'العمليات', 'Processes', false),
  (1407, 1, 'القيمة', 'Value', true),
  (1407, 2, 'النتائج', 'Artifacts', false),
  (1407, 3, 'القوالب', 'Templates', false),
  (1408, 0, 'في نظام إدارة التهيئة', 'In the configuration management system', true),
  (1408, 1, 'في قاعدة المعرفة للشركة', 'In the corporate knowledge base', false),
  (1408, 2, 'في نظام إدارة التغيير', 'In the change management system', false),
  (1408, 3, 'في تقارير حالة المشروع', 'In the project status reports', false),
  (1409, 0, 'مخطط المهام المنجزة', 'Burnup chart', false),
  (1409, 1, 'خريطة القصة', 'Story map', true),
  (1409, 2, 'مخطط التدفق التراكمي (CFD)', 'Cumulative flow diagram (CFD)', false),
  (1409, 3, 'مخطط المهام غير المنجزة', 'Burndown chart', false),
  (1410, 0, 'اكتب طلب تغيير وقدمه إلى مجلس التحكم في التغيير.', 'Write up a change request and submit it to the change control board.', false),
  (1410, 1, 'إجراء التغيير في أسرع وقت ممكن. فإنه سوف يتسبب في توفير الوقت، ولا أحد يريد أن المشروع يستغرق وقتًا أطول مما ينبغي.', 'Make the change ASAP; it’s going to save time and nobody will want the project to take longer than it should.', false),
  (1410, 2, 'معرفة تأثير ذلك على نطاق العمل والتكلفة قبل أن تكتب طلب التغيير.', 'Figure out the impact on the scope of the work and the cost before you write up the change request.', true),
  (1410, 3, 'أخبر عضو الفريق أنك كنت قد أبلغت بالفعل بالموعد النهائي للمشروع، بحيث لا يمكن إجراء أية تغييرات الآن.', 'Tell the team member that you’ve already communicated the deadline for the project, so you can’t make any changes now.', false),
  (1411, 0, 'خطة إدارة المشروع', 'Project management plan', false),
  (1411, 1, 'بيان نطاق المشروع', 'Project scope statement', false),
  (1411, 2, 'خطة إدارة التغيير', 'Change management plan', false),
  (1411, 3, 'سجل التغيير', 'Change log', true),
  (1412, 0, 'مخطط التدفق التراكمي (CFD)', 'Cumulative flow diagram (CFD)', true),
  (1412, 1, 'خطة الإصدار', 'Release plan', false),
  (1412, 2, 'مخطط المهام المنجزة', 'Burnup chart', false),
  (1412, 3, 'خطة التكرار', 'Iteration plan', false),
  (1413, 0, 'مخطط الطاقة الإنتاجية', 'Throughput chart', false),
  (1413, 1, 'قصة المستخدم', 'User story', false),
  (1413, 2, 'حالة الاستخدام', 'Use case', true),
  (1413, 3, 'خريطة القصة', 'Story map', false),
  (1414, 0, 'إجراء تصحيحي', 'Corrective action', false),
  (1414, 1, 'إجراء وقائي', 'Preventive action', false),
  (1414, 2, 'إصلاح العيوب', 'Defect repair', true),
  (1414, 3, 'تحديثات', 'Updates', false),
  (1415, 0, 'ما سيتم شراؤه', 'What to purchase', true),
  (1415, 1, 'تقدير تقريبي للافتراضات', 'Rough order of magnitude estimates', false),
  (1415, 2, 'الافتراضات والقيود', 'Constraints and assumptions', false),
  (1415, 3, 'تنظيم المشروع الأولي', 'Initial project organization', false),
  (1416, 0, 'خطة إدارة التواصل', 'Communication management plan', true),
  (1416, 1, 'خطة إدارة المخاطر', 'Risk management plan', false),
  (1416, 2, 'سجل المخاطر', 'Risk register', false),
  (1416, 3, 'مصفوفة تحديد المسؤوليات RAM', 'Responsibility assignment matrix (RAM)', false),
  (1417, 0, 'مخاطرة قد حدثت.', 'A project risk that has occurred.', false),
  (1417, 1, 'مخاطرة سلبية قد حدثت.', 'A negative project risk that has occurred.', true),
  (1417, 2, 'مخاطرة سلبية قد تحدث.', 'A negative risk that may occur.', false),
  (1417, 3, 'مخاطرة إيجابية قد حدثت.', 'A positive risk that has occurred.', false),
  (1418, 0, 'ميثاق المشروع', 'Project charter', false),
  (1418, 1, 'خطة إدارة المشروع', 'Project management plan', false),
  (1418, 2, 'العقود', 'Contracts', true),
  (1418, 3, 'خطة إدارة المنافع', 'Benefits management plan', false),
  (1419, 0, 'حاول تقليل عدد العناصر التي تحتاج إلى موافقة قدر الإمكان.', 'Try to reduce the items that need approval as much as possible.', false),
  (1419, 1, 'يجب على أعضاء الفريق الاستمرار في تذكير المعنيين بالموافقة حتى يتم حل التبعيات (الاعتماديات) الخاصة بهم.', 'Team members should keep reminding the approvers till their dependencies are cleared out.', false),
  (1419, 2, 'ضع في الحساب التأخيرات بسبب الاختناقات في احتياطي الطوارئ.', 'Account for the delays due to bottlenecks in the contingency reserve.', false),
  (1419, 3, 'قم بتفصيل العمليات الحالية من خلال تبسيط قرارات الموافقة من خلال عدد أقل من الأشخاص المخولين لاتخاذ قرارات في حدود قيم معينة.', 'Tailor the existing processes by streamlining approval decisions through fewer people authorized to make decisions up to certain value thresholds.', true),
  (1420, 0, 'المزيد من التفصيل للتوجيه والتدريب.', 'More tailoring to guidance and training.', true),
  (1420, 1, 'استبدال هؤلاء الأعضاء بآخرين أكثر مهارة.', 'Replace those team members with more skilled ones.', false),
  (1420, 2, 'ناقش هذه المشكلة مع المدرين الوظيفيين لهؤلاء الأعضاء.', 'Discuss this issue with the functional managers of those team members.', false),
  (1420, 3, 'تقليل اسناد المهام لهم وأضف هذه الأعمال إلى الأعضاء الأكثر مهارة.', 'Reduce their work assignment and add this work to the skilled members.', false),
  (1421, 0, 'يمكن اعتبار ميثاق المشروع كعقد لأنه يؤسس ويمنح الصلاحية رسميًا بوجود المشروع.', 'A project charter can be considered as a contract because it initiates and authorizes a project.', false),
  (1421, 1, 'ميثاق المشروع يعتبر كافٍ عند تنفيذ مشروع لعميل خارجي.', 'A project charter is sufficient when performing a project for an external customer.', false),
  (1421, 2, 'العقد يصدر عن طريق راعي أو بادئ المشروع ليمنح الصلاحية رسميًا بوجود المشروع.', 'A contract is issued by the project initiator or sponsor to formally authorize a project.', false),
  (1421, 3, 'يؤسس ميثاق المشروع شراكة بين المؤسسات القائمة بالتنفيذ وصاحبة الطلب. في حالة المشاريع الخارجية يكون العقد الرسمي هو الطريقة المفضلة لإبرام الاتفاق.', 'A project charter establishes a partnership between the performing and requesting organization. For external project a formal contract is the preferred way to establish an agreement.', true),
  (1422, 0, 'خارطة الطريق', 'Roadmap', false),
  (1422, 1, 'مخطط المهام غير المنجزة', 'Burndown chart', false),
  (1422, 2, 'مخطط المهام المنجزة', 'Burnup chart', false),
  (1422, 3, 'مخطط التدفق التراكمي (CFD)', 'Cumulative flow diagram (CFD)', true),
  (1423, 0, 'مصفوفة تتبع المتطلبات', 'Requirements traceability matrix', false),
  (1423, 1, 'سجل الافتراضات', 'Assumptions log', true),
  (1423, 2, 'خطة إدارة النطاق', 'Scope management plan', false),
  (1423, 3, 'خطة إدارة المتطلبات', 'Requirements management plan', false),
  (1424, 0, 'ميثاق الفريق', 'Team charter', false),
  (1424, 1, 'خطة الإصدار', 'Release plan', false),
  (1424, 2, 'بيان رؤية المشروع', 'Project vision statement', true),
  (1424, 3, 'سجل الأعمال المعدل حسب المخاطر', 'Risk-adjusted backlog', false),
  (1425, 0, '5', '5', false),
  (1425, 1, '1', '1', true),
  (1425, 2, 'إما 1 أو 5 حسب تفضيل مالك المنتج.', 'Either 1 or 5 according to the product owner preference.', false),
  (1425, 3, 'إما 1 أو 5 حسب تفضيل مدير إسكرام.', 'Either 1 or 5 according to the scrum master preference.', false),
  (1426, 0, 'خريطة طريق المنتج - السمة - خطة الإصدار - خطة التكرار', 'Product roadmap - Feature - Release plan - Iteration plan', false),
  (1426, 1, 'السمة - خريطة طريق المنتج - خطة الإصدار - خطة التكرار', 'Feature - Product roadmap - Release plan - Iteration plan', false),
  (1426, 2, 'خريطة طريق المنتج - خطة التكرار - خطة الإصدار - السمة', 'Product roadmap - Iteration plan - Release plan - Feature', false),
  (1426, 3, 'خريطة طريق المنتج - خطة الإصدار - خطة التكرار - السمة', 'Product roadmap - Release plan - Iteration plan - Feature', true),
  (1427, 0, 'مهمة - قصة مستخدم - تكرار - إصدار', 'Task - User Story - Iteration - Release', true),
  (1427, 1, 'قصة مستخدم - مهمة - تكرار - إصدار', 'User Story - Task - Iteration - Release', false),
  (1427, 2, 'مهمة - قصة مستخدم - إصدار - تكرار', 'Task - User Story - Release - Iteration', false),
  (1427, 3, 'مهمة - تكرار - قصة مستخدم - إصدار', 'Task - Iteration - User Story - Release', false),
  (1428, 0, 'مخطط المهام غير المنجزة', 'Burndown chart', false),
  (1428, 1, 'خريطة القصة', 'Story map', false),
  (1428, 2, 'مخطط التدفق التراكمي (CFD)', 'Cumulative flow diagram (CFD)', false),
  (1428, 3, 'مخطط الطاقة الإنتاجية', 'Throughput chart', true),
  (1429, 0, 'خريطة القصة', 'Story map', false),
  (1429, 1, 'مخططات المهام المنجزة', 'Burndown charts', false),
  (1429, 2, 'تحديد تدفق القيمة', 'Value stream mapping', true),
  (1429, 3, 'مخططات المهام غير المنجزة', 'Burnup charts', false),
  (1430, 0, 'سجل أعمال المنتجات', 'Product backlog', false),
  (1430, 1, 'خارطة طريق المنتج', 'Product roadmap', true),
  (1430, 2, 'ميثاق المشروع الرشيق', 'Agile charter', false),
  (1430, 3, 'سجل أعمال الإطلاقات', 'Sprint backlog', false),
  (1431, 0, 'سجل الأعمال', 'Backlog', false),
  (1431, 1, 'لوحة نموذج الأعمال', 'Business model canvas', true),
  (1431, 2, 'هيكل تجزئة المنتجات', 'Product breakdown structure', false),
  (1431, 3, 'لوحات المعلومات', 'Dashboards', false),
  (1432, 0, 'سجل الأعمال', 'Backlog', true),
  (1432, 1, 'لوحة نموذج الأعمال', 'Business model canvas', false),
  (1432, 2, 'بيان رؤية المشروع', 'Project vision statement', false),
  (1432, 3, 'خارطة الطريق', 'Roadmap', false),
  (1433, 0, 'سجل الإشكالات', 'Issue log', true),
  (1433, 1, 'سجل المخاطر', 'Risk register', false),
  (1433, 2, 'تقرير المخاطر', 'Risk report', false),
  (1433, 3, 'سجل الدروس المستفادة', 'Lessons learned register', false),
  (1434, 0, 'لوحة كانبان', 'Kanban board', false),
  (1434, 1, 'شاشة المعلومات', 'Information radiators', false),
  (1434, 2, 'العروض', 'Demonstrations', true),
  (1434, 3, 'التخطيط للتكرار', 'Iteration planning', false),
  (1435, 0, 'يجب على مدير المشروع إضافة المواصفة الجديدة إلى سجل أعمال المنتج وإعطائها أولوية قصوى.', 'The project manager should add the new feature to the product backlog and make it the top priority.', false),
  (1435, 1, 'في أي مشروع رشيق، يتم الترحيب بالتغييرات في أي وقت، لذلك يجب إسناد هذه المواصفة للفريق من أجل العمل عليها.', 'On an agile project, changes are welcomed at any time, so this feature should be assigned to the team for development.', false),
  (1435, 2, 'قم بإبلاغ طلب المواصفة الجديدة إلى مالك المنتج ليتم النظر فيها خلال جلسة سجل الأعمال التالية.', 'Communicate the new feature request to the product owner to be considered in the next backlog session.', false),
  (1435, 3, 'أخبر الراعي بالتحدث مع مالك المنتج حول هذه المواصفة، وتذكيره بأن مالك المنتج لديه سلطة تحديد أولويات المواصفات.', 'Tell the sponsor to talk with the product owner about this feature, reminding them that the product owner has authority to prioritize features.', true),
  (1436, 0, 'يجب أن تقوم بتحديث خطة إدارة المشروع ومستندات المشروع لتعكس التغيير.', 'She should update the project management plan and project documents to reflect the change.', false),
  (1436, 1, 'يجب عليها إبلاغ مجلس التحكم في التغيير بموافقة أو رفض طلب التغيير', 'She should inform the CCB whether or not to approve the change.', false),
  (1436, 2, 'المعنيين في مجلس التحكم في التغيير يستخدمون استشارة الخبراء لتقييم التغيير المطلوب للموافقة عليه.', 'Stakeholders on the CCB use expert judgment to evaluate the requested change for approval.', true),
  (1436, 3, 'يجب أن تجتمع مع الفريق لتحليل تأثير التغيير على وقت المشروع ونطاقه وتكلفته.', 'She should meet with the team to analyze the impact of the change on the project''s time, scope, and cost.', false),
  (1437, 0, 'حصر العمل قيد التنفيذ', 'Limiting WIP', false),
  (1437, 1, 'تنقيح سجل الأعمال', 'Grooming the backlog', true),
  (1437, 2, 'التحقق و التأكيد المتكرر', 'Frequent verification and validation', false),
  (1437, 3, 'تقليل الهدر', 'Minimizing waste', false),
  (1438, 0, '(1) و (3)', '(1) and (3)', false),
  (1438, 1, '(2) و (5)', '(2) and (5)', false),
  (1438, 2, '(4) و (5)', '(4) and (5)', true),
  (1438, 3, 'كل ما سبق.', 'All of them.', false),
  (1439, 0, 'تقييم تأثير التغيير.', 'Evaluate impacts.', false),
  (1439, 1, 'طلب إشراك مجلس التحكم في التغيير.', 'Request change control board involvement.', false),
  (1439, 2, 'منع السبب الجذري للتغيير.', 'Prevent the root cause of change.', false),
  (1439, 3, 'مراجعة خطة ادارة المشروع و/أو وثائق المشروع.', 'Revise the project management plan and/or project documents.', true),
  (1440, 0, 'توبيخ عضو الفريق وتحقق من الموارد المتاحة للنظر في استبداله.', 'Reprimand the team member and check available resources to consider replacing him.', false),
  (1440, 1, 'إرسال طلب تغيير ليعكس المتطلبات الجديدة.', 'Submit a change request to reflect new requirements.', true),
  (1440, 2, 'إبلاغ العميل أن جميع المعلومات المتعلقة تقدم المشروع يجب أن يتم إبلاغها من قِبل مدير المشروع فقط.', 'Inform the customer that all information related to project progress should be communicated by the project manager only.', false),
  (1440, 3, 'اطلب من أعضاء الفريق عدم التحدث إلى العميل مرة أخرى ، ما لم يتم الحصول على إذن من مدير المشروع.', 'Ask team members not to talk to the customer again, unless permission is taken from the project manager.', false),
  (1441, 0, 'لا تفعل شيئاً ، فقد تمت الموافقة على الخطة بالفعل بما في ذلك التصميم القديم.', 'Do nothing, the plan has already been approved including the old design.', false),
  (1441, 1, 'اطلب من المهندس تقديم طلب تغيير.', 'Ask the engineer to submit a change request.', true),
  (1441, 2, 'اطلب من المهندس تقييم التأثيرات على قيود المشروع الأخرى.', 'Ask the engineer to evaluate the impacts on other project constraints.', false),
  (1441, 3, 'عقد لقاء مع المهندس ومصمم النظام القديم لاكتشاف الفروق.', 'Hold a meeting with the engineer and the designer of the old system to discover variances.', false),
  (1442, 0, 'تحديث خطة إدارة المشروع لتعكس التغيير.', 'Update the project management plan to reflect the change.', false),
  (1442, 1, 'الدعوة لعقد اجتماع مع المعنيين بالمشروع لمعرفة ما إذا كان سيتم إجراء التغيير من عدمه.', 'Call for a meeting with the stakeholders to figure out whether or not to make the change.', false),
  (1442, 2, 'توثيق التغيير وتأثيره، وتقديمه إلى مجلس التحكم في التغيير.', 'Document the change and its impact, and submit it to the change control board.', true),
  (1442, 3, 'إرشاد مجلس التحكم في التغيير للموافقة على التغيير حتى لا يسبب مشاكل للمنتج.', 'Instruct the change control board to approve the change in order not to cause problems to the product.', false),
  (1443, 0, 'كتابة طلب التغيير و تقديمه الى مجلس التحكم في التغيير.', 'Write up a change request and submit it to the change control board.', false),
  (1443, 1, 'إجراء التغيير. فأنه سيقوم بتوفير الوقت ولا أحد يريد أن يستغرق المشروع وقتاً أطول مما ينبغي.', 'Make the change; it’s going to save time and nobody will want the project to take longer than it should.', false),
  (1443, 2, 'معرفة تأثير التغيير على نطاق العمل والتكلفة قبل أن نكتب طلب التغيير.', 'Figure out the impact on the scope of the work and the cost before you write up the change request.', true),
  (1443, 3, 'أخبر عضو الفريق أنك قد أبلغت بالفعل بالموعد النهائي لهذا المشروع، لذلك لا يمكن إجراء أية تغييرات الآن.', 'Tell the team member that you’ve already communicated the deadline for the project, so you can’t make any changes now.', false),
  (1444, 0, 'حساب المخاطر المصاحبة للتغيير.', 'Calculate the risks associated with the change.', true),
  (1444, 1, 'إجراء التغيير بما أنه تم تحديد خصائصه.', 'Make the change as its specifications are determined.', false),
  (1444, 2, 'ابحث عن التغييرات الأخرى من العملاء قبل إجراء التغيير.', 'Look for other changes from the customer before making the change.', false),
  (1444, 3, 'ارسل التغيير الى مجلس التحكم في التغيير.', 'Send the change request to the change control board.', false),
  (1445, 0, 'يجب أن يذكر مدير المشروع بأن تحليل التكلفة و المنفعة للمشروع قد تم أثناء التخطيط للمشروع.', 'He should remind the project manager that the cost-benefit analysis for the project was done during project planning.', false),
  (1445, 1, 'يجب على مدير المشروع إعداد هذا التقرير بنفسه، فهذا جزء من وظيفته.', 'The project manager should do this report himself as a part of his job.', false),
  (1445, 2, 'يجب على عضو الفريق أن يفعل ما طلب منه، فهذا النوع من المعلومات يجب أن يقدم لراعي المشروع لإجراء التغيير.', 'The team member should do what was asked because this sort of information must be given to the project sponsor to make the change.', false),
  (1445, 3, 'يجب أن يكون مدير المشروع قادراً على الموازنة بين منفعة التغيير مقابل التكاليف ومقارنتة مع غيره من التغييرات المحتملة. يجب على عضو الفريق أن يفعل ما طلب منه.', 'A project manager must be able to weigh the benefits of the change versus the costs and compare them to other possible changes. The team member should do what was asked.', true),
  (1446, 0, 'اجعل راعي المشروع يجتمع مع العميل ليشرح له الموقف.', 'Have the project sponsor meet with the customer to explain the situation.', false),
  (1446, 1, 'عقد اجتماع مع العميل لمعرفة لماذا يطلب التغيير.', 'Hold a meeting with the customer to know why he required the change.', true),
  (1446, 2, 'لا تفعل شيئاً.', 'Do nothing.', false),
  (1446, 3, 'إبلاغ العميل أن الوقت و التكلفة المضافة هي أقل بكثير من الفوائد الناتجة عن التغيير.', 'Tell the customer that the added time and cost are much less than the benefits resulting from the change.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1447, 0, 'تقديم طلب تغيير لإضافة المتطلبات المفقودة لنطاق المشروع.', 'Submit a change request to add the missed requirements to the project scope.', true),
  (1447, 1, 'لا تفعل شيئاً، هذه المتطلبات ليست جزءاً من نطاق المشروع.', 'Do nothing, these requirements are not a part of the project scope.', false),
  (1447, 2, 'هذا عبارة عن زحف للنطاق. هذه المتطلبات يجب تجاهلها.', 'This is scope creep; these requirements must be ignored.', false),
  (1447, 3, 'طلب تمويل ووقت إضافيين لتنفيذ هذه المتطلبات', 'Request additional funds and time to implement these requirements.', false),
  (1448, 0, 'إنشاء طلب تغيير.', 'Create a change request.', false),
  (1448, 1, 'تقييم آثار استخدام النوع الجديد.', 'Evaluate impacts of using the new type.', false),
  (1448, 2, 'تغيير الخط المرجعي للنطاق و التكلفة لاستخدام النوع الجديد', 'Change the scope baseline and cost baseline to use the new type.', true),
  (1448, 3, 'استشارة مجلس التحكم في التغيير.', 'Consult the Change Control Board.', false),
  (1449, 0, 'التغييرات عموماً تكون غير متوقعة، وبالتالي فالتخطيط لإدارة التغيير غير منطقي.', 'Changes are generally not predictable, therefore planning for change management cannot be reasonable.', false),
  (1449, 1, 'التخطيط لإدارة التغيير يجب أن يتم أثناء تطبيق العمليات الأخرى للتحكم في التغيير.', 'Planning for change management should be done while the various change control processes are being applied.', false),
  (1449, 2, 'يمكن التخطيط لإدارة التغيير في مجموعة من خطط الإدارة أو خطة محددة لإدارة التغيير.', 'Change management can be planned in a set of management plans or a specific change management plan.', true),
  (1449, 3, 'التغييرات هي علامة على سوء التخطيط. ينبغي للمرء تجنب التغييرات خلال المشروع، وبالتالي القضاء على الحاجة إلى إدارتها.', 'Changes are a sign of poor planning. One should avoid changes during a project, thus eliminating the need to manage them.', false),
  (1450, 0, 'يجب على أصحاب الأعمال و المطورين العمل معاً يومياً على مدار المشروع.', 'Business people and developers must work together daily throughout the project.', false),
  (1450, 1, 'الانتباه المستمر للتميز الفني و التصميم الجيد يحسن من الرشاقة.', 'Continuous attention to technical excellence and good design enhances agility.', false),
  (1450, 2, 'الترحيب بالمتطلبات المتغيرة ، حتى لو كان في مرحلة متأخرة من التطوير. تعمل عمليات الأسلوب الرشيق على تسخير التغيير للمنفعة التنافسية للعميل.', 'Welcome changing requirements, even late in development. Agile processes harness change for the customer’s competitive advantage.', true),
  (1450, 3, 'تدعم عمليات الأسلوب الرشيق Agile التطوير المستدام. يجب أن يكون الرعاة و المطورين و المستخدمين قادرين على المحافظة على خطوّة منتظمة دون أجل محدد.', 'Agile processes promote sustainable development. The sponsors, developers, and users should be able to maintain a constant pace indefinitely.', false),
  (1451, 0, 'يجب على مدير المشروع إضافة المواصفة الجديدة إلى سجل أعمال المنتج وإعطائها أولوية قصوى.', 'The project manager should add the new feature to the product backlog and make it the top priority.', false),
  (1451, 1, 'في أي مشروع رشيق، يتم الترحيب بالتغييرات في أي وقت، لذلك يجب إسناد هذه المواصفة للفريق من أجل العمل عليها.', 'On an agile project, changes are welcomed at any time, so this feature should be assigned to the team for development.', false),
  (1451, 2, 'قم بإبلاغ طلب المواصفة الجديدة إلى مالك المنتج ليتم النظر فيها خلال جلسة سجل الأعمال التالية.', 'Communicate the new feature request to the product owner to be considered in the next backlog session.', false),
  (1451, 3, 'أخبر الراعي بالتحدث مع مالك المنتج حول هذه المواصفة، و تذكيره بأن مالك المنتج لديه سلطة تحديد أولويات المواصفات.', 'Tell the sponsor to talk with the product owner about this feature, reminding them that the product owner has authority to prioritize features.', true),
  (1452, 0, 'الطلب من الراعي الموافقة على التغيير.', 'Ask the sponsor to approve the change.', false),
  (1452, 1, 'تقييم الآثار المترتبة على القيود الأخرى مثل الوقت والتكلفة والموارد.', 'Evaluate impacts on other constraints like time, cost, and resources.', false),
  (1452, 2, 'تعديل خطة إدارة المشروع ومستندات المشروع.', 'Revise the project management plan and project documents.', true),
  (1452, 3, 'إرسال طلب التغيير إلى مجلس التحكم في التغيير.', 'Send the change request to the Change Control Board.', false),
  (1453, 0, 'عدم وجود بيان نطاق مشروع واضح.', 'Lack of a clear project scope statement.', false),
  (1453, 1, 'عدم وجود خطة لإدارة التغيير.', 'Lack of a change management plan.', true),
  (1453, 2, 'عدم وجود خطة لإدارة التواصل.', 'Lack of a communications management plan.', false),
  (1453, 3, 'علاقات جيدة بين أعضاء الفريق.', 'Good team relations.', false),
  (1454, 0, 'العمل مع المعنيين لمعرفة كيفية خفض تكلفة التغيير.', 'Work with the stakeholder to figure out how to reduce the cost of the change.', false),
  (1454, 1, 'طلب موافقة من الرئيس التنفيذي.', 'Request approval from the CEO.', true),
  (1454, 2, 'رفض التغيير لأنه أكثر من 2% من الميزانية.', 'Refuse the change because it is over 2% of the budget.', false),
  (1454, 3, 'توثيق طلب التغيير، إذ لابد من توثيق جميع التغيرات.', 'Document the change request, since all changes must be documented.', false),
  (1455, 0, 'حصر العمل قيد التنفيذ', 'Limiting WIP', false),
  (1455, 1, 'تنقيح سجل الأعمال', 'Grooming the backlog', true),
  (1455, 2, 'التحقق و التأكيد المتكرر', 'Frequent verification and validation', false),
  (1455, 3, 'تقليل الهدر', 'Minimizing waste', false),
  (1456, 0, 'لجنة التحكم في التغيير', 'Change Control Board', false),
  (1456, 1, 'تسيب النطاق', 'Scope creep', false),
  (1456, 2, 'تباين النطاق', 'Scope variance', false),
  (1456, 3, 'تنقيح سجل الأعمال', 'Backlog refinement', true),
  (1457, 0, 'البحث عن تأثير ذلك التغيير على الجودة.', 'Look for impacts to quality.', false),
  (1457, 1, 'إرسال التغيير إلى مجلس التحكم لتغيير للموافقة عليه.', 'Submit the change to the Change Control Board for approval.', false),
  (1457, 2, 'البحث عن التغييرات الأخرى من المعنيين.', 'Look for other changes from the stakeholders.', false),
  (1457, 3, 'إبلاغ المعنيين المتأثرين بالتغيير.', 'Notify stakeholders affected by the change.', true),
  (1458, 0, 'يجب على الفريق تحليل تأثير ميزته الجديدة.', 'The team should analyze the impact of his new feature.', false),
  (1458, 1, 'يجب على الفريق أن يطلب من المعني بالمشروع رفع طلب التغيير.', 'The team should ask the stakeholder to raise a change request.', true),
  (1458, 2, 'يجب على الفريق تصعيد المشكلة أولاً إلى راعي المشروع.', 'The team should escalate the key stakeholder first to the project sponsor.', false),
  (1458, 3, 'إنه أحد المعنيين الرئيسيين، لذا يجب تنفيذ متطلباته.', 'He is a key stakeholder, so his requirements should be applied.', false),
  (1459, 0, 'نعم، جميع الوثائق تتطلب موافقة رسمية للتغييرات من قبل الإدارة.', 'Yes. All documents require formal approval of changes by management.', false),
  (1459, 1, 'ذلك يعتمد على ما هي التغييرات التي تتم.', 'It depends on what changes are being made.', false),
  (1459, 2, 'نعم، يحتاج التغيير أن مر على مجلس التحكم في التغيير للموافقة عليه.', 'Yes. The change needs to go through the Change Control Board for approval.', false),
  (1459, 3, 'لا، هذه أجزاء من وثائق المشروع، و ليست خطة إدارة المشروع.', 'No. These are part of project documents, not the project management plan.', true),
  (1460, 0, 'إبلاغ ممثل العميل أن الإطلاق قد بدأ بالفعل ولا يمكننا إضافة متطلبات جديدة للإطلاق الحالي.', 'Inform the customer representative that the sprint has already started and we can''t add new requirements to the current sprint.', false),
  (1460, 1, 'إضافة المطلب الجديد إلى سجل أعمال المنتج، بحيث يمكن مالك المنتج منحه الأولوية القصوى لإضافته إلى الإطلاق التالي.', 'Add the new requirement to the product backlog, so that the product owner can give it the highest priority to be added to the next sprint.', false),
  (1460, 2, 'إضافة المطلب الجديد إلى سجل أعمال الإطلاق وإذا لزم الأمر، يمكن للفريق إعادة المتطلبات ذات الأولوية المنخفضة إلى سجل أعمال المنتج.', 'Add the new requirement to the sprint backlog and if needed, the team can move a low-priority requirement back to the product backlog.', false),
  (1460, 3, 'مناقشة المتطلبات الجديدة مع مالك المنتج، والذي قد يقوم بإلغاء الإطلاق الحالي.', 'Discuss the new requirement with the product owner, who may cancel the current sprint.', true),
  (1461, 0, 'يجب على مدير المشروع إضافة المواصفة الجديدة إلى سجل أعمال المنتج وإعطائها أولوية قصوى.', 'The project manager should add the new feature to the product backlog and make it the top priority.', false),
  (1461, 1, 'في أي مشروع رشيق، يتم الترحيب بالتغييرات في أي وقت، لذلك يجب إسناد هذه المواصفة للفريق من أجل العمل عليها.', 'On an agile project, changes are welcomed at any time, so this feature should be assigned to the team for development.', false),
  (1461, 2, 'قم بإبلاغ طلب المواصفة الجديدة إلى مالك المنتج ليتم النظر فيها خلال جلسة سجل الأعمال التالية.', 'Communicate the new feature request to the product owner to be considered in the next backlog session.', false),
  (1461, 3, 'أخبر الراعي بالتحدث مع مالك المنتج حول هذه المواصفة، و تذكيره بأن مالك المنتج لديه سلطة تحديد أولويات المواصفات.', 'Tell the sponsor to talk with the product owner about this feature, reminding them that the product owner has authority to prioritize features.', true),
  (1462, 0, 'يجب أن يذكر مدير المشروع بأن تحليل التكلفة و المنفعة للمشروع قد تم أثناء التخطيط للمشروع.', 'He should remind the project manager that the cost-benefit analysis for the project was done during project planning.', false),
  (1462, 1, 'يجب على مدير المشروع إعداد هذا التقرير بنفسه، فهذا جزء من وظيفته.', 'The project manager should do this report himself as a part of his job.', false),
  (1462, 2, 'يجب على عضو الفريق أن يفعل ما طُلب منه، فهذا النوع من المعلومات يجب أن يقدم لراعي المشروع لإجراء التغيير.', 'The team member should do what was asked because this sort of information must be given to the project sponsor to make the change.', false),
  (1462, 3, 'يجب أن يكون مدير المشروع قادراً على الموازنة بين منفعة التغيير مقابل التكاليف ومقارنته مع غيره من التغييرات المحتملة. يجب على عضو الفريق أن يفعل ما طُلب منه.', 'A project manager must be able to weigh the benefits of the change versus the costs and compare them to other possible changes. The team member should do what was asked.', true),
  (1463, 0, 'تقديم طلب تغيير لإضافة المتطلبات المفقودة لنطاق المشروع.', 'Submit a change request to add the missed requirements to the project scope.', true),
  (1463, 1, 'لا تفعل شيئاً، هذه المتطلبات ليست جزءاً من نطاق المشروع.', 'Do nothing, these requirements are not a part of the project scope.', false),
  (1463, 2, 'هذا عبارة عن زحف للنطاق. هذه المتطلبات يجب تجاهلها.', 'This is scope creep; these requirements must be ignored.', false),
  (1463, 3, 'طلب تمويل ووقت إضافيين لتنفيذ هذه المتطلبات', 'Request additional funds and time to implement these requirements.', false),
  (1464, 0, 'إنه تغيير بسيط . يمكنك الموافقة عليه لزيادة رضا العملاء.', 'It is a minor change; you can approve it to increase customer satisfaction.', false),
  (1464, 1, 'يمكنك استخدام الاحتياطي الإداري لاستيعاب هذا التغيير الطفيف.', 'You can use the management reserve to accommodate for this minor change.', false),
  (1464, 2, 'يمكنك استخدام التغيير المطلوب لزيادة الربح من العقد.', 'You can use the requested change to increase the profit from the contract.', false),
  (1464, 3, 'التعامل مع الطلب، وفقاً لعمليات التحكم المتكامل في التغيير الموصوفة في خطة الإدارة الخاصة بمشروعك.', 'Handle the request according to the integrated change control processes described in your project management plan.', true),
  (1465, 0, 'الطلب من الراعي الموافقة على التغيير.', 'Ask the sponsor to approve the change.', false),
  (1465, 1, 'تقييم الآثار المترتبة على القيود الأخرى مثل الوقت والتكلفة والموارد.', 'Evaluate impacts on other constraints like time, cost, and resources.', false),
  (1465, 2, 'تعديل خطة إدارة المشروع ومستندات المشروع.', 'Revise the project management plan and project documents.', true),
  (1465, 3, 'إرسال طلب التغيير إلى مجلس التحكم في التغيير.', 'Send the change request to the Change Control Board.', false),
  (1466, 0, 'تنفيذ التغيير وتعديل الجدول الزمني عند الضرورة لأن هذا يدعم طلب العميل الأصلي.', 'Implement the change and adjust the schedule as necessary because this supports the customer’s original request.', false),
  (1466, 1, 'إبلاغ العميل بالتحديث المتاح وتأثيره على الجدول الزمني للمشروع والأداء الوظيفي إذا تم تنفيذ التحديث.', 'Inform the customer of the available upgrade and the impacts to the project’s timeline and functionality if the upgrade is implemented.', true),
  (1466, 2, 'الإستمرار كما كان مخططاً. العميل لم يطلب تغيير.', 'Continue as planned. Your customer didn’t request a change.', false),
  (1466, 3, 'تنفيذ التغيير على التركيبات المتبقية والاستمرار بالجدول الزمني.', 'Implement the change on the remaining installations and continue with the schedule.', false),
  (1467, 0, 'حصر العمل قيد التنفيذ', 'Limiting WIP', false),
  (1467, 1, 'تنقيح سجل الأعمال', 'Grooming the backlog', true),
  (1467, 2, 'التحقق و التأكيد المتكرر', 'Frequent verification and validation', false),
  (1467, 3, 'تقليل الهدر', 'Minimizing waste', false),
  (1468, 0, 'تحليل تأثير التغيير على العمل الذي يتعين القيام به، والجدول الزمني، والميزانية', 'Analyze the impact that the change will have on the work to be done, the schedule, and the budget.', true),
  (1468, 1, 'لا تقم بالتغيير فإن أي تأخير غير مقبول.', 'Don’t make the change because any delays are unacceptable.', false),
  (1468, 2, 'أطلب إرشاد راعي المشروع.', 'Ask the sponsor for guidance.', false),
  (1468, 3, 'إجراء التغيير على خطة المشروع والخطط الفرعية، وأطلب من الفريق تنفيذ التغيير.', 'Make the change as soon as possible to the project plan and subsidiary plans, and ask the team to implement the change.', false),
  (1469, 0, 'البحث عن تأثير ذلك التغيير على الجودة.', 'Look for impacts to quality.', false),
  (1469, 1, 'إرسال التغيير إلى مجلس التحكم لتغيير للموافقة عليه.', 'Submit the change to the Change Control Board for approval.', false),
  (1469, 2, 'البحث عن التغييرات الأخرى من المعنيين.', 'Look for other changes from the stakeholders.', false),
  (1469, 3, 'إبلاغ المعنيين المتأثرين بالتغيير.', 'Notify stakeholders affected by the change.', true),
  (1470, 0, 'لا تفعل شيئًا، فقد تمت الموافقة على الخطة بالفعل بما في ذلك التصميم القديم.', 'Do nothing, the plan has already been approved including the old design.', false),
  (1470, 1, 'اطلب من المهندس تقديم طلب تغيير.', 'Ask the engineer to submit a change request.', true),
  (1470, 2, 'اطلب من المهندس تقييم التأثيرات على قيود المشروع الأخرى.', 'Ask the engineer to evaluate the impacts on other project constraints.', false),
  (1470, 3, 'عقد لقاء مع المهندس ومصمم النظام القديم لاكتشاف الفروق.', 'Hold a meeting with the engineer and the designer of the old system to discover variances.', false),
  (1471, 0, 'التغييرات عموماً تكون غير متوقعة، وبالتالي فالتخطيط لإدارة التغيير غير منطقي.', 'Changes are generally not predictable, therefore planning for change management cannot be reasonable.', false),
  (1471, 1, 'التخطيط لإدارة التغيير يجب أن يتم أثناء تطبيق العمليات الأخرى للتحكم في التغيير.', 'Planning for change management should be done while the various change control processes are being applied.', false),
  (1471, 2, 'يمكن التخطيط لإدارة التغيير في مجموعة من خطط الإدارة أو خطة محددة لإدارة التغيير.', 'Change management can be planned in a set of management plans or a specific change management plan.', true),
  (1471, 3, 'التغييرات هي علامة سوء التخطيط. ينبغي للمرء تجنب التغيرات خلال المشروع، وبالتالي القضاء على الحاجة إلى إدارتها.', 'Changes are a sign of poor planning. One should avoid changes during a project, thus eliminating the need to manage them.', false),
  (1472, 0, '(1) و (3)', '(1) and (3)', false),
  (1472, 1, '(2) و (5)', '(2) and (5)', false),
  (1472, 2, '(4) و (5)', '(4) and (5)', true),
  (1472, 3, 'كل ما سبق.', 'All of them.', false),
  (1473, 0, 'لا تحتاج المشاريع الرشيقة إلى تخطيط مكثف، لذا تعد طلبات التغيير أكثر أهمية لأنها تمثل مدخلات العملاء.', 'Agile projects don''t need intense planning, so change requests are more important as they represent customer inputs.', false),
  (1473, 1, 'يلتزم فريق المشروع بالخطة الموضوعة في البداية، ولكن يمكن الموافقة أو رفض أي طلب تغيير اللحظة المشروع.', 'The project team commits to the initially developed plan, however any change request to the project plan can be approved or rejected.', false),
  (1473, 2, 'في المشاريع الرشيقة، يتم التخطيط الأولي عندما نعرف أقل ما يمكن عن المشروع وقد يتم تحديث هذه الخطة مع تقدم العمل.', 'In agile projects, initial planning is done when we know the least about the project and this plan may be updated as the work progresses.', true),
  (1473, 3, 'في المشاريع الرشيقة، يمضي فريق المشروع وقتاً أقل في التخطيط والموافقة على طلبات التغيير أكثر من المشاريع التقليدية.', 'In agile projects, the project team spends less time in planning and approves more change requests than traditional projects.', false),
  (1474, 0, 'القيام بتسليم المنتج وبدء إجراءات إغلاق المشروع.', 'Handover the product and start project closure procedures.', false),
  (1474, 1, 'تقييم آثار إضافة المتطلب الجديد على المشروع.', 'Assess the impacts of adding the new requirement on the project.', true),
  (1474, 2, 'إبلاغ راعي المشروع أنه لا يمكن إضافة متطلب جديد قبل التسليم مباشرة.', 'Inform the project sponsor that it is not possible to add a new requirement just before handover.', false),
  (1474, 3, 'عقد اجتماعاً مع الفريق ومناقشة جميع الخيارات المتاحة.', 'Hold a meeting with the team and discuss all available options.', false),
  (1475, 0, 'كتابة طلب التغيير و تقديمه الى مجلس التحكم في التغيير.', 'Write up a change request and submit it to the Change Control Board.', false),
  (1475, 1, 'إجراء التغيير. فإنه سيقوم بتوفير الوقت ولا أحد يريد أن يستغرق المشروع وقتاً أطول مما ينبغي.', 'Make the change; it’s going to save time and nobody will want the project to take longer than it should.', false),
  (1475, 2, 'معرفة تأثير التغيير على نطاق العمل والتكلفة قبل أن نكتب طلب التغيير.', 'Figure out the impact on the scope of the work and the cost before you write up the change request.', true),
  (1475, 3, 'أخبر عضو الفريق أنك قد أبلغت بالفعل بالموعد النهائي لهذا المشروع، لذلك لا يمكن إجراء أية تغييرات الآن.', 'Tell the team member that you’ve already communicated the deadline for the project, so you can’t make any changes now.', false),
  (1476, 0, 'مخطط المزاجية', 'Mood Chart', false),
  (1476, 1, 'صافي نقاط المؤيدين NPS', 'NPS', true),
  (1476, 2, 'معدل الدوران الوظيفي', 'Turnover', false),
  (1476, 3, 'صافي القيمة الحالية', 'NPV', false),
  (1477, 0, 'إنشاء بيان نطاق المشروع', 'Create a project scope statement', false),
  (1477, 1, 'تحديد أي من المعنيين بالمشروع ساهم في نطاق المشروع', 'Confirm which stakeholders had input to the scope', true),
  (1477, 2, 'بدء العمل في خطة إدارة المشروع', 'Begin working on a project management plan', false),
  (1477, 3, 'البدء في جمع المتطلبات من المعنيين بالمشروع', 'Start collecting requirements from stakeholders', false),
  (1478, 0, 'يجب على أصحاب الأعمال و المطورين العمل معاً يومياً على مدار المشروع.', 'Business people and developers must work together daily throughout the project.', true),
  (1478, 1, 'الترحيب بالمتطلبات المتغيرة ، حتى لو كان في مرحلة متأخرة من التطوير. تعمل عمليات الأسلوب الرشيق على تسخير التغيير لمنفعة التنافسية للعميل.', 'Welcome changing requirements, even late in development. Agile processes harness change for the customer’s competitive advantage.', false),
  (1478, 2, 'البساطة - فن تعظيم العمل غير المنجز - أمر أساسي.', 'Simplicity—the art of maximizing the amount of work not done—is essential.', false),
  (1478, 3, 'تسليم برمجيات فعالة بصورة متكررة في فترة تتراوح بين أسبوعين إلى شهرين مع تفضيل النطاق الزمني الأقصر.', 'Deliver working software frequently, from a couple of weeks to a couple of months, with a preference to the shorter timescale.', false),
  (1479, 0, 'الاستقلالية', 'Autonomy', false),
  (1479, 1, 'الإتقان', 'Mastery', false),
  (1479, 2, 'الغاية', 'Purpose', false),
  (1479, 3, 'المكافآت', 'Rewards', true),
  (1480, 0, 'اجتماع الوقوف اليومي', 'Daily Standups', true),
  (1480, 1, 'التطوير القائم على الاختبار', 'Test-Driven Development (TDD)', false),
  (1480, 2, 'الفرق ذاتية التنظيم', 'Self-organizing teams', false),
  (1480, 3, 'فترة زمنية محددة', 'Timeboxing', false),
  (1481, 0, 'مؤتمرات الفيديو، لأنها تتيح للمعنيين الموزعين التواصل كما لو كانوا متواجدين في نفس الموقع.', 'Videoconferencing, because it allows distributed stakeholders to communicate as if they are co-located.', false),
  (1481, 1, 'وجهاً لوجه، لأنه يُستخدم لنقل معظم المعلومات في فترة زمنية معينة.', 'Face-to-face, because it is used to transfer the most information in a given period of time.', true),
  (1481, 2, 'المراسلة الفورية، لأنها تتيح للمعنيين توصيل المعلومات العاجلة على الفور بغض النظر عن وجودهم في نفس الموقع أم لا.', 'Instant messaging, because it allows stakeholders to communicate urgent information immediately regardless they are co-located or not.', false),
  (1481, 3, 'رسائل البريد الإلكتروني، لأنه يحتفظ بسجل لجميع الرسائل المرسلة والمستلمة إذا كانت هناك حاجة إليها لاحقاً في المشروع.', 'Emails, because it keeps record of all sent and received messages if they are needed later in the project.', false),
  (1482, 0, 'الهاتف، المراسلات الفورية، التسجيل الصوتي، المراسلات الورقية.', 'Phone, instant messaging, audio recording, paper', true),
  (1482, 1, 'وجهاً لوجه، الهاتف، مؤتمرات الفيديو، المراسلات الفورية.', 'Face-to-face, phone, video recording, instant messaging', false),
  (1482, 2, 'وجهاً لوجه، تسجيلات الفيديو، المراسلات الورقية، البريد الإلكتروني', 'Face-to-face, video recording, paper, email', false),
  (1482, 3, 'وجهاً لوجه، التسجيل الصوتي، الهاتف، المراسلات الورقية.', 'Face-to-face, audio recording, phone, paper', false),
  (1483, 0, 'تحديد حالة المشروع', 'Determine project status', false),
  (1483, 1, 'عمل أنشطة بناء الفريق', 'Make team building activities', false),
  (1483, 2, 'عمل تغييرات المشروع', 'Make changes to the project', false),
  (1483, 3, 'التواصل', 'Communicate', true),
  (1484, 0, 'تقارير سير العمل تعرض معلومات عن الإتجاهات.', 'Progress reports supply information about trends.', false),
  (1484, 1, 'تقارير سير العمل ليست مفصلة بالشكل الكافي.', 'Progress reports are not detailed enough.', false),
  (1484, 2, 'تقارير سير العمل تتطلب قضاء وقت في جمع المعلومات من المعنيين.', 'Progress reports require expending time gathering information from stakeholders.', false),
  (1484, 3, 'تقارير سير العمل عامةً تعرض المشاكل بعد حدوثها.', 'Progress reports generally show problems after they have occurred.', true),
  (1485, 0, 'أرِه ميثاق المشروع بحيث يعلم أنك مسؤول عن المشروع.', 'Show him the project charter so that he knows that you are in charge of the project.', false),
  (1485, 1, 'العمل معه لفهم المتطلبات الحالية وتحديد ما إذا كان لديه متطلبات أخرى جديدة لتضاف إلى المشروع.', 'Work with him to understand the current requirements and determine if he has new ones to add to the project.', true),
  (1485, 2, 'لا تفعل شيء.', 'Do nothing.', false),
  (1485, 3, 'قم بإضافته الى خطة إدارة التواصل.', 'Add him to the communications management plan.', false),
  (1486, 0, 'غير الرسمية المكتوبة', 'Informal written', false),
  (1486, 1, 'غير الرسمية الشفهية', 'Informal verbal', false),
  (1486, 2, 'الرسمية المكتوبة', 'Formal written', true),
  (1486, 3, 'الرسمية الشفهية', 'Formal verbal', false),
  (1487, 0, 'الاتصال بالشرطة.', 'Call the police.', false),
  (1487, 1, 'إضافة مخاطرة إلى سجل المخاطر لمقاومة الجيران وتوثيق تأثيرها السلبي على تقدم المشروع.', 'Add a risk to the risk register for neighbours resistance and document its negative impact on the project progress.', false),
  (1487, 2, 'تجاهل متطلبات المعنيين والاستمرار في بناء المصنع.', 'Disregard the stakeholders requirements and continue building the factory.', false),
  (1487, 3, 'الاجتماع مع الجيران وشرح أهداف المشروع لهم ومناقشة متطلباتهم.', 'Meet with the neighbours, explain the project objectives and discuss their requirements.', true),
  (1488, 0, 'إنهم يساعدون على تحديد قيود المشروع و مخرجات المنتج.', 'They help to determine project constraints and product deliverables.', true),
  (1488, 1, 'إنهم يساعدون على تحديد مخرجات المشروع والجدول الزمني للمشروع.', 'They help determine the project deliverables and project schedule.', false),
  (1488, 2, 'إنهم يساعدون على تحديد افتراضات المشروع وتحديد احتياجات المشروع من الموارد.', 'They help to provide project assumptions and determine the resources needs on the project.', false),
  (1488, 3, 'إنهم يقومون بإنشاء خطة إدارة المشروع والموافقة على ميثاق المشروع.', 'They create the project management plan and approve the project charter.', false),
  (1489, 0, 'إلى أعلى', 'Upward', false),
  (1489, 1, 'إلى أسفل', 'Downward', false),
  (1489, 2, 'إلى الخارج', 'Outward', false),
  (1489, 3, 'إلى الجانب', 'Sideward', true),
  (1490, 0, 'النظرية X', 'Theory X', false),
  (1490, 1, 'النظرية Y', 'Theory Y', false),
  (1490, 2, 'النظرية Z', 'Theory Z', true),
  (1490, 3, 'نظرية الاحتياجات', 'Theory of needs', false),
  (1491, 0, 'خطة مشاركة المعنيين', 'Stakeholder engagement plan', false),
  (1491, 1, 'خطة إدارة التواصل', 'Communication management plan', true),
  (1491, 2, 'سجل المعنيين', 'Stakeholder register', false),
  (1491, 3, 'خطة إدارة التغيير', 'Change management plan', false),
  (1492, 0, 'القيام بتعديل نظام التقارير لتضمين تقرير حالة المشروع بالنقالب القديم.', 'Modify the reporting system to include the project status report with the old template.', false),
  (1492, 1, 'ارسال له التقرير المطلوب بالنموذج المطلوب.', 'Send him the needed report with the needed template.', false),
  (1492, 2, 'الإتصال ببيتر وسؤاله عن احتياجاته بالتفصيل.', 'Contact Peter and ask him about his needs in details.', true),
  (1492, 3, 'منح بيتر حق استخدام نظام التقارير الجديد.', 'Grant Peter access to the new reporting system.', false),
  (1493, 0, 'مخططات الحالة المزاجية لا يمكنها تقليل معدل الدوران الوظيفي.', 'Mood charts will not help to reduce turnover rate.', false),
  (1493, 1, 'لن تساعد مخططات الحالة المزاجية في تحديد مشكلات الفريق المحتملة.', 'Mood charts will not help to identify potential team issues.', false),
  (1493, 2, 'مخططات الحالة المزاجية لا تقيس معنويات فريق المشروع.', 'Mood charts does not measure the project team morale.', false),
  (1493, 3, 'مخططات الحالة المزاجية يمكن أن تكون ذاتية.', 'Mood charts can be subjective.', true),
  (1494, 0, 'يطلب من الفريق إدارة وقتهم بشكل أفضل وتخصيص فترة للإجابة على أسئلة واستفسارات المعنيين.', 'Ask the team to better manage their time and dedicate a slot to answer stakeholders questions and inquiries.', false),
  (1494, 1, 'يطلب من المعنيين توجيه أسئلتهم إليه رسمياً.', 'Ask the stakeholders to formally address their questions to him.', false),
  (1494, 2, 'يطلب من أعضاء الفريق عدم الرد على أي استفسارات من المعنيين لأن هذه ليست مسؤوليتهم.', 'Ask the team members not to respond to any stakeholders inquiries as this is not their responsibility.', false),
  (1494, 3, 'قم بمراجعة خطة إدارة التواصل وإرسال طلب التغيير إذا لزم الأمر.', 'Review the communication management plan and submit change request if needed.', true),
  (1495, 0, 'حسناً ، نتفق على السعر الذي طلبته، حيث ستقدم الخدمة التي نحتاجها بجميع المواصفات المذكورة.', 'Fine, we agree on the price you asked for as you will provide the service we need with all mentioned specifications.', true),
  (1495, 1, 'سوف نوافق على اقتراح سام ، وكل الآخرين مرفوضون.', 'We will go with Sam''s suggestion, all others are rejected.', false),
  (1495, 2, 'دعنا نقبل الربح الأقل في الوقت الحالي ، فهذا سيمنحنا فرصة لاختراق هذا السوق الجديد.', 'Let''s accept the less profit for now, this will give us an opportunity to penetrate this new market.', false),
  (1495, 3, 'سنقوم بتنفيذ الجزء الأول من النهج الذي اقترحه مايك والجزء الثاني من النهج الذي اقترحته جوليا.', 'We will implement the first part of the approach proposed by Mike and the second part of the approach proposed by Julia.', false),
  (1496, 0, 'مخطط المعالم', 'Milestone chart', false),
  (1496, 1, 'المخطط الشبكي', 'Network diagram', false),
  (1496, 2, 'قائمة الأنشطة', 'Activity list', false),
  (1496, 3, 'المخططات الشريطية', 'Bar chart', true);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1497, 0, 'القيام بتحديث سجل المعنيين وخطة إدارة التواصل ومناقشة متطلبات المشروع مع الممثل الجديد.', 'Update the stakeholder register and communication management plan and discuss the project requirements with the new representative.', true),
  (1497, 1, 'الاعتذار إلى الممثل الجديد وإرسال تقرير حالة المشروع له.', 'Apologize to the new representative and send him the project status report.', false),
  (1497, 2, 'مشاركة خطة إدارة التواصل مع الممثل الجديد.', 'Share the communication management plan with the new representative.', false),
  (1497, 3, 'القيام بتحديث قائمة مستلمي البريد الإلكتروني الخاص بتقرير حالة المشروع.', 'Update the list of recipients of the project status report email.', false),
  (1498, 0, 'قم بتحليل جميع المعنيين وتضميل استراتيجية مشاركة لكل منهم.', 'Analyze all stakeholders and tailor an engagement strategy for each stakeholder.', true),
  (1498, 1, 'وضع استراتيجية مشاركة واحدة لجميع المعنيين.', 'Develop one engagement strategy for all stakeholders.', false),
  (1498, 2, 'ترتيب اجتماعات منتظمة وجها لوجه مع جميع المعنيين الداخليين والخارجيين.', 'Arrange regular face to face meetings with both internal and external stakeholders.', false),
  (1498, 3, 'الطلب من راعي المشروع تحمل مسؤولية مشاركة الإدارة العليا.', 'Ask the project sponsor to take the responsibility of senior management engagement.', false),
  (1499, 0, 'يقرر مدير المشروع التخلي عن نهجه الخاص واستخدام النهج الذي قدمه مارك من أجل اكتساب الثقة.', 'The project manager decides to give up on his own approach and use the approach provided by Mark in order to gain confidence.', false),
  (1499, 1, 'يتفاوض الفريق الفني حول الأساليب المختلفة وسينفذون نهج فيليب بدلاً من النهج الذي قدمته ماري.', 'The technical team negotiates different approaches and they will implement Phillip''s approach rather than the approach provided by Mary.', false),
  (1499, 2, 'وافق مدير المشروع مع عضوي الفريق المتنازعين على التسوية.', 'The project manager has agreed with the two team members who are in a conflict to compromise.', true),
  (1499, 3, 'نجح المورد في التفاوض مع مدير المشتريات للوصول إلى سعر عادل ومعقول للخدمة التي سيقدمها.', 'The supplier succeeded in negotiation with the procurement manager to reach a fair and reasonable price for the service which he will provide.', false),
  (1500, 0, 'إرسال نسخة من سجل المشكلات لكلا المعنيين بالمشروع وطلب تعقيبات إضافية منهما.', 'Send both stakeholders a copy of the issue log and ask for additional comments.', false),
  (1500, 1, 'طلب من كلا المعنيين توجيه أي أسئلة إلى مدير المشروع كتابياً.', 'Ask both stakeholders to direct any questions to the project manager in writing.', false),
  (1500, 2, 'تقديم عرض لجميع المعنيين بالمشروع فيما يتعلق بوضع المشروع.', 'Make a presentation to all the stakeholders regarding the status of the project.', false),
  (1500, 3, 'ترتيب لقاء مع كلا المعنيين للسماح لهما بالتعبير عن أية تحفظات قد تكون لديهما.', 'Arrange a meeting with both stakeholders to allow them to voice any concerns they may have.', true),
  (1501, 0, 'مخطط المزاجية', 'Mood Chart', false),
  (1501, 1, 'صافي نقاط المؤيدين NPS', 'Net Promoter Score', false),
  (1501, 2, 'تحليل الطاقة الإنتاجية', 'Throughput analysis', true),
  (1501, 3, 'الروح المعنوية', 'Morale', false),
