  (1507, 2, 'التواصل الرسمي', 'Formal communication', false),
  (1507, 3, 'التواصل التفاعلي', 'Interactive communication', true),
  (1508, 0, 'القياسات اللازمة لا يتم جمعها وتحليلها و مشاركتها و مناقشتها خلال اجتماعات الفريق و المعنيين.', 'Appropriate measures are not being collected, analyzed, shared or discussed during team and stakeholder meetings.', true),
  (1508, 1, 'المعنيين بالمشروع لا يقومون بقراءة تقرير حالة المشروع قبل اجتماع حالة المشروع.', 'The project stakeholders don''t read the project status report before the project status meeting.', false),
  (1508, 2, 'لا يستخدم فريق المشروع طريقة التواصل المفضلة المعنيين بالمشروع.', 'The project team don''t use the preferred communication method for project stakeholders.', false),
  (1508, 3, 'لا يوجد خطة لإدارة التواصل في المشروع.', 'There is no communication management plan in place.', false),
  (1509, 0, 'التواصل من خلال ارسال المعلومات', 'Push communication', false),
  (1509, 1, 'التواصل من خلال إتاحة المعلومات', 'Pull communication', true),
