INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (1547, 0, 'يوائم', 'Compromising', false),
  (1547, 1, 'يجبر', 'Forcing', false),
  (1547, 2, 'ينسحب', 'Withdrawing', true),
  (1547, 3, 'يواجه', 'Confronting', false),
  (1548, 0, 'إرسال طلب لتغيير لإعادة جدولة نشاط المشروع.', 'Submit a change request to reschedule the project activity.', false),
  (1548, 1, 'يجب على مدير المشروع إبلاغ المورد المعين لتحديد أولويات نشاط المشروع.', 'The project manager should inform the assigned resource to prioritize the project activity.', false),
  (1548, 2, 'يجب أن يناقش مدير المشروع مع المدير الوظيفي للتحقق مما إذا كان يمكن تعديل الجدول الزمني.', 'The project manager should discuss with the functional manager to check if the schedule can be adjusted.', true),
  (1548, 3, 'يجب على مدير المشروع أن يطلب من مكتب إدارة المشروع تحديد أولويات عمل المشروع بشكل رسمي على العمل التشغيلي.', 'The project manager should ask PMO to formally prioritize the project work over the operational work.', false),
  (1549, 0, 'العميل', 'Customer', false),
  (1549, 1, 'أعضاء الفريق', 'Team members', true),
  (1549, 2, 'مدير المشروع', 'Project manager', false),
  (1549, 3, 'الراعي', 'Sponsor', false),
  (1550, 0, 'محاولة إيجاد حل وسط يجلب درجة معينة من الرضا لكلا الطرفين.', 'Try to find a compromise that brings some degree of satisfaction to both parties.', false),
  (1550, 1, 'القيام بإشراك مديريهم الوظيفيين لأنه خلاف تقني.', 'Involve their functional managers as it is a technical conflict.', false),
  (1550, 2, 'السماح لأعضاء الفريق بحل النزاع بأنفسهم.', 'Allow the team members to resolve the conflict themselves.', true),
  (1550, 3, 'عقد اجتماعاً مع كل من أعضاء الفريق ومحاولة إيجاد حل باستخدام نهج مباشر وتعاوني.', 'Have a meeting with both team members and try to find a solution using a direct and collaborative approach.', false),
  (1551, 0, 'اخبرهما أنهما بحاجة إلى حل خلافاتهما الفنية فيما بينهما.', 'Tell them they need to resolve their technical differences between themselves.', true),
  (1551, 1, 'قم بالإبلاغ عن سلوكهما الغير محترم إلى إدارة الموارد البشرية.', 'Report the team members to human resources for disrespectful behavior toward each other.', false),
  (1551, 2, 'اشرح أساليب التواصل المختلفة الخاصة بهما لمساعدتهما على فهم بعضهما البعض بشكل أفضل.', 'Explain their different communication styles to help them understand each other better.', false),
  (1551, 3, 'اطلب من أحد أعضاء الفريق أن ينتقل إلى فريق آخر حيث من الواضح أنهما لا يتفقان.', 'Have one of the team members transferred to another team, since they obviously don''t get along.', false),
  (1552, 0, 'الاجبار', 'Forcing', false),
  (1552, 1, 'المواجهة', 'Confronting', false),
  (1552, 2, 'السلاسة', 'Smoothing', false),
  (1552, 3, 'المواءمة', 'Compromise', true),
  (1553, 0, 'تأجيل التعامل مع هذه النزاعات عندما يكون ذلك ممكنًا للسماح لهؤلاء المشاركين في النزاع لتهدئة الأمر مما يجعل حل النزاع أسهل.', 'Postpone handling these conflicts whenever possible to allow those involved in the conflict to calm down which makes solving conflict easier.', false),
  (1553, 1, 'التعامل مع النزاع في اجتماع فريق المشروع بحيث يمكن للفريق بأكمله المشاركة في إيجاد حل.', 'Handle the conflict in the project team meeting so that the entire team can participate in finding a solution.', false),
  (1553, 2, 'معالجة النزاعات على انفراد، وذلك باستخدام نهج تعاوني مباشر.', 'Address the conflict in private using a direct, collaborative approach.', true),
  (1553, 3, 'استخدام سلطتك لدفع وجهة النظر الصحيحة ثم التركيز على تحقيق أهداف المشروع.', 'Use your power to push the correct point of view to focus on achieving the project objectives.', false),
  (1554, 0, 'تقديم طلب تغيير لتمديد تاريخ انتهاء المشروع لاستيعاب التأخير المتوقع.', 'Raise a change request to extend the project end date to accommodate the expected delay.', false),
  (1554, 1, 'تصعيد هذا الموضوع إلى راعي المشروع.', 'Escalate this topic to the project sponsor.', false),
  (1554, 2, 'استخدام مخطط الطوابق الذي قدمه العميل حيث أن العميل مسؤول عن توفير مخطط الطوابق الصحيح.', 'Use the floor plan provided by the customer as the customer is accountable to provide the correct floor plan.', false),
  (1554, 3, 'استشارة العميل لتحديد ما إذا كان ينبغي مواصلة تنفيذ المشروع.', 'Consult with the customer to determine if the project execution should be continued.', true),
  (1555, 0, 'المواجهة', 'Confronting', false),
  (1555, 1, 'الإنسحاب', 'Withdrawal', false),
  (1555, 2, 'السلاسة', 'Smoothing', false),
  (1555, 3, 'الإجبار', 'Forcing', true),
  (1556, 0, 'المواءمة', 'Compromising', true),
  (1556, 1, 'السلاسة', 'Smoothing', false),
  (1556, 2, 'الإجبار', 'Forcing', false),
  (1556, 3, 'المواجهة', 'Confronting', false),
  (1557, 0, 'استبعد ملاحظات هذا الشخص المعني بالمشروع وانتقل إلى إصدار المنتج.', 'Exclude this particular stakeholder''s feedback and proceed to product release.', false),
  (1557, 1, 'تصعيد هذا الموضوع إلى راعي المشروع.', 'Escalate this topic to the project sponsor.', false),
  (1557, 2, 'اعقد اجتماعاً مع فريق المشروع والشخص المعني بالمشروع لحل الخلاف.', 'Hold a meeting with the project team and the stakeholder to resolve the conflict.', true),
  (1557, 3, 'اتصل بالشخص المعني بالمشروع على انفراد لفهم سبب الخلاف.', 'Call the stakeholder privately to understand the reason of the conflict.', false),
  (1558, 0, 'يتعين التعامل معها طبقاً لعملية حل النزاع البديل.', 'It should be handled in accordance with alternative dispute resolution.', true),
  (1558, 1, 'ينبغي توثيق المشاكل في سجل الإشكالات ووضع علامة على أنها لم تحل.', 'The issues should be documented in the issue log and marked as unresolved.', false),
  (1558, 2, 'يجب إنهاء العقد وفقاً للشروط والأحكام.', 'The contract should be terminated according to the terms and conditions.', false),
  (1558, 3, 'يجب تصعيد المشكلة لراعي المشروع.', 'You should escalate the issue to the project sponsor.', false),
