  (1806, 2, 'مؤشر أداء الجدول الزمني هو 0.94، ومؤشر أداء التكلفة هو 1.04.', 'The SPI is 0.94, and the CPI is 1.04.', false),
  (1806, 3, 'مؤشر أداء الجدول الزمني هو 0.80، ومؤشر أداء التكلفة هو 0.91.', 'The SPI is 0.80, and the CPI is 0.91.', false),
  (1807, 0, 'إصدار طلب تغيير لإعادة وضع خط الأساس للتكلفة.', 'Issue a change request to redo the cost baseline.', true),
  (1807, 1, 'طلب موارد إضافية.', 'Ask for additional resources.', false),
  (1807, 2, 'ضغط الجدول الزمني للمشروع.', 'Crash the project schedule.', false),
  (1807, 3, 'استخدام احتياطي الإدارة.', 'Utilize the management reserve.', false),
  (1808, 0, 'المشروع سابق للجدول الزمني وأقل من الميزانية.', 'The project is ahead of schedule and under budget.', false),
  (1808, 1, 'المشروع متأخر عن الجدول الزمني ويتجاوز الميزانية.', 'The project is behind schedule and over budget.', true),
  (1808, 2, 'المشروع سابق للجدول الزمني ويتجاوز الميزانية.', 'The project is ahead of schedule and over budget.', false),
  (1808, 3, 'المشروع متأخر عن الجدول الزمني وأقل من الميزانية.', 'The project is behind schedule and under budget.', false),
  (1809, 0, 'الاجتماع مع مدير عضو الفريق والتفاوض على وقت بديل لإكمال المهمة الأخرى.', 'Meet with the team member’s manager and negotiate for an alternative time to complete the other task.', true),
  (1809, 1, 'الطلب من عضو الفريق التركيز على المهمة الحرجة والحصول على مورد إضافي من قسم آخر.', 'Ask the team member to focus on the critical task and obtain an additional resource from another department.', false),
  (1809, 2, 'إرسال تقرير إلى راعي المشروع لتوثيق عدم الامتثال من جانب مدير العضو.', 'Send a report to the project sponsor, documenting noncompliance from the member’s manager.', false),
  (1809, 3, 'إبلاغ مدير عضو الفريق بإعفاء عضو الفريق من الأنشطة الخارجية حتى يكتمل نشاط المشروع المجدول.', 'Tell the team member’s manger to release the team member from outside activities until the scheduled project activity is complete.', false),
  (1810, 0, 'مؤشر أداء الجدول الزمني (SPI) هو 0.79، ومؤشر أداء التكلفة (CPI) هو 0.71.', 'The SPI is 0.79, and the CPI is 0.71.', true),
  (1810, 1, 'مؤشر أداء الجدول الزمني (SPI) هو 1.27، ومؤشر أداء التكلفة (CPI) هو 0.98.', 'The SPI is 1.27, and the CPI is 0.98.', false),
  (1810, 2, 'مؤشر أداء الجدول الزمني (SPI) هو 0.82، ومؤشر أداء التكلفة (CPI) هو 1.05.', 'The SPI is 0.82, and the CPI is 1.05.', false),
  (1810, 3, 'مؤشر أداء الجدول الزمني (SPI) هو 0.99، ومؤشر أداء التكلفة (CPI) هو 0.96.', 'The SPI is 0.99, and the CPI is 0.96.', false),
