  (1867, 1, 'إطار العمل الرشيق الموحد (Scaled Agile Framework)، سكرام على نطاق واسع (Large Scale Scrum)', 'Scaled Agile Framework, Large Scale Scrum', true),
  (1867, 2, 'اجتماعات مجموعات العمل، مراجعات ما بعد المشروع', 'Working Group Meetings, Project Post Mortems', false),
  (1867, 3, 'المخططات الانسيابية، مخططات التقارب', 'Flow Charting, Affinity Diagrams', false),
