INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2681, 2, 'محاذاة التكرارات لعقد اجتماعات دروس مستفادة (retrospectives) مشتركة.', 'Align iterations for common retrospectives.', false),
  (2681, 3, 'مشاركة لوحة كانبان (Kanban) إلكترونية مشتركة.', 'Share a common electronic Kanban.', false),
  (2682, 0, 'تنقيح سجل أعمال المنتج مع الفريق ومالك المنتج قبل التكرار التالي.', 'Refine the product backlog with the team and product owner before the next iteration.', false),
  (2682, 1, 'زيادة وتيرة اجتماعات تنقيح سجل أعمال المنتج وتدوين التغيير في الاجتماع الاستعادي.', 'Increase the frequency of backlog refinement meetings and note the change in the retrospective.', false),
  (2682, 2, 'عقد اجتماع استعادي استثنائي وإضافة عملية التغيير العاجل المتفق عليها إلى ميثاق الفريق.', 'Run an ad-hoc retrospective and add the agreed urgent change process to the team charter.', true),
  (2682, 3, 'تذكير قائد الفريق بشكل خاص بأن الدور يتطلب حلاً سريعاً واستباقياً للمشكلات.', 'Privately remind the team lead that the role requires fast and proactive problem solving.', false),
  (2683, 0, 'إجراء نفس اختبارات الوحدة في مختبر الفريق الرشيق وفي المواقع الميدانية.', 'Run the same unit tests in the agile lab and in the field sites.', false),
  (2683, 1, 'إرسال تحديثات سجل المشكلات على مستوى المشروع عبر الرسائل الفورية.', 'Send project-wide issue log updates via instant messaging.', true),
  (2683, 2, 'التأكد من مشاركة نتائج الاجتماعات الاستعادية مع الفريق التنبؤي.', 'Ensure that retrospectives are shared with the predictive team.', false),
  (2683, 3, 'إعادة تخطيط مسار البرمجيات ضمن الجدول الزمني التنبؤي.', 'Replan the software track into the predictive schedule', false),
