INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2730, 3, '20 يوماً', '20 days', false),
  (2731, 0, 'إعادة القصص إلى سجل أعمال المنتج والانتظار حتى يحين تكرار أقل كثافة للعمل عليها.', 'Put the stories back into the product backlog and wait for a less intensive iteration to work on them.', false),
  (2731, 1, 'استخدام التكرار التالي لإجراء بحث تقني (Spike) من قبل الفريق لتحديد جدوى إكمال القصص.', 'Use the next iteration for a team spike to determine feasibility of completing the stories.', false),
  (2731, 2, 'وضع القصص في عمود المعوقات والعمل مع مالك المنتج لإزالة العقبات.', 'Put the stories in the blocked column and work with the product owner to remove impediments.', false),
  (2731, 3, 'العمل مع مالك المنتج لمزيد من التجزئة للقصص في سجل الأعمال وتحديث تعريف الجاهزية (Definition of Ready).', 'Work with the product owner to further break down the stories in the backlog and update the Definition of Ready.', true),
  (2732, 0, 'منح القائد الخادم الفريق حرية مفرطة.', 'The servant leader has granted the team a bit too much freedom.', false),
  (2732, 1, 'اعتمد المورد أساليب البرمجة القصوى (eXtreme Programming).', 'The supplier has adopted eXtreme Programming methods.', true),
  (2732, 2, 'يبدو أن المورد يعقد جلسات تدريبية قائمة على "الألعاب".', 'The supplier appears to be conducting “gaming” training sessions.', false),
  (2732, 3, 'صادفت زيارة مدير المشروع تمرينًا لبناء الفريق.', 'The project manager happened to visit during a team building exercise.', false),
  (2733, 0, 'تتبع حالة الجاهزية لمساعدة الفريق على بدء المهام في الوقت المناسب.', 'Track readiness status to help the team initiate tasks at the right time.', true),
  (2733, 1, 'وضع مواعيد نهائية لضمان إكمال الفريق للعمل ضمن حدود مقبولة.', 'Set deadlines to ensure that the team completes the work in acceptable limits.', false),
  (2733, 2, 'استخدام لوحة مهام لتجميع المهام في صفوف وتتبع التقدم عبر الأعمدة.', 'Use a task board to group tasks into rows and track progress across columns.', true),
  (2733, 3, 'الاحتفاظ بمجموعة مهام للقيام بها (To-do pool) للحد من عدد المهام قيد التنفيذ.', 'Maintain a to do task pool to limit the number of tasks in progress.', true),
  (2733, 4, 'تحديد المعوقات مسبقًا لتحديد ترتيب التنفيذ.', 'Pre-identify blockers to determine the order of execution.', false),
  (2734, 0, 'سكرم السكرم (Scrum of Scrums)', 'Scrum of Scrums', false),
  (2734, 1, 'العمل الجماعي المكثف (Mobbing)', 'Mobbing', false),
  (2734, 2, 'سكرمبان (Scrumban)', 'Scrumban', false),
  (2734, 3, 'التطوير المدفوع بالميزات (Feature-Driven Development)', 'Feature-Driven Development', true),
  (2735, 0, 'ضمان تفصيل بنود سجل الأعمال القادمة بمزيد من الدقة مع الفريق.', 'Ensure upcoming backlog items are elaborated in more detail with the team.', true),
  (2735, 1, 'تثقيف اللجنة التنفيذية حول الطبيعة المرنة لتخطيط الأجايل.', 'Educate the executive committee on the flexible nature of agile planning.', false),
  (2735, 2, 'التخطيط لتكرارات متغيرة الحجم وفقاً لتعقيد القصة وحجم العمل.', 'Plan for variable-size iterations according to story complexity and load.', false),
  (2735, 3, 'تقليل وتيرة تقارير التقدم المرسلة إلى أصحاب المصلحة الرئيسيين.', 'Reduce frequency of the progress reports sent to senior stakeholders.', false),
  (2736, 0, 'SPI = 0.98', 'SPI = 0.98', false),
  (2736, 1, 'CPI = 1.05', 'CPI = 1.05', true),
  (2736, 2, 'CPI = 1.30', 'CPI = 1.30', false),
  (2736, 3, 'SPI = 1.01', 'SPI = 1.01', true),
  (2736, 4, 'CPI = 0.95', 'CPI = 0.95', false),
  (2737, 0, 'إزالة التبعيات بين الفرق.', 'Eliminate dependencies between teams.', false),
  (2737, 1, 'تفضيل أدوات التعاون على الاجتماعات.', 'Favor collaboration tools over meetings.', false),
  (2737, 2, 'تطبيق طبقة "سكرم الفرق" (Scrum of Scrums).', 'Implement a Scrum of Scrums layer.', true),
  (2737, 3, 'الدمج في فريقين كبيرين لتقليل المشكلات.', 'Merge into two large teams to reduce issues.', false),
  (2738, 0, 'الاجتماع مع سكروم ماستر لتحديد ما إذا كانت رؤية المنتج لا تزال صالحة.', 'Meet with the scrum master to determine if the product vision is still valid.', false),
  (2738, 1, 'الاجتماع مع مالك المنتج والفريق لتحديث قائمة تراكم المنتج خلال السبرنت.', 'Meet with the product owner and team to update the product backlog during the sprint.', true),
  (2738, 2, 'العمل مع فريق الأجايل لإجراء تحليل السبب الجذري لمعرفة سبب عدم ظهور المشكلة في وقت سابق.', 'Work with the agile team to run root cause analysis on why the problem did not surface earlier.', false),
  (2738, 3, 'إبلاغ الفريق في الاجتماع اليومي وتحديث تعريف الإنجاز وتعريف الجاهزية.', 'Inform the team at the daily meeting and update the Definition of Done and Definition of Ready.', false),
  (2739, 0, 'تعريف الجاهزية مع معالم التبعية', 'Definition of Ready with dependency milestones', true),
  (2739, 1, 'تفكيك الملحمة مع هيكل تجزئة العمل', 'Epic breakdown with work breakdown structure', false),
  (2739, 2, 'قائمة تراكم المنتج مع تسلسل مهام المسار الحرج', 'Product backlog with critical path task sequence', false),
  (2739, 3, 'تعريف الإنجاز مع معايير الخروج', 'Definition of Done with exit criteria', true),
  (2739, 4, 'تعريف الجاهزية مع هيكل تجزئة العمل', 'Definition of Ready with work breakdown structure', false),
  (2740, 0, 'دمج مهام بسيطة متعددة لجعل أحجام القصص متوافقة مع الأهداف الرئيسية.', 'Combine multiple minor tasks to make story sizes consistent with key objectives.', false),
  (2740, 1, 'إعادة ترتيب أولويات سجل الأعمال المؤجلة لتفضيل أصغر القصص وإعادة تعيينها يومياً.', 'Reprioritize the backlog to favor the smallest stories and reassign them daily.', false),
  (2740, 2, 'إعادة ترتيب أولويات سجل الأعمال المؤجلة على أساس يومي بحيث تؤدي المحفزات الأخيرة إلى رفع أولوية القصة.', 'Reprioritize the backlog on a daily basis so that recent triggers boost story priority.', false),
  (2740, 3, 'دمج المهام الصغيرة إما في تعريف الاكتمال (Definition of Done) أو في معايير القبول.', 'Integrate the small tasks to either the Definition of Done or acceptance criteria.', true),
  (2741, 0, 'مخطط التشتت', 'Scatter diagram', false),
  (2741, 1, 'مخطط الألفة', 'Affinity diagram', false),
  (2741, 2, 'مخطط الرقابة', 'Control chart', true),
  (2741, 3, 'المخطط التكراري', 'Histogram', false),
  (2742, 0, 'التواصل مع راعي المشروع للحصول على مرئياته.', 'Reach out to the project sponsor for their input.', false),
  (2742, 1, 'تعديل خطة إدارة الجودة لتتوافق مع ممارسات المشروع.', 'Modify the quality management plan to conform to project practices.', false),
  (2742, 2, 'طلب إخضاع المشروع لتدقيق داخلي.', 'Request that the project undergo an internal audit.', false),
  (2742, 3, 'استخدام مخطط السبب والأثر لتحليل السبب الجذري.', 'Use a cause-and-effect diagram for root cause analysis.', true),
  (2743, 0, 'ضبط المشتريات', 'Control procurement', false),
  (2743, 1, 'المعاينة الإحصائية', 'Statistical sampling', true),
  (2743, 2, 'تدقيق العمليات', 'Process audit', false),
  (2743, 3, 'تأكيد الجودة', 'Quality assurance', false),
  (2744, 0, 'الاجتماع مع مدير المشاريع الأول لتحديد الخطط والعمليات القائمة، ثم طلب المساعدة في اختيار المعايير المناسبة.', 'Meet with the senior project manager to identify established plans and processes. Then, ask for assistance in selecting the appropriate standards.', true),
  (2744, 1, 'تحديد موعد لاجتماع مع العميل لجمع المتطلبات والحصول على عينات المقارنة المعيارية.', 'Schedule a meeting with the customer to collect requirements and obtain benchmarking samples.', false),
  (2744, 2, 'الحصول على عينات المقارنة المعيارية اللازمة وتحليلات التكلفة والعائد من الراعي.', 'Obtain the necessary benchmarking samples and cost-benefit analyses from the sponsor.', false),
  (2744, 3, 'تأجيل تطوير خطة إدارة الجودة حتى يتم إنشاء مقاييس الجودة وقوائم التحقق من الجودة.', 'Postpone the development of the quality management plan until quality metrics and quality checklists are created.', false),
  (2745, 0, 'رفع سعر المنتج لتمويل استخدام مواد ذات جودة أفضل.', 'Raise the product price to fund use of better-quality materials.', false),
  (2745, 1, 'مقارنة الميزات مع منتجات المنافسين وتتبع العيوب.', 'Benchmark features against competitor products and track defects', false),
  (2745, 2, 'إنشاء منصة اختبار مؤتمتة للقضاء على الخطأ البشري.', 'Create an automated testing bench to eliminate human error.', false),
  (2745, 3, 'استخدام التطوير القائم على الاختبار (TDD) بناءً على مدخلات مستمرة من مجموعات تركيز المستخدمين.', 'Use Test-Driven Development based on continuous user focus group input.', true),
  (2746, 0, 'استخدام التقدير بالمناظرة بناءً على اختبارات مماثلة لقصص مماثلة.', 'Use analogous estimating based on similar tests on similar stories.', false),
  (2746, 1, 'يقوم مالك المنتج بتحديد ملحمة (Epic) جديدة للسماح بالاختبار في الفترة الزمنية القادمة.', 'The product owner defines a new epic to allow testing in the next sprint.', false),
  (2746, 2, 'إضافة معايير القبول ذات الصلة في "تعريف الجاهزية" قبل عملية التقدير.', 'Add the relevant acceptance criteria in the Definition of Ready before estimating.', true),
  (2746, 3, 'يجب على مالك المنتج تقديم التقدير الأولي ليتم تنقيحه من قبل الفريق.', 'The product owner should provide the initial estimate to be refined by the team.', false),
  (2747, 0, 'عقد اجتماعات فردية للاستماع إلى وجهات نظر مختلفة والوصول إلى توافق واسع النطاق.', 'Conduct one-on-one meetings to hear different perspectives and reach widespread consensus.', false),
  (2747, 1, 'نفِّذ الأنظمة المعيارية على الفور لضمان الاتساق في عملية اتخاذ القرار.', 'Implement standardized systems immediately to ensure consistency in decision-making.', false),
  (2747, 2, 'تيسير عقد اجتماع للفريق لتوضيح الأدوار والمسؤوليات وسلطة اتخاذ القرارات.', 'Facilitate a team meeting to clarify roles, responsibilities, and decision-making authority.', true),
  (2747, 3, 'تصعيد النزاع إلى مالك المشروع لحلّه فورًا تجنبًا لتأخيرات المشروع.', 'Escalate the conflict to the project owner for immediate resolution to avoid project delays.', false),
  (2748, 0, 'تنفيذ خطة إدارة التكامل التي تحدد المتطلبات والمعايير المشتركة وآليات التنسيق.', 'Implement an integration management plan that defines requirements, shared standards, and coordination mechanisms.', true),
  (2748, 1, 'إرشاد كل فريق إلى اتباع جدول المشروع عن كثب ومعالجة أي مشكلات تكامل خلال المرحلة النهائية من المشروع.', 'Instruct each team to follow the project schedule closely and address any integration issues during the project’s final phase.', false),
  (2748, 2, 'إجراء مراجعات تكامل منتظمة بين الفرق لتحديد مشكلات الواجهة وحلها فور ظهورها.', 'Conduct regular cross-team integration reviews to identify and resolve interface issues as they arise.', false),
  (2748, 3, 'تعيين فريق مخصص لدمج التسليمات بعد إنجاز عمل كل فريق بشكل مستقل.', 'Assign a dedicated team to combine deliverables after each teams’ work is completed independently.', false),
  (2749, 0, 'قم بتحديث سجل المخاطر لتوثيق النزاع وتأثيره المحتمل على المشروع.', 'Update the risk register to document the conflict and its potential impact on the project.', false),
  (2749, 1, 'فصل عضو فريق المشروع لمنع المزيد من الاضطراب في المشروع وإرساء سابقة.', 'Dismiss the project team member to prevent further disruption to the project and establish precedent.', false),
  (2749, 2, 'تصعيد النزاع إلى مشرف المورِّد لضمان المساءلة والحل الفوري.', 'Escalate the conflict to the supplier’s supervisor to ensure accountability and immediate resolution.', false),
  (2749, 3, 'تيسير عقد اجتماع وجهًا لوجه بين الطرفين لتحديد السبب الجذري وإيجاد حل.', 'Facilitate a face-to-face meeting between both parties to identify the root cause and find a resolution.', true),
  (2750, 0, 'التأكيد على مجالات الاتفاق.', 'Emphasizing areas of agreement.', false),
  (2750, 1, 'تطوير حل يحقق مكاسب للطرفين.', 'Developing a win-win solution.', true),
  (2750, 2, 'فرض السلطة والنفوذ.', 'Commanding authority and power.', false),
  (2750, 3, 'نقل ملكية الجدولة.', 'Transferring scheduling ownership.', false),
  (2751, 0, 'تيسير جلسة عصف ذهني بين الفئات المستهدفة لتحديد استجابة مناسبة.', 'Facilitate a brainstorming session among target demographics to identify an appropriate response.', false),
  (2751, 1, 'تيسير اجتماع لالمعنيين لفهم وجهات نظرهم وإعادة تقييم أهداف المشروع.', 'Facilitate a stakeholder meeting to understand their perspectives and reassess project objectives.', true),
  (2751, 2, 'تحديد أثر النزاع من خلال سرد إيجابيات الموقف وسلبياته وتطبيق التغذية الراجعة.', 'Determine the impact of the conflict by listing the pros and cons of the situation and applying feedback.', false),
  (2751, 3, 'مطالبة راعي المشروع بالعمل كطرف محايد في المفاوضات مع المعنيين غير الراضين.', 'Request the project sponsor act as a neutral party in negotiations with dissatisfied stakeholders.', false),
  (2752, 0, 'حدِّث سجل المخاطر لتوثيق المخاوف، وواصل مناقشة بنود جدول أعمال الاجتماع المجدولة.', 'Update the risk register to document concerns and continue with the meeting’s scheduled agenda items.', false),
  (2752, 1, 'ناقِش وحلّ الشاغل الرئيسي قبل المتابعة في بنود جدول أعمال الاجتماع.', 'Discuss and resolve the main concern prior to continuing with the meeting’s agenda items.', false),
  (2752, 2, 'تذكير الفريق بآداب الاجتماع، ثم سؤال الفريق عمّا إذا كانوا يرغبون في استخدام وقت الاجتماع لمناقشة مخاوفهم.', 'Address the team with a reminder about meeting etiquette, then ask the team if they want to use meeting time to discuss their concerns.', false),
  (2752, 3, 'الإقرار بمخاوف عضو الفريق، والمتابعة مع جدول أعمال الاجتماع المقرَّر، ثم تحديث سجل المخاطر ليعكس هذا الإشكال.', 'Acknowledge the team member’s concern, continue with the meeting’s scheduled agenda, then update the risk register to reflect this issue.', true),
  (2753, 0, 'تحديد الثغرات المحددة في الميزات قبل تيسير تحليل السبب الجذري مع المعنيين الرئيسيين لحل المشكلة.', 'Identify specific feature gaps prior to facilitating a root cause analysis with key stakeholders to resolve the issue.', true),
  (2753, 1, 'عقد جلسة عصف ذهني مع المعنيين لتوليد حلول بديلة وإجراءات تصحيحية.', 'Convene a brainstorming session with stakeholders to generate alternative solutions and corrective actions.', false),
  (2753, 2, 'تحليل وتوثيق أثر رفض المعنيين من خلال المقارنة بين إيجابيات الميزة وسلبياتها.', 'Analyze and document the impact of stakeholder rejection by comparing the feature’s pros and cons.', false),
  (2753, 3, 'تصعيد المشكلة إلى راعي المشروع وطلب الوساطة بين المعنيين الرئيسيين وفريق التسليم.', 'Escalate the issue to the project sponsor and request mediation between key stakeholders and the delivery team.', false),
  (2754, 0, 'حافظ على السيطرة على جدول أعمال الاجتماع، واعترف بمخاوف عضو الفريق، وتابع معه بعد الاجتماع لمناقشة تلك المخاوف.', 'Maintain control of the meeting agenda, acknowledge the team member’s concern, and follow up with them after the meeting to discuss their concerns.', true),
  (2754, 1, 'تابع الاجتماع كما هو مخطط له، وسجل هذه المخاوف في سجل المخاطر لتقييمها بعد انتهاء الاجتماع.', 'Continue with the meeting as planned and record the concern in the risk register for evaluation after the meeting concludes.', false),
  (2754, 2, 'إيقاف الاجتماع مؤقتًا والدخول في مناقشة جماعية لحل الخلاف قبل المتابعة مع بقية بنود جدول الأعمال.', 'Pause the meeting and engage in a group discussion to resolve the disagreement before proceeding with the remaining agenda items.', false),
  (2754, 3, 'تذكير عضو الفريق بآداب الاجتماع المتوقعة، والمتابعة مع جدول الأعمال، وطلب التغذية الراجعة بشأن توقعات التواصل في نهاية الاجتماع.', 'Remind the team member of expected meeting etiquette, continue with the agenda, and request feedback on communication expectations at the end of the meeting.', false),
  (2755, 0, 'أرسل بريدًا إلكترونيًا لتوثيق المشكلة رسميًا، مع ضمان وجود سجل تدقيق، وإتاحة الوقت للمورّد للتحقيق داخليًا قبل الرد.', 'Send an email to formally document the issue, ensuring an audit trail and allowing the vendor time to investigate internally before responding.', false),
  (2755, 1, 'تيسير عقد اجتماع مع المعنيين لتقديم الإيضاحات، وملاحظة الإشارات غير اللفظية، وتحليل المشكلة لتحديد الإجراء التصحيحي المناسب.', 'Facilitate a meeting with the relevant stakeholders to provide clarification, observe nonverbal cues, and analyze the issue to determine corrective action.', true),
  (2755, 2, 'تصعيد المشكلة عبر إشعار تعاقدي رسمي لفرض الالتزام بالشروط المتفق عليها.', 'Escalate the issue through a formal contractual notice to enforce compliance with agreed terms.', false),
  (2755, 3, 'مطالبة فريق المشروع بتوثيق المشكلة بالتفصيل وإحالتها إلى البائع لمراجعتها وحلّها بشكل غير متزامن.', 'Request that the project team document the issue in detail and forward it to the vendor for asynchronous review and resolution.', false),
  (2755, 4, 'الاستعانة بمحكّم لتيسير جلسات الوساطة الخاصة بالفريق للوصول إلى حل عادل وغير متحيز.', 'Engage an arbitrator to facilitate team mediation sessions to arrive at a fair and unbiased resolution.', true),
  (2756, 0, 'إنشاء آلية تزامن منتظمة لإبراز وحلّ الاعتماد المتبادل قبل عملية الدمج.', 'Establish a regular synchronization mechanism to surface and resolve interdependencies before integration.', true),
  (2756, 1, 'أعط الأولوية لمخرجات فريق واحد على الفرق الأخرى، وقم بتعديل الجداول الزمنية لترتيب تنفيذ العمل بالتسلسل، وتقليل التطوير المتزامن إلى الحد الأدنى لتجنب التعارضات.', 'Prioritize one team’s deliverables over the others and adjust schedules to sequence work execution, minimizing simultaneous development to avoid conflicts.', false),
  (2756, 2, 'السماح لكل فريق بالعمل بشكل مستقل وتوثيق النزاعات فور ظهورها، ثم معالجة المشكلات خلال مرحلتي التكامل والاختبار.', 'Allow each team to proceed independently and document conflicts as they arise, then address issues during integration and testing phases.', false),
  (2756, 3, 'إسناد اختبار التكامل إلى بائع خارجي مستقل لتحديد جميع الاعتماديات المتبادلة وحلّها.', 'Assign integration testing to an independent third-party vendor to identify and resolve all interdependencies.', false),
  (2757, 0, 'شجِّع التواصل وعالج النزاعات المحتملة لمواءمة التوقعات.', 'Encourage communication and address potential conflicts to align expectations.', false),
  (2757, 1, 'تعزيز العمليات المعتمدة ودعم اتخاذ القرارات التعاونية.', 'Reinforce established processes and support collaborative decision-making.', false),
  (2757, 2, 'توفير توجيه واضح وتحديد الأدوار والتواصل بشأن أهداف المشروع.', 'Provide clear direction, define roles, and communicate project objectives.', true),
  (2757, 3, 'تفويض ملكية المهام ومراقبة التنفيذ عالي الأداء.', 'Delegate task ownership and monitor high-performance execution.', false),
  (2758, 0, 'تعزيز سلطة مالك المنتج وتوجيه الفريق لاتباع الأولويات المحددة.', 'Reinforce the product owner’s authority and direct the team to follow the defined priorities.', false),
  (2758, 1, 'أوقف النقاش واطلب من كل مشارك أن يعبّر باختصار عن وجهة نظره دون مقاطعة.', 'Pause the discussion and ask each participant to briefly express their perspective without interruption.', true),
  (2758, 2, 'تنبيه عضو الفريق الذي يخالف سلوكه القواعد على انفراد وإصدار تحذير رسمي.', 'Admonish the team member whose behavior violates norms privately and issue a formal warning.', false),
  (2758, 3, 'تيسير مناقشة تمكّن الفريق من حل الخلاف بشكل تعاوني.', 'Facilitate a discussion that enables the team to collaboratively resolve the disagreement.', true),
  (2758, 4, 'قدّم عرضًا تقديميًا حول مفاهيم الذكاء العاطفي قبل متابعة الجلسة.', 'Conduct a presentation on emotional intelligence concepts before continuing the session.', false),
  (2759, 0, 'إلزام ممثلي الإدارات الداعمة بحضور جميع اجتماعات التنسيق اليومية وتقديم تحديثات الحالة لفرقهم.', 'Require representatives from supporting departments attend all daily coordination meetings and provide status updates to their teams.', false),
  (2759, 1, 'اطلب أن يكون مالك المنتج متاحًا بسهولة للإجابة عن أسئلة الفريق عند ظهورها.', 'Request that the product owner is readily available to address team questions as they arise.', false),
  (2759, 2, 'توجيه الفريق إلى نقل بنود العمل المتأثرة إلى حالة "محظور" عند حدوث التأخيرات.', 'Direct the team to transfer affected work items to a blocked status when delays occur.', false),
  (2759, 3, 'التأكد من أن مالك المنتج يشرح للفريق بأكمله الغرض من تنقيح سجل الأعمال واعتماديات سير العمل ذات الصلة.', 'Ensure the product owner explains the purpose of backlog refinement and related workflow dependencies to the entire team.', true),
  (2760, 0, 'صنِّف عناصر الأعمال المتراكمة حسب الوحدة السوقية والتزم باختيار نسبة ثابتة من العناصر المتخصصة خلال تخطيط السبرينت.', 'Categorize backlog items by market unit and commit to selecting a fixed percentage of niche items during sprint planning.', true),
  (2760, 1, 'صنِّف عناصر سجل الأعمال على أنها رئيسية أو متخصصة، وخصّص ما يقرب من 40% من نقاط قصص الفريق للعمل المتخصص في كل إطلاق.', 'Classify backlog items as mainstream or niche and allocate approximately 40% of the team’s story points to niche work each sprint.', false),
  (2760, 2, 'تخصيص نسبة متساوية من القدرة لكل وحدة سوقية عن طريق توزيع نقاط القصة بالتساوي على الوحدات في كل إطلاق.', 'Assign an equal percentage of capacity to each market unit by distributing story points evenly across units every sprint.', false),
  (2760, 3, 'تصنيف بنود سجل الأعمال إلى رئيسية أو متخصصة وقصر العمل الرئيسي على نسبة ثابتة من البنود المنجزة في كل إطلاق.', 'Classify backlog items as mainstream or niche and limit mainstream work to a fixed percentage of completed items per sprint.', false),
  (2761, 0, 'تصعيد المشكلة إلى الإدارة العليا لمنع المزيد من تدخل المعنيين.', 'Escalate the issue to senior management to prevent further stakeholder interference.', false),
  (2761, 1, 'تيسير مناقشة بين صاحب المصلحة ومالك المنتج لإنشاء سير عمل واضح.', 'Facilitate a discussion between the stakeholder and the product owner to establish a clear workflow.', true),
  (2761, 2, 'اشتراط أن يقدّم المعني طلبات التغيير رسميًا قبل أن يقبل الفريق أي عمل جديد.', 'Require that the stakeholder formally submits change requests before the team accepts any new work.', false),
  (2761, 3, 'منح المعني إذنًا بإضافة بنود في سجل أعمال المنتج وإعادة تحديد أولوياتها.', 'Grant the stakeholder permission to add and reprioritize items in the product backlog.', false),
  (2762, 0, 'طبِّق الذكاء العاطفي لفهم اهتمامات المعنيين والتأثير على مشاركتهم.', 'Apply emotional intelligence to understand stakeholder interests and influence participation.', false),
  (2762, 1, 'حدِّد وقتًا للاجتماعات لضمان بقاء المشاركة قصيرة ومركزة.', 'Timebox meetings to ensure participation remains brief and focused.', false),
  (2762, 2, 'استخدام أساليب تيسير فعّالة لتشجيع المشاركة وتوجيه المناقشات المثمرة.', 'Use effective facilitation techniques to encourage participation and guide productive discussions.', true),
  (2762, 3, 'تصعيد نقص مشاركة المعنيين إلى الإدارة العليا.', 'Escalate the lack of stakeholder participation to senior management.', false),
  (2763, 0, 'راجع خطة إشراك المعنيين لتحديد إجراء التصحيح المناسب.', 'Review the stakeholder engagement plan to determine the appropriate corrective action.', false),
  (2763, 1, 'تيسير اجتماع للفريق لمراجعة ميثاق الفريق ووضع المعايير والتوقعات.', 'Facilitate a team meeting to review the team charter and establish norms and expectations.', true),
  (2763, 2, 'تنظيم نشاط لبناء الفريق لترسيخ الثقة ورفع الروح المعنوية العامة للفريق.', 'Organize a team-building activity to establish trust and increase overall team morale.', false),
  (2763, 3, 'الاجتماع بأعضاء الفريق فرديًا لجمع المدخلات حول كيفية التعامل مع الموقف.', 'Meet individually with team members to gather input on how to handle the situation.', false),
  (2764, 0, 'تيسير إعداد ميثاق الفريق.', 'Facilitate the creation of a team charter.', true),
  (2764, 1, 'جدول أنشطة بناء الفريق.', 'Schedule team-building activities.', false),
  (2764, 2, 'إرسال تحديثات يومية عن حالة المشروع للحفاظ على مواءمة أعضاء الفريق.', 'Send daily project status updates to keep team members aligned.', false),
  (2764, 3, 'إجراء اجتماعات فردية لبناء علاقات شخصية.', 'Conduct one-on-one meetings to build individual relationships.', false),
  (2765, 0, 'تعيين عضو الفريق ليكون قائد المشروع بناءً على علاقته السابقة مع الجهة الراعية.', 'Assign the team member to be project lead based on their previous relationship with the sponsor.', false),
  (2765, 1, 'اطلب من عضو الفريق مشاركة المعلومات حول الراعي مع الفريق لتحسين التعاون.', 'Demand the team member shares information about the sponsor with the team to improve collaboration.', false),
  (2765, 2, 'الاستفادة من خبرة عضو الفريق وتوظيفها لتحسين التواصل ونتائج المشروع.', 'Capitalize on the team member’s expertise and use it to enhance communication and project outcomes.', true),
  (2765, 3, 'تقييم ما إذا كانت العلاقة السابقة تُنشئ تضاربًا في المصالح قد يؤثر على نزاهة المشروع.', 'Evaluate whether the prior relationship creates a conflict of interest that could affect the project’s integrity.', false),
  (2766, 0, 'أعد هيكلة اجتماعات التنسيق اليومية من خلال تطبيق جدول أعمال محدد بمدة 15 دقيقة، وعيِّن شخصًا لتدوين محاضر الاجتماع.', 'Restructure the daily coordination meetings by implementing a timed 15-minute agenda and assign a note-taker to document the meeting.', false),
  (2766, 1, 'طبِّقْ حدًّا زمنيًا صارمًا لكل متحدث، باستخدام مؤقّتٍ مرئي، للحدّ من وقت حديث كل شخص خلال اجتماعات التنسيق اليومية.', 'Apply a strict per-speaker timebox, using a visible timer, to limit each person’s speaking time during the daily coordination meetings.', false),
  (2766, 2, 'توجيه الفريق لتركيز اجتماعات التنسيق اليومية على تحديد العوائق، وإنشاء منتدى مخصص للمناقشات الموجهة نحو الحلول.', 'Coach the team to focus the daily coordination meetings on impediment identification and establish a dedicated forum for solution-driven discussions.', false),
  (2766, 3, 'التعاون مع الفريق لإعادة تصميم صيغة اجتماع التنسيق، بتحديد فترة زمنية محددة مدتها 15 دقيقة واعتماد عملية منظمة لتوجيه العوائق.', 'Collaborate with the team to redesign the coordination meeting format, setting a 15-minute timebox and introducing a structured process for routing impediments.', true),
  (2767, 0, 'طوّر مهارات ومعارف أعضاء الفريق بفعالية مع الحفاظ على دافعهم طوال دورة حياة المشروع.', 'Actively develop team members'' skills and knowledge while sustaining their motivation throughout the project life cycle.', true),
  (2767, 1, 'التعرّف على أصحاب الأداء المتميز من خلال المكافآت، والحفاظ على نظام جدولة منظّم لتتبع توافر أعضاء الفريق.', 'Recognize top performers with rewards and maintain a structured scheduling system to track team member availability.', false),
  (2767, 2, 'إجراء استبيان لتحديد كفاءات أعضاء الفريق وتيسير عقد اجتماع للفريق لمشاركة النتائج.', 'Conduct a survey to identify team members'' competencies and facilitate a team meeting to share the results.', false),
  (2767, 3, 'إسناد المهام بشكل استراتيجي بما يستفيد من الخبرة الحالية لأعضاء الفريق مع ربط الأداء ببرنامج مكافآت رسمي.', 'Strategically assign tasks that leverage team members'' existing expertise while linking performance to a formal rewards program.', false),
  (2768, 0, 'طبّق استراتيجيات الذكاء العاطفي.', 'Apply emotional intelligence strategies.', false),
  (2768, 1, 'وضع وتنفيذ سياسة قائمة تحقق موحّدة.', 'Develop and enforce a standardized checklist policy.', false),
  (2768, 2, 'البحث في أساليب إدارة الاجتماعات.', 'Research meeting management techniques.', false),
  (2768, 3, 'تطبيق استراتيجيات تيسير فعّالة.', 'Apply effective facilitation strategies.', true),
  (2769, 0, 'إدخال زيادة في الإبداع في التكرارات القادمة لتمكين الاستكشاف المنهجي.', 'Introduce a creativity spike in upcoming iterations to enable structured exploration.', false),
  (2769, 1, 'تمديد مدة التكرار لمنح الفريق مزيدًا من الوقت لتقديم عمل إبداعي.', 'Extend iteration length to give the team more time to deliver creative work.', false),
  (2769, 2, 'تشجيع نموذج فريق بمهارات على شكل حرف T لزيادة القدرة الإجمالية على التسليم.', 'Encourage a T-shaped team model to increase overall delivery capacity.', true),
  (2769, 3, 'تنظيم فعالية لبناء الفريق لتحسين الروح المعنوية وتعزيز التعاون.', 'Organize a team-building event to improve morale and cultivate collaboration.', false),
  (2770, 0, 'يجب على الفرق المتخصصة التركيز على تقليل معدلات الخطأ.', 'Specialist teams should focus on reducing error rates.', false),
  (2770, 1, 'تتفوق الفرق التقنية في البيئات الرشيقة.', 'Technical teams are superior in agile environments.', false),
  (2770, 2, 'محدودية نطاق المهارات تؤثر على قدرة الفريق على التكيف.', 'Limited skill range is impacting the team’s adaptability.', true),
  (2770, 3, 'التركيز على العمل التقني وحده يحسّن الكفاءة.', 'Focusing only on technical work improves efficiency.', false),
  (2771, 0, 'يتجنب أعضاء الفريق تولّي المهام الصعبة.', 'Team members avoid taking on challenging tasks.', true),
  (2771, 1, 'يتجنب أعضاء الفريق التواصل المباشر مع الإدارات الأخرى.', 'Team members avoid direct communication with other departments.', true),
  (2771, 2, 'يثير أعضاء الفريق عوائق لا يستطيعون حلها بأنفسهم.', 'Team members raise impediments they cannot resolve on their own.', true),
  (2771, 3, 'ينتقل أعضاء الفريق ذوو الأداء العالي إلى أدوار أعلى.', 'High-performing team members move into more senior roles.', false),
  (2771, 4, 'يبدي المعنيين في المشروع تشككًا بشأن الممارسات الرشيقة.', 'Project stakeholders express skepticism about agile practices.', false),
  (2772, 0, 'قدرة عضو الفريق على عرض تقدم السبرينت لالمعنيين الخارجيين.', 'The team member’s ability to articulate sprint progress to external stakeholders.', false),
  (2772, 1, 'وعي عضو الفريق بالأعمال الجارية في الفرق المشاركة الأخرى.', 'The team member''s awareness of work occurring in other participating teams.', true),
  (2772, 2, 'خبرة عضو الفريق في المجال التقني للإطلاق الحالي.', 'The team member''s expertise in the technical domain of the current sprint.', false),
  (2772, 3, 'مدة خدمة عضو الفريق وخبرته في تطبيق الأطر المحايدة.', 'The team member’s tenure and experience applying agnostic frameworks.', false),
  (2773, 0, 'يقلّل المطوّر المتمرّس من عدد الساعات المبلَّغ عنها مقارنةً بأعضاء الفريق المبتدئين.', 'The senior developer underreports hours relative to junior team members.', false),
  (2773, 1, 'أعضاء الفريق المبتدئون يُظهرون إنتاجية أعلى في البيئات الرشيقة.', 'Junior team members demonstrate higher productivity in agile environments.', false),
  (2773, 2, 'نقاط القصة المخصصة لمهام المطوّر الأقدم مُقدَّرة باستمرار بأقل من قيمتها الفعلية.', 'The story points assigned to the senior developer''s tasks are consistently underestimated.', true),
  (2773, 3, 'أسلوب المطوّر الأقدم يقلّل عدد نقاط القصة المنجزة في كل إطلاق.', 'The senior developer''s approach reduces the number of story points completed per sprint.', false),
  (2774, 0, 'ضع شاشات تعرض مخططات تصاعد إنجاز الخصائص بجوار موجز مُنتقى بعناية لنتائج جلسات التقييم الرجعي (الريتروسبيكتيف).', 'Place monitors displaying feature burnup charts alongside a curated digest of retrospective outcomes.', true),
  (2774, 1, 'تثبيت نوافذ عرض حوض السمك لبث لوحات كانبان والمخططات الخاصة بجميع فرق المشروع في الوقت الفعلي.', 'Install fishbowl windows streaming all project teams'' kanban boards and charts in real time.', false),
  (2774, 2, 'تركيب كاميرات ويب لبث لوحة كانبان لكل فريق وعرض اللقطات بالتناوب على عارض المعلومات.', 'Position webcams to broadcast each team''s kanban board and cycle the footage on the radiator.', false),
  (2774, 3, 'إنشاء صفحة ويكي داخلية تحدّثها جميع الفرق الرشيقة باستمرار ويرجع إليها المعنيون عند الحاجة.', 'Build an internal wiki page that all agile teams update continuously and stakeholders consult on demand.', false),
  (2775, 0, 'تنفيذ أدوات أتمتة الاختبارات لتسريع التنفيذ في التكرارات القادمة.', 'Implement test automation tools to accelerate execution for the upcoming iterations.', false),
  (2775, 1, 'خصّص دورةً كاملة للاختبار للتخلص من الأعمال المتراكمة المتراكمة.', 'Dedicate an entire iteration to testing to eliminate the accumulated backlog.', false),
  (2775, 2, 'اعتماد الاختبار الثنائي لتوزيع عبء العمل بين أعضاء الفريق.', 'Introduce paired testing to distribute the workload among team members.', false),
  (2775, 3, 'زيادة وتيرة تنقيح سجل الأعمال وعمقه لتحسين جاهزية القصص.', 'Increase the frequency and depth of backlog refinement to improve story readiness.', true),
  (2776, 0, 'زيادة في قيمة الأعمال المُقدَّمة لكل قصة.', 'An increase in the business value delivered per story.', false),
  (2776, 1, 'انخفاض في الوقت المطلوب لحل معوقات السباق السريع.', 'A reduction in the time required to resolve sprint impediments.', false),
  (2776, 2, 'تحسّن في عدد القصص المنجزة لكل تكرار.', 'An improvement in the number of stories completed per iteration.', true),
  (2776, 3, 'انخفاض في إجمالي عدد البنود المتبقية في سجل الأعمال.', 'A decrease in the total number of items remaining in the backlog.', false),
  (2777, 0, 'تمكين الفريق من تنظيم نفسه وبناء تأييد المعنيين من خلال إشراكهم في قرارات المشروع وتحديد الأولويات.', 'Empower the team to self-organize and build stakeholder buy-in by involving them in project decisions and priority setting.', false),
  (2777, 1, 'إنشاء احتياطي للطوارئ لامتصاص أثر فجوات التقارير المستقبلية ومخاطر سوء التواصل.', 'Establish a contingency reserve to absorb the impact of future reporting gaps and miscommunication risks.', false),
  (2777, 2, 'اشتراط أن يُكمل الفريق دورة شهادة معتمدة حول نظام التقارير الرشيق المستخدم حاليًا في المشروع.', 'Require the team to complete a certification course on the agile reporting system currently in use on the project.', false),
  (2777, 3, 'تقديم تدريب رشيق عند إطلاق المشروع وتوفير توجيه مستمر لمواءمة فهم الفريق لتقدّم العمل الرشيق.', 'Deliver agile training at project launch and provide continuous mentoring to align the team''s understanding of agile progress.', true),
  (2778, 0, 'تصعيد القلق إلى الإدارة العليا والتوصية بإعادة تعيين المورد الجديد إلى مشروع آخر.', 'Escalate the concern to senior management and recommend reassigning the new resource to a different project.', false),
  (2778, 1, 'قابل المورد الجديد لإعادة تقييم مهاراته وفهم مستوى نقاط قوته.', 'Meet with the new resource to reassess their skills and understand their strength level.', true),
  (2778, 2, 'مطالبة أعضاء الفريق بتوثيق جميع أوجه القصور المتعلقة بالمهام التي يُظهرها المورد.', 'Ask team members to document all task-related deficiencies displayed by the resource.', false),
  (2778, 3, 'إطلاع راعي المشروع على مخاوف الفريق والتحديد المشترك لأنسب مسار عمل.', 'Brief the project sponsor on the team''s concerns and jointly determine the most appropriate course of action.', false),
  (2779, 0, 'إشراك قائد الفريق لتشخيص فجوة المهارات وتطوير حل للتنفيذ الفوري.', 'Engage the team leader to diagnose the skills gap and develop a solution for immediate implementation.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2779, 1, 'حلل المتطلبات التقنية للمشروع ونظّم الفريق لضمان تمثيل المهارات الأساسية وتوزيعها.', 'Analyze the project’s technical requirements and organize the team to ensure critical skills are represented and distributed.', true),
  (2779, 2, 'إجراء تقييم للمهارات أثناء التنفيذ لتحديد الكفاءات اللازمة لتسليم المشروع.', 'Conduct a skills assessment during execution to define the competencies required for project delivery.', false),
  (2779, 3, 'الاستعانة باستشاري خارجي متخصص لتعزيز تطوير المهارات الحرجة للفريق الداخلي.', 'Engage a specialized external consultant to reinforce the development of critical skills of the internal team.', false),
  (2779, 4, 'سجِّل فجوة المهارات التي تم تحديدها بوصفها مخاطرة ضمن المشروع، وطوِّر استراتيجية تخفيف مقابلة للحدّ من تكرارها.', 'Log the identified skills gap as a project risk and develop a corresponding mitigation strategy to reduce the recurrence.', true),
  (2780, 0, 'طمئن عضو الفريق وشجِّعه على تجاوز التحديات الحالية.', 'Reassure the team member and encourage them to push through the current challenges.', false),
  (2780, 1, 'التقِ مع عضو الفريق لاستكشاف المجالات التي تتوافق فيها نقاط قوته وتحديد الدور المناسب له بشكل مشترك.', 'Meet with the team member to explore where their strengths align and jointly determine the right role for them.', true),
  (2780, 2, 'تسجيل عضو الفريق في تدريب موجّه لسد فجوة المهارات وتهيئته بشكل أفضل لمتطلبات دوره الحالي.', 'Enroll the team member in targeted training to close the skill gap and better equip them for the demands of their current role.', false),
  (2780, 3, 'إعادة تعيين عضو الفريق فورًا إلى مشروع آخر لحل مشكلات روحه المعنوية.', 'Immediately reassign the team member to a different project to resolve their morale issues.', false),
  (2781, 0, 'وجّه الفريق إلى تبنّي النهج التقني الجديد فورًا لإظهار الاستجابة لطلب صاحب المصلحة.', 'Direct the team to immediately adopt the new technical approach to demonstrate responsiveness to the stakeholder’s request.', false),
  (2781, 1, 'فوّض القرار إلى الفريق، ومكّنهم من تقييم النهج التقني والتحقق من استنتاجهم مباشرةً مع الجهة الراعية.', 'Delegate the decision to the team, empowering them to evaluate the technical approach and validate their conclusion directly with the sponsor.', false),
  (2781, 2, 'تيسير مناقشة مع المعنيين لتقييم إيجابيات النهج التقني المقترح وسلبياته لتحديد المسار الصحيح للمضي قدمًا.', 'Facilitate a discussion with stakeholders to evaluate the pros and cons of the proposed technical approach to decide the correct path forward.', true),
  (2781, 3, 'السماح للفريق بإجراء مقارنة مرجعية بين النهج التقني المقترح والنهج الحالي لبناء مبرر للحصول على تأييد الراعي.', 'Allow the team to benchmark the proposed technical approach against the current one to build a case for sponsor buy-in.', false),
  (2782, 0, 'العمل مع راعي المشروع لتيسير جلسات تدريبية لضمان اكتساب الفريق جميع المهارات المطلوبة للتسليم الناجح.', 'Work with the project sponsor to facilitate training sessions to ensure the team acquires all skills required for successful delivery.', false),
  (2782, 1, 'إجراء تقييم شامل للمهارات وإعادة هيكلة الفريق وفقًا للكفاءات التي يتطلبها كل دور.', 'Conduct a comprehensive skills assessment and re-structure the team around the competencies each role demands.', true),
  (2782, 2, 'تحديث خطة إدارة الموارد لمعالجة فجوة المهارات والتنسيق مع الراعي لترتيب التدريب عند ظهور أوجه القصور.', 'Update the resource management plan to reconcile the skills gap and coordinate with the sponsor to arrange training as deficiencies surface.', false),
  (2782, 3, 'تشجيع أعضاء الفريق على الاستفادة من مهاراتهم الحالية بشكل إبداعي للتغلب على أي فجوات يواجهونها أثناء المشروع.', 'Encourage team members to leverage their existing skills creatively to work around any gaps they encounter during the project.', false),
  (2783, 0, 'استعن بمترجم لسد فجوة اللغة وتمكين الفريق البعيد من تولّي كامل الأعمال المتراكمة دون إجراء أي تغييرات.', 'Engage an interpreter to bridge the language gap and enable the remote team to take on the full backlog without changes.', false),
  (2783, 1, 'أَعِد توجيه جميع قصص قابلية الاستخدام إلى أعضاء الفريق المحليين المتبقين، واسمح للفريق البعيد بمواصلة العمل بشكل مستقل على القصص التقنية.', 'Redirect all usability stories to the remaining local team members and allow the remote team to continue working independently on technical stories.', false),
  (2783, 2, 'تيسير مناقشة مع مالك المنتج لتوضيح متطلبات قابلية الاستخدام وإعادة تحديد أولويات سجل الأعمال.', 'Facilitate a discussion with the product owner to clarify the usability requirements and re-prioritize the backlog.', true),
  (2783, 3, 'استبدال الفريق الحالي بمجموعة مقاولين مختلفة تتمتع بمهارات أقوى في قابلية الاستخدام والفهم التقني.', 'Replace the current team with a different contractor group that has stronger usability and technical comprehension skills.', false),
  (2784, 0, 'تتبّع معدل العيوب التي يتم اكتشافها أثناء الاختبار كمؤشر على الجودة العامة للفريق والعمق التقني.', 'Track the rate of defects detected during testing as an indicator of overall team quality and technical depth.', false),
  (2784, 1, 'راقب تكرار إعادة إسناد المهام لتقييم مدى قدرة أعضاء الفريق على الانتقال إلى أنواع مختلفة من العمل.', 'Monitor the frequency of task reassignments to assess how flexible team members can shift to different types of work.', true),
  (2784, 2, 'تقييم حجم جلسات تبادل المعرفة الداخلية كمقياس للتعاون متعدد الوظائف واتساع المهارات.', 'Assess the volume of internal knowledge sharing sessions as a measure of cross-functional collaboration and skill breadth.', false),
  (2784, 3, 'مراقبة وتيرة التعاون مع الخبراء المتخصصين لقياس مدى حاجة الفريق إلى طلب خبرة خارجية.', 'Observe the frequency of collaboration with subject matter experts to gauge how often the team needs to seek outside expertise.', false),
  (2785, 0, 'تيسير جلسة مراجعة مع فريق المشروع الأوسع لمشاركة أسباب القرارات وتوثيق الدروس المستفادة.', 'Facilitate a retrospective with the broader project team to share reasoning and document the lessons learned.', true),
  (2785, 1, 'رتّب مراجعةً للفريق لتحديد الثغرات في تعريف الإنجاز التي سمحت لوصول حل غير مختبَر إلى بيئة الإنتاج.', 'Arrange a team review to identify gaps in the definition of done that allowed an untested solution to reach production.', true),
  (2785, 2, 'إصدار تحذير رسمي لعضو الفريق لقيامه بمفرده بإصلاح عالي المخاطر دون موافقة مسبقة.', 'Issue a formal warning to the team member for independently taking on a high-risk fix without prior approval.', false),
  (2785, 3, 'تيسير مراجعة جماعية لتحديد الفجوات في تعريف المنجز التي قد تكون أسهمت في بقاء العائق دون حل.', 'Facilitate a team review to identify gaps in the definition of done that may have contributed to the blocker going unresolved.', false),
  (2785, 4, 'أبلغ مدير الجودة بأن العيوب جزء متأصل من عملية تطوير البرمجيات، وأن الفريق سيتولى معالجة المشكلة.', 'Inform the quality director that defects are an inherent part of software development and that the team will address the issue.', false),
  (2786, 0, 'لم يتدخل مدير المشروع في وقت مبكر بما يكفي لحماية فريق المشروع من الضغوط الخارجية.', 'The project manager did not intervene early enough to shield the project team from external pressures.', false),
  (2786, 1, 'قبل أعضاء الفريق التزامات الإطلاق التي تجاوزت قدرتهم دون تصعيد مخاوفهم.', 'The team members accepted sprint commitments that exceeded their capacity without escalating their concerns.', false),
  (2786, 2, 'ملأ مالك المنتج سجل أعمال الإطلاق بعمل يفوق ما تستطيع قدرة الفريق وسرعته الإنتاجية تحمّله.', 'The product owner populated the sprint backlog with more work than the team''s capacity and velocity could support.', false),
  (2786, 3, 'لم يحمِ سكرم ماستر وتيرة عمل الفريق أو يعترض على الإفراط في الالتزام أثناء تخطيط الإطلاق.', 'The scrum master did not safeguard the team''s pace or challenge the overcommitment during sprint planning.', true),
  (2787, 0, 'تنقيح عناصر سجل الأعمال وفقًا للقيمة التجارية والأولوية لتوجيه عمل الفريق القادم.', 'Refining the backlog items by business value and priority to guide the team''s upcoming work.', false),
  (2787, 1, 'تيسير جلسات تنقيح سجل الأعمال للحفاظ على تهذيبها وجاهزيتها للسباق السريع.', 'Facilitating backlog refinement sessions to keep the backlog groomed and sprint ready.', false),
  (2787, 2, 'التعاون أثناء تخطيط الإطلاق لاختيار البنود ذات الأولوية القصوى من سجل الأعمال والالتزام بها.', 'Collaborating during sprint planning to select and commit to the highest priority items from the backlog.', true),
  (2787, 3, 'تسجيل بنود سجل الأعمال الجديدة المحددة عبر ملاحظات المعنيين وتنقيحها قبل إعادة تحديد الأولويات.', 'Capturing and refining new backlog items identified through stakeholder feedback before reprioritization.', false),
  (2788, 0, 'قيِّم كفاءات الفريق المُشكَّل حديثًا مقارنة بمتطلبات المهارات الحرجة في المشروع.', 'Evaluate the competencies of the newly assembled team against the project''s critical skill requirements.', false),
  (2788, 1, 'صمّم تفاعلات منظَّمة لتسريع أداء الفريق، وفرص التعاون، والتماسك.', 'Design structured interactions to accelerate team performance, collaboration opportunities, and cohesion.', false),
  (2788, 2, 'تقديم تدريب موجّه لمعالجة أي فجوات في المهارات يجري تحديدها داخل الفريق المُشكَّل حديثًا.', 'Deliver targeted training to address any skill gaps identified within the newly formed team.', false),
  (2788, 3, 'إعداد جدول زمني تفصيلي للمشروع لتحديد المواعيد والاعتماديات ومعالم التسليم.', 'Develop a detailed project schedule to establish timelines, dependencies, and delivery milestones.', true),
  (2789, 0, 'يسّر التدريب لسد فجوات المهارات وزيادة وضوح العمل، بحيث يفهم جميع أعضاء الفريق بوضوح أولوياتهم وما عليهم تسليمه.', 'Facilitate training to close skill gaps and increase work visibility, so all team members clearly understand their priorities and deliverables.', true),
  (2789, 1, 'إعادة تموضع الموارد العليا بصفتهم مرشدين لنقل المعرفة والمساهمة في تطوير الأعضاء الأقل خبرة.', 'Reposition senior resources as mentors to transfer knowledge and contribute to the development of less experienced members.', false),
  (2789, 2, 'تقديم حوافز لأعضاء الفريق الأقل خبرة لزيادة سرعة إنتاجهم وإرسال بريد إلكتروني إلى الموارد الأقدم بشأن أدائهم.', 'Offer incentives to junior team members to increase their output speed and send an email to senior resources addressing their performance.', false),
  (2789, 3, 'إعادة مواءمة أهداف عضو الفريق الأقل خبرة وأدواره ومواعيده في اجتماع الفريق المقرَّر التالي.', 'Realign the less experienced team member’s project goals, roles, and timelines during the next scheduled team meeting.', false),
  (2790, 0, 'تدريب ودعم الأعضاء الجدد من خلال تسهيل جلسة تعريف مخصصة لتمكينهم من مواكبة سير العمليات التجارية.', 'Train and support the new members by facilitating a dedicated onboarding session to bring them up to speed on business operations.', true),
  (2790, 1, 'طمئن أعضاء الفريق الجدد إلى أنهم مُشجَّعون على طلب المساعدة من كلٍّ من الأعضاء القدامى ومدير المشروع كلما دعت الحاجة.', 'Reassure new team members that they are encouraged to seek help from both long-term members and the project manager whenever needed.', false),
  (2790, 2, 'استبدال الموارد الجدد بموارد أكثر خبرة تمتلك بالفعل المعرفة المطلوبة بعمليات الأعمال.', 'Replace the new resources with more experienced ones who already possess the required knowledge of the business operations.', false),
  (2790, 3, 'الإقرار بانخفاض الإنتاجية كنتيجة طبيعية وتعديل الجدول الزمني للمشروع لاستيعاب التباطؤ المؤقت.', 'Acknowledge the productivity dip as a natural consequence and adjust the project schedule to accommodate the temporary slowdown.', false),
  (2791, 0, 'إعادة تعيين أعضاء الفريق غير المدربين إلى مشاريع أخرى، وسدّ الشواغر في أدوارهم بموارد تمتلك خبرة سابقة في المنهجيات الرشيقة.', 'Reassign untrained team members to other projects and backfill their roles with resources who already have agile experience.', false),
  (2791, 1, 'تحقق من أن احتياطي الطوارئ الخاص بالمشروع يحتوي على أموال كافية لتغطية التدريب الإلزامي على المنهجيات الرشيقة لجميع أعضاء الفريق قبل المتابعة.', 'Verify that the project''s contingency reserve contains sufficient funds to cover mandatory agile training for all team members before proceeding.', false),
  (2791, 2, 'تطوير جلسات تدريب عبر الإنترنت تستهدف أعضاء الفريق الرئيسيين حول أهم المفاهيم الرشيقة اللازمة للمرحلة المقبلة.', 'Develop online training sessions targeting key team members on the most critical agile concepts needed for the upcoming phase.', false),
  (2791, 3, 'تقييم خيارات التدريب الرشيق المتاحة وتطبيق حل يوازن بين فعالية التكلفة واحتياجات الفريق.', 'Evaluate available agile training options and implement a solution that balances cost effectiveness with the team''s needs.', true),
  (2792, 0, 'دمج الموارد الجديدة وتزويدها بالمعرفة المطلوبة لتنفيذ طلب مراجعة الميزة ضمن الجدول الزمني الحالي.', 'Onboard new resources with the required knowledge to fulfill the feature revision request within the existing schedule.', false),
  (2792, 1, 'التوصية بوضع المشروع قيد الانتظار حتى يتوصل المعنيون إلى قرار حاسم بشأن تعديل الميزة.', 'Recommend placing the project on hold until stakeholders reach a definitive decision on the feature revision.', false),
  (2792, 2, 'إشراك راعي المشروع في مناقشة منظمة لتقييم جميع الخيارات المتاحة واختيار المسار الأكثر جدوى للمضي قدمًا.', 'Engage the project sponsor in a structured discussion to evaluate all available options and select the most viable path forward.', true),
  (2792, 3, 'الاعتراض على طلب مالك المنتج وتكليف جهة بإجراء أبحاث للعملاء للتحقق مما إذا كان تعديل الميزة الجديد يحقق قيمة سوقية كافية.', 'Push back on the product owner''s request and commission customer research to validate whether the new feature revision delivers sufficient market value.', false),
  (2793, 0, 'تيسير التدريب من أجل تعزيز قدرة الفريق على تقدير نقاط القصص وتحديد التزامات واقعية للسبرت.', 'Facilitate coaching to strengthen the team''s ability to estimate story points and set realistic sprint commitments.', true),
  (2793, 1, 'تسريع التسليم عن طريق تقليل عدد بنود سجل الأعمال لتخفيف الضغط عن الفريق المتدني الأداء.', 'Accelerate delivery by reducing the number of backlog items to relieve pressure on the underperforming team.', false),
  (2793, 2, 'تمديد الجدول الزمني للمشروع بإضافة المزيد من التكرارات لإيجاد قدرة إضافية لإنجاز نقاط القصة.', 'Extend the project timeline by adding more iterations to create additional capacity for story point completion.', false),
  (2793, 3, 'الاستفادة من مخططات الإنجاز التنازلي والتصاعدي لتقييم اتجاهات أداء الفريق وتتبّع إنجاز نقاط القصة.', 'Leverage burndown and burnup charts to assess team performance trends and track story point completion.', true),
  (2793, 4, 'زيادة الميزانية للتعاقد مع خبير متخصص في الموضوع (SME) لقيادة جلسات التيسير ونقل المخاطر.', 'Increase the budget to contract a subject matter expert (SME) to lead facilitation sessions and transfer the risk.', false),
  (2794, 0, 'قدّم طلب تغيير رسميًا لتوثيق وتفويض التدريب الرشيق المطلوب ضمن الوقت المتاح.', 'Submit a formal change request to document and authorize the agile training needed within the available time.', false),
  (2794, 1, 'تصعيد فجوة المهارات إلى راعي المشروع باعتبارها مشكلة على مستوى الشركة تتطلب تدخلًا تنظيميًا فوريًا.', 'Escalate the skills gap to the project sponsor as a company-wide issue requiring immediate organizational intervention.', false),
  (2794, 2, 'الاستفادة من أعضاء الفريق ذوي الخبرة كموجّهين لتسريع نقل المعرفة وبناء قدرة الفريق من الداخل.', 'Leverage the experienced team members as mentors to accelerate knowledge transfer and build the team''s capability from within.', true),
  (2794, 3, 'تقييم خيارات التدريب الرشيق المتاحة وتطبيق الحل الأكثر فعالية من حيث التكلفة الذي يلبي احتياجات الفريق ضمن الوقت المتاح.', 'Evaluate available agile training options and implement the most cost-effective solution that meets the team''s needs within the available time.', false),
  (2795, 0, 'الْتَقِ بقائد الفريق لتقييم ما إذا كانت خطورة مشكلات الأداء تستدعي التصعيد إلى راعي المشروع.', 'Meet with the team leader to assess whether the severity of the performance issues warrants escalation to the project sponsor.', false),
  (2795, 1, 'إطلاق برنامج تدريبي على مستوى الشركة يركّز على ممارسات العمل الفعّالة وإنجاز المهام في الوقت المناسب لجميع أعضاء الفريق.', 'Roll out a company-wide training program focused on efficient working practices and timely task completion for all team members.', false),
  (2795, 2, 'التعاون مع الفريق للتصميم المشترك لتدريب موجّه وقائمة فحص لإنجاز المهام تواءم العمل الفردي مع أهداف المشروع.', 'Collaborate with the team to co-design targeted training and a task completion checklist that aligns individual work with project goals.', true),
  (2795, 3, 'إعداد قائمة فحص موحدة للمهام وتوزيعها على جميع أعضاء الفريق لتحسين الاتساق والتركيز داخل المشروع.', 'Develop and distribute a standardized task checklist to all team members to improve consistency and focus within the project.', false),
  (2795, 4, 'إقامة جلسات إرشاد منظَّمة تُقرِن بين الكفاءات senior والزملاء junior لنقل المعرفة ومواءمة الجهود مع أولويات المشروع.', 'Establish structured mentoring sessions that pair senior resources with junior colleagues to transfer knowledge and align effort with project priorities.', true),
  (2796, 0, 'وجّه أعضاء الفريق الجدد إلى طلب الإرشاد من الأعضاء القدامى كلما واجهوا ثغرات في فهمهم لعمليات الشركة.', 'Direct newer team members to seek guidance from long-term members whenever they encounter gaps in their understanding of company operations.', false),
  (2796, 1, 'الاستفادة من أعضاء الفريق الحاليين لدعم الأعضاء الأحدث وعقد جلسة تدريبية لمواءمتهم مع معرفة العمليات الخاصة بالمشروع.', 'Leverage current team members to support newer members and conduct a training session to align them with project-specific operations knowledge.', true),
  (2796, 2, 'سد شواغر الفريق بموارد تمتلك المعرفة التشغيلية، وإعادة تعيين الأعضاء الجدد، وتوثيق فجوة التوظيف في سجل الدروس المستفادة.', 'Backfill the team with resources who possess operational knowledge, reassign the new members, and capture the staffing gap in the lessons learned register.', false),
  (2796, 3, 'قبول انخفاض الإنتاجية كنتيجة متوقعة لتوسّع الفريق وتحليل الجدول الزمني للمشروع لتحديد كيفية استيعاب الأثر.', 'Accept the productivity decline as an expected consequence of team expansion and analyze the project schedule to determine how to absorb the impact.', false),
  (2797, 0, 'توزيع العمل المتخصص على الفريق القائم من خلال تكليفهم بساعات عمل إضافية لتعويض غياب المورد.', 'Distribute the specialized work to the existing team by assigning overtime to compensate for the resource''s absence.', false),
  (2797, 1, 'تقليص نطاق المشروع لحذف العمل الذي يعتمد على المورد المتخصص غير المتوفر.', 'Reduce the project scope to eliminate the work that depends on the unavailable specialized resource.', false),
  (2797, 2, 'تأجيل المشروع لمدة تأخير التأشيرة واستئنافه بمجرد توفر المورد في الموقع.', 'Postpone the project by the duration of the visa delay and resume once the resource is available onsite.', false),
  (2797, 3, 'إشراك المورد فورًا بطلب أن يعمل عن بُعد إلى أن يُحَلّ وضع التأشيرة.', 'Engage the resource immediately by requesting they work remotely until the visa situation is resolved.', true),
  (2798, 0, 'اعرض النزاع على راعي المشروع وطوروا معًا استراتيجية استجابة لمعالجة تأثير قرار إعادة التعيين على المشروع.', 'Bring the conflict to the project sponsor and jointly develop a response strategy to address the reassignment decision impact on the project.', false),
  (2798, 1, 'تطبيق أساليب التوجيه لإعادة تنشيط الفريق واستعادة الثقة عقب فقدان عضو الفريق الرئيسي.', 'Apply coaching techniques to reenergize the team and rebuild confidence following the loss of the key team member.', false),
  (2798, 2, 'البحث الفوري عن مورد بديل بمهارات مكافئة وضمه لسد الفجوة التي خلّفها عضو الفريق الرئيسي المغادر.', 'Immediately source and onboard a replacement resource with equivalent skills to fill the gap left by the departing key team member.', false),
  (2798, 3, 'التحقق من مخاوف الفريق وإجراء تحليل شامل للأثر لفهم كيفية تأثير إعادة التعيين على تسليم المشروع.', 'Validate the team''s concern and conduct a thorough impact analysis to understand how the reassignment affects project delivery.', true),
  (2799, 0, 'قيّم قدرات المورد الجديد من خلال ملاحظة مدى فعاليته في التواصل مع فريق المشروع الحالي.', 'Assess the new resource''s capabilities by observing how effectively they communicate with the existing project team.', false),
  (2799, 1, 'إجراء تقييم منظم للمورد الجديد لتحديد كيفية إسهامه في المشروع بشكل موضوعي.', 'Conduct a structured evaluation of the new resource to objectively determine how they can contribute to the project.', true),
  (2799, 2, 'تقديم طلب إلى مكتب إدارة المشاريع (PMO) لاستبدال المورد الجديد بمرشح آخر.', 'Submit a request to the project management office (PMO) to replace the new resource with another candidate.', false),
  (2799, 3, 'معالجة المشكلة مباشرة مع المدير الوظيفي للمورد الجديد لمنعها من إحداث نزاع داخل فريق المشروع.', 'Address the issue directly with the new resource''s functional manager to prevent it from creating conflict within the project team.', false),
  (2800, 0, 'الاستعانة بمختصين من جهات خارجية لتحديد مجالات التحسين وتعزيز القدرات التقنية للفريق.', 'Engage third-party specialists to identify the areas of improvement and supplement the team''s technical capabilities.', false),
  (2800, 1, 'استخدام اجتماع التنسيق اليومي التالي لتعزيز أهمية التعاون وتشجيع أعضاء الفريق على العمل معًا.', 'Use the next daily coordination meeting to reinforce the importance of collaboration and encourage team members to work together.', false),
  (2800, 2, 'دمج موارد متعددة الوظائف والتواصل بشأن كيفية تعزيز تنوّعها لقدرة الفريق وتعاونه بشكل عام.', 'Integrate cross-functional resources and communicate how their diversity strengthens the team’s overall capability and collaboration.', true),
  (2800, 3, 'استبدال مخططات جانت بلوحات كانبان لجعل الاعتماديات المتبادلة للعمل شفافة ودفع سلوك أكثر تعاونًا داخل الفريق بشكل طبيعي.', 'Replace Gantt charts with kanban boards to make work interdependencies transparent and naturally drive more collaborative behavior within the team.', false),
  (2801, 0, 'قدّم موجزًا للراعي المشروع حول عدم موافقة الفريق، وتعاون معه على تطوير استجابة مناسبة لإعادة التكليف.', 'Brief the project sponsor on the team''s disapproval and collaborate on developing an appropriate response to the reassignment.', false),
  (2801, 1, 'تطبيق أساليب القيادة والذكاء العاطفي للإقرار بمشاعر الفريق وإعادة تنشيط التزامهم.', 'Apply leadership and emotional intelligence techniques to acknowledge the team''s feelings and reenergize their commitment.', true),
  (2801, 2, 'ضمّ مورد بديل بمهارات مكافئة لسد الفجوة التي خلّفها عضو الفريق المغادر.', 'Onboard a replacement resource with equivalent skills to fill the gap left by the departing team member.', false),
  (2801, 3, 'تنظيم نشاط لبناء الفريق لرفع الروح المعنوية وتحويل تركيز الفريق بعيدًا عن إعادة تعيين عضو الفريق.', 'Organize a team-building activity to boost morale and shift the team''s focus away from the team member’s reassignment.', false),
  (2802, 0, 'تقديم مورد جديد يمتلك مجموعة المهارات المطلوبة وتحديد كيفية مساهمته في المشروع.', 'Introduce a new resource with the required skill set and identify how they can contribute to the project.', false),
  (2802, 1, 'مطالبة المورد الحالي بإيجاد مرشح بديل مؤهل قبل مغادرته.', 'Demand the current resource find a qualified replacement candidate before their departure.', false),
  (2802, 2, 'تحليل أثر المشروع واعتماد خطة لتقييم المخاطر للتخفيف من أي أثر مستقبلي محتمل.', 'Analyze the project impact and introduce a risk assessment plan to mitigate any potential future impact.', true),
  (2802, 3, 'إشراك الفريق بأكمله في الاختيار الفعّال لمورد جديد ليحل محل المورد المغادر.', 'Engage the whole team in actively choosing a new resource to replace the departing one.', false),
  (2803, 0, 'قم بإسناد المهام إلى الأعضاء المتناوبين، مع منحهم مزيدًا من التحكم في توزيع عبء العمل.', 'Assign tasks to rotating members, giving them greater control over workload distribution.', false),
  (2803, 1, 'تقييد عدد أعضاء الفريق الذين يمكنهم التناوب للانضمام إلى فريق المشروع الدائم.', 'Limit the number of team members that can rotate into the permanent project team.', false),
  (2803, 2, 'منح الأعضاء الدائمين الأولوية في اختيار المهام لحمايتهم من حالة عدم التيقن التي يُدخلها الموظفون المتناوبون.', 'Give permanent members priority in selecting tasks to shield them from the uncertainty introduced by rotating staff.', false),
  (2803, 3, 'مطالبة الموظفين المتناوبين بتيسير ورشة عمل منظمة لتبادل المعرفة قبل المغادرة لتقليل الفجوات.', 'Require rotating staff to facilitate a structured knowledge sharing workshop before leaving to minimize the gaps.', true),
  (2804, 0, 'الْتَقِ بفريقين كليهما بشكل مستقل، وكلف كلاً منهما بوضع حله الخاص لتلبية المواعيد النهائية المطلوبة.', 'Meet with both teams independently and task each of them with developing their own solution to meet the required deadlines.', false),
  (2804, 1, 'إعادة تحديد أولويات سجل أعمال التكرار، بالاشتراك مع مالك المنتج، بطريقة تعالج التحدي دون المساس بالتزامات الفريق.', 'Reprioritize the iteration backlog, with the product owner, in a way that addresses the challenge without compromising team obligations.', true),
  (2804, 2, 'توسيع قدرة الفريق بإضافة موارد وتمديد مدة التكرار لضمان إنجاز العمل وفق الجدول الأصلي.', 'Expand the team''s capacity by adding resources and extending the iteration length to ensure the work is completed as originally scheduled.', false),
  (2804, 3, 'الإقرار للفريق بصعوبة الموقف، وتوثيق التحديات التي ووجهت، ومعاودة النظر فيها أثناء التقييم الرجعي التالي.', 'Acknowledge the difficulty of the situation to the team, document the challenges encountered, and revisit them during the next retrospective.', false),
  (2805, 0, 'تصعيد مسألة نقص الموارد إلى راعي المشروع وطلب تدخّله لتأمين الدعم الفني اللازم.', 'Escalate the resource shortage to the project sponsor and request their intervention in securing the necessary technical support.', false),
  (2805, 1, 'رفع المشكلة فورًا إلى القيادة العليا لبدء استجابة رسمية للجدول الزمني المضغوط وفجوة الموارد.', 'Immediately raise the issue to senior leadership to initiate a formal response to the compressed timeline and resource gap.', false),
  (2805, 2, 'التحقق داخليًا مع مديري الموارد البشرية لاستكشاف جميع خيارات إعادة تخصيص الموارد الممكنة.', 'Check internally with human resource managers to explore all possible resource reallocation options.', true),
  (2805, 3, 'الاستعانة بمقاول خارجي لتلبية متطلب الموارد والوفاء بالموعد النهائي المُعجَّل.', 'Engage an external contractor to fulfill the resource requirement and meet the accelerated deadline.', false),
  (2806, 0, 'اسمح للفريق بمواصلة العمل وتعويض تعطل لوحة المعلومات من خلال إرسال تحديثات يومية عن التقدم عبر البريد الإلكتروني.', 'Allow the team to continue working and compensate for the dashboard failure by sending daily progress updates via email.', false),
  (2806, 1, 'تقييم عطل لوحة المعلومات في ضوء أولويات التكرار المقبلة وترتيب حلّه وفقًا لقيمته للأعمال.', 'Evaluate the dashboard failure against upcoming iteration priorities and rank its resolution according to its business value.', false),
  (2806, 2, 'تصعيد عطل لوحة المعلومات إلى الجهة المعنية وضمان استعادتها لكامل وظائفها في أسرع وقت ممكن.', 'Escalate the dashboard failure to the appropriate party and ensure it is restored to full functionality as quickly as possible.', true),
  (2806, 3, 'تسجيل عطل لوحة المعلومات كمخاطرة جديدة للمشروع ووضع حل مقترح لمراجعة المعنيين قبل المتابعة.', 'Log the dashboard failure as a new project risk and develop a proposed solution for stakeholder review before proceeding.', false),
  (2807, 0, 'قم فورًا بإلحاق مورد بديل ليتولى مهام عضو الفريق الغائب.', 'Immediately onboard a replacement resource to take over the absent team member''s tasks.', false),
  (2807, 1, 'إشراك المدير الوظيفي لعضو الفريق لمناقشة الغياب والتماس مساعدته في تخفيف مخاطر الجدول الزمني.', 'Engage the team member''s functional manager to discuss the absence and solicit their assistance in mitigating the schedule risk.', true),
  (2807, 2, 'الاتصال بعضو الفريق مباشرة لمعالجة مساءلته وتذكيره بالتزامه.', 'Contact the team member directly to address their accountability and remind them of their commitment.', false),
  (2807, 3, 'مطالبة عضو فريق تربطه علاقة وثيقة بالشخص الغائب بتحديد مكانه والإبلاغ بأي معلومات متاحة.', 'Ask a team member with a close relationship to the absent individual to locate them and report back with any available information.', false),
  (2808, 0, 'حث الدولة ب على تكثيف جهودها وإعطاء أولوية للإنجاز في الوقت المحدد لتجنب حدوث تأخيرات متتالية بالنسبة للدولة أ.', 'Urge Country B to intensify their efforts and prioritize on-time completion to avoid cascading delays for Country A.', false),
  (2808, 1, 'تيسير جلسة تعاون عبر الإنترنت لتشخيص المشكلة بشكل مشترك ووضع حل يحمي الجدول الزمني المشترك للتسليم.', 'Facilitate an online collaboration session to jointly diagnose the problem and develop a solution that protects the shared delivery timeline.', true),
  (2808, 2, 'تمديد مدة التكرار ودعم الدولة (ب) بإضافة موارد إضافية لضمان قدرتهم على الوفاء بالموعد النهائي.', 'Extend the iteration length and support Country B by adding additional resources to ensure they can meet the deadline.', false),
  (2808, 3, 'تشجيع كلا الفريقين على الأداء بأقصى قدراتهما أثناء التكرار ومعالجة السبب الجذري للتأخير أثناء التقييم الرجعي التالي.', 'Encourage both teams to perform to their optimum abilities during the iteration and address the root cause of the delay during the next retrospective.', false),
  (2809, 0, 'تواصل مباشرةً مع المورّد ووضّح تأثير التأخير على الجدول الزمني والعواقب المترتبة على استمرار التأخير بعبارات واضحة وغير ملتبسة.', 'Contact the vendor directly and communicate the schedule impact and consequences of continued delays in clear, unambiguous terms.', false),
  (2809, 1, 'إنشاء مساحة عمل مشتركة عبر الإنترنت تجعل المهام والمواعيد النهائية والمساءلة مرئية للفريق والبائع ومالك المنتج فوريًا.', 'Establish a shared online workspace that makes tasks, deadlines, and accountability visible to the team, vendor, and product owner in real time.', true),
  (2809, 2, 'التعاون مع المشتريات لمراجعة اتفاقية خدمة المورِّد لتضمين أحكام وشروط محددة قابلة للإنفاذ مرتبطة بأداء الجدول الزمني.', 'Partner with procurement to revise the vendor''s service agreement to include specific, enforceable terms and conditions tied to schedule performance.', false),
  (2809, 3, 'مطالبة مالك المنتج بالاستفادة من نفوذه الشخصي وعلاقته التجارية لإعادة إشراك البائع واستعادة الزخم.', 'Ask the product owner to leverage their personal influence and business relationship to re-engage the vendor and restore momentum.', false),
  (2810, 0, 'الشروع في عملية استبدال عضو الفريق لحماية المسار الحرج ومنع مزيد من تدهور الجدول الزمني.', 'Initiate the replacement process for the team member to protect the critical path and prevent further schedule deterioration.', false),
  (2810, 1, 'إجراء محادثة متعاطفة مع عضو الفريق لفهم الموقف وتحديد حل يدعم رفاهه واحتياجات المشروع معًا.', 'Have an empathetic conversation with the team member to understand the situation and identify a solution that supports both their wellbeing and the project''s needs.', true),
  (2810, 2, 'تصعيد الموقف إلى الموارد البشرية (HR) وإعادة توزيع عبء العمل بإسناد ساعات عمل إضافية إلى أعضاء الفريق الآخرين.', 'Escalate the situation to human resources (HR) and redistribute the workload by assigning overtime to other team members.', false),
  (2810, 3, 'طلب دعم إضافي بالموارد من المدير الوظيفي، بما في ذلك إمكانية تعيين مورد جديد لاستيعاب الأثر على المسار الحرج.', 'Request additional resource support from the functional manager, including the potential assignment of a new resource to absorb the impact on the critical path.', false),
  (2811, 0, 'أزل التحديات من خلال حلّ مشكلات عملية الأعمال المعلّقة بنفسك، مع إعادة توجيه تركيز الفريق نحو نشاط لبناء الفريق.', 'Remove the challenges by personally resolving the pending business process issues while redirecting the team''s focus toward a team-building activity.', false),
  (2811, 1, 'تخصيص التكرار التالي بالكامل لتدريب الفريق على عمليات الأعمال ذات الصلة لبناء استقلاليته في التعامل معها.', 'Dedicate the next iteration entirely to training the team on the relevant business processes to build their autonomy in navigating them.', false),
  (2811, 2, 'التعاون مع أصحاب العمليات لتبسيط العمليات وتزويد الفريق بتوجيه موجّه حول كيفية العمل ضمنها بفعالية.', 'Collaborate with process owners to streamline processes and equip the team with targeted coaching on how to work within them effectively.', true),
  (2811, 3, 'العمل مع الفريق على تضخيم تقديرات نقاط القصة في سجل الأعمال لإدراج وقت احتياطي يقاوم التأخيرات الناتجة عن عمليات الأعمال.', 'Work with the team to inflate story point estimates in the backlog to build in buffer time that counteracts delays caused by the business processes.', false),
  (2812, 0, 'اطلب تعويضًا ماليًا من رئيس القسم يتناسب مع التأخيرات التراكمية التي تسبب فيها نقص تعاونهم.', 'Request budgetary compensation from the department head proportional to the cumulative delays their lack of cooperation has caused.', false),
  (2812, 1, 'إجراء تحليل للمعنيين لتحديد معني رفيع المستوى أو راعٍ يمكنه التأثير على موقف رئيس القسم.', 'Conduct a stakeholder analysis to identify a senior stakeholder or sponsor who can influence the department head''s position.', true),
  (2812, 2, 'تمكين أعضاء الفريق من تحديد وإشراك معنيين بدلاء يمكنهم المساعدة في تجاوز عوائق رئيس القسم.', 'Empower team members to identify and engage alternative stakeholders who can help navigate around the department head''s barriers.', false),
  (2812, 3, 'نشر عارض معلومات يرتّب المعنيين حسب مستوى دعمهم الفعّال لإظهار مقاومة رئيس القسم علنًا.', 'Deploy an information radiator that ranks stakeholders by their level of active support to publicly surface the department head''s resistance.', false),
  (2813, 0, 'الدرجة التي يمكن لفريق المشروع من خلالها التحكم بنشاط في الخطر والاستجابة له.', 'The degree to which the project team can actively control and respond to a risk.', false),
  (2813, 1, 'طول المدة التي يمكن أن تظل فيها المخاطرة غير مكتشفة قبل أن يصبح أثرها مرئيًا للفريق.', 'The length of time a risk can remain undetected before its impact becomes visible to the team.', false),
  (2813, 2, 'مدى تسبّب مصدر مخاطرة واحد في إحداث آثار متعددة مترابطة داخل المشروع.', 'The extent to which a single risk source triggers multiple related impacts within the project.', true),
  (2813, 3, 'القابلية للتنبؤ بكيفية استجابة المخاطرة لجهود التخفيف التي يبذلها الفريق بمجرد تحديدها.', 'The predictability of how a risk will respond to the team''s mitigation efforts once identified.', false),
  (2814, 0, 'حدد موعدًا لاجتماع مع مدير ضمان الجودة لعرض مخاوفه، والاتفاق على التوقعات المتبادلة، وبناء أساس للتعاون.', 'Schedule a meeting with the QA manager to surface their concerns, align on mutual expectations, and build a foundation for collaboration.', true),
  (2814, 1, 'مطالبة راعي المشروع بإبلاغ مدير ضمان الجودة رسميًا بالمبرر الاستراتيجي وراء مبادرة أتمتة الاختبار.', 'Ask the project sponsor to formally communicate the strategic rationale behind the test automation initiative to the QA manager.', false),
  (2814, 2, 'تقديم أدلة قائمة على البيانات إلى مدير ضمان الجودة تعيد تأطير الأتمتة من كونها مخاطرة إلى تحسين تنظيمي.', 'Present data-driven evidence to the QA manager that reframes automation from a risk to an organizational improvement.', true),
  (2814, 3, 'التسجيل الرسمي لمخاطرة احتمال حجب مهندسي الاختبار الأقدمين أو عدم توفرهم بسبب مقاومة مدير ضمان الجودة.', 'Formally log the risk that senior test engineers may be withheld or unavailable due to the QA manager''s resistance.', false),
  (2814, 4, 'التعاون مع راعي المشروع لإعادة صياغة ميثاق المشروع بطريقة تعالج مخاوف مدير ضمان الجودة وتقلل من مستوى الإحساس بالتهديد.', 'Collaborate with the project sponsor to reframe the project charter in a way that addresses the QA manager''s concerns and reduces the threat perception.', false),
  (2815, 0, 'قم بإشراك أعضاء الفريق الحاليين لرفع مهاراتهم بسرعة واستيعاب مهام عمل الموارد غير المتاحة.', 'Engage current team members to rapidly upskill and absorb the work of the unavailable resources.', false),
  (2815, 1, 'التواصل مع راعي المشروع لطلب تمويل إضافي لتوظيف مقاولين خارجيين كبديل عن الموارد الملتزمة.', 'Approach the project sponsor to request additional funding to hire external contractors as an alternative to the committed resources.', false),
  (2815, 2, 'الاتصال بالموارد مباشرة لإقناعها بالانضمام إلى الفريق أو الموافقة على تقديم التوجيه ونقل المعرفة إلى الفريق الحالي.', 'Contact the resources directly to persuade them to join the team or agree to provide coaching and knowledge transfer to the existing team.', false),
  (2815, 3, 'الدخول في مفاوضة مباشرة لاستكشاف خيارات إعادة تخصيص الموارد المطلوبة أو مشاركتها.', 'Engage in a direct negotiation to explore options for reallocating or sharing the required resources.', true),
  (2816, 0, 'يتطلب الحصول على موافقة رسمية من الفريق بعد كل تغيير في المتطلبات لضمان التوافق قبل المضي قدمًا.', 'Require a formal sign-off from the team after each change to the requirements to ensure alignment before moving forward.', false),
  (2816, 1, 'تخصيص موارد إضافية لاختبار المنتج عقب كل تغيير في المتطلبات لاكتشاف الفجوات قبل التسليم.', 'Allocate additional resources to product testing following each requirement change to catch the gaps before delivery.', false),
  (2816, 2, 'إشراك العميل بفاعلية طوال العروض التوضيحية للتكرار والتأكد من فهمه لدوره في اعتماد التسليمات في كل مرحلة.', 'Actively engage the customer throughout the iteration demos and ensuring they understood their role in approving deliverables at each stage.', true),
  (2816, 3, 'التأكد من تحمّل فريق التطوير الملكية الكاملة لمراجعات التكرار من خلال شرح عملهم بدقة والإجابة عن أسئلة العملاء فوريًا.', 'Ensure the development team took full ownership of iteration reviews by thoroughly explaining their work and addressing customer questions in real time.', false),
  (2817, 0, 'راجع حدود مفاوضات المعنيين لتحديد مدى المرونة المتاحة في تأمين موارد إضافية.', 'Review the boundaries of stakeholder negotiations to determine how much flexibility exists in securing additional resources.', false),
  (2817, 1, 'إعادة تقييم الأهداف الأساسية للمشروع من خلال التقييم الدقيق للأولويات والنطاق والجدول الزمني لتحديد ما هو أساسي مقابل ما يمكن تعديله.', 'Reassess the project''s core objectives by carefully evaluating priorities, scope, and schedule to determine what is essential versus what can be adjusted.', false),
  (2817, 2, 'بدء المفاوضات مع أصحاب الموارد فورًا لتأمين الموارد الإضافية اللازمة لتنفيذ الخطة الأصلية.', 'Start negotiations with resource owners immediately to secure the additional resources needed to fulfill the original plan.', false),
  (2817, 3, 'إجراء إعادة تقييم شاملة لأهداف المشروع والأنشطة المخططة ومتطلبات الموارد لتحديد ما إذا كانت الخطة الحالية قابلة للتحقيق.', 'Conduct a comprehensive reevaluation of project objectives, planned activities, and resource requirements to determine if the current plan is achievable.', true),
  (2818, 0, 'رتّب اجتماعًا مع قسم المشتريات والمقاول للتفاوض حول شروط سداد منقحة تراعي جسامة هذا الطلب.', 'Arrange a meeting with procurement and the contractor to negotiate revised payment terms that accommodate the gravity of the request.', false),
  (2818, 1, 'الموافقة على الدفع فورًا بإخطار قسم الذمم الدائنة والمتابعة للتأكد من اكتمال المعاملة.', 'Approve the payment immediately by notifying accounts payable and following up to confirm the transaction is completed.', false),
  (2818, 2, 'تقييم طلب الدفع في ضوء الأحكام والشروط الواردة في خطة إدارة المشتريات والعقد قبل اتخاذ أي إجراء.', 'Evaluate the payment request against the terms and conditions in the procurement management plan and contract before taking action.', true),
  (2818, 3, 'الموافقة على الدفع فقط بعد مقارنة الإنفاق المتوقع بالإنفاق الفعلي للتأكد من أن المركز المالي للمشروع يدعم ذلك.', 'Approve the payment only after comparing forecasted spending against actual spending to confirm the project''s financial position supports it.', false),
  (2819, 0, 'ذكّر المدير أنه تم التشاور معه مسبقًا بشأن المتطلبات المتفق عليها للإصدار 6.0، وأن المعنيين المسؤولين قد وافقوا عليها رسميًا قبل الإصدار.', 'Remind the director that they were previously consulted on the agreed requirements for Version 6.0 and that accountable stakeholders formally approved it prior to release.', false),
  (2819, 1, 'تيسير مراجعة نوعية وكمية لأبحاث العملاء والسوق التي تدعم دراسة أعمال الإصدار 6.0 ومشاركة النتائج مع المعنيين.', 'Facilitate a qualitative and quantitative review of customer and market research that supports the Version 6.0 business case and share the findings with the stakeholders.', true),
  (2819, 2, 'الإقرار بالنتائج المخيّبة للآمال وإبلاغ المدير بأن ردة فعل العملاء والسوق قد صُنّفت كمخاطرة محتملة أثناء التخطيط.', 'Acknowledge the disappointing results and inform the director that customer and market reaction was marked as a probable risk during planning.', false),
  (2819, 3, 'ترتيب أن يعيد الفريق تقديم العرض التوضيحي النهائي للإصدار 6.0 لمنح المدير رؤية كاملة لما جرى تسليمه.', 'Arrange for the team to conduct a repeat of the final Version 6.0 demo to give the director complete visibility of what was delivered.', false),
  (2820, 0, 'أنشئ مخططًا سببيًا‑نتائجيًا لتحليل العوامل التي أسهمت في إخفاقات مراجعة الجودة في المخرجات الأربعة.', 'Generate a cause-and-effect diagram to analyze the factors contributing to the quality review failures in the four deliverables.', true),
  (2820, 1, 'مراجعة الأقسام ذات الصلة من خطة إدارة الجودة لتعكس مواعيد مراجعة أكثر قابلية للتحقيق بناءً على الأداء الحالي للفريق.', 'Revise the relevant sections of the quality management plan to reflect more achievable review timelines based on the team''s current performance.', false),
  (2820, 2, 'استكشاف جدوى تكليف جهة بإجراء تدقيق داخلي لتقييم ما إذا كانت عمليات الجودة في المشروع تُتّبع باستمرار.', 'Explore the feasibility of commissioning an internal audit to assess whether the project''s quality processes are being followed consistently.', false),
  (2820, 3, 'تصعيد إخفاقات مراجعة الجودة إلى راعي المشروع وطلب توجيه حول كيفية المضي قدمًا في التسليمات الأربعة.', 'Escalate the quality review failures to the project sponsor and request guidance on how to proceed with the four deliverables.', false),
  (2821, 0, 'أنشئ مخططًا سببيًا‑نتائجيًا لتحليل العوامل التي أسهمت في إخفاقات مراجعة الجودة في النواتج الأربعة.', 'Generate a cause-and-effect diagram to analyze the factors contributing to the quality review failures in the four deliverables.', true),
  (2821, 1, 'مراجعة الأقسام ذات الصلة من خطة إدارة الجودة لتعكس مواعيد مراجعة أكثر قابلية للتحقيق بناءً على الأداء الحالي للفريق.', 'Revise the relevant sections of the quality management plan to reflect more achievable review timelines based on the team''s current performance.', false),
  (2821, 2, 'استكشاف جدوى تكليف جهة بإجراء تدقيق داخلي لتقييم ما إذا كانت عمليات الجودة في المشروع تُتّبع باستمرار.', 'Explore the feasibility of commissioning an internal audit to assess whether the project''s quality processes are being followed consistently.', false),
  (2821, 3, 'تصعيد إخفاقات مراجعة الجودة إلى راعي المشروع وطلب توجيه حول كيفية المضي قدمًا في أربعة تسليمات.', 'Escalate the quality review failures to the project sponsor and request guidance on how to proceed with four deliverables.', false),
  (2822, 0, 'تحقَّق من أولويات المتطلبات وأعِد تأكيدها في كل تكرار لضمان تركيز الفريق باستمرار على الميزات الأكثر أهمية لتحقيق جاهزية الإنتاج.', 'Validate and reconfirm requirement priorities at each iteration to ensure the team continuously focuses on the features most critical to production readiness.', false),
  (2822, 1, 'حماية معالم المشروع من خلال التأكيد على المسار الحرج لتسليم الميزات والتحقق منها في دفعات أصغر، وبالتالي تقليل المخاطر.', 'Safeguard the project milestones by emphasizing the critical path to deliver and validate features in smaller batches, thereby reducing the risk.', true),
  (2822, 2, 'استخدام خارطة تعيين التأثير لتجميع قصص المستخدم المترابطة وتوضيح كيفية إسهام كل ميزة في أهداف الأعمال الأوسع للمشروع.', 'Use impact mapping to group related user stories and clarify how each feature contributes to the project''s broader business objectives.', false),
  (2822, 3, 'تجزئة الملاحم عالية المستوى إلى قصص دقيقة لتحسين دقة التقدير وجعل تخطيط الإطلاق قابلًا للإدارة من قبل الفريق.', 'Decompose high-level epics into granular stories to improve estimation accuracy and make sprint planning manageable for the team.', false),
  (2823, 0, 'التقِ بالمعنيين للتحقق من السبب الجذري لملاحظاتهم والتعاون معهم في معالجة المشكلات الأساسية التي تقف وراء قلقهم.', 'Meet with the stakeholders to investigate the root cause of their feedback and collaborate on addressing the underlying issues driving their concern.', true),
  (2823, 1, 'إجراء مراجعة لمتطلبات المشروع للتأكد من أنها واقعية وأن الفريق يمتلك القدرة اللازمة لتسليمها.', 'Conduct a review of project requirements to confirm they are realistic and that the team has the capability needed to deliver them.', false),
  (2823, 2, 'توجيه الفريق للتعامل مع العروض التوضيحية بثقة أكبر، والتواصل بشأن عملهم بفعالية، وإشراك المعنيين كشركاء متعاونين.', 'Coach the team to approach demos with greater confidence, communicate their work effectively, and engage stakeholders as collaborative partners.', false),
  (2823, 3, 'الرجوع إلى مصفوفة مشاركة المعنيين لتحديد ما إذا كان أيٌّ من المعنيين الذين يقدمون الملاحظات له تاريخ في كونه صعب المراس.', 'Consult the stakeholder engagement matrix to determine whether any of the stakeholders providing feedback have a history of being difficult.', false),
  (2824, 0, 'إقامة اتصال مباشر مع القسم المسؤول عن تحديد متطلبات المنتج للقضاء على الوسطاء.', 'Establish direct contact with the department responsible for defining product requirements to eliminate intermediaries.', false),
  (2824, 1, 'اشتراط أن تتضمن جميع إصدارات البرمجيات المستقبلية ميزات إمكانية وصول قابلة للتهيئة لاستيعاب نطاق أوسع من القيود الجسدية للمستخدم النهائي.', 'Mandate that all future software releases include configurable accessibility features to accommodate a broader range of end-user physical constraints.', false),
  (2824, 2, 'مطالبة المطوّرين باختبار البرمجيات بمحاكاة واقعية لظروف عمل المستخدم النهائي قبل الانتقال إلى الإنتاج.', 'Demand developers test software with realistic simulations of end-user working conditions before progressing into production.', false),
  (2824, 3, 'دمج المستخدمين النهائيين في عملية الاختبار للتحقق من النماذج الأولية والإصدارات التزايدية في بيئات العمل الفعلية.', 'Integrate end users into the testing process to validate prototypes and incremental releases in the actual working environments.', true),
  (2825, 0, 'جدولة فعاليات تدريبية للفريق لتحويل وقت التوقف إلى فرص تعلم منظمة.', 'Schedule team training events to convert downtime into structured learning opportunities.', false),
  (2825, 1, 'تيسير مبادرات أبحاث السوق لتوليد رؤى جديدة تُبقي المدير على اطلاع وتتيح اتخاذ قرارات أسرع لتحديد الأهداف.', 'Facilitate market research initiatives to generate fresh insights that keep the director informed and enable faster goal-setting decisions.', true),
  (2825, 2, 'تقليص حجم الفريق لإزالة الفائض وإيجاد منحنى إنتاج أكثر اتساقًا يتوافق مع وتيرة اتخاذ القرار لدى المدير.', 'Reduce the team''s size to eliminate slack and create a more consistent output curve to match the director''s decision-making pace.', false),
  (2825, 3, 'تيسير جلسات عصف ذهني لمساعدة المدير على تقييم الأهداف وتنقيحها بناءً على أبحاث السوق.', 'Facilitate brainstorming sessions to help the director evaluate and refine goals based on market research.', false),
  (2826, 0, 'ضع بروتوكولات واضحة لاتخاذ القرار تُحدِّد متى تتطلّب التغييرات إشراك مالك المنتج، وصحِّح الانحرافات عند ظهورها.', 'Establish clear decision-making protocols that define when changes require product owner involvement, and correct deviations as they emerge.', false),
  (2826, 1, 'طلب تمويل إضافي من مالك المنتج لتغطية تكلفة إعادة العمل الناتجة عن ضعف مشاركته مع الفريق أثناء دورة التكرار.', 'Request additional funding from the product owner to cover the cost of rework resulting from their lack of engagement with the team during the iteration cycle.', false),
  (2826, 2, 'الحفاظ على تواصل مستمر مع مالك المنتج طوال كل تكرار وجدولة جلسات كلما بدأت فجوات المواءمة في الظهور.', 'Maintain consistent engagement with the product owner throughout each iteration and schedule sessions whenever alignment gaps begin to appear.', true),
  (2826, 3, 'تطبيق القيادة الخادمة من خلال الإزالة الفعّالة لعوائق الفريق لمساعدته على الحفاظ على التركيز والتسليم باتساق عبر التكرارات.', 'Apply servant leadership by actively removing team impediments to help the team maintain focus and deliver consistently across iterations.', false),
  (2827, 0, 'توجيه فريق ضمان الجودة لإجراء تحليل للفجوات يقارن بين الوظيفة المنفذة والتوثيق الأصلي للتصميم.', 'Direct the quality assurance team to perform a gap analysis comparing the delivered function to the original design documentation.', false),
  (2827, 1, 'تيسير مناقشة مع مالك المنتج للتعرف على توقعاته والفجوات التي يراها في عملية التطوير.', 'Facilitate a discussion with the product owner to learn their expectations and perceived gaps in the development process.', true),
  (2827, 2, 'توجيه فريق التطوير إلى مراجعة الوظيفة فورًا لمطابقتها مع نطاق المشروع الموثَّق.', 'Instruct the development team to immediately revise the function to match the documented project scope.', false),
  (2827, 3, 'زيادة وتيرة تحديثات حالة التطوير المقدَّمة لمالك المنتج إلى مرتين أسبوعيًا.', 'Increase the frequency of development status updates to the product owner to twice per week.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2828, 0, 'تصعيد المشكلة إلى راعي المشروع وطلب تحديثات لميثاق المشروع، بما في ذلك إعادة تعيين المسؤوليات والسلطة.', 'Escalate the issue to the project sponsor and request updates to the project charter, including reassignment of responsibilities and authority.', false),
  (2828, 1, 'توجيه فريق المشروع إلى تحسين التسليم بإضافة ميزات جديدة لتحل محل الوظيفة المرفوضة.', 'Direct the project team to enhance the deliverable by adding new features to replace the rejected functionality.', false),
  (2828, 2, 'التعاون مع المعنيين الرئيسيين لفهم مخاوفهم ومعالجتها مع فريق المشروع.', 'Collaborate with the key stakeholders to understand their concerns and address them with the project team.', true),
  (2828, 3, 'جدولة اجتماع مع المعني الرئيسي وممثل عن الفريق لتخفيف التوتر ومعاودة النظر في قرار الرفض.', 'Schedule a meeting with the key stakeholder and a team representative to reduce tension and revisit the rejection decision.', false),
  (2829, 0, 'ابدأ عملية إدارة التغيير بما أن الوظيفة قد تم اعتمادها مسبقًا.', 'Initiate the change management process since the functionality was previously approved.', false),
  (2829, 1, 'تيسير ورشة عمل مع المعنيين ذوي الصلة لتوضيح الوظيفة وتنقيحها.', 'Facilitate a workshop with the relevant stakeholders to clarify and refine the functionality.', true),
  (2829, 2, 'تصعيد المشكلة إلى راعي المشروع لمعالجتها مباشرة مع المعني ذي الصلة.', 'Escalate the issue to the project sponsor to address it directly with the relevant stakeholder.', false),
  (2829, 3, 'المتابعة مع التكرار الحالي والاعتماد على أنشطة الاختبار لتحديد المشكلة وتصحيحها لاحقًا.', 'Continue with the current iteration and rely on testing activities to identify and correct the issue later.', false),
  (2830, 0, 'فرض لغة مشتركة واحدة في جميع تفاعلات المشروع، بما في ذلك جلسات العمل، لضمان الشفافية الكاملة على الرغم من التأثير المحتمل في الإنتاجية.', 'Enforce a single shared language in all project interactions, including working sessions, to ensure full transparency despite the potential impact on productivity.', false),
  (2830, 1, 'تصعيد ديناميكية اللغة إلى قسم الموارد البشرية باعتبارها مشكلة رسمية في تواصل الفريق تتطلب تدخلًا تنظيميًا.', 'Escalate the language dynamic to the human resources department as a formal team communication issue requiring organizational intervention.', false),
  (2830, 2, 'شراء خدمات ترجمة احترافية أو تدريب لغوي رسمي لسد فجوة التواصل بين المقاولين والفريق الأوسع.', 'Procure professional translation services or formal language training to bridge the communication gap between the contractors and the broader team.', false),
  (2830, 3, 'تيسير مناقشة جماعية تتيح لجميع الأعضاء التحديد التعاوني للقواعد الأساسية لاستخدام اللغة في مختلف أنواع تفاعلات المشروع.', 'Facilitate a team discussion that allows all members to collaboratively define ground rules for language use in different types of project interactions.', true),
  (2831, 0, 'ادرس الكتب والموارد المتعلقة بالحساسية الثقافية في القيادة لبناء أساس معرفي راسخ.', 'Study books and resources on cultural sensitivity in leadership to build foundational knowledge.', true),
  (2831, 1, 'الاستعانة بمدرب محترف لتطوير مهارات قيادية أقوى مُصمَّمة لإدارة الفرق المتنوعة.', 'Engage a professional coach to develop stronger leadership skills tailored to managing diverse teams.', false),
  (2831, 2, 'طلب إعادة التعيين إلى مشروع آخر، مع الإشارة إلى حاجز اللغة بوصفه عائقًا أمام إدارة المشروع بفعالية.', 'Request reassignment to a different project, citing the language barrier as an obstacle to effective project management.', false),
  (2831, 3, 'تسجيل الفريق في دورات انغماس ثقافي لتعميق فهمهم لأسلوب التواصل والأعراف الثقافية لمختلف الدول.', 'Enroll the team in cultural immersion courses to deepen their understanding of the various countries’ communication style and cultural norms.', false),
  (2832, 0, 'نشر شاشات عرض المعلومات لبث مقاييس المشروع.', 'Deploy information radiator monitors to broadcast project metrics.', false),
  (2832, 1, 'تطبيق منصة إلزامية لمؤتمرات الفيديو عند الطلب.', 'Implement a mandatory on-demand video conferencing platform.', false),
  (2832, 2, 'تمكين عرض شاشات محطات العمل لأعضاء الفريق عن بُعد لمشاهدة شاشاتهم الفردية وعملهم الجاري.', 'Enable workstation screen viewing of remote team members'' individual screens and active work.', false),
  (2832, 3, 'الحفاظ على رابط فيديو دائم بين مختلف المواقع التي تتوزع فيها الفرق.', 'Maintain a long-lived video link between the various locations where the teams are dispersed.', true),
  (2833, 0, 'حدد موعد اجتماع السكَرَم اليومي الموسَّع (Scrum of Scrums) في وقت ثابت يمكن لجميع المواقع حضوره في الوقت نفسه.', 'Schedule daily Scrum of Scrums at a fixed time that all locations can attend simultaneously.', false),
  (2833, 1, 'جدولة نوافذ "حوض السمك" (fishbowl) بين الفرق التي تتداخل ساعات عملها.', 'Schedule fishbowl windows between teams whose work hours overlap.', true),
  (2833, 2, 'تطبيق أداة لإدارة المشاريع لتسجيل المشكلات ومراجعتها.', 'Implement a project management tool to log and review problems.', false),
  (2833, 3, 'تعيين قائد مخصص لحل المشكلات في كل موقع يحضر مكالمة تسليم يومية.', 'Assign a dedicated problem resolution lead in each location who attends a daily handoff call.', false),
  (2834, 0, 'احتفظ بمراجعات لوحة كانبان للاجتماعات الخاصة بمراجعة التكرارات بدلاً من اجتماعات التنسيق اليومية.', 'Reserve kanban board reviews for iteration reviews rather than the daily coordination meetings.', false),
  (2834, 1, 'توجيه الفريق لتبنّي المبادئ الرشيقة طوال مدة الاجتماع اليومي، مع تذكير أعضاء الفريق بتحديد فترة زمنية للاجتماع.', 'Coach the team to adopt agile principles for the duration of the daily meeting, reminding team members to timebox the meeting.', true),
  (2834, 2, 'وضع كاميرا ويب ثابتة واحدة موجّهة نحو عوارض المعلومات للقضاء على التعطيل.', 'Position a single stationary webcam facing the information radiators to eliminate  disruption.', true),
  (2834, 3, 'نقل مناقشات العوائق خارج الاجتماع حتى تتمكن الاجتماعات اليومية من التركيز على تحديثات التقدم بدلًا من محادثات حل المشكلات.', 'Move blocker discussions offline so the daily meetings can focus on progress updates rather than problem-solving conversations.', false),
  (2834, 4, 'قم بتدوير دور مُيسّر الاجتماع بين أعضاء الفريق في كل سبريت لتوزيع مسؤولية كفاءة الاجتماعات داخل الفريق.', 'Rotate the meeting facilitator role among team members each sprint to distribute ownership of meeting efficiency within the team.', false),
  (2835, 0, 'إنشاء إطار لتعريف "الانتهائية" لتوحيد معايير إكمال جميع المشاريع وضمان تقارير جودة متسقة.', 'Establish a definition of done framework to standardize completion criteria for all projects and ensure consistent quality reporting.', false),
  (2835, 1, 'تطبيق لوحة كانبان إلكترونية مشتركة لمنح مكتب إدارة المشاريع (PMO) وجميع مديري المشاريع رؤية فورية للتقدم والعوائق وحالة العمل في كل موقع.', 'Implement a shared electronic kanban board to give the PMO and all project managers real-time visibility into progress, blockers, and work status in every location.', true),
  (2835, 2, 'إجراء جلسات منتظمة لتنقيح سجل الأعمال للحفاظ على مواءمة أولويات كل مشروع مع أهداف البرنامج العامة لمكتب إدارة المشاريع.', 'Conduct regular backlog refinement sessions to keep each project''s priorities aligned with the PMO''s overall program objectives.', false),
  (2835, 3, 'عقد اجتماعات تنسيق يومية عبر الإنترنت لإنشاء نقطة تواصل منظمة ومتكررة لمديري المشاريع للإبلاغ عن العوائق والحفاظ على المواءمة.', 'Hold online daily coordination meetings to create a structured, recurring touchpoint for project managers to report impediments and maintain alignment.', true),
  (2835, 4, 'جدولة اجتماعات استرجاعية نصف شهرية لمنح مديري المشاريع منبرًا مخصصًا للتأمل في التحديات ومشاركة الدروس المستفادة في جميع المشاريع.', 'Schedule biweekly retrospectives to give project managers a dedicated forum for reflecting on challenges and sharing lessons learned in all projects.', false),
  (2836, 0, 'تيسير إجراء فحص منظّم للمسألة غير المحسومة أثناء الاستعراض الرجعي بهدف تحديد السبب الجذري ووضع عملية فعّالة لتصعيد العوائق.', 'Facilitate a structured examination of the unresolved issue during the retrospective to identify the root cause and establish an effective impediment escalation process.', true),
  (2836, 1, 'استخدام العرض التوضيحي للإطلاق لإظهار المشكلة غير المحلولة أمام المعنيين وجمع مدخلاتهم حول كيفية تعامل الفريق مع المواقف المماثلة مستقبلًا.', 'Use the sprint demo to surface the unresolved issue with stakeholders and gather their input on how the team should handle similar situations going forward.', false),
  (2836, 2, 'طرح المشكلة في اجتماع تخطيط التكرار القادم لدمج استراتيجيات إدارة المخاطر في التزامات الإطلاق المقبلة للفريق.', 'Bring the issue to the next iteration planning meeting to incorporate risk management strategies into the team''s upcoming sprint commitments.', false),
  (2836, 3, 'إرسال بريد إلكتروني لكامل الفريق يوضح توقعات تصعيد العوائق وطلب الإبلاغ عن المشكلات المماثلة فورًا مستقبلًا.', 'Send a team-wide email outlining the impediment escalation expectations and request that similar issues are reported promptly in the future.', false),
  (2837, 0, 'نصح المعنيين الاثنين بتجاهل رسائل البريد الإلكتروني، بما يتسق مع الطريقة التي يتعامل بها الفريق معها.', 'Advise the two concerned stakeholders to disregard the emails, consistent with how the team has been handling them.', false),
  (2837, 1, 'عقد اجتماع جماعي مع جميع المعنيين المشاركين لمعالجة مخاوف التواصل معًا بصراحة، حتى تُحَلّ المسألة.', 'Convene a group meeting with all involved stakeholders to openly work through the communication concerns together, until the matter is resolved.', false),
  (2837, 2, 'إشراك المعني المُعطِّل في محادثة خاصة لفهم مخاوفه وإعادة مواءمته مع بروتوكولات التواصل المعتمدة.', 'Engage the disruptive stakeholder in a private conversation to understand their concerns and realign them with the established communication protocols.', true),
  (2837, 3, 'إجراء تحقيق شامل في السبب الجذري لسلوك المعني قبل اتخاذ أي إجراء تصحيحي.', 'Conduct a thorough investigation into the root cause of the stakeholder''s behavior before taking any corrective action.', false),
  (2838, 0, 'يُنصَح أعضاء الفريق بتطبيق الحزم عند اختيار عناصر سجل الأعمال.', 'Recommend team members apply assertiveness during backlog selection.', false),
  (2838, 1, 'الاجتماع بعضو الفريق المخالف لمناقشة أهمية توزيع العمل بشكل عادل.', 'Meet with the offending team member to discuss the importance of equitable work distribution.', false),
  (2838, 2, 'منح كل عضو في الفريق فرصة متساوية لاختيار بنود سجل الأعمال.', 'Give each team member equal opportunity to choose backlog items.', false),
  (2838, 3, 'تيسير مناقشة جماعية لوضع القواعد الأساسية لاختيار بنود سجل الأعمال وتوزيعها.', 'Facilitate a team discussion to establish backlog selection and distribution ground rules.', true),
  (2839, 0, 'طمئن الفريق بأن التغييرات الناتجة عن تفويض المؤسسة سيتم تأجيلها إلى وقت لاحق لتقليل تعطيل العمل الحالي إلى الحد الأدنى.', 'Reassure the team that changes resulting from the organization’s mandate will be deferred to minimize disruption to current work.', false),
  (2839, 1, 'تبنّي نهج الانتظار والترقّب، حتى تصدر المؤسسة تعليماتها، قبل تحديد كيفية الاستجابة.', 'Adopt a wait-and-see approach, until the organization issues instructions, before determining how to respond.', false),
  (2839, 2, 'إشراك مالك المنتج لتضمين تغييرات المؤسسة في سجل الأعمال من خلال تحديد الأولويات والتخطيط.', 'Engage the product owner to capture the organization’s changes in the backlog through prioritization and planning.', true),
  (2839, 3, 'تحديد فترة لا تُطرح خلالها مبادرات جديدة على الفريق، حفاظًا على التركيز على التزامات الإطلاق الحالية.', 'Establish a period during which new initiatives will not be introduced to the team, preserving focus on current sprint commitments.', false),
  (2840, 0, 'أجرِ تقييمًا للأثر من أجل تقييم تأثيرات الجدول المقترح على المشروع قبل الالتزام بأي تغييرات.', 'Conduct an impact assessment to evaluate the effects of the proposed schedule on the project before committing to any changes.', true),
  (2840, 1, 'عقد جلسة عمل مع جميع المعنيين ذوي الصلة لفحص متطلبات الأعمال الدافعة للموعد النهائي المضغوط.', 'Convene a working session with all relevant stakeholders to examine the business requirements driving the compressed deadline.', false),
  (2840, 2, 'مراجعة الجدول الزمني للمشروع فورًا ليعكس الموعد النهائي الجديد وإعادة توزيع العمل المتبقي وفقًا لذلك.', 'Revise the project schedule immediately to reflect the new deadline and redistribute the remaining work accordingly.', false),
  (2840, 3, 'الاجتماع بأعضاء الفريق فرديًا لتحديد عناصر النطاق التي يمكن حذفها لتحقيق الجدول الزمني المضغوط.', 'Meet individually with team members to identify which scope elements can be eliminated to achieve the compressed timeline.', false),
  (2841, 0, 'إعادة النظر في هيكل تقسيم العمل (WBS) مع راعي المشروع لإعادة التفاوض بشأن نطاق المشروع وتلبية الاحتياجات التجارية.', 'Revisit the work breakdown structure (WBS) with the project sponsor to renegotiate the project''s scope and meet business needs.', false),
  (2841, 1, 'إشراك جميع المعنيين ذوي الصلة في تحديد الحد الأدنى المقبول للمنتج (MVP) اللازم لتلبية احتياجات الأعمال الأكثر إلحاحًا.', 'Engage all relevant stakeholders in defining the minimum viable product (MVP) required to address the most urgent business needs.', true),
  (2841, 2, 'حساب مؤشر أداء الجدول الزمني (SPI) لقياس مخاطر الجدول الزمني وتصعيد النتائج إلى راعي المشروع.', 'Calculate the schedule performance index (SPI) to quantify the schedule risk and escalate the findings to the project sponsor.', false),
  (2841, 3, 'تعديل الخط المرجعي لهيكل تجزئة العمل ليعكس متطلبات المعنيين واستخدام مخطط الإنجاز التنازلي لمراقبة التقدم.', 'Adjust the WBS baseline to reflect stakeholder requirements and use a burndown chart to monitor progress.', false),
  (2842, 0, 'التعرّف على فرصة العمل التي تقدّمها هذه الوظيفة، ولكن تحديد أنها تقع خارج نطاق العمل ورفض الطلب.', 'Recognize the business opportunity the functionality presents but determine that it falls outside the scope and decline the request.', false),
  (2842, 1, 'تقديم طلب تغيير رسمي وإجراء تقييم شامل لأثر الوظيفة على النطاق والجدول الزمني والتكلفة والمخاطر قبل المضي قدمًا.', 'Submit a formal change request and conduct a thorough evaluation of the functionality’s impact on scope, schedule, cost, and risk before proceeding.', true),
  (2842, 2, 'إجراء تحليل نقاط القوة والضعف والفرص والتهديدات (SWOT) على الوظيفة فورًا، والاستعانة بالاحتياطي الإداري لتغطية التكاليف المرتبطة بها.', 'Perform a strengths, weaknesses, opportunities, and threats (SWOT) analysis on the functionality immediately, and tap into the management reserve to cover the associated costs.', false),
  (2842, 3, 'تحديد ميزة مطوَّرة قائمة يمكن دمجها مع الوظيفة المطلوبة وتنفيذها دون تغيير رسمي في النطاق.', 'Identify an existing developed feature that can be combined with the requested functionality and implement it without a formal scope change.', false),
  (2843, 0, 'قدّم لوحة كانبان لتحديد الأماكن التي تتراكم فيها الاختناقات.', 'Introduce a kanban board to identify where bottlenecks are accumulating.', false),
  (2843, 1, 'تطبيق تحديد الفترات الزمنية للتحكم في كيفية تخصيص الوقت بين بنود عبء العمل المتنافسة.', 'Implement timeboxing to control how time is allocated in competing workload items.', false),
  (2843, 2, 'تقييم أداء كل عضو من أعضاء الفريق لتحديد ما إذا كانت فجوات المهارات تسهم في إعادة العمل المبلَّغ عنها.', 'Evaluate individual team members'' performance to determine whether skill gaps are contributing to the reported rework.', false),
  (2843, 3, 'تيسير تقييم للوصول إلى ما إذا كانت إعادة العمل ناتجة عن قيود الوقت أو فجوات الجودة أو اختلال توازن عبء العمل.', 'Facilitate an assessment to conclude if the rework is being driven by time constraints, quality gaps, or a workload imbalance.', true),
  (2844, 0, 'تيسير المفاوضات مع المعنيين لتقليل متطلبات المشروع وجعل الجدول الزمني المضغوط قابلاً للتحقيق.', 'Facilitate negotiations with relevant stakeholders to reduce project requirements and make the compressed timeline achievable.', false),
  (2844, 1, 'إجراء تقييم لتحديد مخاطر ضغط الجدول الزمني ومشاركة النتائج مع المعنيين ذوي الصلة للتوصل إلى حل.', 'Conduct an assessment to identify timeline compression risks and share the findings with relevant stakeholders to reach a resolution.', true),
  (2844, 2, 'تسريع التسليم بإضافة أعضاء إلى الفريق لزيادة القدرة على العمل وتقصير الجدول الزمني الإجمالي.', 'Accelerate delivery by adding team members to increase the work capacity and shorten the overall timeline.', false),
  (2844, 3, 'نصح المعنيين بعدم تعديل الجدول الزمني وسرد العواقب المرتبطة بالضغط المقترح.', 'Advise stakeholders against modifying the timeline and list consequences associated with the proposed compression.', false),
  (2845, 0, 'شلال', 'Waterfall', false),
  (2845, 1, 'التزايدي.', 'Incremental', true),
  (2845, 2, 'الهجين.', 'Hybrid', false),
  (2845, 3, 'التكراري.', 'Iterative', false),
  (2846, 0, 'تجاوز الفريق عمليات ضبط الجودة أثناء التطوير، مما أدى إلى وجود ميزات لا تستوفي معايير القبول.', 'The team bypassed quality control processes during development, resulting in features that do not meet the acceptance criteria.', false),
  (2846, 1, 'مالك محفظة المشاريع غير راغب في تحمّل التكلفة المرتبطة بالميزات التي تُطوَّر خارج الميزانية المعتمدة.', 'The portfolio owner is unwilling to absorb the cost associated with features that are developed outside the approved budget.', false),
  (2846, 2, 'يؤدي التطوير المستقل للميزات إلى غموض بشأن حقوق الملكية الفكرية.', 'The independent development of features results in ambiguity around intellectual property rights.', false),
  (2846, 3, 'أخفق مالك المنتج في التحقق من أفكار ميزات الفريق قبل إضافتها إلى سجل الأعمال.', 'The product owner failed to validate the team''s feature ideas prior to adding them to the backlog.', true),
  (2847, 0, 'التعاون مع المعنيين لتفصيل مجموعة المتطلبات إلى قصص مستخدمين جاهزة لتخطيط السبرينت.', 'Collaborate with relevant stakeholders to break down the set of requirements into user stories ready for sprint planning.', false),
  (2847, 1, 'عقد اجتماع للمعنيين ذوي الصلة لتحديد مخاطر المشروع ووضع استراتيجيات الاستجابة للمخاطر قبل بدء التطوير.', 'Convene the relevant stakeholders to identify project risks and develop risk response strategies before development begins.', false),
  (2847, 2, 'تقدير إجمالي جهد التطوير واستخدامه لبناء دراسة أعمال تبرر الاستثمار للمعنيين ذوي الصلة.', 'Estimate the total development effort and use it to construct a business case that justifies the investment for the relevant stakeholders.', false),
  (2847, 3, 'إشراك المعنيين ذوي الصلة لتحديد الحد الأدنى المقبول للمنتج (MVP) الذي يحقق قيمة للمستخدم في الإطلاق المبدئي للسوق.', 'Engage relevant stakeholders to define the minimum viable product (MVP) that delivers value to the user for the initial market launch.', true),
  (2848, 0, 'سيُعاد ترتيب أولويات سجل المنتج لتوفير الوظائف الأساسية من خلال زيادات صغيرة.', 'The product backlog will be reprioritized to deliver core functionality through small increments.', true),
  (2848, 1, 'سيُحدَّث رؤية المنتج لتعكس خارطة طريق للإصدار مدفوعة باحتياجات المستخدم.', 'The product vision will be updated to reflect a release roadmap driven by user needs.', false),
  (2848, 2, 'سيُحدَّث سجل أعمال الإطلاق لضمان إعطاء الأولوية لأصغر قصص المستخدم وأبسطها.', 'The sprint backlog will be updated to ensure the smallest and simplest user stories are prioritized.', false),
  (2848, 3, 'سيُقلَّص حجم كل زيادة من زيادات المنتج لتقصير دورة التطوير.', 'The size of each product increment will be reduced to shorten the development cycle.', false),
  (2849, 0, 'قم بتوسيع فريق الاختبار لضمان اكتشاف العيوب وحلّها قبل تاريخ الإطلاق.', 'Expand the test team to ensure defects are detected and resolved prior to the launch date.', false),
  (2849, 1, 'إزالة اختبارات المنتج وحذف المتطلبات المرتبطة بتلك الاختبارات من نطاق الإصدار.', 'Remove product tests and eliminate the requirements associated with those tests from the release scope.', false),
  (2849, 2, 'تطبيق التتابع السريع على الأنشطة المتبقية وتحديد معالم جديدة للاختبار والجاهزية أقرب ما يمكن إلى تاريخ الإطلاق.', 'Fast track remaining activities and establish new testing and readiness milestones as close to the launch date as possible.', false),
  (2849, 3, 'تخطيط مسار تكراري متوازٍ لتطوير متطلبات الحد الأدنى المقبول للمنتج (MVP) وإزالة المهام غير الأساسية.', 'Plan a parallel iterative track to develop requirements for a minimum viable product (MVP) and remove nonessential tasks.', true),
  (2850, 0, 'تصعيد الطلب إلى لجنة حوكمة المشروع بوصفه احتمالًا لخرق الأخلاقيات.', 'Escalate the request to the project governance committee as a potential breach of ethics.', false),
  (2850, 1, 'تلبية الطلب والاحتفاظ بسجل للرجوع إليه مستقبلًا.', 'Fulfill the request and maintain a record for future reference.', false),
  (2850, 2, 'مشاركة المعلومات المطلوبة بعد حجب جميع المكوّنات السرية من الوثائق.', 'Share the requested information after redacting all classified components from the documentation.', false),
  (2850, 3, 'مراجعة خطة إدارة التواصل لتحديد ما إذا كان يمكن مشاركة هذه المعلومات.', 'Review the communications management plan to determine if this information can be shared.', true),
  (2851, 0, 'راجع خطط الاتصالات وإشراك المعنيين لتحديد مستوى التفصيل المناسب ونهج الاتصال المتبع.', 'Review the communications and stakeholder engagement plans to determine the respective level of detail and communication approach.', false),
  (2851, 1, 'تقديم طلب تغيير إضافي لدمج توقعات التواصل للمعنيين في خطة إدارة المشروع.', 'Submit an additional change request to incorporate the stakeholders'' communication expectations into the project management plan.', false),
  (2851, 2, 'جدولة اجتماع مع راعي المشروع للحصول على فهم تفصيلي لتوقعات المعنيين فيما يتعلق بإعداد التقارير والشفافية.', 'Schedule a meeting with the project sponsor to gain a detailed understanding of the stakeholders’ expectations in terms of reporting and transparency.', false),
  (2851, 3, 'الرجوع إلى خطة إدارة التواصل لتحديد قنوات إعداد التقارير المناسبة وإيقاعها، ثم إصدار تقرير حالة تفصيلي.', 'Consult the communications management plan to identify the appropriate reporting channels and cadence, then issue a detailed status report.', true),
  (2852, 0, 'قم بتوزيع الخطة على جميع المعنيين لمراجعتها بشكل مستقل، ويسِّر عقد اجتماع جماعي لمناقشة ملاحظاتهم.', 'Distribute the plan to all the stakeholders for independent review and facilitate a group meeting to discuss their feedback.', false),
  (2852, 1, 'مطالبة كل معني بمراجعة الخطة بشكل فردي وتدوين ملاحظاته مباشرة في الوثيقة.', 'Request each stakeholder review the plan individually and have them annotate their feedback directly in the document.', false),
  (2852, 2, 'إسناد أقسام محددة من الخطة إلى المعنيين بناءً على مجال خبرتهم، بما يتيح مراجعات متوازية يمكن إنجازها ضمن الإطار الزمني المتاح.', 'Assign specific sections of the plan to stakeholders based on their area of expertise, enabling parallel reviews that can be completed within the available timeframe.', true),
  (2852, 3, 'جدولة اجتماعات مراجعة الآن مع المعنيين الذين يستطيعون الالتزام بالإطار الزمني الحالي وتأجيل الموافقات المتبقية إلى أن يتوفر المعنيون الآخرون.', 'Schedule review meetings now with the stakeholders that can meet the current timeframe and defer the remaining approvals until the other stakeholders are available.', false),
  (2853, 0, 'قم بتكييف خطة إدارة الاتصالات لتعكس التغيير وتلبية احتياجات هيكل لجنة التوجيه.', 'Tailor the communications management plan to reflect the change and meet the needs of the steering committee''s structure.', true),
  (2853, 1, 'إدراك أن الراعي يظل المعني الأساسي وأن أعضاء اللجنة التوجيهية يؤدون دورًا داعمًا.', 'Recognize that the sponsor remains the primary stakeholder and that the steering committee members serve in a supporting capacity.', false),
  (2853, 2, 'تيسير عقد اجتماع تعارفي لبناء علاقة ودية مع الحفاظ على خطة المشروع وخطة إدارة التواصل القائمتين.', 'Facilitate an introductory meeting to establish rapport while maintaining the existing project and communications management plan.', false),
  (2853, 3, 'توزيع أحدث تقرير حالة للمشروع على جميع المعنيين ذوي الصلة لإطلاعهم على الأداء الحالي للمشروع.', 'Distribute the most recent project status report to all relevant stakeholders to bring them up to speed on current project performance.', false),
  (2854, 0, 'خطة إدارة التغيير، من أجل تقديم واعتماد التغييرات التي قد تكون مطلوبة لمعالجة التأخير في الجدول الزمني.', 'The change management plan, to submit and approve changes that may be required to address the schedule slippage.', false),
  (2854, 1, 'خطة مشاركة المعنيين، لتحديد من ينبغي إشراكه في حل المشكلة وكيفية إدارة مشاركته.', 'The stakeholder engagement plan, to identify who should be involved in resolving the issue and how to manage their participation', false),
  (2854, 2, 'خطة إدارة التواصل، لتحديد كيفية إيصال التصعيد، وإلى مَن، وعبر أي قنوات.', 'The communications management plan, to determine how the escalation should be communicated, to whom, and through which channels', true),
  (2854, 3, 'خطة إدارة المخاطر، لتقييم ما إذا كان التأخر قد جرى تحديده مسبقًا وتحديد عتبات التصعيد واستراتيجيات الاستجابة المناسبة.', 'The risk management plan, to assess whether the slippage was previously identified and determine the appropriate escalation thresholds and response strategies', true),
  (2854, 4, 'خطة إدارة التهيئة، لضمان أن التغييرات التي تُجرى على وثائق المشروع أو على المخرجات نتيجة التصعيد يتم تتبعها والتحكم فيها بشكل صحيح', 'The configuration management plan, to ensure that changes made to project documents or deliverables due to the escalation are properly tracked and controlled', false),
  (2855, 0, 'جدولة اجتماعات منظمة مع الجهة الحكومية لفهم متطلباتها التنظيمية، وتوقعاتها، ومستوى تأثيرها على المشروع.', 'Schedule structured meetings with the governmental agency to understand their regulatory requirements, expectations, and level of influence on the project.', true),
  (2855, 1, 'تحديث سجل الافتراضات لتسجيل أي افتراضات جديدة ناشئة عن التغيير التنظيمي ومشاركة الجهة في المشروع.', 'Update the assumption log to capture any new assumptions introduced by the regulatory change and the agency''s involvement in the project.', false),
  (2855, 2, 'تحديث خطة إدارة المعنيين لتضمين احتياجات التواصل للجهة الحكومية واستراتيجية مشاركتها وسلطتها في اتخاذ القرارات.', 'Update the stakeholder management plan to incorporate the governmental agency''s communication needs, engagement strategy, and decision-making authority.', true),
  (2855, 3, 'الرجوع إلى خطة إدارة المخاطر لتحديد العملية المناسبة لتحديد المخاطر عالية المستوى الناشئة عن التغيير التنظيمي وتقييمها والاستجابة لها.', 'Consult the risk management plan to determine the appropriate process for identifying, assessing, and responding to the high-level risks introduced by the regulatory change.', false),
  (2855, 4, 'تحديث ميثاق المشروع للاعتراف رسميًا بالجهة الحكومية بوصفها طرفًا معنيًا رئيسيًا، وعكس أثر التغيير التنظيمي على أهداف المشروع.', 'Update the project charter to formally recognize the governmental agency as a key stakeholder and reflect the impact of the regulatory change on the project''s objectives.', false),
  (2856, 0, 'راجع محتوى المدوّنة فيما يتعلّق بخطة إدارة الاتصالات، وحدّد التهديد الأمني، وقرّر مسار العمل المناسب.', 'Review the blog’s content in relation to the communications management plan, identify the security threat, and determine a course of action.', true),
  (2856, 1, 'إصدار تحذيرات رسمية لجميع الأفراد المعنيين وتصعيد المسألة إلى مكتب الامتثال لمزيد من التحقيق.', 'Issue formal warnings to all individuals involved and escalate the matter to the compliance office for further investigation.', false),
  (2856, 2, 'إغلاق المدونة فورًا على أساس أنها لم تُنشأ كجزء من خطة إدارة التواصل المعتمدة.', 'Shut the blog down immediately on the grounds that it was not established as part of the approved communications management plan.', false),
  (2856, 3, 'تعيين مسؤول للمدونة لمراقبة جميع الاتصالات المستقبلية وضمان بقاء المنشورات ملائمة ومتوافقة مع معايير الفريق.', 'Appoint a blog administrator to monitor all future communications and ensure the posts remain appropriate and aligned with team standards.', false),
  (2857, 0, 'توجيه الفريق إلى التوقف فورًا عن استخدام نموذج اللغة الكبير (LLM)، وإعادة مراجعة خطة إدارة الاتصالات لتعزيز استخدام أدوات الذكاء الاصطناعي المعتمدة من قِبل المنظمة.', 'Direct the team to immediately discontinue use of the LLM and revisit the communications management plan to reinforce organization-approved AI tools.', false),
  (2857, 1, 'توثيق المشكلة رسميًا وتذكير فريق المشروع بأن جميع المحتوى المتعلق بالمشروع مملوك ولا يمكن مشاركته على منصات غير مصرح بها.', 'Document the issue formally and remind the project team that all project-related content is proprietary and cannot be shared on unauthorized platforms.', true),
  (2857, 2, 'تقييد استخدام المنصة فورًا على أساس أنها ليست جزءًا من خطة إدارة التواصل المعتمدة.', 'Restrict use of the platform immediately on the basis that it is not part of the approved communications management plan.', false),
  (2857, 3, 'تعيين مسؤول للإشراف على أنشطة نماذج اللغة الكبيرة (LLM) لدى الفريق ومراقبتها لمنع المزيد من تسريب المعلومات المملوكة للمؤسسة.', 'Assign an administrator to oversee and monitor the team’s LLM activities to prevent further compromise of the organizational proprietary information.', false),
  (2858, 0, 'وزّع استطلاعًا على كلتا مجموعتي المعنيين لطلب تعليقات محددة حول أداء النموذج الأوّلي مقارنةً بكل متطلّب وظيفي.', 'Distribute a survey to both stakeholder groups requesting specific feedback on the prototype''s performance against each functional requirement.', false),
  (2858, 1, 'إشراك مجموعة الامتياز التجاري في مراجعة توثيق المتطلبات وهيكل تجزئة العمل (WBS) للتحقيق في المتطلب الوظيفي غير الملبّى.', 'Engage the franchise group in a review of the requirements documentation and work breakdown structure (WBS) to investigate the unmet functional requirement.', false),
  (2858, 2, 'تيسير جلسة تشاور مع مجموعة الامتياز التجاري، وعرض موافقة مجموعة العملاء المباشرين كنقطة مرجعية، والتفاوض على اعتماد النموذج الأولي.', 'Facilitate a consultation with the franchise group, present the direct customer group''s approval as a point of reference, and negotiate the prototype sign-off.', false),
  (2858, 3, 'الرجوع إلى مصفوفة RACI لتحديد أي مجموعة من المعنيين تملك سلطة الموافقة الرسمية والتصعيد إلى فريق القيادة إذا ظلت المساءلة غير واضحة.', 'Refer to the RACI matrix to determine which stakeholder group holds formal approval authority and escalate to the leadership team if accountability remains unclear.', true),
  (2859, 0, 'ارجع إلى خطة إدارة الاتصالات وأصدر تقرير حالة يعالج احتياجات المعلومات التي عبّر عنها المعنيين.', 'Refer to the communications management plan and issue a status report that addresses the information needs that stakeholders have expressed.', false),
  (2859, 1, 'تقديم طلب تغيير لدمج توقعات التواصل للمعنيين رسميًا في خطة إدارة المشروع قبل المضي قدمًا.', 'Submit a change request to formally incorporate stakeholder communication expectations into the project management plan before proceeding.', false),
  (2859, 2, 'جدولة اجتماع مع راعي المشروع للحصول على فهم أوضح لما يتوقعه المعنيون من التواصل وكيفية تلبية تلك التوقعات مستقبلًا.', 'Schedule a meeting with the project sponsor to gain a clearer understanding of what stakeholders expect from communications and how to meet those expectations going forward.', false),
  (2859, 3, 'مراجعة كل من خطة إدارة التواصل وخطة إدارة المعنيين لتحديد ما إذا كانت العمليات المعتمدة قد اتُّبعت وتقييم ما إذا كانت هناك حاجة إلى تحديثات.', 'Review both the communications and stakeholder management plans to determine if the established processes were followed and assess whether updates are required.', true),
  (2860, 0, 'راجع خطة إشراك المعنيين للتأكد من الاستراتيجية المناسبة لإشراك صاحب مصلحة رئيسي جديد.', 'Review the stakeholder engagement plan to confirm the appropriate strategy for engaging a new key stakeholder.', true),
  (2860, 1, 'تعيين عضو فريق ليعمل كحلقة وصل أساسية بين فريق المشروع والمعني الجديد.', 'Designate a team member to serve as the primary liaison between the project team and the new stakeholder.', false),
  (2860, 2, 'الرجوع إلى خطة إدارة التغيير لتحديد العملية الرسمية لإدراج التغييرات التنظيمية في المشروع.', 'Consult the change management plan to determine the formal process for incorporating the regulatory changes into the project.', false),
  (2860, 3, 'نصح راعي المشروع بشأن كيفية تأثير اللوائح الجديدة ومشاركة الجهة الحكومية على المشروع.', 'Advise the project sponsor on how the new regulations and the governmental agency''s involvement may impact the project.', false),
  (2861, 0, 'إنشاء نافذة تواصل دائمة وشفافة بين الفريق الداخلي والفريق الخارجي.', 'Establish an always-on fishbowl window between the internal and external teams.', false),
  (2861, 1, 'اعتماد سكرم السكرمات (Scrum of Scrums).', 'Introduce a Scrum of Scrums.', true),
  (2861, 2, 'مواءمة جداول التكرار لكلا الفريقين لإتاحة تقييمات رجعية مشتركة في نهاية كل دورة.', 'Align both teams'' iteration schedules to enable shared retrospectives at the end of each cycle.', false),
  (2861, 3, 'تطبيق لوحة كانبان مشتركة.', 'Implement a shared kanban board.', false),
  (2862, 0, 'تنقيح سجل المنتج قبل التكرار التالي.', 'Refine the product backlog before the next iteration.', false),
  (2862, 1, 'زيادة وتيرة اجتماعات تنقيح سجل الأعمال.', 'Increase the frequency of backlog refinement meetings.', false),
  (2862, 2, 'إجراء تقييم رجعي طارئ لتحديد السبب الجذري للفجوة وتوثيق التغيير في ميثاق المشروع.', 'Run an ad-hoc retrospective to identify the root cause of the gap and document the change in the project charter.', true),
  (2862, 3, 'معالجة المشكلة على انفراد مع قائد الفريق، مع التأكيد على أن الدور يتطلب حلًا استباقيًا وفي الوقت المناسب.', 'Address the issue privately with the team lead, reinforcing that the role requires proactive and timely resolution.', false),
  (2863, 0, 'توحيد بروتوكولات الاختبار الوحدوي في كلا مساري العمل لضمان اكتشاف العيوب بغض النظر عن موقع إجراء الاختبار.', 'Standardize unit testing protocols in both workstreams to ensure defects are caught regardless of where testing occurs.', false),
  (2863, 1, 'توزيع تحديثات سجل الإشكالات على نطاق المشروع عبر الرسائل الفورية لضمان وصول إشعارات العيوب إلى كلا مساري العمل فوريًا.', 'Distribute project-wide issue log updates via instant messaging to ensure defect notifications reach both workstreams in real time.', false),
  (2863, 2, 'مشاركة مخرجات التقييم الرجعي الرشيق مع الفريق التنبؤي لزيادة وضوح المشكلات المحددة والإجراءات التصحيحية.', 'Share agile retrospective outcomes with the predictive team to increase visibility of identified issues and corrective actions.', true),
  (2863, 3, 'دمج أنشطة تطوير البرمجيات في الجدول الزمني التنبؤي لتوحيد التخطيط وتوحيد أطر النشر.', 'Integrate the software development activities into the predictive schedule to unify planning and standardize deployment frameworks.', false),
  (2864, 0, 'يخفّف', 'Mitigate', true),
  (2864, 1, 'التحويل.', 'Transfer', false),
  (2864, 2, 'القبول.', 'Accept', false),
  (2864, 3, 'التفادي.', 'Avoid', false),
  (2865, 0, 'إجراء تحليل لإدارة المخاطر لتقييم احتمال وتأثير فجوة المتطلبات المحددة وتقييم خيارات الاستجابة المتاحة.', 'Conduct a risk management analysis to assess the probability and impact of the identified requirement gap and evaluate available response options.', false),
  (2865, 1, 'إجراء عملية تحكم متكامل في التغيير لتقييم أثر التصحيح المطلوب على جميع أبعاد التسليم الأساسية قبل الحل.', 'Perform an integrated change control process to evaluate the impact of the required correction to all core delivery dimensions before resolution.', true),
  (2865, 2, 'ضغط الجدول الزمني لاستيعاب العمل الإضافي ضمن الإطار الزمني القائم دون تجاوز قيد التمويل.', 'Compress the schedule to absorb the additional work within the existing timeline without exceeding the funding constraint.', false),
  (2865, 3, 'إشراك العميل مباشرة للتفاوض على قبول المخاطرة المحددة كقيد معروف للمنتج المُسلَّم.', 'Engage the customer directly to negotiate acceptance of the identified risk as a known limitation of the delivered product.', false),
  (2866, 0, 'نقل مسؤولية المخاطر إلى طرف خارجي من خلال ترتيب تعاقدي.', 'Transfer the risk responsibility to an external party through a contractual arrangement.', false),
  (2866, 1, 'اتخاذ خطوات استباقية لتقليل الضرر الذي قد يحدث أثناء تسليم المعدات.', 'Take proactive steps to reduce the damage that may occur during equipment delivery.', false),
  (2866, 2, 'الإقرار بالمخاطرة والمضي قدمًا دون تطبيق تدابير التخفيف.', 'Acknowledge the risk and proceed without implementing mitigation measures.', false),
  (2866, 3, 'القضاء على المخاطرة تمامًا عن طريق تولّي السيطرة المباشرة على تسليم جميع المعدات الثقيلة.', 'Eliminate the risk entirely by taking direct control of all heavy equipment delivery.', true),
  (2867, 0, 'طوِّر متطلبات مشروع تفصيلية لوضع خط أساس قبل معالجة فجوة المهارات.', 'Develop detailed project requirements to establish a baseline before addressing the skills gap.', false),
  (2867, 1, 'تطبيق تدابير ضبط الجودة لضمان أن يفي تطوير المنتج بالمعايير المعتمدة منذ البداية.', 'Implement quality control measures to ensure that product development meets the established standards from the outset.', false),
  (2867, 2, 'توثيق فجوة المهارات في ميثاق المشروع لتسجيلها كقيد معروف يتطلب الاهتمام أثناء التخطيط.', 'Capture the skills gap in the project charter to document it as a known constraint that will require attention during planning.', true),
  (2867, 3, 'إجراء تحليل للمنافسين لإجراء مقارنة مرجعية للمنتج الجديد مع العروض المتوفرة في السوق.', 'Conduct a competitor analysis to benchmark the new product against existing market offerings.', false),
  (2868, 0, 'رتِّب وفقًا لدرجة الاحتمال فقط، مع معالجة المخاطر الأعلى احتمالًا أولًا.', 'Rank by probability score alone, with the highest likelihood risks addressed first.', false),
  (2868, 1, 'الترتيب حسب درجة مجمّعة للاحتمالية والتأثير، مع معالجة أعلى تعرّض للمخاطر أولًا.', 'Rank by a combined probability and impact score, with the highest risk of exposure addressed first.', true),
  (2868, 2, 'الترتيب حسب درجة التأثير أولًا، ثم حسب الاحتمالية كعامل ترجيح للمخاطر المتساوية في التأثير.', 'Rank by impact score first and then by probability as a tiebreaker, for equally impactful risks.', false),
  (2868, 3, 'الترتيب حسب درجة التأثير وحدها مع معالجة العواقب الشديدة أولًا، بغض النظر عن الاحتمالية.', 'Rank by impact score alone with severe consequences addressed first, regardless of likelihood.', false),
  (2869, 0, 'استشر سجل القضايا لتحديد ما إذا كانت أي من المخاطر قد تحولت بالفعل إلى قضايا في المشروع تتطلب حلاً فوريًا.', 'Consult the issue log to determine whether any of the risks have already materialized into project issues, requiring immediate resolution.', false),
  (2869, 1, 'مراجعة سجل المخاطر لمقارنة المخاطر الجديدة بالمخاطر الموثَّقة وتقييمات احتماليتها وتأثيرها واستراتيجيات الاستجابة القائمة.', 'Review the risk register to compare the new risks against documented risks, their probability and impact assessments, and existing response strategies.', true),
  (2869, 2, 'الرجوع إلى خطة إدارة المخاطر لفهم المنهجية المعتمدة ومعايير التقييم والعمليات التي يستخدمها المشروع لتحديد المخاطر وتقييمها والاستجابة لها.', 'Refer to the risk management plan to understand the established methodology, scoring criteria, and processes the project uses to identify, assess, and respond to risks.', false),
  (2869, 3, 'الرجوع إلى مخزون الدروس المستفادة لتحديد ما إذا كانت مخاطر مماثلة قد ووجهت في مشاريع سابقة واستراتيجيات الاستجابة الفعالة لها.', 'Consult the lessons learned repository to identify whether similar risks were encountered on previous projects and effective response strategies.', false),
  (2870, 0, 'تحديد المخاطر المحتملة وإجراء تقييم منظم لاحتمال حدوثها وتأثيرها قبل بدء التنفيذ.', 'Identify potential risks and conduct a structured assessment of their probability and impact before execution begins.', true),
  (2870, 1, 'طلب تمويل إضافي من الراعي لتوسيع مرحلة التخطيط وتوفير مزيد من الوقت للاستعداد للمخاطر غير المتوقعة.', 'Request additional funding from the sponsor to expand the planning phase and provide more time to prepare for unforeseen risks.', false),
  (2870, 2, 'الاجتماع بالمدير الوظيفي لمناقشة الأثر المحتمل للمخاطر على توفر الموارد وقدرة الفريق.', 'Meet with the functional manager to discuss the potential impact of risks to resource availability and team capacity.', false),
  (2870, 3, 'المضي قدمًا في تنفيذ المشروع كما هو مخطط ومعالجة أي مخاطر محتملة فور ظهورها خلال دورة حياة المشروع.', 'Proceed with executing the project as planned and address any potential risks as they emerge during the project life cycle.', false),
  (2871, 0, 'احتمالية رفض الطلب استنادًا إلى افتقار الشركة للخبرة في برامج كفاءة الطاقة.', 'The likelihood of the application being rejected based on the company''s lack of experience with energy-efficiency programs.', false),
  (2871, 1, 'الأثر على سمعة الشركة إذا اكتملت المنشأة دون استيفاء معايير كفاءة الطاقة.', 'The company’s reputational impact if the facility is completed without meeting energy-efficiency standards.', false),
  (2871, 2, 'احتمالية تجاوز المشروع للجدول الزمني المقدَّر، مما يُنشئ مخاطرة على الجدول الزمني لتاريخ الإنجاز المخطط للمنشأة.', 'The probability of the project exceeding the estimated timeline, creating a schedule risk for the facility''s planned completion date.', false),
  (2871, 3, 'الزيادة المحتملة في التكلفة الإجمالية للمشروع إذا لم يكن التطبيق ناجحًا وتطلّب استراتيجية تخفيف مقابلة.', 'The potential increase in total project cost if the application is unsuccessful and requires a corresponding mitigation strategy.', true),
  (2872, 0, 'أضِف المخاطر إلى خطة إدارة المشروع كمتطلب، مع اعتبار الفريق الموزَّع قيدًا محددًا للمشروع منذ البداية.', 'Add the risk to the project management plan as a requirement, establishing the distributed team as a defined project constraint from the outset.', false),
  (2872, 1, 'تطبيق خطة لمشاركة المعنيين الرئيسيين، مع تحديد أعضاء الفريق كمعنيين يجب إدارة مواقعهم ومناطقهم الزمنية بشكل تفصيلي دقيق.', 'Implement a key stakeholder engagement plan, identifying the team members as stakeholders whose locations and time zones must be micromanaged.', false),
  (2872, 2, 'إدراج المخاطرة في ميثاق المشروع وتوثيق مخاطر التواصل والتنسيق والتعاون الناشئة عن طلب الراعي.', 'Introduce the risk in the project charter and document the communication, coordination, and collaboration risks from the sponsor’s request.', true),
  (2872, 3, 'تيسير عقد اجتماع لإدارة الموارد لتحديد كيفية تخصيص الموارد وجدولتها وإدارتها عبر المناطق الزمنية.', 'Facilitate a resource management meeting to outline how resources will be allocated, scheduled, and managed across the time zones.', false),
  (2873, 0, 'حدّث مصفوفة الاحتمال والتأثير لتعكس أي تغيّرات في ملف مخاطر المشروع بعد فشل الاستجابة.', 'Update the probability and impact matrix to reflect any changes in the project''s risk profile following the failed response.', false),
  (2873, 1, 'مراجعة سجل الافتراضات لتحديد ما إذا كانت افتراضات قديمة أو غير صحيحة قد أسهمت في فشل الاستجابة وتحديثها وفقًا لذلك.', 'Review the assumption log to identify whether outdated or incorrect assumptions contributed to the response’s failure and update them accordingly.', false),
  (2873, 2, 'توثيق الاستجابة الفاشلة للمخاطر وعواقبها والرؤى المكتسبة في سجل الدروس المستفادة.', 'Document the failed risk response, its consequences, and the insights gained in the lessons learned register.', true),
  (2873, 3, 'إضافة الاستجابة الفاشلة للمخاطر وعواقبها السلبية إلى سجل المخاطر لضمان تتبّعها مع مخاطر المشروع الحالية.', 'Add the failed risk response and its negative consequences to the risk register to ensure it is tracked along with current project risks.', false),
  (2874, 0, 'جمع معلومات إضافية للتحقق من احتمال وجود نشاط نقابي قبل تحديد الإجراء المناسب.', 'Gather additional information to validate the likelihood of union activity before determining the appropriate course of action.', true),
  (2874, 1, 'تحديث سجل المخاطر وإخطار المعنيين ذوي الصلة بالتهديد للميزانية والجدول الزمني.', 'Update the risk register and notify relevant stakeholders of the threat to the budget and schedule.', false),
  (2874, 2, 'وضع نظام مكافآت لأعضاء الفريق الذين لا يشاركون في النشاط النقابي وفرض تدابير تأديبية على من يشاركون فيه.', 'Develop a rewards system for team members who do not partake in union activity and enforce disciplinary measures for those who do.', false),
  (2874, 3, 'تيسير عقد اجتماع مع القائد النقابي لمعالجة الأثر على الميزانية والجدول الزمني بشكل استباقي.', 'Facilitate a meeting with the union leader to proactively address the budget and schedule impact.', false),
  (2875, 0, 'استبدال المقاول فورًا بمورّد جديد قادر على إكمال الأعمال المتبقية ضمن قيد الجدول الزمني.', 'Replace the contractor immediately with a new vendor capable of completing the remaining work within the schedule constraint.', false),
  (2875, 1, 'استخدام الهامش المتاح في الميزانية للاستعانة ببائعين بدلاء يمكنهم تعزيز قدرة المقاول الحالي وتسريع الإنجاز.', 'Use the available budget buffer to engage alternative vendors who can supplement the current contractor''s capacity and accelerate completion.', false),
  (2875, 2, 'إشراك المقاول في نقاش حول التداعيات التعاقدية للتأخير والتفاوض على التزام مُلزِم بالإنجاز في الوقت المحدد.', 'Engage the contractor in a discussion about the contractual implications of the delay and negotiate a binding commitment to on-time completion.', true),
  (2875, 3, 'تصعيد التأخير إلى راعي المشروع فورًا وطلب توجيه حول كيفية المضي قدمًا في ظل قيد الجدول الزمني.', 'Escalate the delay to the project sponsor immediately and request guidance on how to proceed given the schedule constraint.', false),
  (2876, 0, 'قم بتوثيق الفجوة في سجل المخاطر، ووضع خطة عمل لإكمال التدريب المطلوب.', 'Document the gap in the risk register and develop an action plan to complete the required training.', true),
  (2876, 1, 'تحديث سجل المخاطر لتضمين فجوة التدريب ومناقشة البند في اجتماع التنسيق التالي.', 'Update the risk log to include the training gap and discuss the item in the next coordination meeting.', false),
  (2876, 2, 'تخصيص موارد إضافية لاستبدال المستخدمين النهائيين الذين لا يُكملون التدريب المطلوب.', 'Allocate additional resources to replace end users that do not complete the required training.', false),
  (2876, 3, 'مراجعة الجدول الزمني للمشروع لتخصيص وقت لاستيعاب تدريب المستخدم النهائي غير المكتمل.', 'Revise the project schedule to allocate time to accommodate the incomplete end user training.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2877, 0, 'راجع خطة إدارة المخاطر لتحديد ما إذا كان هذا النوع من الإخفاق قد تم التعرف عليه كخطر، وما إذا كانت هناك استراتيجيات استجابة محددة مسبقًا متاحة.', 'Review the risk management plan to determine whether this type of failure was identified as a risk and if predefined response strategies are available.', true),
  (2877, 1, 'التواصل مع الخبراء المتخصصين المحليين لجمع وجهات نظرهم حول كيفية تعاملهم مع عطل المكوّن هذا.', 'Reach out to local subject matter experts to gather their perspectives on how they would approach this component failure.', false),
  (2877, 2, 'مراجعة الجدول الزمني للمشروع لمراعاة تأخر الجدول الناتج عن تدابير التخفيف المتخذة لمعالجة عطل المكوّن.', 'Revise the project timeline to account for the schedule slippage resulting from the mitigation measures taken to address the component failure.', false),
  (2877, 3, 'إخطار جميع المعنيين بعطل المكوّن، مع تحديد التكاليف المتوقعة والتغييرات المحتملة قبل اكتمال التقييم الكامل.', 'Notify all stakeholders of the component''s failure, outlining the anticipated costs and potential changes before a full assessment is complete.', false),
  (2878, 0, 'التعاون مع فريق المشروع لتحديد المخاطر الجديدة وتقييمها قبل تحديد كيفية الاستجابة لها.', 'Collaborate with the project team to identify and evaluate the new risks before determining how to respond.', true),
  (2878, 1, 'العودة إلى الجدول الزمني الأصلي، وإزالة تداخل الأنشطة الحرجة، وفرض تسلسل التسليم المعتمد.', 'Revert to the original schedule, eliminate the overlap of critical activities, and enforce the approved delivery sequence.', false),
  (2878, 2, 'مراجعة سجل المخاطر لتحديد تغيير الجدول الزمني وترتيب جميع مخاطر المشروع لتعكس مشهد التهديدات الجديد.', 'Revise the risk log to identify the schedule change and rank all project risks to reflect the new threat landscape.', false),
  (2878, 3, 'إسناد استراتيجيات الاستجابة للمخاطر إلى المخاطر المستحدثة والتخفيف من تداخل الأنشطة الحرجة في الجدول الزمني المنقَّح.', 'Assign risk response strategies to the newly introduced risks and mitigate the overlap of critical activities on the revised schedule.', false),
  (2879, 0, 'دمج درجات الاحتمال والتأثير، مع معالجة أعلى مستويات التعرض للمخاطر أولاً.', 'Combining probability and impact scores, with the highest overall risk exposure addressed first.', true),
  (2879, 1, 'حسب درجة الاحتمالية وحدها، مع معالجة المخاطر الأكثر احتمالًا أولًا بغض النظر عن تأثيرها.', 'By probability score alone, with the most likely risks addressed first regardless of their impact.', false),
  (2879, 2, 'حسب درجة التأثير وحدها، بمعالجة المخاطر ذات العواقب الأشد أولًا، بغض النظر عن احتمالية حدوثها.', 'By impact score alone, addressing risks with the most severe consequences first, regardless of their likelihood of occurrence.', false),
  (2879, 3, 'حساب الفرق بين درجتي الاحتمالية والتأثير، ومعالجة المخاطر التي يتجاوز فيها التأثير الاحتمالية بشكل كبير أولًا.', 'Calculating the difference between probability and impact scores, addressing risks where impact significantly exceeds probability first.', false),
  (2880, 0, 'راجع تقرير المخاطر ومستودع الدروس المستفادة.', 'Review the risk report and lessons learned repository.', false),
  (2880, 1, 'الرجوع إلى أصول عمليات المؤسسة وسجل المخاطر.', 'Consult the organizational process assets and risk register.', false),
  (2880, 2, 'الرجوع إلى خطة إدارة المخاطر وتقرير المخاطر قبل إضافة معلومات جديدة.', 'Refer to the risk management plan and risk report before adding new information.', false),
  (2880, 3, 'توثيق المخاطر في سجل المخاطر وتحليل أثرها وتحديد خطط الاستجابة.', 'Document risks in the risk register, analyze their impact, and identify response plans.', true),
  (2881, 0, 'ركّز على خطة المشروع المعتمدة وأَعطِ أولوية للتسليم في الوقت المحدد باعتباره المقياس الأساسي للنجاح.', 'Focus on the approved project plan and prioritize on-time delivery as the primary measure of success.', false),
  (2881, 1, 'طلب تمويل إضافي لتوسيع مرحلة التخطيط وزيادة القدرة على مواجهة المخاطر غير المحددة.', 'Request additional funding to expand the planning phase and increase capacity for unidentified risks.', false),
  (2881, 2, 'إشراك المعنيين ذوي الصلة في عملية تحديد المخاطر وتقييمها لوضع نهج مشترك للمخاطر.', 'Engage relevant stakeholders in a risk identification and assessment process to develop a shared risk approach.', true),
  (2881, 3, 'تحديد المخاطر وتقييمها بشكل مستقل وعرض النتائج على مسؤولي المدينة للموافقة قبل المضي قدمًا.', 'Independently identify and assess risks and present the findings to city officials for approval before moving forward.', false),
  (2882, 0, 'توثيق حالة عدم اليقين في سجل المخاطر وتطوير استراتيجية استجابة مقابلة لها.', 'Document the uncertainty in the risk register and develop a corresponding response strategy.', true),
  (2882, 1, 'رفع التصنيف الإجمالي للمخاطر ليعكس زيادة التعرّض المالي الناتج عن فقدان الدعم.', 'Elevate the overall risk rating to reflect the increased financial exposure of the subsidy loss.', false),
  (2882, 2, 'تخصيص جزء من احتياطي الطوارئ لتغطية فجوة التمويل المتوقعة.', 'Designate a portion of the contingency reserve to cover the projected funding gap.', false),
  (2882, 3, 'تقديم طلب تغيير رسمي لتعديل ميزانية المشروع ونطاقه.', 'Submit a formal change request to adjust the project''s budget and scope.', false),
  (2883, 0, 'تحديث خطة إشراك المعنيين لضمان تسجيل احتياجات السلامة لأعضاء الفريق الجدد وضمان تلبيتها.', 'Update the stakeholder engagement plan to ensure the new team members’ safety needs are recorded and guaranteed.', false),
  (2883, 1, 'تصعيد المخاطر المالية ومخاطر السلامة والمخاطر التشغيلية الناشئة عن مطالبة الفرق بالعمل في مناوبات ليلية في ظروف غير آمنة.', 'Escalate the financial, safety, and operational risks introduced by requiring teams to work night shifts in unsafe conditions.', false),
  (2883, 2, 'إعادة هيكلة خطة المشروع لتضمين متطلبات الفرق كشروط إلزامية لتنفيذ هيكل المناوبات الجديد.', 'Restructure the project plan to include the teams’ requirements as mandatory conditions for executing the new shift structure.', true),
  (2883, 3, 'تحديد حدود ما سيغطّيه المشروع وما لن يغطّيه فيما يتعلق بعمليات المناوبة الليلية والتزامات السلامة.', 'Define the boundaries of what the project will and will not cover regarding nighttime shift operations and safety obligations.', false),
  (2884, 0, 'تسجيل قرار تغيير المورّد وعواقبه في سجل الدروس المستفادة لإعلام قرارات الاستجابة للمخاطر.', 'Capture the supplier change decision and its consequences in the lessons learned register to inform risk response decisions.', false),
  (2884, 1, 'مراجعة سجل الافتراضات لتحديد ما إذا كانت افتراضات غير صحيحة بشأن معايير جودة المورد الجديد قد أسهمت في مخاطرة الجودة غير المكتشفة.', 'Review the assumption log to identify if incorrect assumptions about the new supplier''s quality standards contributed to the undetected quality risk.', false),
  (2884, 2, 'إنشاء لوحة كانبان لمراقبة فعالية الاستجابات المطبقة للمخاطر والتحقق منها قبل إغلاق الإشكال.', 'Establish a kanban board to monitor and validate the effectiveness of implemented risk responses before closing the issue.', true),
  (2884, 3, 'تقييم مخاطر الجودة الناشئة عن تغيير المورد وتحديث مصفوفة الاحتمالية والتأثير لتعكس ملف المخاطر المنقَّح للمشروع.', 'Assess the quality risk introduced by the supplier change and update the probability and impact matrix to reflect the project''s revised risk profile.', false),
  (2885, 0, 'وضع خطة لإشراك المعنيين.', 'Develop a stakeholder engagement plan.', true),
  (2885, 1, 'مراجعة أهداف المشروع مع الراعي.', 'Review project objectives with the sponsor.', false),
  (2885, 2, 'تيسير عقد اجتماع للمعنيين للتوصل إلى توافق.', 'Facilitate a stakeholder meeting to gain consensus.', false),
  (2885, 3, 'مراجعة سجل المعنيين وتحديثه.', 'Review and update the stakeholder register.', false),
  (2886, 0, 'قارن نطاق المشروع مع معايير القبول المعتمدة قبل التواصل مع صاحب المصلحة.', 'Compare the project scope with the approved acceptance criteria, prior to engaging with the stakeholder.', true),
  (2886, 1, 'جدولة مكالمة مع المعني لمراجعة ميثاق المشروع وإعادة مواءمة توقعاته.', 'Schedule a call with the stakeholder to review the project charter and realign their expectations.', false),
  (2886, 2, 'مراجعة خطة إدارة الجودة مع المعني لإثبات أن التسليمات تفي بمعايير القبول.', 'Review the quality management plan with the stakeholder to show deliverables meet the acceptance criteria.', false),
  (2886, 3, 'إجراء تحليل للمخاطر مع راعي المشروع لتقييم أثر إدخال متطلبات إضافية.', 'Conduct a risk analysis with the project sponsor to assess the impact of introducing additional requirements.', false),
  (2887, 0, 'الاجتماع مع صاحب المصلحة الجديد لمراجعة خطة إشراك المعنيين وتقييم مستوى مشاركته الحالي.', 'Meet with the new stakeholder to review the stakeholder engagement plan and assess their current level of engagement.', true),
  (2887, 1, 'مشاركة الجدول الزمني للمشروع والمهام المسندة إلى المعني الجديد لتوضيح مسؤولياته وترسيخ المساءلة.', 'Share the project schedule and the tasks assigned to the new stakeholder to clarify their responsibilities and establish accountability.', false),
  (2887, 2, 'مطالبة المدير الوظيفي بإطلاع المعني الجديد شخصيًا على مسؤولياته واشتراط حضوره جميع الاجتماعات.', 'Ask the functional manager to personally brief the new stakeholder on their responsibilities and demand they attend all meetings.', false),
  (2887, 3, 'إقران المعني الجديد بعضو أكثر خبرة لمساعدته على الاندماج في هيكل مشاركة المشروع.', 'Pair the new stakeholder with a more experienced member to help them integrate into the project''s engagement structure.', false),
  (2888, 0, 'أجرِ تحليلًا لالمعنيين قبل تحديد نهج فعّال لحلّ الخلاف.', 'Conduct a stakeholder analysis before determining an effective approach for resolving the disagreement.', false),
  (2888, 1, 'تيسير حوار، مع تطبيق أساليب إدارة النزاعات لإيجاد أرضية مشتركة والتوصل إلى اتفاق.', 'Facilitate a dialogue, applying conflict management techniques to find common ground and reach an agreement.', true),
  (2888, 2, 'تصعيد النزاع إلى راعي المشروع وطلب أن تنعكس رؤيته في ميثاق المشروع.', 'Escalate the conflict to the project sponsor and request their vision be reflected in the project charter.', false),
  (2888, 3, 'استخدام اجتماع بدء المشروع كمنتدى لعرض الرؤى المتنافسة قبل اعتماد ميثاق المشروع.', 'Use the project kickoff meeting as the forum for presenting competing visions before the project charter is approved.', false),
  (2889, 0, 'زيادة تكرار تحديثات حالة المعنيين طوال المشروع.', 'Increase the frequency of stakeholder status updates throughout the project.', false),
  (2889, 1, 'إجراء تقييمات منتظمة للمخاطر لتحديد التهديدات الناشئة والاستجابة لها.', 'Conduct regular risk assessments to identify and respond to emerging threats.', false),
  (2889, 2, 'تطبيق أساليب إدارة النزاعات لمنع تصاعد التوترات.', 'Apply conflict management techniques to prevent tensions from escalating.', false),
  (2889, 3, 'دمج ملاحظات المعنيين في نقاط رئيسية متعددة طوال المشروع.', 'Incorporate stakeholder feedback at various key points throughout the project.', true),
  (2890, 0, 'قم بتحديث سجل المعنيين أولاً، ثم خطة إشراك المعنيين.', 'Update the stakeholder register first, then the stakeholder engagement plan.', true),
  (2890, 1, 'توثيق مشهد المعنيين الحالي في ميثاق المشروع.', 'Document the current stakeholder landscape in the project charter.', false),
  (2890, 2, 'مطالبة راعي المشروع بتعيين معني بديل.', 'Request the project sponsor assign a replacement stakeholder.', false),
  (2890, 3, 'تحديث خطة مشاركة المعنيين وخطة إدارة التواصل وفقًا لذلك.', 'Update the stakeholder engagement and communications management plans accordingly.', false),
  (2891, 0, 'قم بإعداد شرائح عرض توضيحية تبيّن دور كل صاحب مصلحة ومستوى المشاركة المتوقع منه.', 'Develop presentation slides that outline each stakeholder’s role and expected level of involvement.', false),
  (2891, 1, 'تحديد جدول زمني يستوعب توفر جميع المعنيين بغض النظر عن المناطق الزمنية.', 'Identify a schedule that captures all of the stakeholders’ availability regardless of time zones.', false),
  (2891, 2, 'التأكد من أن جميع المشاركين أو مندوبيهم المعيَّنين متاحون وملتزمون بالحضور.', 'Confirm that all participants or their designated delegates are available and committed to attending.', true),
  (2891, 3, 'إجراء مراجعة لمواد المشروع لضمان وضوح المحتوى لجمهور عالمي متنوع.', 'Conduct a review of the project materials to ensure the content is clear to a diverse global audience.', false),
  (2892, 0, 'طبّق نموذج البروز لتوجيه استراتيجية تواصل أكثر استهدافًا.', 'Apply the salience model to inform a more targeted engagement strategy.', true),
  (2892, 1, 'توجيه دعوات للمعنيين ذوي الصلة لحضور اجتماعات الفريق بانتظام.', 'Extend invitations to relevant stakeholders to regularly attend team meetings.', false),
  (2892, 2, 'تحديث خطة مشاركة المعنيين لتعكس ملاحظات الاستبيان الإلزامية.', 'Update the stakeholder engagement plan to reflect mandatory survey feedback.', false),
  (2892, 3, 'تطبيق مبادئ القيادة الخادمة لإعطاء الأولوية لاحتياجات المعنيين.', 'Apply servant leadership principles to prioritize the stakeholders'' needs.', true),
  (2892, 4, 'مشاركة مصفوفة مشاركة المعنيين مع فريق المشروع.', 'Share the stakeholder engagement matrix with the project team.', false),
  (2893, 0, 'إجراء تقييمات متكررة للمخاطر لتحديد التهديدات التي قد تؤثر في رضا المعنيين وتحديد الإجراءات التصحيحية اللازمة.', 'Conduct frequent risk assessments to identify threats to stakeholder satisfaction and determine corrective action.', false),
  (2893, 1, 'تطبيق أساليب الذكاء العاطفي عند نشوء خلافات المستخدمين لمنع تصاعد التوترات غير المحلولة.', 'Apply emotional intelligence techniques when user disagreements arise to prevent unresolved tensions from escalating.', false),
  (2893, 2, 'تطبيق ممارسات مشاركة المعنيين طوال دورة حياة المشروع لتحديد احتياجات المستخدمين وتتبّعها ومعالجتها.', 'Apply stakeholder engagement practices throughout the project life cycle to identify, track, and address user needs.', true),
  (2893, 3, 'الحفاظ على علاقات مهنية مع المستخدمين لإيجاد بيئة تتواءم فيها التوقعات.', 'Maintain professional relationships with users to create an environment where expectations are aligned.', false),
  (2894, 0, 'تجنّب الخطر ثم حدّث خطة إشراك المعنيين لتعكس هذا التغيير.', 'Avoid the risk and then update the stakeholder engagement plan to reflect this change.', false),
  (2894, 1, 'تفادي المخاطرة ثم تحديث سجل المعنيين ليعكس قدرتهم.', 'Avoid the risk and then update the stakeholder register to reflect their capacity.', false),
  (2894, 2, 'تخفيف المخاطرة ثم تحديث خطة مشاركة المعنيين لتعديل استراتيجيات التواصل والمشاركة وفقًا لذلك.', 'Mitigate the risk and then update the stakeholder engagement plan to adjust communication and engagement strategies accordingly.', true),
  (2894, 3, 'تخفيف المخاطرة ثم تحديث تقويم الموارد لتسجيل التغيير في توفر المعني ومستوى مساهمته.', 'Mitigate the risk and then update the resource calendar to capture the change in the stakeholder''s availability and contribution level.', false),
  (2895, 0, 'الاستعانة بمستشار طرف ثالث يمتلك خبرة متخصصة لوضع إطار شامل لنطاق العمل.', 'Engage a third-party consultant with specialized expertise to develop a comprehensive scope framework.', false),
  (2895, 1, 'التعاون مع معنيي المشروع لاعتماد نهج تكراري يتيح تنقيح النطاق بشكل تدريجي.', 'Collaborate with project stakeholders to introduce an iterative approach that allows the scope to be progressively refined.', true),
  (2895, 2, 'مراجعة خطة إدارة المشروع لتحديد مرونة الجدول الزمني وإجراء تمرين شامل لتحديد النطاق.', 'Review the project management plan to identify schedule flexibility and conduct a thorough scope definition exercise.', false),
  (2895, 3, 'المضي قدمًا في المشروع ومراقبة الجدول الزمني يوميًا لإدارة مسائل الطوارئ فور ظهورها أثناء التنفيذ.', 'Proceed with the project and monitor the schedule daily to manage contingency issues as they emerge during execution.', false),
  (2896, 0, 'اجتماعات التقييم الرجعي في السبرينت', 'Sprint retrospectives', false),
  (2896, 1, 'استشارات المنتج.', 'Product consultations', false),
  (2896, 2, 'اجتماعات التنسيق اليومية.', 'Daily coordination meetings', true),
  (2896, 3, 'مراجعات أداء الفريق.', 'Team performance reviews', true),
  (2896, 4, 'جلسات ملاحظات المستخدم النهائي', 'End-user feedback sessions', false),
  (2897, 0, 'سيتم تنفيذ أنشطة المسار الحرج بالتوازي لتقصير الجدول الزمني.', 'Execution of critical path activities will run in parallel to compress the schedule.', true),
  (2897, 1, 'سيُراجَع نطاق المشروع لتأجيل التسليمات غير الحرجة.', 'The project scope will be revised to defer noncritical deliverables.', false),
  (2897, 2, 'ستنخفض المخاطر المرتبطة بجهد استرداد الجدول الزمني.', 'Risks associated with the schedule recovery effort will decrease.', false),
  (2897, 3, 'ستزداد تكاليف المشروع مع إضافة موارد إضافية للوفاء بالمسار الحرج.', 'Project costs will increase as additional resources are added to meet the critical path.', true),
  (2897, 4, 'يجب أن يتوقع فريق المشروع إعادة العمل الناتجة عن الجدول الزمني المضغوط.', 'The project team should expect rework resulting from the compressed schedule.', false),
  (2898, 0, 'تشير قيمة مؤشر أداء الجدول الزمني (SPI) البالغة 0.98 إلى أن المشروع متأخر عن الجدول الزمني.', 'The SPI of 0.98 indicates the project is behind schedule.', false),
  (2898, 1, 'يشير مؤشر أداء الجدول الزمني (SPI) البالغ 0.72 إلى أن المشروع متقدم على الجدول الزمني.', 'The SPI of 0.72 indicates the project is ahead of schedule.', false),
  (2898, 2, 'يشير مؤشر أداء الجدول الزمني (SPI) البالغ 0.98 إلى أن المشروع متقدم قليلًا على الجدول الزمني.', 'The SPI of 0.98 indicates the project is slightly ahead of schedule.', false),
  (2898, 3, 'يشير مؤشر أداء الجدول الزمني (SPI) البالغ 0.72 إلى أن المشروع متأخر بشكل كبير عن الجدول الزمني.', 'The SPI of 0.72 indicates the project is significantly behind schedule.', true),
  (2899, 0, 'قدّم طلب تغيير رسميًا لإنشاء خط أساس جديد للتكلفة.', 'Submit a formal change request to establish a new cost baseline.', true),
  (2899, 1, 'طلب موارد إضافية لزيادة قدرة الفريق.', 'Request additional resources to increase the team''s capacity.', false),
  (2899, 2, 'ضغط الجدول الزمني للمشروع عن طريق ضغط زمن أنشطة المسار الحرج.', 'Compress the project schedule by crashing critical path activities.', false),
  (2899, 3, 'استخدام الاحتياطي الإداري لتغطية تجاوز التكلفة.', 'Utilize the management reserve to cover the cost overrun.', false),
  (2900, 0, 'المشروع متقدم على الجدول الزمني وأقل من الميزانية، مما يشير إلى أداء أقوى من المخطط له بتكلفة أقل من المتوقعة.', 'The project is ahead of schedule and under budget indicating stronger than planned delivery at a cost lower than expected.', false),
  (2900, 1, 'المشروع متأخر عن الجدول الزمني ومتجاوز للميزانية، مما يشير إلى تسليم قيمة أقل وتجاوز التكلفة المخططة.', 'The project is behind schedule and over budget, indicating that less value has been delivered and exceeding planned cost.', true),
  (2900, 2, 'المشروع متقدم على الجدول الزمني ومتجاوز للميزانية، مما يشير إلى تسليم أسرع من المخطط لكنه يتجاوز التكلفة المخططة.', 'The project is ahead of schedule and over budget, indicating faster than planned delivery but exceeding planned cost.', false),
  (2900, 3, 'المشروع متأخر عن الجدول الزمني وأقل من الميزانية، مما يشير إلى تسليم قيمة أقل ضمن التكلفة المخططة.', 'The project is behind schedule and under budget, indicating that less value has been delivered within the planned cost.', false),
  (2901, 0, 'التواصل مع المدير الوظيفي لعضو الفريق للتفاوض بشأن تخصيص الموارد.', 'Engage with the team member''s functional manager to negotiate resource allocation.', true),
  (2901, 1, 'تأمين مورد خارجي لتحويل المهمة إليه.', 'Secure an external resource to transfer the assignment.', false),
  (2901, 2, 'توثيق تعارض الجدولة كإشكال امتثال.', 'Document the scheduling conflict as a compliance issue.', false),
  (2901, 3, 'مطالبة أعضاء الفريق بإعطاء الأولوية لمهام المشروع المهمة حتى اكتمالها.', 'Demand the team members prioritize important project assignments until they are complete.', false),
  (2902, 0, 'تشير قيمة مؤشر الأداء للتكلفة (CPI) البالغة 0.71 إلى أن المشروع يتجاوز الميزانية بشكل كبير.', 'A CPI of 0.71 indicates the project is substantially over budget.', true),
  (2902, 1, 'يشير مؤشر أداء التكلفة (CPI) البالغ 0.79 إلى أن المشروع شبه مطابق للميزانية.', 'A CPI of 0.79 indicates the project is nearly on budget.', false),
  (2902, 2, 'يشير مؤشر أداء التكلفة (CPI) البالغ 0.71 إلى أن المشروع ضمن الميزانية.', 'A CPI of 0.71 indicates the project is within budget.', false),
  (2902, 3, 'يشير مؤشر أداء التكلفة (CPI) البالغ 0.79 إلى أن المشروع متجاوز للميزانية قليلًا.', 'A CPI of 0.79 indicates the project is slightly over budget.', false),
  (2903, 0, 'مؤشر أداء الجدول الزمني (SPI) بقيمة 0.93 ومؤشر أداء التكلفة (CPI) بقيمة 1.13', 'SPI of 0.93 and CPI of 1.13', true),
  (2903, 1, 'مؤشر أداء الجدول الزمني (SPI) البالغ 1.07 ومؤشر أداء التكلفة (CPI) البالغ 0.99.', 'SPI of 1.07 and CPI of 0.99', false),
  (2903, 2, 'مؤشر أداء الجدول الزمني (SPI) البالغ 1.15 ومؤشر أداء التكلفة (CPI) البالغ 0.93.', 'SPI of 1.15 and CPI of 0.93', false),
  (2903, 3, 'مؤشر أداء الجدول الزمني (SPI) البالغ 0.96 ومؤشر أداء التكلفة (CPI) البالغ 1.18.', 'SPI of 0.96 and CPI of 1.18', false),
  (2904, 0, 'رئيس الشؤون المالية للأعمال', 'The head of business finance', false),
  (2904, 1, 'مالك المنتج.', 'The product owner', true),
  (2904, 2, 'مدير المشتريات.', 'The procurement manager', false),
  (2904, 3, 'مدير البرنامج.', 'The program manager', false),
  (2905, 0, 'من النهاية إلى البداية', 'Finish-to-start', false),
  (2905, 1, 'نهاية إلى نهاية.', 'Finish-to-finish', true),
  (2905, 2, 'بداية إلى بداية.', 'Start-to-start', false),
  (2905, 3, 'بداية إلى نهاية.', 'Start-to-finish', false),
  (2906, 0, 'أ. التقدير القياسي باستخدام بيانات التكاليف من مشاريع سابقة مماثلة.', 'A. Analogous estimation by using cost data from similar past projects.', false),
  (2906, 1, 'ب. التقدير ثلاثي النقاط عن طريق حساب متوسط تكلفة مرجح.', 'B. Three-point estimation by calculating a weighted cost average.', false),
  (2906, 2, 'ج. التقدير من القاعدة إلى القمة عن طريق تجميع التقديرات الفردية لتكلفة كل مكوّن محدد.', 'C. Bottom-up estimation by aggregating the individual cost estimates of each defined component.', true),
  (2906, 3, 'د. التقدير باستخدام المعاملات عن طريق استخدام العلاقات الإحصائية بين البيانات التاريخية وتكاليف المشروع.', 'D. Parametric estimation by using statistical relationships between historical data and project costs.', false),
  (2907, 0, '٢٠ يومًا', '20 days', false),
  (2907, 1, '30 يومًا.', '30 days', false),
  (2907, 2, '40 يومًا.', '40 days', true),
  (2907, 3, '60 يومًا.', '60 days', false),
  (2908, 0, 'حساب مُرجَّح يقلّل بدرجة كبيرة من التقدير التشاؤمي المعدَّل حسب المخاطر الذي قدّمه خبير الموضوع الثاني.', 'A weighted calculation that heavily discounts the risk-adjusted pessimistic estimate provided by the second SME.', false),
  (2908, 1, 'متوسط تقديرات الخبراء المتخصصين الثلاثة باستخدام صيغة التقدير المثلثي.', 'An average of the three SME estimates using the triangular estimation formula.', true),
  (2908, 2, 'حساب يطبّق ترجيحًا إضافيًا للتقدير المقدَّم من الخبير المتخصص الأول.', 'A calculation that applies additional weight to the estimate provided by the first SME.', false),
  (2908, 3, 'متوسط يطبّق الترجيح الأكبر للتقدير المُعجَّل المعدَّل حسب المخاطر المقدَّم من الخبير المتخصص الثالث.', 'An average that applies the greatest weight to the accelerated 4risk-adjusted estimate provided by the third SME.', false),
  (2909, 0, '12 يومًا', '12 days', false),
  (2909, 1, '16 يومًا.', '16 days', true),
  (2909, 2, '14 يومًا.', '14 days', false),
  (2909, 3, '20 يومًا.', '20 days', false),
  (2910, 0, 'أعد القصص غير المكتملة إلى سجل المنتج وارجئها إلى تكرار أقل تطلبًا.', 'Return the incomplete stories to the product backlog and defer them to a less demanding iteration.', false),
  (2910, 1, 'استخدام التكرار التالي لإجراء بند استكشافي (spike) جماعي يبحث في الجدوى الفنية لإنجاز القصص.', 'Use the next iteration for a team spike that investigates the technical feasibility of completing the stories.', false),
  (2910, 2, 'نقل القصص غير المكتملة إلى عمود "محظور" وإشراك مالك المنتج لتحديد العوائق التي تمنع إنجازها وإزالتها.', 'Move the incomplete stories to the blocked column and engage the product owner to identify and remove the impediments preventing their completion.', false),
  (2910, 3, 'التعاون مع مالك المنتج لتجزئة القصص غير المكتملة إلى أجزاء أصغر وأكثر قابلية للإدارة وتحديث تعريف الجاهزية.', 'Collaborate with the product owner to break down the incomplete stories into smaller, more manageable pieces and update the definition of ready.', true),
  (2911, 0, 'لقد انحرف الفريق عن المعايير القياسية للتطوير.', 'The team has deviated from standard development norms.', false),
  (2911, 1, 'اعتمد المورد نهج البرمجة القصوى (XP).', 'The supplier has adopted an extreme programming (XP) approach.', true),
  (2911, 2, 'تزامنت زيارة مدير المشروع مع تمرين لبناء الفريق.', 'The project manager''s visit coincided with a team-building exercise.', false),
  (2911, 3, 'اعتمد المورد نهج التطوير المُوجَّه بالميزات (FDD).', 'The supplier has adopted a feature-driven development (FDD) approach.', false),
  (2912, 0, 'راقب حالة الجاهزية بحيث يتمكن الفريق من بدء العمل في الوقت المناسب عند استيفاء المتطلبات المسبقة.', 'Monitor readiness status so that the team can initiate work at the right time when prerequisites are met.', true),
  (2912, 1, 'تحديد مواعيد نهائية لترسيخ المساءلة وضمان إنجاز الفريق للعمل ضمن حدود زمنية مقبولة.', 'Set deadlines to create accountability and ensure the team completes work within acceptable time limits.', false),
  (2912, 2, 'تطبيق لوحة كانبان تنظّم العمل في صفوف حسب الهدف وتتتبّع التقدم عبر الأعمدة.', 'Implement a kanban board that organizes work into rows by goal and tracks progress across columns.', false),
  (2912, 3, 'الاحتفاظ بقائمة مهام مشتركة تحدّ من عدد المهام قيد التنفيذ لمنع إثقال كاهل الفريق.', 'Maintain a shared to-do list that limits the number of tasks in progress to prevent overloading the team.', false),
  (2912, 4, 'حدِّد العوائق المحتملة مسبقًا لتحديد الترتيب الأكثر منطقية وكفاءة لتنفيذ المهام.', 'Identify potential blockers in advance to determine the most logical and efficient order of task execution.', true),
  (2913, 0, 'دمج اجتماع "سكرم من السكرم".', 'Integrate a Scrum of Scrums.', true),
  (2913, 1, 'الاستفادة من البرمجة الجماعية (mob programming).', 'Leverage mob programming.', false),
  (2913, 2, 'إعداد بيان عمل (SOW).', 'Develop a statement of work (SOW).', false),
  (2913, 3, 'توظيف التطوير المُوجَّه بالميزات (FDD).', 'Employ feature-driven development (FDD).', false),
  (2914, 0, 'تيسير جلسات تنقيح سجل الأعمال للفريق بحيث تستند التقديرات المستقبلية إلى معلومات موثوقة.', 'Facilitate team backlog refinement sessions so that future estimates are rooted in reliable information.', true),
  (2914, 1, 'ضبط توقعات المعنيين بأن توقعات تاريخ الإنجاز ستتذبذب مع تطوّر سجل الأعمال.', 'Set stakeholder expectations that completion date forecasts will fluctuate as the backlog evolves.', false),
  (2914, 2, 'تطبيق تكرارات متغيرة الحجم مُعايَرة وفق تعقيد القصص وحجمها في كل دورة.', 'Implement variable-size iterations calibrated to the complexity and volume of stories in each cycle.', false),
  (2914, 3, 'تقليل وتيرة تقارير التقدم للحدّ من الانكشاف وتجنّب تقديم توقّع للإنجاز.', 'Reduce the frequency of progress reports to limit exposure and avoid providing a completion forecast.', false),
  (2915, 0, '١٫٠٥', '1.05', true),
  (2915, 1, '1.30.', '1.30', false),
  (2915, 2, '1.01.', '1.01', false),
  (2915, 3, '0.95.', '0.95', false),
  (2916, 0, 'إزالة الاعتماد المتبادل بين الفرق حتى تتمكن الفرق من العمل دون الاعتماد على مخرجات الفرق الأخرى.', 'Eliminate inter-team dependencies so teams can operate without relying on other teams’ outputs.', false),
  (2916, 1, 'تقليل الأعباء الإضافية للجدولة عن طريق استبدال الاجتماعات بين الفرق بأدوات تعاون مشتركة.', 'Reduce scheduling overhead by replacing cross-team meetings with shared collaboration tools.', false),
  (2916, 2, 'اعتماد سكرم السكرمات (Scrum of Scrums) ليجتمع ممثلو الفرق وفق إيقاع منتظم.', 'Introduce a Scrum of Scrums so team representatives come together on a regular cadence.', true),
  (2916, 3, 'تبسيط إدارة الاعتماديات بين الفرق عن طريق دمج الفرق في فريق كبير موحّد.', 'Simplify the management of inter-team dependencies by merging teams into a unified large team.', false),
  (2917, 0, 'قابل سكرم ماستر فورًا لتحديد ما إذا كان ينبغي للمشروع أن يستمر أم لا.', 'Meet with the scrum master immediately to determine whether the project should continue.', false),
  (2917, 1, 'التواصل مع مالك المنتج والفريق لتحديث سجل أعمال المنتج أثناء الإطلاق.', 'Engage with the product owner and team to update the product backlog during the sprint.', true),
  (2917, 2, 'تيسير تحليل السبب الجذري لتحديد سبب عدم اكتشاف عدم التوافق في وقت أبكر.', 'Facilitate a root cause analysis to determine why the incompatibility was not identified earlier.', false),
  (2917, 3, 'الإعلان عن تغيير نظام التشغيل في الاجتماع التالي وتحديث تعريف المنجز.', 'Announce an operating system change at the next meeting and update the definition of done.', false),
  (2918, 0, 'تعريف الجاهزية (DoR) ومعالم الاعتماديات.', 'The definition of ready (DoR) and the dependency milestones.', false),
  (2918, 1, 'تجزئة الملحمة ومعايير الخروج.', 'The epic breakdown and the exit criteria.', true),
  (2918, 2, 'سجل أعمال المنتج وتسلسل مهام المسار الحرج.', 'The product backlog and the critical path task sequence.', true),
  (2918, 3, 'تعريف المنجز (DoD) ومعايير الخروج.', 'The definition of done (DoD) and the exit criteria.', false),
  (2918, 4, 'تعريف الجاهزية (DoR) وهيكل تقسيم العمل (WBS).', 'The definition of ready (DoR) and the work breakdown structure (WBS).', false),
  (2919, 0, 'دمج المهام الصغيرة وفقًا لحجمها والجهد المطلوب لها مع إعطاء الأولوية لتحقيق الاتساق.', 'Consolidate minor tasks according to their size and effort prioritizing alignment.', false),
  (2919, 1, 'إعادة تحديد أولويات سجل الأعمال لتفضيل أصغر القصص وإعادة إسنادها يوميًا.', 'Reprioritize the backlog to favor the smallest stories and reassign them daily.', false),
  (2919, 2, 'إعادة تحديد أولويات سجل الأعمال يوميًا بحيث ترتقي المهام القابلة للتنفيذ تلقائيًا إلى القمة.', 'Reprioritize the backlog daily so that actionable tasks automatically rise to the top.', true),
  (2919, 3, 'دمج المهام الثانوية إما في تعريف المنجز (DoD) أو في معايير القبول.', 'Integrate minor tasks into either the definition of done (DoD) or the acceptance criteria.', false),
  (2920, 0, 'مخطط مبعثر', 'Scatter diagram', false),
  (2920, 1, 'مخطط التقارب.', 'Affinity diagram', false),
  (2920, 2, 'خريطة المراقبة.', 'Control chart', true),
  (2920, 3, 'المدرج التكراري.', 'Histogram', false),
  (2921, 0, 'تواصل مع راعي المشروع لطلب التوجيه حول كيفية التعامل مع حالات فشل مراجعة الجودة.', 'Reach out to the project sponsor for guidance on how to handle the quality review failures.', false),
  (2921, 1, 'تعديل خطة إدارة الجودة لإعادة مواءمة متطلبات موعد المراجعة.', 'Modify the quality management plan to realign the review timeline requirements.', false),
  (2921, 2, 'طلب تدقيق داخلي لتقييم ما إذا كانت عمليات الجودة تُطبَّق باستمرار.', 'Request an internal audit to assess if quality processes are being consistently implemented.', false),
  (2921, 3, 'إعداد مخطط السبب والأثر لتتبّع الإخفاقات المتكررة وصولًا إلى سببها الجذري.', 'Develop a cause-and-effect diagram to trace the repeated failures back to their root cause.', true),
  (2922, 0, 'التحكّم في المشتريات', 'Control procurement', false),
  (2922, 1, 'اشتقاق العينات الإحصائية.', 'Statistical sampling', true),
  (2922, 2, 'تدقيق العملية.', 'Process audit', false),
  (2922, 3, 'ضمان المطابقة.', 'Conformance assurance', false),
  (2923, 0, 'جدولة اجتماع مع المعنيين لجمع متطلبات المشروع وجمع عينات القياس المعياري لإبلاغ المعايير.', 'Schedule a meeting with the stakeholders to gather project requirements and collect benchmarking samples to inform the standards.', false),
  (2923, 1, 'طلب عينات مقارنة مرجعية وتحليلات التكلفة والمنفعة من الراعي لإرساء أساس خطة إدارة الجودة.', 'Request benchmarking samples and cost-benefit analyses from the sponsor to set the foundation for the quality management plan.', false),
  (2923, 2, 'تحديد الفجوات في الخطط والعمليات القائمة بالفعل والتعاون مع معنيي المشروع لتحسين معايير الجودة.', 'Identify the gaps in the plans and processes already in place and collaborate with the project stakeholders to improve quality standards.', true),
  (2923, 3, 'تأجيل العمل حتى يجري إنشاء المقاييس وقوائم الفحص لضمان استناد الخطة إلى مجموعة كاملة من معايير الجودة.', 'Postpone the work until metrics and checklists have been created to ensure the plan is grounded on a full set of quality criteria.', false),
  (2924, 0, 'زيادة السعر المحدد للمنتج من أجل تمويل استخدام مواد عالية الجودة خلال عملية الإنتاج.', 'Increase the product''s price point to fund higher quality materials during the production process.', false),
  (2924, 1, 'إجراء مقارنة مرجعية لميزات المنتج مع عروض المنافسين وتطبيق نظام لتتبّع العيوب.', 'Benchmark the product’s features against their competitors’ offerings and implement a defect tracking system.', false),
  (2924, 2, 'تضمين منصة اختبار آلي في تعريف المنجز (DoD) وتكثيف الاختبار قبل النشر.', 'Include an automated testing bench in the definition of done (DoD) and ramp up testing before deployment.', false),
  (2924, 3, 'تطبيق التطوير المُوجَّه بالاختبار (TDD) مُستنِدًا إلى ملاحظات مستمرة من مجموعات المستخدمين التخصصية.', 'Implement test-driven development (TDD) informed by continuous user focus group feedback.', true),
  (2925, 0, 'استخدم بيانات من اختبارات مماثلة على قصص مشابهة لإنتاج تقديرات أولية للجهد لعناصر الأعمال المتراكمة الجديدة.', 'Apply data from similar tests on comparable stories to produce initial effort estimates for the new backlog items.', false),
  (2925, 1, 'أن يحدّد مالك المنتج ملحمة جديدة ويُدرج التعريف في تعريف المنجز (DoD) قبل تنفيذ الإطلاق التالي.', 'Have the product owner define a new epic and include the definition in the definition of done (DoD) before executing the following sprint.', false),
  (2925, 2, 'إدراج معايير القبول ذات الصلة في تعريف الجاهزية (DoR) قبل محاولة تقدير بنود سجل الأعمال الجديدة.', 'Incorporate the relevant acceptance criteria into the definition of ready (DoR) before attempting to estimate the new backlog items.', true);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2925, 3, 'أن يقدّم مالك المنتج معايير القبول للبنود التي يمكن إدراجها في سجل أعمال الإطلاق.', 'Have the product owner provide the acceptance criteria for items that can be included in the sprint backlog.', false),
  (2926, 0, 'تطوير البرمجيات المدفوع باختبارات القبول (ATDD)', 'Acceptance test-driven development (ATDD)', false),
  (2926, 1, 'التطوير المُوجَّه بالميزات (FDD).', 'Feature-driven development (FDD)', false),
  (2926, 2, 'التطوير المُوجَّه بالسلوك (BDD).', 'Behavior-driven development (BDD)', true),
  (2926, 3, 'التطوير المُوجَّه بالاختبار (TDD).', 'Test-drive development (TDD)', false),
  (2927, 0, 'إجراء تحليل لجذر السبب خلال الجلسات الرجعية القادمة.', 'Perform a root cause analysis during upcoming retrospectives.', false),
  (2927, 1, 'إعادة مواءمة التزامات محفظة المشاريع لتتناسب مع قدرات الفرق.', 'Realign portfolio commitments to match the teams’ capacities.', true),
  (2927, 2, 'إعادة هيكلة الفرق لإسناد فريق واحد لكل شخص.', 'Restructure the teams to assign everyone a single team.', true),
  (2927, 3, 'إنشاء فرق اختبار منفصلة ومخصصة.', 'Establish separate dedicated testing teams.', false),
  (2927, 4, 'توفير تدريب على إدارة الوقت وتركيز الانتباه للقيادة.', 'Provide time and focus training to leadership.', false),
  (2928, 0, 'استشر مالك المنتج لتحديد ما إذا كان راضياً عن النتائج.', 'Consult with the product owner to determine whether they are satisfied with the results.', false),
  (2928, 1, 'تقييم جميع القصص المكتملة في ضوء تعريف المنجز (DoD) للتأكد من معايير الإكمال.', 'Evaluate all completed stories against the definition of done (DoD) to confirm the completion criteria.', true),
  (2928, 2, 'مطالبة أعضاء الفريق بالتحقق المتبادل من تعريف المنجز (DoD) لتحديد أي فجوات أو تناقضات.', 'Ask team members to cross-check the definition of done (DoD) to identify any gaps or inconsistencies.', false),
  (2928, 3, 'مراجعة القصص المكتملة للتحقق من أن العمل المُسلَّم يفي بالجودة المطلوبة.', 'Review the completed stories to verify that the work delivered meets the required quality.', false),
  (2929, 0, 'الحكم الخبير', 'Expert judgment', true),
  (2929, 1, 'تحليل المنتج.', 'Product analysis', false),
  (2929, 2, 'مصفوفة تتبع المتطلبات.', 'Requirements traceability matrix', false),
  (2929, 3, 'المقارنة المرجعية.', 'Benchmarking', false),
  (2930, 0, 'إشراك المعنيين لتحديد ما إذا كانت المخرجات المفقودة ضمن نطاق العمل ويجب دمجها في هيكل تقسيم العمل.', 'Engage stakeholders to determine whether the missing deliverables are within scope and should be incorporated into the WBS.', true),
  (2930, 1, 'تقديم طلب إلى مكتب إدارة المشاريع للحصول على تمويل إضافي لتغطية تكلفة التسليمات المفقودة.', 'Submit a request to the project management office for additional funding to cover the cost of missing deliverables.', false),
  (2930, 2, 'إضافة التسليمات المفقودة إلى هيكل تجزئة العمل (WBS) وإعادة حساب التكلفة الإجمالية للمشروع لتعكس النطاق الكامل.', 'Add the missing deliverables to the WBS and recalculate the total project cost to reflect the complete scope.', false),
  (2930, 3, 'استشارة الخبراء المتخصصين لتقييم ما إذا كانت التسليمات المفقودة ضرورية قبل إجراء أي تغييرات على هيكل تجزئة العمل (WBS).', 'Consult subject matter experts to assess whether the missing deliverables are necessary before making any changes to the WBS.', false),
  (2931, 0, 'قائمة المعالم', 'Milestone list', false),
  (2931, 1, 'قاموس هيكل تجزئة العمل.', 'Work breakdown structure dictionary', false),
  (2931, 2, 'خطة إدارة النطاق.', 'Scope management plan', true),
  (2931, 3, 'خطة إدارة المتطلبات.', 'Requirements management plan', false),
  (2932, 0, 'سجل المخاطر.', 'The risk register', false),
  (2932, 1, 'سجل التغيير.', 'The change log', false),
  (2932, 2, 'سجل الإشكالات.', 'The issue log', true),
  (2932, 3, 'سجل الدروس المستفادة.', 'The lessons learned register', false),
  (2933, 0, 'الرشيق.', 'Agile', false),
  (2933, 1, 'الهجين.', 'Hybrid', false),
  (2933, 2, 'التزايدي.', 'Incremental', false),
  (2933, 3, 'التنبؤي.', 'Predictive', true),
  (2934, 0, 'الامتثال لطلب الرئيس التنفيذي للعمليات لأن الراعي يملك صلاحية اعتماد طلبات التغيير.', 'Comply with the COO''s request since the sponsor has the authority to approve change requests.', false),
  (2934, 1, 'تقديم طلب تغيير لتقييم الإضافة رسميًا من خلال عملية التحكم المتكامل في التغيير.', 'Submit a change request to formally evaluate the addition through the integrated change control process.', true),
  (2934, 2, 'رفض الإضافة وتذكير الرئيس التنفيذي للعمليات بأن وحدة التقارير كانت مستبعدة صراحةً من النطاق المعتمد.', 'Refuse the addition and remind the COO that the reporting module was explicitly excluded from the approved scope.', false),
  (2934, 3, 'التفاوض مع الرئيس التنفيذي للعمليات على تقليص بنود أخرى من النطاق لاستيعاب الإضافة دون طلب تغيير رسمي.', 'Negotiate with the COO to reduce other scope items to accommodate the addition without a formal change request.', false),
  (2935, 0, 'تصعيد الأمر إلى اللجنة التوجيهية للمشروع أو الهيئة الحاكمة المكافئة المسؤولة عن الإشراف على المشروع.', 'Escalate the matter to the project steering committee or equivalent governing body responsible for project oversight.', true),
  (2935, 1, 'تصعيد المخاوف مباشرةً إلى مجلس الإدارة لأن المجلس وحده يملك الصلاحية الكافية لتجاوز قرارات الرئيس التنفيذي للعمليات.', 'Escalate the concern directly to the board of directors because only the board has sufficient authority to override the COO.', false),
  (2935, 2, 'توثيق السلوك في سجل الإشكالات وطرحه في اجتماع حالة المشروع المجدول التالي لمناقشته رسميًا مع المعنيين.', 'Document the behavior in the issue log and raise it at the next scheduled project status meeting for formal stakeholder discussion.', false),
  (2935, 3, 'إبلاغ المدير الوظيفي لأعضاء الفريق المتأثرين عن الرئيس التنفيذي للعمليات لاتخاذ إجراء تصحيحي.', 'Report the COO to the functional manager of the affected team members for corrective action.', false),
  (2936, 0, 'جدولة اجتماعات حالة منتظمة مع الرئيس التنفيذي للعمليات للحفاظ على التوافق المستمر.', 'Scheduled regular status meetings with the COO to maintain ongoing alignment.', false),
  (2936, 1, 'تحديد تدخل الراعي بوصفه مخاطرة ووضع استراتيجية تخفيف لها خلال التخطيط.', 'Identified sponsor interference as a risk and developed a mitigation strategy during planning.', false),
  (2936, 2, 'وضع خطة لمشاركة المعنيين تحدد دور الرئيس التنفيذي للعمليات وعملية صنع القرار الرسمية.', 'Established a stakeholder engagement plan that defined the COO''s role and formal decision-making process.', true),
  (2936, 3, 'التأكد من مراجعة الرئيس التنفيذي للعمليات لعملية التحكم في التغيير واعتماده لها.', 'Ensured the COO reviewed and signed off on the change control process.', false),
  (2937, 0, 'إبلاغ الفريق بالاعتماد والبدء في إسناد مهام وحدة التقارير.', 'Notify the team of the approval and begin assigning tasks for the reporting module.', false),
  (2937, 1, 'جدولة اجتماع مع الرئيس التنفيذي للعمليات للتوافق على أولويات تنفيذ الوحدة الجديدة.', 'Schedule a meeting with the COO to align on implementation priorities for the new module.', false),
  (2937, 2, 'تحديث الخطوط المرجعية للنطاق والجدول الزمني والتكلفة في المشروع لتعكس التغيير المعتمد.', 'Update the project''s scope, schedule, and cost baselines to reflect the approved change.', true),
  (2937, 3, 'تقديم ميثاق مشروع منقّح لتوثيق النطاق الموسّع.', 'Submit a revised project charter to document the expanded scope.', false),
  (2938, 0, 'التنبؤي.', 'Predictive', false),
  (2938, 1, 'التزايدي.', 'Incremental', false),
  (2938, 2, 'الهجين.', 'Hybrid', false),
  (2938, 3, 'الرشيق.', 'Agile', true),
  (2939, 0, 'توجيه أعضاء الفريق وإسناد المهام لضمان تحقيق أهداف السبرينت.', 'Directing team members and assigning tasks to ensure sprint goals are met.', false),
  (2939, 1, 'إدارة سجل أعمال المنتج واتخاذ قرارات ترتيب الأولويات حسب الحاجة.', 'Managing the product backlog and making prioritization decisions as needed.', false),
  (2939, 2, 'تيسير عمل الفريق من خلال إزالة المعوقات ودعم التنظيم الذاتي.', 'Facilitating the team''s work by removing impediments and supporting self-organization.', true),
  (2939, 3, 'رفع تقارير تقدم السبرينت إلى الراعي وتعديل جدول التسليم وفقًا لذلك.', 'Reporting sprint progress to the sponsor and adjusting the delivery schedule accordingly.', false),
  (2940, 0, 'أصبح الفريق معتمدًا على مدير المشروع في التوجيه بدلًا من تطوير مهارات التنظيم الذاتي.', 'The team became dependent on the project manager for direction rather than developing self-organization skills.', true),
  (2940, 1, 'تقوّضت قدرة مالك المنتج على إدارة سجل الأعمال بفعالية بسبب انخراط مدير المشروع في تخطيط السبرينت.', 'The Product Owner''s ability to manage the backlog effectively was undermined by the project manager''s involvement in sprint planning.', false),
  (2940, 2, 'كان إخفاق الفريق في الوفاء بموعد التسليم النهائي نتيجة مباشرة للتوزيع غير المتكافئ للمهام عبر السبرينتات.', 'The team''s failure to meet a delivery deadline was a direct result of the uneven task distribution across sprints.', false),
  (2940, 3, 'فقد البرنامج التجريبي مصداقيته لدى القيادة العليا بسبب استمرار معاناة الفريق في تخطيط السبرينت.', 'The pilot program lost credibility with senior leadership due to the team''s continued struggle with sprint planning.', false),
  (2941, 0, 'نعم، لأن مدير المشروع مسؤول عن ضمان وفاء المشروع بموعد التسليم النهائي.', 'Yes, because the project manager is responsible for ensuring the project meets its delivery deadline.', false),
  (2941, 1, 'لا، لأن إعادة ترتيب أولويات سجل الأعمال تتطلب موافقة القيادة العليا قبل التنفيذ.', 'No, because backlog reprioritization requires approval from senior leadership before implementation.', false),
  (2941, 2, 'لا، لأن سجل أعمال المنتج من مسؤولية مالك المنتج، وقرارات إعادة ترتيب الأولويات تعود إليه حصريًا.', 'No, because the product backlog is the Product Owner''s responsibility and reprioritization decisions belong exclusively to them.', true),
  (2941, 3, 'لا، لأن تقليص النطاق في منتصف المشروع ينتهك المبدأ الرشيق القائل بالاستجابة للتغيير أكثر من اتباع الخطة.', 'No, because reducing scope mid-project violates the agile principle of responding to change over following a plan.', false),
  (2942, 0, 'أن يطلب من مالك المنتج أداء دور أكثر فاعلية في تخطيط السبرينت حتى يكتسب الفريق الثقة.', 'Requested the Product Owner to take a more active role in sprint planning until the team gained confidence.', false),
  (2942, 1, 'أن يصعّد صعوبات الفريق إلى القيادة العليا نظرًا لأهمية نجاح البرنامج التجريبي.', 'Escalated the team''s struggles to senior leadership given the importance of the pilot program''s success.', false),
  (2942, 2, 'أن يدرّب الفريق على ممارسات تخطيط السبرينت الرشيقة لبناء قدرته على التنظيم الذاتي بمرور الوقت.', 'Coached the team on agile sprint planning practices to build their self-organization capability over time.', true),
  (2942, 3, 'أن يقلل عدد بنود سجل الأعمال المخصصة لكل سبرينت لمنح الفريق عبء عمل أكثر قابلية للإدارة.', 'Reduced the number of backlog items assigned to each sprint to give the team a more manageable workload.', false),
  (2943, 0, 'العمل مع مالك المنتج على مشاركة سجل أعمال المنتج كاملًا مع الفريق لتوفير رؤية للأعمال القادمة.', 'Work with the Product Owner to share the full product backlog with the team to provide visibility into upcoming work.', false),
  (2943, 1, 'إعادة اعتماد خطة تسليم عامة لمنح الفريق ثقة أكبر في اتجاه المشروع.', 'Reintroduce a high-level delivery plan to give the team greater confidence in the project''s direction.', false),
  (2943, 2, 'تصعيد المخاوف إلى القيادة العليا لأن انزعاج الفريق يهدد نجاح البرنامج التجريبي.', 'Escalate the concern to senior leadership since the team''s discomfort threatens the pilot program''s success.', false),
  (2943, 3, 'تدريب الفريق على كيفية توفير سجل أعمال المنتج والتخطيط التكراري رؤيةً للأعمال المستقبلية.', 'Coach the team on how the product backlog and iterative planning provide visibility into future work.', true),
  (2944, 0, 'سجل الإشكالات.', 'The issue log', false),
  (2944, 1, 'سجل المخاطر.', 'The risk register', true),
  (2944, 2, 'خطة إدارة المخاطر.', 'The risk management plan', false),
  (2944, 3, 'سجل الافتراضات.', 'The assumption log', false),
  (2945, 0, 'التحليل الكمي للمخاطر.', 'Quantitative risk analysis', true),
  (2945, 1, 'مصفوفة الاحتمالية والتأثير.', 'Probability and impact matrix', false),
  (2945, 2, 'محاكاة مونت كارلو.', 'Monte Carlo simulation', true),
  (2945, 3, 'تقييم مدى إلحاح المخاطر.', 'Risk urgency assessment', false),
  (2945, 4, 'تحليل الحساسية.', 'Sensitivity analysis', true),
  (2946, 0, 'أخفق تحليل المخاطر التتبعي الذي أجراه مدير المشروع في رصد شدة تدهور التربة بدقة.', 'The project manager''s follow-up risk analysis failed to accurately capture the severity of the soil degradation.', false),
  (2946, 1, 'لم يصعّد مدير المشروع مخاطرة السلامة عندما تجاوزت قدرته على إدارتها بمفرده.', 'The project manager did not escalate the safety risk when it exceeded their ability to manage it independently.', true),
  (2946, 2, 'لم يحضر عدد من أعضاء الفريق اجتماعات السلامة المجدولة التي كانت جزءًا من خطة الاستجابة للمخاطر.', 'Several team members did not attend the scheduled safety meetings that were part of the risk response plan.', false),
  (2946, 3, 'أدى تعارض في الجدولة إلى عمل عدد مفرط من الأفراد والمعدات في المنطقة نفسها وقت الحادث.', 'A scheduling conflict resulted in excessive personnel and equipment operating in the same area at the time of the incident.', false),
  (2947, 0, 'معلوم معلوم (Known Known)، لأن مدير المشروع كان قد وثّق تدهور التربة بالفعل في سجل المخاطر.', 'A known known, because the project manager had already documented the soil degradation in the risk register.', false),
  (2947, 1, 'مجهول معلوم (Known Unknown)، لأن المدى الكامل لتدهور التربة لم يكن قد تحدد بعد وقت التقييم.', 'A known unknown, because the full extent of the soil degradation had not yet been determined at the time of the assessment.', false),
  (2947, 2, 'مجهول مجهول (Unknown Unknown)، لأن تدهور التربة بهذه الطبيعة ما كان يمكن توقعه خلال تخطيط المخاطر.', 'An unknown unknown, because soil degradation of this nature could not have been anticipated during risk planning.', false),
  (2947, 3, 'معلوم مجهول (Unknown Known)، لأن الدلالة المتعلقة بالسلامة للنتائج كانت قابلة للمعرفة، لكن مدير المشروع افتقر إلى الخبرة اللازمة لإدراكها دون استشارة خبير متخصص.', 'An unknown known, because the safety significance of the findings was knowable but the project manager lacked the expertise to recognize it without consulting a subject matter expert.', true),
  (2948, 0, 'جدولة اجتماع سلامة إضافي لإحاطة طاقم البناء بالنتائج المحدّثة.', 'Scheduled an additional safety meeting to brief the construction crew on the updated findings.', false),
  (2948, 1, 'استشارة خبير متخصص لتفسير نتائج تقييم التربة وتحديد مسار العمل المناسب.', 'Consulted a subject matter expert to interpret the soil assessment findings and determine the appropriate course of action.', true),
  (2948, 2, 'تكليف أحد أعضاء الفريق بمراقبة ظروف السلامة في الموقع والإبلاغ عن أي تغيرات في استقرار التربة.', 'Assigned a team member to monitor site safety conditions and report any changes in soil stability.', false),
  (2948, 3, 'تحديث سجل المخاطر بالنتائج الجديدة ومواصلة مراقبة الموقف.', 'Updated the risk register with the new findings and continued monitoring the situation.', false),
  (2949, 0, 'سجل مخاطر شامل يوثّق جميع مخاطر السلامة المحتملة المرتبطة بمشروع التشييد.', 'A comprehensive risk register capturing all potential safety risks associated with the construction project.', false),
  (2949, 1, 'إطار للحدود الفاصلة للمخاطر يحدد الشروط التي يجب عندها تصعيد المخاطر إلى ما يتجاوز صلاحية مدير المشروع.', 'A risk threshold framework defining the conditions under which risks must be escalated beyond the project manager''s authority.', true),
  (2949, 2, 'خطة مفصلة لإدارة السلامة توضح إجراءات الفحص ومتطلبات الامتثال.', 'A detailed safety management plan outlining inspection procedures and compliance requirements.', false),
  (2949, 3, 'خطة تواصل مع المعنيين تضمن إبلاغ جميع الأطراف بمخاطر السلامة على مدار المشروع.', 'A stakeholder communication plan ensuring all parties were informed of safety risks throughout the project.', false),
  (2950, 0, 'السماح لأداة الذكاء الاصطناعي بإرسال التقارير تلقائيًا، لأن الهدف من الأتمتة هو تقليل الجهد اليدوي.', 'Allowed the AI tool to send reports automatically since automation is meant to remove manual effort', false),
  (2950, 1, 'مراجعة التقرير الذي أنشأه الذكاء الاصطناعي والتحقق من صحته قبل توزيعه على أصحاب المصلحة.', 'Reviewed and validated the AI-generated report before it was distributed to stakeholders', true),
  (2950, 2, 'مطالبة أحد أعضاء الفريق بإعادة كتابة كل تقرير يدويًا لتجنب الاعتماد على أداة الذكاء الاصطناعي.', 'Asked a team member to rewrite every report manually to avoid relying on the AI tool', false),
  (2950, 3, 'إزالة تواريخ المعالم الرئيسية من قالب التقرير لمنع حدوث أخطاء مستقبلية.', 'Removed the milestone dates from the report template to prevent future errors', false),
  (2951, 0, 'منح العقد للمورد الذي صنّفه الذكاء الاصطناعي في المرتبة الأولى لأن التحليل قائم على البيانات.', 'Award the contract to the AI''s top-ranked supplier because the analysis was data-driven', false),
  (2951, 1, 'مطالبة أداة الذكاء الاصطناعي بإعادة إجراء التحليل حتى تنتج فائزًا أكثر وضوحًا.', 'Ask the AI tool to re-run the analysis until it produces a clearer winner', false),
  (2951, 2, 'مراجعة تحليل الذكاء الاصطناعي، وتطبيق الحكم البشري، واتخاذ القرار النهائي بشأن اختيار المورد.', 'Review the AI analysis, apply human judgment, and make the final selection decision', true),
  (2951, 3, 'نقل مسؤولية قرار اختيار المورد إلى أداة الذكاء الاصطناعي للتخلص من التحيز الشخصي.', 'Transfer responsibility for the vendor decision to the AI tool to remove personal bias', false),
  (2952, 0, 'الاستمرار في استخدام توزيعات المهام لأن الذكاء الاصطناعي يعمل على تحسين التوزيع وفقًا للمهارات ومدى التوافر.', 'Continue using the assignments because the AI is optimizing for skills and availability', false),
  (2952, 1, 'مراجعة مخرجات الذكاء الاصطناعي من حيث العدالة والدقة قبل تطبيق توزيعات المهام.', 'Review the AI outputs for fairness and accuracy before applying the task assignments', true),
  (2952, 2, 'التوقف عن استخدام الذكاء الاصطناعي في جميع مهام المشروع لإلغاء احتمال حدوث نتائج غير عادلة.', 'Stop using AI for any project task to eliminate the possibility of unfair outcomes', false),
  (2952, 3, 'إبلاغ أعضاء الفريق الذين تم تجاهلهم بأن أداة الذكاء الاصطناعي هي التي تحدد جميع توزيعات المهام.', 'Inform the overlooked team members that the AI tool determines all assignments', false),
  (2953, 0, 'تحميل الملف كاملًا إلى أداة الذكاء الاصطناعي العامة لكي يتضمن الملخص جميع التفاصيل.', 'Upload the full file to the public tool so the summary captures every detail', false),
  (2953, 1, 'التحقق من متطلبات الخصوصية وحماية البيانات والحصول على التفويض المناسب قبل استخدام البيانات.', 'Check privacy and data protection requirements and obtain proper authorization before using the data', true),
  (2953, 2, 'مطالبة أحد أعضاء الفريق بتحميل الملف من حسابه الشخصي لتجنب المسؤولية.', 'Ask a team member to upload the file from their own account to avoid responsibility', false),
  (2953, 3, 'إلغاء عملية التلخيص بالكامل لأن الذكاء الاصطناعي لا يمكن استخدامه أبدًا مع بيانات أصحاب المصلحة.', 'Skip the summary entirely because AI can never be used with stakeholder data', false),
  (2954, 0, 'السماح للذكاء الاصطناعي باختيار التوجه الاستراتيجي لأنه يستطيع التنبؤ بالنتائج بسرعة أكبر.', 'Let the AI select the strategic direction since it can forecast outcomes more quickly', false),
  (2954, 1, 'تجنب استخدام الذكاء الاصطناعي لأن القرارات المعقدة ينبغي ألا تتضمن أبدًا دعمًا من الذكاء الاصطناعي.', 'Avoid using AI because complex decisions should never involve AI support', false),
  (2954, 2, 'إرسال توقعات الذكاء الاصطناعي مباشرة إلى راعي المشروع باعتبارها التوجه الموصى به للمشروع.', 'Forward the AI''s forecast directly to the sponsor as the project''s recommended direction', false),
  (2954, 3, 'استخدام الذكاء الاصطناعي كشريك في التفكير لاستكشاف الخيارات، مع بقاء مدير المشروع مسؤولًا عن القرار النهائي.', 'Use the AI as a thought partner to explore options while the project manager remains accountable for the final decision', true),
  (2955, 0, 'التحقق من إمكانية استخدام المحتوى الذي أنشأه الذكاء الاصطناعي بشكل قانوني قبل نشره.', 'Verify that the AI-generated content can legally be used before publishing it', true),
  (2955, 1, 'نشر المواد فورًا للحفاظ على إطلاق المنتج وفق الجدول الزمني.', 'Publish the material right away to keep the launch on schedule', false),
  (2955, 2, 'استبدال جميع محتويات الذكاء الاصطناعي بمواد جاهزة دون التحقق من مصدرها أيضًا.', 'Replace all AI content with stock material without checking its source either', false),
  (2955, 3, 'مطالبة أداة الذكاء الاصطناعي بتأكيد كتابي بأن المحتوى خالٍ من أي قيود.', 'Ask the AI tool to confirm in writing that the content is free of any restrictions', false),
  (2956, 0, 'إبقاء استخدام الذكاء الاصطناعي سريًا لتجنب إثارة الشكوك حول التحليل.', 'Kept the use of AI private to avoid raising doubts about the analysis', false),
  (2956, 1, 'إخبار صاحب المصلحة بأن التحليل تم إعداده يدويًا بالكامل للحفاظ على ثقته.', 'Told the stakeholder the analysis was fully manual to preserve their confidence', false),
  (2956, 2, 'توضيح كيفية استخدام الذكاء الاصطناعي لأصحاب المصلحة لدعم العمل والقرارات.', 'Been clear with stakeholders about how AI was being used to support the work and decisions', true),
  (2956, 3, 'إزالة الذكاء الاصطناعي من المشروع حتى لا تعود الشفافية مصدرًا للقلق.', 'Removed AI from the project so transparency would no longer be a concern', false),
  (2957, 0, 'اتباع اقتراح الذكاء الاصطناعي وتجاوز الاختبار حتى يمكن الالتزام بالموعد النهائي.', 'Follow the AI''s suggestion to skip the test so the deadline can be met', false),
  (2957, 1, 'التأكد من عدم استخدام الذكاء الاصطناعي لتجاوز متطلبات السلامة، وتصعيد المخاوف المتعلقة بالسلامة.', 'Ensure AI is not used to bypass safety requirements and escalate the safety concern', true),
  (2957, 2, 'تقليل نطاق اختبار السلامة إلى النصف كحل وسط بناءً على نصيحة الذكاء الاصطناعي.', 'Reduce the scope of the safety test by half as a compromise on the AI''s advice', false),
  (2957, 3, 'السماح للفريق بالتصويت على ما إذا كان ينبغي اتباع اقتراح الذكاء الاصطناعي بتجاوز الاختبار.', 'Let the team vote on whether the AI''s suggestion to skip the test should be followed', false),
  (2958, 0, 'اعتماد الجدول الزمني الذي أنشأه الذكاء الاصطناعي وبدء العمل، لأن المسودة تبدو معقولة.', 'Lock in the AI-generated schedule and begin work, since the draft looks reasonable', false),
  (2958, 1, 'تسليم الجدول الزمني إلى الفريق والسماح لأداة الذكاء الاصطناعي بمعالجة أي تعارضات مستقبلية بنفسها.', 'Hand the schedule to the team and let the AI tool resolve any future conflicts on its own', false),
  (2958, 2, 'مطالبة راعي المشروع باعتماد مسودة الجدول الزمني التي أنشأها الذكاء الاصطناعي دون مراجعة الفريق لتوفير الوقت.', 'Ask the sponsor to approve the AI draft schedule without team review to save time', false),
  (2958, 3, 'التحقق من مسودة الجدول الزمني التي أنشأها الذكاء الاصطناعي وتعديلها قبل أن يلتزم بها الفريق.', 'Validate and adjust the AI-generated draft schedule before the team commits to it', true),
  (2959, 0, 'التأكد من استخدام الذكاء الاصطناعي في المواضع التي يضيف فيها قيمة حقيقية، مع مراعاة كفاءته وتأثيره البيئي.', 'Confirm that AI is used where it adds real value and consider its efficiency and environmental impact', true),
  (2959, 1, 'تشجيع المزيد من استخدام الذكاء الاصطناعي حتى يحصل الفريق على أقصى قيمة ممكنة من الأداة.', 'Encourage even more AI use so the team gets maximum value from the tool', false),
  (2959, 2, 'حظر استخدام الذكاء الاصطناعي بالكامل حتى يعود الفريق إلى العمل اليدوي في كل مهمة.', 'Ban AI entirely so the team returns to manual work for every task', false),
  (2959, 3, 'السماح للفريق بالاستمرار في استخدام الذكاء الاصطناعي في كل شيء لأنه أسرع من اتخاذ القرار لكل حالة على حدة.', 'Let the team continue using AI for everything since it is faster than deciding case by case', false),
  (2960, 0, 'سجل المخاطر.', 'The risk register', false),
  (2960, 1, 'سجل التغيير.', 'The change log', false),
  (2960, 2, 'سجل الإشكالات.', 'The issue log', true),
  (2960, 3, 'سجل الدروس المستفادة.', 'The lessons learned register', false),
  (2961, 0, 'الرشيق.', 'Agile', false),
  (2961, 1, 'الهجين.', 'Hybrid', false),
  (2961, 2, 'التزايدي.', 'Incremental', false),
  (2961, 3, 'التنبؤي.', 'Predictive', true),
  (2962, 0, 'الامتثال لطلب الرئيس التنفيذي للعمليات لأن الراعي يملك صلاحية اعتماد طلبات التغيير.', 'Comply with the COO''s request since the sponsor has the authority to approve change requests.', false),
  (2962, 1, 'تقديم طلب تغيير لتقييم الإضافة رسميًا من خلال عملية التحكم المتكامل في التغيير.', 'Submit a change request to formally evaluate the addition through the integrated change control process.', true),
  (2962, 2, 'رفض الإضافة وتذكير الرئيس التنفيذي للعمليات بأن وحدة التقارير كانت مستبعدة صراحةً من النطاق المعتمد.', 'Refuse the addition and remind the COO that the reporting module was explicitly excluded from the approved scope.', false),
  (2962, 3, 'التفاوض مع الرئيس التنفيذي للعمليات على تقليص بنود أخرى من النطاق لاستيعاب الإضافة دون طلب تغيير رسمي.', 'Negotiate with the COO to reduce other scope items to accommodate the addition without a formal change request.', false),
  (2963, 0, 'تصعيد الأمر إلى اللجنة التوجيهية للمشروع أو الهيئة الحاكمة المكافئة المسؤولة عن الإشراف على المشروع.', 'Escalate the matter to the project steering committee or equivalent governing body responsible for project oversight.', true),
  (2963, 1, 'تصعيد المخاوف مباشرةً إلى مجلس الإدارة لأن المجلس وحده يملك الصلاحية الكافية لتجاوز قرارات الرئيس التنفيذي للعمليات.', 'Escalate the concern directly to the board of directors because only the board has sufficient authority to override the COO.', false),
  (2963, 2, 'توثيق السلوك في سجل الإشكالات وطرحه في اجتماع حالة المشروع المجدول التالي لمناقشته رسميًا مع المعنيين.', 'Document the behavior in the issue log and raise it at the next scheduled project status meeting for formal stakeholder discussion.', false),
  (2963, 3, 'إبلاغ المدير الوظيفي لأعضاء الفريق المتأثرين عن الرئيس التنفيذي للعمليات لاتخاذ إجراء تصحيحي.', 'Report the COO to the functional manager of the affected team members for corrective action.', false),
  (2964, 0, 'جدولة اجتماعات حالة منتظمة مع الرئيس التنفيذي للعمليات للحفاظ على التوافق المستمر.', 'Scheduled regular status meetings with the COO to maintain ongoing alignment.', false),
  (2964, 1, 'تحديد تدخل الراعي بوصفه مخاطرة ووضع استراتيجية تخفيف لها خلال التخطيط.', 'Identified sponsor interference as a risk and developed a mitigation strategy during planning.', false),
  (2964, 2, 'وضع خطة لمشاركة المعنيين تحدد دور الرئيس التنفيذي للعمليات وعملية صنع القرار الرسمية.', 'Established a stakeholder engagement plan that defined the COO''s role and formal decision-making process.', true),
  (2964, 3, 'التأكد من مراجعة الرئيس التنفيذي للعمليات لعملية التحكم في التغيير واعتماده لها.', 'Ensured the COO reviewed and signed off on the change control process.', false),
  (2965, 0, 'إبلاغ الفريق بالاعتماد والبدء في إسناد مهام وحدة التقارير.', 'Notify the team of the approval and begin assigning tasks for the reporting module.', false),
  (2965, 1, 'جدولة اجتماع مع الرئيس التنفيذي للعمليات للتوافق على أولويات تنفيذ الوحدة الجديدة.', 'Schedule a meeting with the COO to align on implementation priorities for the new module.', false),
  (2965, 2, 'تحديث الخطوط المرجعية للنطاق والجدول الزمني والتكلفة في المشروع لتعكس التغيير المعتمد.', 'Update the project''s scope, schedule, and cost baselines to reflect the approved change.', true),
  (2965, 3, 'تقديم ميثاق مشروع منقّح لتوثيق النطاق الموسّع.', 'Submit a revised project charter to document the expanded scope.', false),
  (2966, 0, 'التنبؤي.', 'Predictive', false),
  (2966, 1, 'التزايدي.', 'Incremental', false),
  (2966, 2, 'الهجين.', 'Hybrid', false),
  (2966, 3, 'الرشيق.', 'Agile', true),
  (2967, 0, 'توجيه أعضاء الفريق وإسناد المهام لضمان تحقيق أهداف السبرينت.', 'Directing team members and assigning tasks to ensure sprint goals are met.', false),
  (2967, 1, 'إدارة سجل أعمال المنتج واتخاذ قرارات ترتيب الأولويات حسب الحاجة.', 'Managing the product backlog and making prioritization decisions as needed.', false),
  (2967, 2, 'تيسير عمل الفريق من خلال إزالة المعوقات ودعم التنظيم الذاتي.', 'Facilitating the team''s work by removing impediments and supporting self-organization.', true),
  (2967, 3, 'رفع تقارير تقدم السبرينت إلى الراعي وتعديل جدول التسليم وفقًا لذلك.', 'Reporting sprint progress to the sponsor and adjusting the delivery schedule accordingly.', false),
  (2968, 0, 'أصبح الفريق معتمدًا على مدير المشروع في التوجيه بدلًا من تطوير مهارات التنظيم الذاتي.', 'The team became dependent on the project manager for direction rather than developing self-organization skills.', true),
  (2968, 1, 'تقوّضت قدرة مالك المنتج على إدارة سجل الأعمال بفعالية بسبب انخراط مدير المشروع في تخطيط السبرينت.', 'The Product Owner''s ability to manage the backlog effectively was undermined by the project manager''s involvement in sprint planning.', false),
  (2968, 2, 'كان إخفاق الفريق في الوفاء بموعد التسليم النهائي نتيجة مباشرة للتوزيع غير المتكافئ للمهام عبر السبرينتات.', 'The team''s failure to meet a delivery deadline was a direct result of the uneven task distribution across sprints.', false),
  (2968, 3, 'فقد البرنامج التجريبي مصداقيته لدى القيادة العليا بسبب استمرار معاناة الفريق في تخطيط السبرينت.', 'The pilot program lost credibility with senior leadership due to the team''s continued struggle with sprint planning.', false),
  (2969, 0, 'نعم، لأن مدير المشروع مسؤول عن ضمان وفاء المشروع بموعد التسليم النهائي.', 'Yes, because the project manager is responsible for ensuring the project meets its delivery deadline.', false),
  (2969, 1, 'لا، لأن إعادة ترتيب أولويات سجل الأعمال تتطلب موافقة القيادة العليا قبل التنفيذ.', 'No, because backlog reprioritization requires approval from senior leadership before implementation.', false),
  (2969, 2, 'لا، لأن سجل أعمال المنتج من مسؤولية مالك المنتج، وقرارات إعادة ترتيب الأولويات تعود إليه حصريًا.', 'No, because the product backlog is the Product Owner''s responsibility and reprioritization decisions belong exclusively to them.', true),
  (2969, 3, 'لا، لأن تقليص النطاق في منتصف المشروع ينتهك المبدأ الرشيق القائل بالاستجابة للتغيير أكثر من اتباع الخطة.', 'No, because reducing scope mid-project violates the agile principle of responding to change over following a plan.', false),
  (2970, 0, 'أن يطلب من مالك المنتج أداء دور أكثر فاعلية في تخطيط السبرينت حتى يكتسب الفريق الثقة.', 'Requested the Product Owner to take a more active role in sprint planning until the team gained confidence.', false),
  (2970, 1, 'أن يصعّد صعوبات الفريق إلى القيادة العليا نظرًا لأهمية نجاح البرنامج التجريبي.', 'Escalated the team''s struggles to senior leadership given the importance of the pilot program''s success.', false),
  (2970, 2, 'أن يدرب الفريق على ممارسات تخطيط السبرينت الرشيقة لبناء قدرته على التنظيم الذاتي بمرور الوقت.', 'Coached the team on agile sprint planning practices to build their self-organization capability over time.', true),
  (2970, 3, 'أن يقلل عدد بنود سجل الأعمال المخصصة لكل سبرينت لمنح الفريق عبء عمل أكثر قابلية للإدارة.', 'Reduced the number of backlog items assigned to each sprint to give the team a more manageable workload.', false),
  (2971, 0, 'العمل مع مالك المنتج على مشاركة سجل أعمال المنتج كاملًا مع الفريق لتوفير رؤية للأعمال القادمة.', 'Work with the Product Owner to share the full product backlog with the team to provide visibility into upcoming work.', false),
  (2971, 1, 'إعادة اعتماد خطة تسليم عامة لمنح الفريق ثقة أكبر في اتجاه المشروع.', 'Reintroduce a high-level delivery plan to give the team greater confidence in the project''s direction.', false),
  (2971, 2, 'تصعيد المخاوف إلى القيادة العليا لأن انزعاج الفريق يهدد نجاح البرنامج التجريبي.', 'Escalate the concern to senior leadership since the team''s discomfort threatens the pilot program''s success.', false),
  (2971, 3, 'تدريب الفريق على كيفية توفير سجل أعمال المنتج والتخطيط التكراري رؤيةً للأعمال المستقبلية.', 'Coach the team on how the product backlog and iterative planning provide visibility into future work.', true),
  (2972, 0, 'سجل الإشكالات.', 'The issue log', false),
  (2972, 1, 'سجل المخاطر.', 'The risk register', true),
  (2972, 2, 'خطة إدارة المخاطر.', 'The risk management plan', false),
  (2972, 3, 'سجل الافتراضات.', 'The assumption log', false),
  (2973, 0, 'التحليل الكمي للمخاطر.', 'Quantitative risk analysis', true),
  (2973, 1, 'مصفوفة الاحتمالية والتأثير.', 'Probability and impact matrix', false),
  (2973, 2, 'محاكاة مونت كارلو.', 'Monte Carlo simulation', true),
  (2973, 3, 'تقييم مدى إلحاح المخاطر.', 'Risk urgency assessment', false),
  (2973, 4, 'تحليل الحساسية.', 'Sensitivity analysis', true),
  (2974, 0, 'أخفق تحليل المخاطر التتبعي الذي أجراه مدير المشروع في رصد شدة تدهور التربة بدقة.', 'The project manager''s follow-up risk analysis failed to accurately capture the severity of the soil degradation.', false),
  (2974, 1, 'لم يصعّد مدير المشروع مخاطرة السلامة عندما تجاوزت قدرته على إدارتها بمفرده.', 'The project manager did not escalate the safety risk when it exceeded their ability to manage it independently.', true),
  (2974, 2, 'لم يحضر عدد من أعضاء الفريق اجتماعات السلامة المجدولة التي كانت جزءًا من خطة الاستجابة للمخاطر.', 'Several team members did not attend the scheduled safety meetings that were part of the risk response plan.', false),
  (2974, 3, 'أدى تعارض في الجدولة إلى عمل عدد مفرط من الأفراد والمعدات في المنطقة نفسها وقت الحادث.', 'A scheduling conflict resulted in excessive personnel and equipment operating in the same area at the time of the incident.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (2975, 0, 'معلوم معلوم (Known Known)، لأن مدير المشروع كان قد وثّق تدهور التربة بالفعل في سجل المخاطر.', 'A known known, because the project manager had already documented the soil degradation in the risk register.', false),
  (2975, 1, 'مجهول معلوم (Known Unknown)، لأن المدى الكامل لتدهور التربة لم يكن قد تحدد بعد وقت التقييم.', 'A known unknown, because the full extent of the soil degradation had not yet been determined at the time of the assessment.', false),
  (2975, 2, 'مجهول مجهول (Unknown Unknown)، لأن تدهور التربة بهذه الطبيعة ما كان يمكن توقعه خلال تخطيط المخاطر.', 'An unknown unknown, because soil degradation of this nature could not have been anticipated during risk planning.', false),
  (2975, 3, 'معلوم مجهول (Unknown Known)، لأن الدلالة المتعلقة بالسلامة للنتائج كانت قابلة للمعرفة، لكن مدير المشروع افتقر إلى الخبرة اللازمة لإدراكها دون استشارة خبير متخصص.', 'An unknown known, because the safety significance of the findings was knowable but the project manager lacked the expertise to recognize it without consulting a subject matter expert.', true),
  (2976, 0, 'جدولة اجتماع سلامة إضافي لإحاطة طاقم البناء بالنتائج المحدّثة.', 'Scheduled an additional safety meeting to brief the construction crew on the updated findings.', false),
  (2976, 1, 'استشارة خبير متخصص لتفسير نتائج تقييم التربة وتحديد مسار العمل المناسب.', 'Consulted a subject matter expert to interpret the soil assessment findings and determine the appropriate course of action.', true),
  (2976, 2, 'تكليف أحد أعضاء الفريق بمراقبة ظروف السلامة في الموقع والإبلاغ عن أي تغيرات في استقرار التربة.', 'Assigned a team member to monitor site safety conditions and report any changes in soil stability.', false),
  (2976, 3, 'تحديث سجل المخاطر بالنتائج الجديدة ومواصلة مراقبة الموقف.', 'Updated the risk register with the new findings and continued monitoring the situation.', false),
  (2977, 0, 'سجل مخاطر شامل يوثّق جميع مخاطر السلامة المحتملة المرتبطة بمشروع التشييد.', 'A comprehensive risk register capturing all potential safety risks associated with the construction project.', false),
  (2977, 1, 'إطار للحدود الفاصلة للمخاطر يحدد الشروط التي يجب عندها تصعيد المخاطر إلى ما يتجاوز صلاحية مدير المشروع.', 'A risk threshold framework defining the conditions under which risks must be escalated beyond the project manager''s authority.', true),
  (2977, 2, 'خطة مفصلة لإدارة السلامة توضح إجراءات الفحص ومتطلبات الامتثال.', 'A detailed safety management plan outlining inspection procedures and compliance requirements.', false),
  (2977, 3, 'خطة تواصل مع المعنيين تضمن إبلاغ جميع الأطراف بمخاطر السلامة على مدار المشروع.', 'A stakeholder communication plan ensuring all parties were informed of safety risks throughout the project.', false),
  (2978, 0, 'تأجيل البنود الجديدة إلى السبرينت التالي حفاظًا على أعمال التحضير التي أنجزها الفريق.', 'Defer the new items to the next sprint to preserve the team''s preparation work.', false),
  (2978, 1, 'عرض البنود الجديدة خلال تخطيط السبرينت وإتاحة المجال للفريق لاختيار الأعمال التي يلتزم بإنجازها.', 'Present the new items during sprint planning and allow the team to select the work they commit to completing.', true),
  (2978, 2, 'إزالة البنود الأدنى أولوية من سجل الأعمال لاستيعاب الإضافات الجديدة عالية الأولوية.', 'Remove the lowest-priority items from the backlog to accommodate the new high-priority additions.', false),
  (2978, 3, 'تصعيد الخلاف إلى سكرم ماستر (Scrum Master) لتحديد البنود التي ينبغي إدراجها في السبرينت.', 'Escalate the conflict to the scrum master to determine which items should be included in the sprint.', false),
  (2979, 0, 'إعطاء الأولوية لمشاركة المعنيين الذين يملكون صلاحية مباشرة في صنع القرار، لأن موافقتهم لازمة لنجاح المشروع.', 'Prioritize engagement with stakeholders who hold direct decision-making authority, since their approval is required for project success.', false),
  (2979, 1, 'تصنيف المعنيين وفق مستوى سلطتهم واهتمامهم، وتكييف استراتيجيات المشاركة بحسب موقع كل مجموعة.', 'Categorize stakeholders by their level of power and interest, and tailor engagement strategies to each group''s position.', true),
  (2979, 2, 'تطبيق استراتيجية تواصل موحّدة عبر جميع مجموعات المعنيين لضمان وصول عادل إلى معلومات المشروع.', 'Implement a consistent communication strategy across all stakeholder groups to ensure equitable access to project information.', false),
  (2979, 3, 'تركيز جهود المشاركة على المعنيين ذوي التأثير التشغيلي المرتفع، لأن انخراطهم اليومي هو المحدد الأكثر مباشرة لنجاح التسليم.', 'Concentrate engagement efforts on stakeholders with high operational impact, since their day-to-day involvement most directly determines delivery success.', false),
  (2980, 0, 'التصريح لعضو الفريق بتنفيذ الميزة لأن مدير المشروع وافق عليها بالفعل.', 'Authorize the team member to implement the feature since the project manager has already approved it.', false),
  (2980, 1, 'تقييم أثر الميزة وتنفيذها إذا كانت ضمن موازنة الطوارئ القائمة.', 'Evaluate the feature''s impact and implement it if it falls within the existing contingency budget.', false),
  (2980, 2, 'تقديم طلب تغيير رسمي وتمريره عبر عملية التحكم في التغيير قبل بدء أي عمل.', 'Submit a formal change request and route it through the change control process before any work begins.', true),
  (2980, 3, 'توثيق الميزة بوصفها تحسينًا مستقبليًا ومعالجتها في مرحلة المشروع التالية.', 'Document the feature as a future enhancement and address it in the next project phase.', false),
  (2981, 0, 'إبلاغ عضو الفريق بأن مرحلة تحديد المخاطر قد اكتملت وأن سجل المخاطر مُغلق.', 'Inform the team member that the risk identification phase has been completed and the risk register is closed.', false),
  (2981, 1, 'إضافة المخاطرة إلى سجل المخاطر وإجراء تقييم تعاوني للمخاطر مع الفريق والمعنيين ذوي الصلة.', 'Add the risk to the risk register and conduct a collaborative risk assessment with the team and relevant stakeholders.', true),
  (2981, 2, 'تصعيد الشاغل التنظيمي إلى راعي المشروع وطلب التوجيه قبل اتخاذ أي إجراء.', 'Escalate the regulatory concern to the project sponsor and request guidance before taking any action.', false),
  (2981, 3, 'تحديث الجدول الزمني للمشروع لمراعاة التأخير التنظيمي المحتمل قبل مواصلة تقييم المخاطرة.', 'Update the project schedule to account for the potential regulatory delay before evaluating the risk further.', false),
  (2982, 0, 'مطالبة الفريق بمراجعة التسليم ليطابق توقعات العميل ثم تقديم طلب تغيير بعد ذلك.', 'Ask the team to revise the deliverable to match the client''s expectations and submit a change request afterward.', false),
  (2982, 1, 'تصعيد الخلاف إلى راعي المشروع لحل النزاع مع العميل.', 'Escalate the disagreement to the project sponsor to resolve the conflict with the client.', false),
  (2982, 2, 'مراجعة معايير القبول الموثقة مع العميل لتحديد ما إذا كان التسليم يلبي المعايير المتفق عليها.', 'Review the documented acceptance criteria with the client to determine whether the deliverable meets the agreed-upon standards.', true),
  (2982, 3, 'توثيق مخاوف العميل والمضي في اعتماد التسليم لأن العمل يطابق الخط المرجعي المعتمد للنطاق.', 'Document the client''s concerns and proceed with deliverable sign-off because the work matches the approved scope baseline.', false),
  (2983, 0, 'CPI = 0.83؛ المشروع متجاوز للموازنة، إذ يحصل على قيمة أقل من المبلغ الذي يُنفَق.', 'CPI = 0.83; the project is over budget, receiving less value than the amount being spent.', true),
  (2983, 1, 'CPI = 1.20؛ المشروع دون الموازنة، إذ يُنجَز عمل أكثر مما خُطِّط له مقابل التكلفة المتكبَّدة.', 'CPI = 1.20; the project is under budget, completing more work than planned for the cost incurred.', false),
  (2983, 2, 'CPI = 0.80؛ المشروع متجاوز للموازنة، لأن القيمة المكتسبة أقل من القيمة المخططة.', 'CPI = 0.80; the project is over budget, as earned value falls short of planned value.', false),
  (2983, 3, 'CPI = 1.04؛ المشروع دون الموازنة، إذ تسير التكاليف أدنى قليلًا من القيمة المخططة.', 'CPI = 1.04; the project is under budget, with costs running slightly below planned value.', false),
  (2984, 0, 'اتخاذ قرار نهائي بشأن البنية لإنهاء الجمود وتمكين الفريق من المضي قدمًا.', 'Make a final decision on the architecture to end the impasse and allow the team to move forward.', false),
  (2984, 1, 'جمع المهندسَين معًا في جلسة لحل المشكلات للعمل على التوصل إلى حل مقبول.', 'Bring both engineers together in a problem-solving session to work toward an acceptable solution.', true),
  (2984, 2, 'الفصل بين مسؤوليات المهندسَين لتقليل تفاعلهما فيما تبقى من المشروع.', 'Separate the two engineers'' responsibilities to minimize their interaction for the remainder of the project.', false),
  (2984, 3, 'ترك النزاع ليُحل تلقائيًا، إذ عادةً ما تصحح الخلافات الفنية نفسها بنفسها بمجرد استئناف العمل.', 'Allow the conflict to resolve naturally, as technical disagreements typically self-correct once work resumes.', false),
  (2985, 0, 'التكيفي، لأن المشروع ينطوي على تقنية معقدة وقد يستفيد من التطوير التكراري.', 'Adaptive, because the project involves complex technology and could benefit from iterative development.', false),
  (2985, 1, 'الهجين، لأن البيئة التنظيمية تسوّغ حوكمة منظمة بينما يمكن أن يمضي التطوير تكراريًا.', 'Hybrid, because the regulatory environment justifies structured governance while development could proceed iteratively.', false),
  (2985, 2, 'التنبؤي، لأن المتطلبات ثابتة، والتوثيق مطلوب، والفريق متمرس في التسليم المنظم.', 'Predictive, because the requirements are fixed, documentation is required, and the team is experienced with structured delivery.', true),
  (2985, 3, 'التكيفي، لأن التغذية الراجعة المتكررة من المعنيين ستساعد على ضمان تلبية المنصة للتوقعات التنظيمية.', 'Adaptive, because frequent stakeholder feedback will help ensure the platform meets regulatory expectations.', false),
  (2986, 0, 'زيادة وتيرة دورات الاختبار النهائي لاكتشاف مزيد من العيوب قبل الإصدار.', 'Increase the frequency of final testing cycles to catch more defects before release.', false),
  (2986, 1, 'تطبيق أنشطة ضمان الجودة في مرحلة أبكر من عملية التطوير لمنع حدوث العيوب من الأساس.', 'Implement quality assurance activities earlier in the development process to prevent defects from occurring.', true),
  (2986, 2, 'تعيين اختصاصي متفرغ لضبط الجودة لمراجعة جميع الشيفرات البرمجية قبل انتقالها إلى الاختبار.', 'Assign a dedicated quality control specialist to review all code before it proceeds to testing.', false),
  (2986, 3, 'قبول معدل العيوب الحالي بوصفه جزءًا طبيعيًا من تطوير البرمجيات وتتبعه بوصفه أحد مقاييس المشروع.', 'Accept the current defect rate as a normal part of software development and track it as a project metric.', false),
  (2987, 0, 'عقد اجتماع مع الإدارات المتأثرة لإرساء فهم مشترك والتوافق على كيفية تنفيذ التغيير.', 'Convene a meeting with the affected departments to establish shared understanding and align on how the change should be implemented.', true),
  (2987, 1, 'إرسال تقرير حالة منقّح بصياغة توضيحية إلى مجموعة المعنيين كاملة مع التأكيد على التفسير الصحيح.', 'Send a revised status report with clarifying language to the full stakeholder group emphasizing the correct interpretation.', false),
  (2987, 2, 'تحديث بوابة المشروع بوثائق النطاق المنقّحة وإخطار المعنيين بالبريد الإللكتروني بتوفر النسخة المحدّثة.', 'Update the project portal with the revised scope documentation and notify stakeholders by email that the updated version is available.', false),
  (2987, 3, 'تصعيد التفسيرات المتضاربة إلى راعي المشروع والطلب منه إبلاغ الإدارات بالنهج الصحيح.', 'Escalate the conflicting interpretations to the project sponsor and request that they communicate the correct approach to the departments.', false),
  (2988, 0, 'تطبيق أسلوب المسار السريع ‎(Fast Tracking)‎ على أنشطة مختارة من المسار الحرج من خلال مداخلة الأعمال اللاحقة حيثما أمكن لاستعادة الوقت.', 'Fast-track selected critical path activities by overlapping successor work wherever possible to recover time.', false),
  (2988, 1, 'ضغط زمن الأنشطة الأطول مدة في الجدول الزمني أولًا لاستعادة أقصى قدر ممكن من الوقت إجمالًا.', 'Crash the longest-duration activities on the schedule first to recover the maximum amount of time overall.', false),
  (2988, 2, 'ضغط زمن ‎(Crashing)‎ أنشطة المسار الحرج التي يمكن فيها حشد معدات وأطقم إضافية.', 'Crash the critical path activities where additional equipment and crews can be mobilized.', true),
  (2988, 3, 'إعادة اعتماد الخط المرجعي للجدول الزمني للمشروع ليعكس تاريخ الإكمال المتوقع الحالي.', 'Re-baseline the project schedule to reflect the current projected completion date.', false),
  (2989, 0, 'مواصلة النهج الحالي لترسيخ السلطة وضمان إشراف متسق على الفريق.', 'Continue the current approach to establish authority and ensure consistent oversight of the team.', false),
  (2989, 1, 'تفويض دور مدير المشروع إلى سكرم ماستر لأن الفرق ذاتية التنظيم لا تحتاج إلى مشاركة مدير المشروع.', 'Delegate the project manager role to the scrum master since self-organizing teams do not require project manager involvement.', false),
  (2989, 2, 'جدولة ورشة عمل للفريق لإعادة تحديد الأدوار والمسؤوليات بحيث تستوعب وظائف الإشراف الخاصة بمدير المشروع.', 'Schedule a team workshop to redefine roles and responsibilities to incorporate the project manager''s oversight functions.', false),
  (2989, 3, 'التحول إلى نهج القيادة الخادمة الذي يزيل العقبات، ويدعم استقلالية الفريق، ويتجنب الإدارة التفصيلية.', 'Shift to a servant leadership approach that removes obstacles, supports team autonomy, and avoids micromanagement.', true),
  (2990, 0, 'تحويل المخاطرة من خلال ترتيب تغطية تأمينية على أضرار المعدات والمواد المرتبطة بالعواصف.', 'Transfer the risk by arranging insurance coverage for storm-related equipment and material damage.', true),
  (2990, 1, 'تخفيف المخاطرة من خلال تطبيق إجراءات الاستعداد للعواصف، والتخزين الوقائي، وتدابير تحصين الموقع لتقليل الأضرار المحتملة.', 'Mitigate the risk by implementing storm-preparation procedures, protective storage, and site hardening measures to reduce potential damage.', false),
  (2990, 2, 'تفادي المخاطرة من خلال إعادة جدولة أنشطة الإنشاء خارج نافذة موسم الأعاصير.', 'Avoid the risk by rescheduling construction activities outside the hurricane season window.', false),
  (2990, 3, 'قبول المخاطرة وإرساء بروتوكول لمراقبة الطقس طوال فترة الإنشاء.', 'Accept the risk and establish a weather monitoring protocol for the construction period.', false),
  (2991, 0, 'مطالبة الفريق بتبسيط القصص حيثما أمكن لتقليل التقديرات وإدراج مزيد من البنود في كل سبرينت.', 'Ask the team to simplify stories where possible to reduce estimates and fit more items into each sprint.', false),
  (2991, 1, 'قبول الالتزام الأعلى لأن مواعيد التسليم النهائية تمثل أولوية أعمال يجب على الفريق استيعابها.', 'Accept the higher commitment since delivery deadlines represent a business priority the team must accommodate.', false),
  (2991, 2, 'تخفيض تقديرات نقاط القصة عبر سجل الأعمال بحيث يبدو هدف الل 55 نقطة قابلًا للتحقيق ضمن القدرة الحالية.', 'Reduce story point estimates across the backlog so the 55-point target appears achievable within current capacity.', false),
  (2991, 3, 'توضيح أن السرعة الإنتاجية تعكس القدرة التاريخية، وأن تضخيم التزامات السبرينت عادةً ما يُضعف الجودة ويزيد الدين التقني بدلًا من تسريع التسليم.', 'Explain that velocity reflects historical capacity and that inflating sprint commitments typically degrades quality and increases technical debt rather than accelerating delivery.', true),
  (2992, 0, 'احتياطيات الطوارئ يتحكم فيها مدير المشروع وتُستخدم للمخاطر المحددة؛ أما الاحتياطيات الإدارية فيتحكم فيها الراعي وتتطلب اعتمادًا رسميًا للوصول إليها.', 'Contingency reserves are controlled by the project manager and used for identified risks; management reserves are controlled by the sponsor and require formal approval to access.', true),
  (2992, 1, 'يتحكم مدير المشروع في جميع الاحتياطيات ويمكنه الوصول إلى أي من النوعين عندما تتجاوز التكاليف الفعلية الخط المرجعي للتكلفة.', 'The project manager controls all reserves and can access either type when actual costs exceed the cost baseline.', false),
  (2992, 2, 'كلا نوعي الاحتياطيات يتحكم فيهما الراعي ويتطلب استخدامهما طلب تغيير رسميًا.', 'Both reserve types are controlled by the sponsor and require a formal change request to be used.', false),
  (2992, 3, 'الاحتياطيات الإدارية جزء من الخط المرجعي للتكلفة، بينما تقع احتياطيات الطوارئ خارجه وتتطلب اعتماد الراعي لاستخدامها.', 'Management reserves are part of the cost baseline while contingency reserves sit outside it and require sponsor approval to use.', false),
  (2993, 0, 'وضع استراتيجيات مشاركة مصممة خصيصًا لكل مجموعة بناءً على مواقفها واهتماماتها المحددة وتأثيرها في المشروع.', 'Develop tailored engagement strategies for each group based on their specific positions, interests, and influence on the project.', true),
  (2993, 1, 'إعطاء الأولوية للمشاركة مع لجنة التخطيط البلدية لتأمين دعمها المبدئي قبل معالجة معارضة المجتمع المحلي.', 'Prioritize engagement with the city planning committee to secure their preliminary support before addressing community opposition.', false),
  (2993, 2, 'جدولة اجتماعات أولية مع جمعية الحي لفهم مصدر معارضتها قبل وضع نهج مشاركة أوسع.', 'Schedule initial meetings with the neighborhood association to understand the source of their opposition before developing a broader engagement approach.', false),
  (2993, 3, 'تنظيم جلسة مشتركة للمعنيين تستمع فيها المجموعات الثلاث معًا إلى مقترح المشروع وتطرح مخاوفها.', 'Organize a joint stakeholder session where all three groups can hear the project proposal and raise concerns together.', false),
  (2994, 0, 'إضافة الميزة إلى سجل أعمال السبرينت الحالي فورًا.', 'Add the feature to the current sprint backlog immediately', false),
  (2994, 1, 'رفض الطلب لأن سجل الأعمال قد وُضع في صيغته النهائية.', 'Reject the request because the backlog has been finalized', false),
  (2994, 2, 'جدولة جلسة طارئة لتخطيط السبرينت لاستيعاب الميزة الجديدة.', 'Schedule an emergency sprint planning session to accommodate the new feature', false),
  (2994, 3, 'تقييم الميزة وإضافتها إلى سجل أعمال المنتج إن كان ذلك مناسبًا.', 'Evaluate the feature and add it to the product backlog if appropriate', true),
  (2995, 0, 'يقدّم هيكل تجزئة العمل ملخصًا مرئيًا لوثيقة النطاق ويُعد في المقام الأول لأغراض التواصل مع المعنيين.', 'The WBS provides a visual summary of the scope document and is created primarily for stakeholder communication purposes.', false),
  (2995, 1, 'هيكل تجزئة العمل مطلوب بموجب أصول عمليات المؤسسة ويجب إكماله بغض النظر عن كون النطاق محدّ دًا جيدًا بالفعل.', 'The WBS is required by organizational process assets and must be completed regardless of whether scope is already well-defined.', false),
  (2995, 2, 'يحل هيكل تجزئة العمل محل وثيقة النطاق بعد اعتماده ويكون المرجع الوحيد لجميع أعمال المشروع خلال مرحلة التنفيذ.', 'The WBS replaces the scope document once approved and serves as the single reference for all project work during the execution phase.', false),
  (2995, 3, 'يجزّئ هيكل تجزئة العمل التسليماتِ إلى حزم عمل يمكن تقديرها وإسنادها وتتبعها بموثوقية، ما يجعل النطاق قابلًا للإدارة والقياس.', 'The WBS decomposes deliverables into work packages that can be reliably estimated, assigned, and tracked, making scope manageable and measurable.', true),
  (2996, 0, 'إقران كل عضو مغادر بشريك معرفة من الموظفين الباقين.', 'Pair each departing team member with a knowledge partner from the remaining staff.', false),
  (2996, 1, 'تسجيل عروض توضيحية بالفيديو مع كل عضو مغادر قبل يومه الأخير.', 'Record video walkthroughs with each departing team member before their last day.', false),
  (2996, 2, 'تكليف الأعضاء المغادرين بكتابة ملاحظات تسليم مفصلة قبل مغادرتهم.', 'Have departing team members write detailed handover notes before they leave.', false),
  (2996, 3, 'عقد جلسات دروس مستفادة منظمة مع الفريق كاملًا قبل مغادرة أي من أعضائه.', 'Conduct structured lessons learned sessions with the full team before any members depart.', true),
  (2997, 0, 'تحديث خطة إدارة المشروع مباشرةً لتعكس الواقع الحالي بحيث يتوفر للفريق توجيه دقيق للمضي قدمًا.', 'Update the project management plan directly to reflect current reality so the team has accurate guidance going forward.', false),
  (2997, 1, 'إخطار راعي المشروع بالتباينات وطلب الإذن بتعديل خطة إدارة المشروع.', 'Notify the project sponsor of the variances and request permission to modify the project management plan.', false),
  (2997, 2, 'تحليل الأسباب الجذرية للتباينات وتقديم طلبات تغيير رسمية لأي تحديثات تتطلب تعديلات على الخطوط المرجعية.', 'Analyze the root causes of the variances and submit formal change requests for any updates that require baseline modifications.', true),
  (2997, 3, 'إصدار توجيهات بإجراءات تصحيحية لإعادة الأداء إلى ما دون الحدود الفاصلة قبل إجراء أي تحديثات على الخطة.', 'Issue corrective action directives to bring performance back within thresholds before making any plan updates.', false),
  (2998, 0, 'عقد السعر الثابت المحدد ‎(FFP)‎.', 'Firm Fixed Price', false),
  (2998, 1, 'عقد التكلفة مضافًا إليها مبلغ تحفيزي ‎(CPIF)‎.', 'Cost Plus Incentive Fee', true),
  (2998, 2, 'عقد الزمن والمواد ‎(T&M)‎.', 'Time and Materials', false),
  (2998, 3, 'عقد التكلفة مضافًا إليها مبلغ ثابت ‎(CPFF)‎.', 'Cost Plus Fixed Fee', false),
  (2999, 0, 'تطبيق منهج تنبؤي على المشروع بأكمله.', 'Apply a predictive approach to the entire project.', false),
  (2999, 1, 'تطبيق منهج تكيفي على المشروع بأكمله.', 'Apply an adaptive approach to the entire project.', false),
  (2999, 2, 'فصل المشروع إلى مشروعين مستقلين بمنهجيتين متمايزتين.', 'Separate the project into two independent projects with distinct methodologies.', false),
  (2999, 3, 'استخدام منهج تنبؤي لمكوّن البنية التحتية ومنهج تكيفي للوحات المعلومات وأدوات إعداد التقارير.', 'Use a predictive approach for the infrastructure component and an adaptive approach for the dashboards and reporting tools.', true),
  (3000, 0, 'تطبيق الصيغة المبسطة التي اقترحها الفريق.', 'Implement the team''s simplified format.', false),
  (3000, 1, 'تطبيق صيغة إدارة الغذاء والدواء كما هو مطلوب.', 'Apply the FDA format as required.', true),
  (3000, 2, 'تقديم طلب تغيير إلى مجلس التحكم في التغيير.', 'Submit a change request to the change control board.', false),
  (3000, 3, 'الطلب من راعي المشروع التقدم بطلب إعفاء تنظيمي.', 'Ask the project sponsor to request a regulatory waiver.', false),
  (3001, 0, 'تركيز جهود الاستعادة على النشاط «ب.»', 'Focus recovery efforts on Activity B.', false),
  (3001, 1, 'تركيز جهود الاستعادة على النشاط «أ.»', 'Focus recovery efforts on Activity A.', true),
  (3001, 2, 'إعادة تخصيص الموارد من النشاط «ب» إلى النشاط «أ».', 'Reallocate resources from Activity B to Activity A.', false),
  (3001, 3, 'التصعيد إلى راعي المشروع.', 'Escalate to the project sponsor.', false),
  (3002, 0, '$480,000.', '$480,000', false),
  (3002, 1, '$600,000.', '$600,000', false),
  (3002, 2, '$660,000.', '$660,000', false),
  (3002, 3, '$750,000.', '$750,000', true),
  (3003, 0, 'الطلب من الراعي إرسال مذكرة توضيحية إلى قادة الفرق تصف الهدف الأساسي للمشروع.', 'Ask the sponsor to send a clarifying memo to the team leads describing the project''s primary objective.', false),
  (3003, 1, 'تحديث وثيقة نطاق المشروع لتعكس الهدفين معًا حتى لا تشعر أي من المجموعتين بالإقصاء.', 'Update the project scope document to reflect both objectives so neither group feels excluded.', false),
  (3003, 2, 'وضع بيان رؤية المشروع أو إعادة النظر فيه لإرساء تعريف واحد مشترك لغاية المشروع.', 'Develop or revisit the project''s vision statement to establish a single shared definition of the project''s purpose.', true),
  (3003, 3, 'السماح باستمرار التفسيرين معًا لأن خفض التكاليف وتحسين الجودة هدفان متكاملان.', 'Allow both interpretations to continue since cost reduction and quality improvement are complementary goals.', false),
  (3004, 0, 'بدء المرحلة بالمطوّر بدوام جزئي وطلب دعم إضافي إذا أصبح عبء العمل خارج السيطرة.', 'Begin the phase with the part-time developer and request additional support if the workload becomes unmanageable.', false),
  (3004, 1, 'تصعيد نزاع الموارد إلى راعي المشروع لحله مع المدير الوظيفي.', 'Escalate the resource conflict to the project sponsor to resolve with the functional manager.', true),
  (3004, 2, 'تعديل الجدول الزمني للمشروع بما يستوعب توفر المورد بدوام جزئي.', 'Revise the project schedule to accommodate part-time resource availability.', false),
  (3004, 3, 'توثيق قيد الموارد بوصفه مخاطرة ومواصلة التفاوض مع المدير الوظيفي.', 'Document the resource constraint as a risk and continue negotiating with the functional manager.', false),
  (3005, 0, 'الاستثمار في أنشطة منع العيوب المبكرة مثل مراجعات التصميم وتدريب المطورين.', 'Invest in earlier defect prevention activities such as design reviews and developer training.', true),
  (3005, 1, 'إضافة مزيد من دورات الاختبار في نهاية التطوير لاكتشاف العيوب قبل وصولها إلى العملاء.', 'Add more testing cycles at the end of development to catch defects before they reach customers.', false),
  (3005, 2, 'زيادة موازنة الدعم لما بعد الإصدار للتعامل مع الحجم المتوقع من مشكلات العملاء.', 'Increase the post-release support budget to handle the expected volume of customer issues.', false),
  (3005, 3, 'تطبيق نظام لتتبع العيوب لتحسين تصنيف المشكلات المبلَّغ عنها من العملاء وترتيب أولوياتها.', 'Implement a defect tracking system to better categorize and prioritize customer-reported issues.', false),
  (3006, 0, 'إغلاق المخاطرة الأصلية لأن استجابة التخفيف المعتمدة سبق توثيقها واعتمادها خلال التخطيط.', 'Close the original risk since the approved mitigation response has already been documented and approved during planning.', false),
  (3006, 1, 'تحديث سجل المخاطر ليعكس محدودية قدرة المورّد الثانوي ومواصلة المراقبة.', 'Update the risk register to reflect the secondary supplier''s capacity limitation and continue monitoring.', false),
  (3006, 2, 'تحديث سجل المخاطر ليعكس التعرض المتبقي وتيسير وضع استجابة إضافية للمخاطرة.', 'Update the risk register to reflect the remaining exposure and facilitate development of an additional risk response.', true),
  (3006, 3, 'التصعيد إلى راعي المشروع لأن استراتيجية التخفيف الموثقة ثبت عدم كفايتها.', 'Escalate to the project sponsor since the documented mitigation strategy has proven insufficient.', false),
  (3007, 0, 'مطالبة عضو الفريق بإزالة جميع الإضافات غير المصرح بها وإعادة التسليم إلى حالته المرساة في الخط المرجعي.', 'Ask the team member to remove all unauthorized additions and return the deliverable to its baselined state.', false),
  (3007, 1, 'تقديم طلبات تغيير بأثر رجعي للإضافات لإدخالها في السجل الرسمي.', 'Submit retroactive change requests for the additions to bring them into the formal record.', false),
  (3007, 2, 'إبلاغ المستخدمين النهائيين بأن جميع الطلبات المستقبلية يجب أن تمر عبر عملية طلبات التغيير.', 'Inform the end users that all future requests must go through the change request process.', false),
  (3007, 3, 'إيقاف الإضافات غير الرسمية، وتقييم أثرها على الجدول الزمني والتكلفة، وتحديد ما إذا كان ينبغي تقديم طلبات تغيير رسمية.', 'Stop the informal additions, assess their impact on schedule and cost, and determine whether formal change requests should be submitted.', true),
  (3008, 0, 'إبلاغ العميل بأن المشاريع الرشيقة لا يمكنها تقديم توقعات.', 'Tell the customer that agile projects cannot provide forecasts.', false),
  (3008, 1, 'تقديم تاريخ إكمال ثابت لطمأنة العميل.', 'Provide a fixed completion date to reassure the customer.', false),
  (3008, 2, 'استخدام السرعة الإنتاجية للفريق وسجل الأعمال المتبقي لتقدير نطاق زمني مرجح.', 'Use the team''s velocity and remaining backlog to project a likely range.', true),
  (3008, 3, 'الطلب من العميل الانتظار حتى تُسلَّم الميزات فعليًا.', 'Ask the customer to wait until the features are actually delivered.', false),
  (3009, 0, 'استخدام منهج هجين، بتطبيق التخطيط التنبؤي على الميزات الأساسية والتكرارات التكيفية على الميزات المتبقية.', 'Use a hybrid approach, applying predictive planning to the core features and adaptive iterations for the remaining features.', true),
  (3009, 1, 'استخدام منهج تنبؤي للحفاظ على تحكم صارم في الجدول الزمني والموازنة نظرًا للموعد النهائي الثابت.', 'Use a predictive approach to maintain tight control over schedule and budget given the fixed deadline.', false),
  (3009, 2, 'استخدام منهج تكيفي لإدماج التغذية الراجعة من المستخدمين مع تطور المنتج بما يتجاوز وظائفه الأساسية.', 'Use an adaptive approach to incorporate user feedback as the product evolves beyond its core functionality.', false),
  (3009, 3, 'استخدام منهج تكيفي لأن بيئة الشركة الناشئة وتفضيلات المستخدمين غير المؤكدة تجعلان المرونة أعلى قيمة من التخطيط المسبق.', 'Use an adaptive approach since the startup environment and uncertain user preferences make flexibility more valuable than upfront planning.', false),
  (3010, 0, 'اتباع كل أولوية جديدة فورًا وفق توجيهات الراعي.', 'Follow each new priority immediately as the sponsor directs.', false),
  (3010, 1, 'تجاهل تغييرات الراعي والالتزام بالخطة الأصلية.', 'Ignore the sponsor''s changes and stick to the original plan.', false),
  (3010, 2, 'مطالبة الفريق بالعمل على جميع الأولويات في آنٍ واحد.', 'Ask the team to work on all priorities simultaneously.', false),
  (3010, 3, 'مناقشة الأثر مع الراعي.', 'Discuss the impact of shifting priorities with the sponsor.', true),
  (3011, 0, 'انتظار قيام مجلس التحكم في التغيير بتقييم التغيير واعتماده رسميًا قبل بدء العمل.', 'Wait for the change control board to formally evaluate and approve the change before work begins.', true),
  (3011, 1, 'بدء العمل فورًا لأن الراعي اعتمد التغيير وأي تأخير يضيف تكلفة لا داعي لها.', 'Begin work immediately since the sponsor has approved the change and any delay adds unnecessary cost.', false),
  (3011, 2, 'بدء التخطيط الأولي للتغيير في أثناء انتظار اجتماع مجلس التحكم في التغيير.', 'Begin preliminary planning for the change while waiting for the change control board to meet.', false),
  (3011, 3, 'الطلب من الراعي إصدار تصريح كتابي حتى يمكن بدء العمل دون انتظار المجلس.', 'Ask the sponsor to issue a written authorization so work can begin without waiting for the board.', false),
  (3012, 0, 'الإفراج عن أعضاء الفريق إلى مهامهم الجديدة لأن العميل أكد رضاه شفهيًا.', 'Release the team members to their new assignments since the client has verbally confirmed satisfaction.', false),
  (3012, 1, 'الإفراج عن الفريق والطلب من العميل استكمال وثيقة القبول الرسمية عن بُعد في الوقت الذي يناسبه.', 'Release the team and ask the client to complete the formal acceptance document remotely at their convenience.', false),
  (3012, 2, 'التصعيد إلى راعي المشروع للتفاوض مع العميل على تعجيل التوقيع الرسمي.', 'Escalate to the project sponsor to negotiate with the client to expedite the formal sign-off.', false),
  (3012, 3, 'الاحتفاظ بالفريق حتى يوثّق العميل القبول رسميًا، ثم المضي في الإفراج عن الموارد.', 'Retain the team until the client formally documents acceptance, then proceed with resource release.', true),
  (3013, 0, 'رفض الطلب حمايةً للجدول الزمني المعتمد.', 'Reject the request to protect the approved schedule.', false),
  (3013, 1, 'تقييم الطلب بناءً على القيمة طويلة الأمد للمعنيين.', 'Evaluate the request based on long-term stakeholder value.', true),
  (3013, 2, 'تأجيل الطلب حتى اكتمال أعمال الإنشاء.', 'Delay the request until construction is complete.', false),
  (3013, 3, 'الطلب من المجتمع المحلي تقديم الطلب بعد إغلاق المشروع.', 'Ask the community to submit the request after project closure.', false),
  (3014, 0, 'توثيق الدروس المستفادة فورًا للحفاظ على التفاصيل وهي لا تزال حاضرة في الأذهان.', 'Document the lessons learned immediately to preserve the details while they are still fresh.', false),
  (3014, 1, 'إرجاء التوثيق إلى ما بعد الوفاء بالتزام التسليم كما طلب الراعي.', 'Defer documentation until after the delivery commitment is met as the sponsor has requested.', false),
  (3014, 2, 'الطلب من أعضاء الفريق الاحتفاظ بملاحظات شخصية وتجميعها رسميًا عند إغلاق المشروع.', 'Ask team members to keep personal notes and compile them formally at project closure.', false),
  (3014, 3, 'التقاط الدروس المستفادة في التقييم الرجعي المقبل للسبرينت.', 'Capture the lessons learned at the upcoming sprint retrospective.', true),
  (3015, 0, 'العودة إلى التخطيط لتحديد تحسينات إضافية يمكن أن تخفض معدلات العيوب أكثر.', 'Return to planning to identify additional improvements that could reduce defect rates further.', false),
  (3015, 1, 'مواصلة جمع البيانات أربعة أسابيع أخرى قبل استخلاص استنتاجات بشأن فعالية البروتوكول.', 'Continue collecting data for another four weeks before drawing conclusions about the protocol''s effectiveness.', false),
  (3015, 2, 'اعتماد بروتوكول الاختبار الجديد بوصفه العملية الدائمة المعيارية وتحديث أصول عمليات المؤسسة.', 'Standardize the new testing protocol as the permanent process and update the organizational process assets.', true),
  (3015, 3, 'استحداث إجراءات اختبار إضافية للبناء على التحسن المتحقق بالفعل.', 'Introduce additional testing procedures to build on the improvement already achieved.', false),
  (3016, 0, 'اختيار المورّد ذي سعر الشراء الأدنى.', 'Select the supplier with the lowest purchase price.', false),
  (3016, 1, 'تقييم المورّدَين معًا باستخدام معياري الاستدامة والقيمة طويلة الأمد.', 'Evaluate both suppliers using sustainability and long-term value.', true),
  (3016, 2, 'اختيار المورّد ذي جدول التسليم الأقصر.', 'Choose the supplier with the shortest delivery schedule.', false),
  (3016, 3, 'ترك الاختيار لمدير المشتريات.', 'Allow the procurement manager to make the selection.', false),
  (3017, 0, 'شراء أرصدة اللكربون بعد اكتمال الإنتاج.', 'Purchase carbon credits after production is complete.', false),
  (3017, 1, 'إعادة تأهيل المنطقة المتأثرة بعد انتهاء الإنتاج.', 'Restore the affected area after production ends.', false),
  (3017, 2, 'تقليل كمية النفايات المنتَجة أثناء التصنيع.', 'Reduce the amount of waste produced during manufacturing.', false),
  (3017, 3, 'إعادة تصميم العملية لمنع توليد النفايات من الأساس.', 'Redesign the process to prevent the waste from being generated.', true),
  (3018, 0, 'اختيار البديل الذي يصنّفه الذكاء الاصطناعي في المرتبة الأعلى لأنه قيّم بيانات أكثر مما قيّمه فريق المشروع.', 'Select the alternative that AI ranks highest because it evaluated more data than the project team.', false),
  (3018, 1, 'تأجيل القرار حتى يحدد الذكاء الاصطناعي حلًا أمثل واحدًا.', 'Delay the decision until AI identifies a single optimal solution.', false),
  (3018, 2, 'الطلب من اللجنة التوجيهية اختيار البديل المفضل باستخدام المقارنة المولَّدة بالذكاء الاصطناعي.', 'Ask the steering committee to select the preferred alternative using the AI-generated comparison.', false),
  (3018, 3, 'استخدام الذكاء الاصطناعي لتحليل البدائل، ثم إعمال التقدير المهني قبل تقديم توصية.', 'Use AI to analyze the alternatives, then apply professional judgment before making a recommendation.', true),
  (3019, 0, 'الطلب من مدير الموارد تخصيص مهندسين متفرغين للمشروع الجديد.', 'Request that the resource manager assign dedicated engineers to the new project.', false),
  (3019, 1, 'تقييم الأثر على المشروعين معًا وتحديد المهام التي يمكن ترتيبها تسلسليًا أو إرجاؤها لتقليل التزاحم.', 'Assess the impact on both projects and identify tasks that can be sequenced or deferred to reduce contention.', true),
  (3019, 2, 'تصعيد التعارض إلى مكتب إدارة المشاريع ‎(PMO)‎ قبل مواصلة تخطيط المشروع.', 'Escalate the conflict to the PMO before continuing project planning.', false),
  (3019, 3, 'إخطار مدير المشروع الآخر واقتراح تنسيق الجدولين الزمنيين بصورة غير رسمية.', 'Notify the other project manager and suggest coordinating schedules informally.', false),
  (3020, 0, 'السماح لنظام الذكاء الاصطناعي بتوزيع التقارير لأن المعلومات تأتي مباشرةً من بيانات مشروع معتمدة.', 'Allow the AI system to distribute the reports because the information comes directly from approved project data.', false),
  (3020, 1, 'مواصلة مراجعة التقارير المولَّدة بالذكاء الاصطناعي قبل توزيعها على المعنيين.', 'Continue reviewing AI-generated reports before they are distributed to stakeholders.', true),
  (3020, 2, 'الطلب من الراعي اعتماد كل تقرير مولَّد بالذكاء الاصطناعي قبل توزيعه.', 'Ask the sponsor to approve each AI-generated report before distribution.', false),
  (3020, 3, 'ضبط أداة الذكاء الاصطناعي بحيث لا توزع التقارير إلا عند عدم تحديد أي إشكالات في المشروع.', 'Configure the AI tool to distribute reports only when no project issues are identified.', false),
  (3021, 0, 'السحب من موازنة الطوارئ لاستيعاب الزيادة في التكلفة كما يقترح الراعي.', 'Draw on the contingency budget to absorb the cost increase as the sponsor suggests.', false),
  (3021, 1, 'إعادة التفاوض على عقود المورّدين لتثبيت الأسعار بالعملة المحلية للمشروع.', 'Renegotiate supplier contracts to fix pricing in the project''s home currency.', false),
  (3021, 2, 'تعليق المشتريات الدولية حتى تستقر أسعار الصرف.', 'Suspend international procurement until exchange rates stabilize.', false),
  (3021, 3, 'العمل مع الفريق المالي على تقييم أدوات التحوط وتطبيقها للحد من مزيد من التعرض.', 'Work with the finance team to evaluate and implement hedging instruments to limit further exposure.', true),
  (3022, 0, 'تقييم الخصائص المحددة للمشروع لتحديد منهج التسليم الأنسب.', 'Evaluate the project''s specific characteristics to determine the most suitable delivery approach.', true),
  (3022, 1, 'اعتماد منهج التسليم الذي يوصي به مكتب إدارة المشاريع لضمان التوافق مع أولويات محفظة المنظمة.', 'Adopt the delivery approach recommended by the PMO to ensure alignment with the organization''s portfolio priorities.', false),
  (3022, 2, 'مراجعة مناهج التسليم المستخدمة في مبادرات تنظيمية مماثلة لتحديد الأفضل أداءً.', 'Review delivery approaches used on similar regulatory initiatives to identify which has performed best.', false),
  (3022, 3, 'التشاور مع راعي المشروع لتحديد المنهج الأكثر توافقًا مع الأولويات الاستراتيجية للمنظمة.', 'Consult with the project sponsor to determine which approach best aligns with the organization''s strategic priorities.', false),
  (3023, 0, 'البحث عن أداة اختبار مؤتمتة توازن بين سرعة التسليم وقدرات الامتثال واقتراحها.', 'Research and propose an automated testing tool that balances delivery speed with compliance capabilities.', false),
  (3023, 1, 'تيسير نقاش مع المعنيين لتوضيح النتائج المنشودة وتقييم الحلول.', 'Facilitate a discussion with stakeholders to clarify the intended outcomes and evaluate solutions.', true),
  (3023, 2, 'تطبيق الأداة التي أوصى بها مدير تقنية المعلومات.', 'Implement the IT Director''s recommended tool.', false),
  (3023, 3, 'رفض اقتراح مدير تقنية المعلومات والطلب من المعنيين اقتراح بدائل.', 'Decline the IT Director''s suggestion and ask stakeholders to propose alternatives.', false),
  (3024, 0, 'تخزين جميع الوثائق الفنية وأدلة العمليات في مستودع مركزي متاح للفريق القادم.', 'Store all technical documentation and process guides in a centralized repository accessible to the incoming team.', false),
  (3024, 1, 'جدولة اجتماع تسليم رسمي يعرض فيه الفريق الحالي الوثائق على الفريق القادم.', 'Schedule a formal handover meeting where the current team presents the documentation to the incoming team.', false),
  (3024, 2, 'تنظيم جلسات منظمة مع الفريق الحالي لإظهار الأحكام التقديرية والحلول الالتفافية والممارسات غير الرسمية التي طُوّرت خلال المشروع وتوثيقها.', 'Organize structured sessions with the current team to surface and document the judgment calls, workarounds, and informal practices developed during the project.', true),
  (3024, 3, 'الترتيب لبقاء أعضاء رئيسيين من الفريق الحالي متاحين للإجابة عن الأسئلة خلال الشهر الأول من المرحلة التالية.', 'Arrange for key members of the current team to remain available for questions during the first month of the next phase.', false);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (3025, 0, 'اختيار النظام الأقل تكلفة حمايةً لموازنة المشروع.', 'Select the lower-cost system to protect the project budget.', false),
  (3025, 1, 'تقييم النظامين معًا باستخدام أهداف الاستدامة والقيمة طويلة الأمد.', 'Evaluate both systems using sustainability objectives and long-term value.', true),
  (3025, 2, 'الطلب من الراعي اختيار نظام التدفئة المفضل.', 'Ask the sponsor to choose the preferred heating system.', false),
  (3025, 3, 'تأجيل القرار حتى بدء أعمال الإنشاء.', 'Delay the decision until construction begins.', false),
  (3026, 0, 'مطالبة فريق التطوير بإضافة الوظيفة المتنازع عليها لإرضاء وحدتي الأعمال قبل الإغلاق.', 'Ask the development team to add the disputed functionality to satisfy both business units before closing.', false),
  (3026, 1, 'مراجعة وثائق المتطلبات ومعايير القبول التي أُّرسيت خلال مرحلة التخطيط.', 'Review the requirements documentation and acceptance criteria established during the planning phase.', true),
  (3026, 2, 'تصعيد الخلاف إلى راعي المشروع لاتخاذ قرار نهائي.', 'Escalate the dispute to the project sponsor to make a final determination.', false),
  (3026, 3, 'الاجتماع بوحدتي الأعمال معًا لمراجعة معايير القبول الموثقة والتوصل إلى فهم مشترك.', 'Meet with both business units to review the documented acceptance criteria and reach a shared understanding.', true),
  (3026, 4, 'طلب الإغلاق الرسمي للمشروع ومعالجة الخلاف حول الميزة بوصفه تحسينًا في الإصدار التالي', 'Request formal project closure and address the feature dispute as an enhancement in the next release.', false),
  (3027, 0, 'مراجعة سجل الأعمال للتأكد من أن جميع قصص المستخدم المخصصة لهذا الإصدار قد وُضعت عليها علامة الاكتمال.', 'Review the backlog to confirm all user stories assigned to this release have been marked complete.', false),
  (3027, 1, 'مقارنة التسليمات المكتملة بتعريف المنجز الخاص بالفريق.', 'Compare the completed deliverables against the team''s definition of done.', true),
  (3027, 2, 'جدولة مراجعة مع المعنيين لتقييم ما إذا كان الإصدار يلبي توقعاتهم.', 'Schedule a review with stakeholders to evaluate whether the release meets their expectations.', false),
  (3027, 3, 'تقييم ما إذا كان الإصدار قد حقق قيمة الأعمال المنشودة منه مقارنةً بدراسة الأعمال الأصلية.', 'Assess whether the release has achieved its intended business value against the original business case.', false),
  (3028, 0, 'تحليل شواغل كل مجموعة من المعنيين وترتيب التوقعات وفق السلطة التنظيمية.', 'Analyze each stakeholder group''s concerns and rank expectations according to organizational authority.', false),
  (3028, 1, 'عرض دراسة أعمال مفصلة على جميع المعنيين تُظهر منافع المبادرة لتأمين توافقهم.', 'Present a detailed business case to all stakeholders demonstrating the initiative''s benefits to secure their alignment.', false),
  (3028, 2, 'جدولة جلسات منظمة مع راعي المشروع ومجموعات المعنيين الرئيسية لمناقشة أهداف المبادرة.', 'Schedule structured sessions with the project sponsor and key stakeholder groups to discuss the initiative''s objectives.', true),
  (3028, 3, 'تحديد التوقعات المشتركة بين معظم مجموعات المعنيين وتركيز جهود التواصل على ترسيخ تلك الأولويات.', 'Identify expectations shared across most stakeholder groups and focus communication efforts on reinforcing those priorities.', false),
  (3029, 0, 'تقييم أثر عدم التوافق على الخط المرجعي للمشروع وتقديم طلب تغيير رسمي إذا لزمت تحديثات.', 'Assess the impact of the incompatibility on the project baseline and submit a formal change request if updates are required.', true),
  (3029, 1, 'مواصلة التركيب كما هو مخطط وتوثيق عدم التوافق اللكهربائي بوصفه بندًا من بنود الدروس المستفادة.', 'Continue the installation as planned and document the electrical incompatibility as a lessons learned item.', false),
  (3029, 2, 'تطبيق التخطيط التدرجي ⁦(Rolling Wave Planning)⁩ لتحسين نهج التركيب تدريجيًا كلما توفر مزيد من المعلومات.', 'Apply rolling wave planning to progressively refine the installation approach as more information becomes available.', false),
  (3029, 3, 'زيادة احتياطيات الطوارئ في المشروع لتغطية تكاليف إعادة تنفيذ الأعمال المحتملة الناجمة عن عدم التوافق.', 'Increase the project''s contingency reserves to cover potential rework costs from the incompatibility.', false),
  (3030, 0, 'حساب الوفورات في التكلفة الناتجة عن تجنب انتهاكات الخصوصية المحتملة ومشاركة التحليل مع الفريق.', 'Calculate the cost savings from avoiding potential privacy violations and share the analysis with the team.', false),
  (3030, 1, 'تطبيق أدوات مؤتمتة لتتبع الامتثال لتقليل الوقت الذي يقضيه الفريق في التوثيق.', 'Implement automated compliance tracking tools to minimize the time the team spends on documentation.', false),
  (3030, 2, 'توعية الفريق والمقاولين بالغرض من متطلبات الخصوصية لبناء الفهم والتوافق.', 'Educate the team and contractors on the purpose of the privacy requirements to build understanding and alignment.', true),
  (3030, 3, 'تحديد سبل لإدماج أنشطة الامتثال في مسارات العمل القائمة لتقليل الإرباك المتصوَّّر.', 'Identify ways to integrate the compliance activities into existing workflows to reduce perceived disruption.', false),
  (3031, 0, 'إضافة وقت احتياطي إضافي إلى الجدول الزمني للمشروع لمراعاة التعقيد واحتمالات إعادة تنفيذ الأعمال.', 'Build additional buffer time into the project schedule to account for the complexity and potential rework.', false),
  (3031, 1, 'إشراك خبراء متخصصين في الأمن السيبراني وتكامل الأنظمة للمساعدة على إظهار المجاهيل وتحديد الترابطات.', 'Engage cybersecurity and systems integration subject matter experts to help surface unknowns and define interdependencies.', true),
  (3031, 2, 'الاستعانة بمستشار خارجي في إدارة المشاريع لتوفير الإشراف وإبقاء عملية التخطيط على مسارها.', 'Bring in an external project management consultant to provide oversight and keep the planning process on track.', false),
  (3031, 3, 'إجراء استطلاع للمعنيين لجمع مدخلات المتطلبات قبل محاولة رسم خريطة الترابطات بين الأنظمة.', 'Conduct a stakeholder survey to gather requirements input before attempting to map system interdependencies.', false),
  (3032, 0, 'ترتيب أولويات جهود الامتثال بناءً على الأهمية التنظيمية لكل مجال وتأثيره المحتمل في اعتماد التجربة.', 'Prioritize compliance efforts based on each area''s regulatory significance and potential impact on trial approval.', true),
  (3032, 1, 'تصنيف جميع متطلبات الامتثال وفق الغرامات والعقوبات المحددة المرتبطة بكل انتهاك.', 'Categorize all compliance requirements by the specific fines and penalties associated with each violation.', false),
  (3032, 2, 'عقد ورشة عمل عن الامتثال مع فريق الشؤون التنظيمية ومدققين خارجيين لتبادل المعرفة عن الانتهاكات السابقة.', 'Hold a compliance workshop with the regulatory affairs team and external auditors to share knowledge about past violations.', false),
  (3032, 3, 'توجيه غالبية موازنة الامتثال نحو بروتوكولات سلامة المرضى لأنها تحمل أعلى العقوبات.', 'Direct the majority of the compliance budget toward patient safety protocols since they carry the highest penalties.', false),
  (3033, 0, 'إعداد خطة إدارة المخاطر الشاملة كما طُلب لإظهار الانضباط في الحوكمة.', 'Develop the comprehensive risk management plan as requested to demonstrate governance discipline.', false),
  (3033, 1, 'إنشاء سجل مخاطر مفصل يوثّق جميع المخاطر الممكنة بغض النظر عن حجم المشروع.', 'Create a detailed risk register documenting all possible risks regardless of the project''s scale.', false),
  (3033, 2, 'طلب وقت وموارد إضافية لإعداد الوثائق التي طلبها رئيس القسم على الوجه الصحيح.', 'Request additional time and resources to properly prepare the documentation the department head has requested.', false),
  (3033, 3, 'التوضيح لرئيس القسم أن حجم المشروع لا يستوجب خطة مخاطر رسمية، واقتراح نهج مبسّط.', 'Explain to the department head that the project''s scale does not warrant a formal risk plan and propose a simplified approach.', true),
  (3034, 0, 'الطلب من راعي المشروع تأكيد التزامات المنظمة بالاستدامة أمام رؤساء الأقسام المعارضين.', 'Ask the project sponsor to reinforce the organization''s sustainability commitments to the resistant department heads.', false),
  (3034, 1, 'عرض بيانات تُظهر انخفاض تكاليف التشغيل، وتقليص المخاطر التنظيمية، والعائد على الاستثمار طويل الأمد للأنظمة الموفرة للطاقة.', 'Present data showing reduced operating costs, regulatory risk reduction, and long-term return on investment for the energy-efficient systems.', true),
  (3034, 2, 'جدولة ورشة عمل إلزامية عن الاستدامة لجميع رؤساء الأقسام لبناء الوعي بالأهداف البيئية للمنظمة.', 'Schedule a mandatory sustainability workshop for all department heads to build awareness of the organization''s environmental goals.', false),
  (3034, 3, 'مراجعة ميثاق المشروع ودراسة الأعمال لتحديد متطلبات الاستدامة المعتمدة رسميًا بالفعل.', 'Review the project charter and business case to identify the sustainability requirements that have already been formally approved.', false),
  (3035, 0, 'عقد اجتماعات وقوف يومية (Stand-up) لإبقاء جميع أعضاء الفريق على توافق.', 'Conduct daily stand-up meetings to keep all team members aligned', false),
  (3035, 1, 'إنشاء قنوات تواصل جماعية غير رسمية لتمكين تبادل المعلومات السريع عبر جميع الفرق.', 'Create informal group communication channels to enable rapid information sharing across all teams.', false),
  (3035, 2, 'استخدام أدوات الترجمة بالذكاء الاصطناعي لتحويل جميع اتصالات المشروع تلقائيًا إلى اللغة الأساسية لكل عضو في الفريق.', 'Use AI translation tools to automatically convert all project communications into each team member''s primary language.', false),
  (3035, 3, 'تقديم تحديثات المشروع بلغات متعددة وجدولة جلسات افتراضية منظمة تراعي اختلاف المناطق الزمنية لجمع المدخلات من جميع الفرق.', 'Provide project updates in multiple languages and schedule structured virtual sessions that accommodate different time zones to collect input from all teams.', true),
  (3036, 0, 'عقد اجتماعات حالة أسبوعية مع المقاولين لإبلاغ معايير العلامة وجمع التغذية الراجعة عن التقدم.', 'Hold weekly status meetings with contractors to communicate brand standards and collect feedback on progress.', false),
  (3036, 1, 'جدولة لقاءات دورية مع الرئيس التنفيذي للفندق لضمان التوافق التنفيذي وتيسير القرارات رفيعة المستوى.', 'Schedule regular check-ins with the hotel''s CEO to ensure executive alignment and facilitate high-level decision-making.', false),
  (3036, 2, 'المقارنة المنتظمة لقرارات التصميم ومخرجات المقاولين والتسليمات برؤية العلامة ومعاييرها الموثقة عند بدء المشروع.', 'Regularly compare design decisions, contractor outputs, and deliverables against the brand vision and standards documented during project initiation.', true),
  (3036, 3, 'تحديث ميثاق المشروع كلما تطورت التفضيلات التصميمية لضمان أن تعكس الوثائق التوجه الحالي للعلامة.', 'Update the project charter whenever design preferences evolve to ensure documentation reflects the current brand direction.', false),
  (3037, 0, 'منح جميع المعنيين حق الوصول إلى سجلات العيوب الخام وبيانات التكلفة ليحلل كلٌّّ ما يحتاجه باستقلالية.', 'Grant all stakeholders access to the raw defect logs and cost data so each can analyze what they need independently.', false),
  (3037, 1, 'تبسيط جميع التقارير إلى ملخصات عامة وتوفير البيانات الخام عند الطلب الرسمي فقط.', 'Simplify all reports to high-level summaries and provide raw data only upon formal request.', false),
  (3037, 2, 'إعداد تقارير منفصلة مصممة وفق الاحتياجات المعلوماتية المعلنة لكل معني.', 'Develop separate reports tailored to each stakeholder''s stated information needs.', true),
  (3037, 3, 'التوضيح بأن بيانات المشروع الخام تُعالَج لتصبح معلومات محللة وتُنسّ ق في تقارير مصممة وفق دور كل معني واحتياجاته المعلوماتية.', 'Explain that raw project data is processed into analyzed information and formatted into reports tailored to each stakeholder''s role and information needs.', false),
  (3038, 0, 'إشراك خبراء متخصصين لتحليل المخرجات غير المتسقة والمساعدة على تحديد مصدرها.', 'Engage subject matter experts to analyze the inconsistent outputs and help identify their source.', true),
  (3038, 1, 'التحقق من أن الفريق اتبع إجراءات إدارة التهيئة السليمة أثناء التطوير.', 'Verify that the team followed proper configuration management procedures during development.', false),
  (3038, 2, 'التكليف بإعادة بناء المكونات المتأثرة بواسطة فريق تطوير أكثر خبرة.', 'Commission a rebuild of the affected components using a more experienced development team.', false),
  (3038, 3, 'استطلاع آراء المستخدمين النهائيين لجمع ملاحظاتهم عن المخرجات غير المتسقة.', 'Survey end users to gather their observations about the inconsistent outputs.', false),
  (3039, 0, 'الانتظار حتى مرحلة تنفيذ المشروع قبل مناقشة متطلبات الاستدامة.', 'Wait until project execution before discussing sustainability requirements.', false),
  (3039, 1, 'استبعاد الاستدامة لأن الراعي لم يطلبها تحديدًا.', 'Exclude sustainability because it was not specifically requested by the sponsor.', false),
  (3039, 2, 'التوصية بإدماج أهداف الاستدامة في وثائق تخطيط المشروع ومناقشتها مع المعنيين.', 'Recommend incorporating sustainability objectives into the project''s planning documents and discussing them with stakeholders.', true),
  (3039, 3, 'التركيز على تسليم النطاق المعتمد فقط لأن الاستدامة خارج مسؤولية مدير المشروع.', 'Focus only on delivering the approved scope because sustainability is outside the project manager''s responsibility.', false),
  (3040, 0, 'مراجعة التسليمات النهائية للمراحل السابقة لفهم ما جرى بناؤه.', 'Review the final deliverables from the earlier phases to understand what was built.', false),
  (3040, 1, 'مراجعة مستودع وثائق البرنامج بما يشمل تقارير المراحل وسجلات القرارات والتقييمات الرجعية.', 'Review the program''s documentation repository including phase reports, decision logs, and retrospectives.', true),
  (3040, 2, 'ترتيب اجتماعات مع أعضاء الفريق الذين عملوا في المراحل السابقة لمناقشة تجاربهم مباشرة.', 'Arrange meetings with team members who worked on the earlier phases to discuss their experiences directly.', false),
  (3040, 3, 'تحليل الفروق بين خطة البرنامج الأصلية وما سُلّم فعليًا في كل مرحلة.', 'Analyze the differences between the original program plan and what was actually delivered in each phase.', false),
  (3041, 0, 'إسناد العمل إلى كتّاب فنيين متمرسين يستطيعون إنتاج التقارير نفسها في ساعات أقل.', 'Assign experienced technical writers who can produce the same reports in fewer hours.', true),
  (3041, 1, 'إسناد كتّاب فنيين إضافيين لتوزيع العمل على فريق أكبر.', 'Assign additional technical writers to distribute the work across a larger team.', false),
  (3041, 2, 'تجزئة التقارير إلى أقسام أصغر لإنتاج تقدير أكثر دقة.', 'Break the reports into smaller sections to produce a more accurate estimate.', false),
  (3041, 3, 'تطبيق أدوات أتمتة المستندات للتعامل مع مهام التنسيق والقوالب.', 'Implement document automation tools to handle formatting and templating tasks.', false),
  (3042, 0, 'أن للمشروع مواصفات فنية محددة جيدًا يستطيع الفريق تنفيذها في تسلسل منظم.', 'The project has well-defined technical specifications the team can implement in a structured sequence.', false),
  (3042, 1, 'أن تسليمات المشروع ستكون متسقة وقابلة للتكرار، ما يجعل التكرار سهل التخطيط.', 'The project deliverables will be consistent and repeatable, making iteration straightforward to plan.', false),
  (3042, 2, 'أن تفضيلات العملاء مجهولة ولن تتضح إلا من خلال الاختبار والتغذية الراجعة المستمرين، ما يتطلب من الفريق التكيف بناءً على ما يُتعلَّّم.', 'Customer preferences are unknown and will only emerge through continuous testing and feedback, requiring the team to adapt based on what is learned.', true),
  (3042, 3, 'أن المشروع يتطلب ضوابط صارمة للتكلفة والجدول الزمني صُمم الإطار التكيفي لفرضها.', 'The project requires strict cost and schedule controls that an adaptive framework is designed to enforce.', false),
  (3043, 0, 'بدء إعادة تنفيذ الأعمال فورًا كما يطلب الراعي للحفاظ على العلاقة مع العميل وتفادي الغرامة.', 'Begin rework immediately as the sponsor requests to maintain the client relationship and avoid the penalty.', false),
  (3043, 1, 'تيسير جلسة مع العميل وفريق التطوير لتوضيح القواعد الحسابية غير الموثقة وتحديث وثائق النطاق رسميًا.', 'Facilitate a session with the client and development team to clarify the undocumented calculation rules and formally update the scope documentation.', true),
  (3043, 2, 'تصعيد النزاع إلى مدير البرنامج لأن الخلاف بين العميل وفريق التطوير يتجاوز صلاحية مدير المشروع.', 'Escalate the dispute to the program manager since the disagreement between the client and development team is beyond the project manager''s authority.', false),
  (3043, 3, 'الطلب من راعي المشروع التفاوض مباشرةً مع العميل على القواعد الحسابية المتنازع عليها لحل المسألة على المستوى التنفيذي.', 'Ask the project sponsor to negotiate directly with the client on the disputed calculation rules to resolve the issue at the executive level.', false),
  (3044, 0, 'مواصلة تتبع المنشورات المتخصصة والمصادر الإخبارية لرصد أي مستجدات بشأن القيود المقترحة.', 'Continue tracking trade publications and news sources for further developments on the proposed restrictions.', false),
  (3044, 1, 'الاتصال بالمورّد مباشرةً لطلب إنذار مسبق في حال اعتماد قيود التصدير.', 'Contact the supplier directly to request advance warning if the export restrictions are approved.', false),
  (3044, 2, 'مراقبة مستويات مخزون الحاويات وتنبيه المعنيين إذا انخفض المخزون دون حدود الأمان.', 'Monitor container inventory levels and alert stakeholders if stock falls below safety thresholds.', false),
  (3044, 3, 'مراجعة خطة إدارة المخاطر الخاصة بهذه المخاطرة وإبلاغ المعنيين إذا دلّت الظروف على تصاعدها.', 'Review the risk management plan for this risk and report to stakeholders if conditions indicate the risk is escalating.', true),
  (3045, 0, 'اتباع توجيه راعي المشروع وتصنيف التكاليف بالطريقة التي تؤمّن أسرع اعتماد للموازنة.', 'Follow the project sponsor''s direction and classify the costs in the way that secures the fastest budget approval.', false),
  (3045, 1, 'العمل مع مدير تقنية المعلومات ومدير العمليات والمراقب المالي على تصنيف التكاليف وفق معايير المحاسبة المعمول بها.', 'Work with the IT director, operations director, and controller to classify costs according to applicable accounting standards.', true),
  (3045, 2, 'تقسيم التكاليف بين الفئتين الرأسمالية والتشغيلية لمنح كل مدير رضًا جزئيًا.', 'Divide the costs between capital and operational categories to give each director partial satisfaction.', false),
  (3045, 3, 'إرجاء قرار التصنيف إلى مرحلة لاحقة من المشروع عندما تصبح التكاليف الفعلية أوضح تحديدًا.', 'Defer the classification decision until later in the project when actual costs are more clearly defined.', false),
  (3046, 0, 'تعديل الخط المرجعي لموازنة المشروع بما يستوعب ارتفاع تكاليف المواد لهذا المكون.', 'Revise the project budget baseline to accommodate the higher material costs for this component.', false),
  (3046, 1, 'تقليص نطاق المكون لإعادة استهلاك المواد إلى حدود المخصص الأصلي.', 'Reduce the scope of the component to bring material consumption back within the original allocation.', false),
  (3046, 2, 'جدولة اجتماع مع فريق المكون للسؤال عن سبب ارتفاع تكاليف المواد عمّا هو مخطط.', 'Schedule a meeting with the component team to ask why material costs are higher than planned.', false),
  (3046, 3, 'تحليل الموقف لتحديد السبب الجذري لفرط الاستهلاك قبل تقرير الإجراء التصحيحي.', 'Analyze the situation to identify the root cause of the overconsumption before deciding on corrective action.', true),
  (3047, 0, 'الاجتماع بكل مطوّر على حدة لفهم منطقه الفني قبل عقد أي نقاش مشترك.', 'Meet separately with each developer to understand their technical reasoning before holding any joint discussion.', false),
  (3047, 1, 'بحث مزايا كل إطار عمل وتقديم توصية للكسر الجمود.', 'Research the merits of each framework and present a recommendation to break the deadlock.', false),
  (3047, 2, 'جمع المطوّرَين معًا للعمل على المفاضلات والتوصل إلى قرار مقبول للطرفين.', 'Bring both developers together to work through the trade-offs and reach a mutually acceptable decision.', true),
  (3047, 3, 'إضافة قرار إطار العمل إلى التقييم الرجعي للسبرينت التالي مع الفريق كاملًا.', 'Add the framework decision to the next sprint retrospective with the full team.', false),
  (3048, 0, 'تقييم القدرة والخبرة الحاليتين لإدارة تقنية المعلومات مقابل المتطلبات المحددة للمشروع.', 'Evaluate the IT department''s current capacity and expertise against the project''s specific requirements.', true),
  (3048, 1, 'الاستعانة بوكالة توظيف خارجية لتحديد اختصاصيين ذوي خبرة في بنية بيانات الرعاية الصحية.', 'Engage an external staffing agency to identify specialists with healthcare data architecture experience.', false),
  (3048, 2, 'إنشاء خطة موارد مفصلة تسرد جميع الأدوار الفنية والمهارات المطلوبة والساعات المقدرة.', 'Create a detailed resource plan listing all technical roles, required skills, and estimated hours.', false),
  (3048, 3, 'اقتراح نموذج توظيف هجخين يجمع بين الموظفين الداخليين والمتعاقدين الخارجيين لإرضاء المعنيَين معًا.', 'Propose a hybrid staffing model that combines internal staff with external contractors to satisfy both stakeholders.', false),
  (3049, 0, 'تنظيم ورشة عمل للخبراء المتخصصين لجمع المعرفة المؤسسية عن بنى معالجة البيانات وتحديد الحلول المحتملة.', 'Organize an SME workshop to gather institutional knowledge about data processing architectures and identify potential solutions.', false),
  (3049, 1, 'التصريح بتجربة استكشافية تقنية (Technical Spike) محددة الإطار الزمني لاستقصاء الحلول المعمارية المحتملة وتقييم جدواها قبل الالتزام بإصلاح.', 'Authorize a timeboxed technical spike to investigate potential architectural solutions and assess their feasibility before committing to a fix.', true),
  (3049, 2, 'تقديم طلب تغيير لتمديد السبرينت وتعديل الجدول الزمني للنموذج الأولي بما يستوعب الاستقصاء الفني.', 'Submit a change request to extend the sprint and adjust the prototype timeline to accommodate the technical investigation.', false),
  (3049, 3, 'إجراء دراسة جدوى شاملة لجميع بنى معالجة البيانات المتاحة لتحديد الحل الأمثل.', 'Perform a comprehensive feasibility study of all available data processing architectures to identify the optimal solution.', false),
  (3050, 0, 'ضمان حصول جميع أعضاء الفريق على منصات التعاون اللازمة والتدريب عليها للعمل بفعالية كفريق موزع.', 'Ensure all team members have access to and training on the collaboration platforms needed to work effectively as a distributed team.', true),
  (3050, 1, 'قصر الفريق على المرشحخين في المنطقة نفسها لتقليل مخاطر الأداء الناجمة عن التشتت الجغرافي.', 'Limit the team to candidates in the same region to reduce the performance risks of geographic dispersion.', false),
  (3050, 2, 'طلب استثناء في الموازنة من الراعي لتمويل اجتماعات حضورية دورية للفريق الموزع.', 'Request a budget exception from the sponsor to fund periodic in-person meetings for the distributed team.', false),
  (3050, 3, 'إعادة هيكلة حزم العمل بحيث يمكن إكمال كل منها باستقلالية في موقع جغرافي واحد.', 'Restructure the work packages so each can be completed independently by a single geographic location.', false),
  (3051, 0, 'اعتماد التسليم فورًا لتأمين دفعة المَعلم وجدولة اجتماع متابعة لمعالجة مخاوف العميل.', 'Approve sign-off immediately to secure the milestone payment and schedule a follow-up meeting to address the client''s concerns.', false),
  (3051, 1, 'رفض طلب العميل لأن الوحدة سُلّمت وفقًا للمواصفات المعتمدة.', 'Reject the client''s request since the module was delivered in accordance with the approved specifications.', false),
  (3051, 2, 'تيسير مراجعة لمعايير القبول مع العميل ومعالجة طلب تغيير إذا لم تكن صيغة التقارير مدرجة في النطاق الأصلي.', 'Facilitate a review of the acceptance criteria with the client and process a change request if the reporting format was not captured in the original scope.', true),
  (3051, 3, 'إعادة تكليف فريق التطوير بإعادة تنفيذ وحدة التقارير فورًا لحل مخاوف العميل.', 'Reassign the development team to rework the reporting module immediately to resolve the client''s concerns.', false),
  (3052, 0, 'نقل جميع مواد الحملة وبياناتها وقوائم جهات الاتصال إلى فريق العمليات للاستخدام المستمر.', 'Transfer all campaign materials, data, and contact lists to the operations team for ongoing use.', false),
  (3052, 1, 'توثيق أساليب التواصل المجتمعي الفعالة والتحديات وأداء قنوات التواصل في سجل الدروس المستفادة.', 'Document the effective outreach methods, challenges, and communication channel performance in a lessons learned register.', true),
  (3052, 2, 'تقديم تقرير ختامي عن الحملة إلى مجلس المدينة يبرز النجاحات ومجالات التحسين.', 'Present a final campaign report to city council highlighting successes and areas for improvement.', false),
  (3052, 3, 'أرشفة جميع وثائق المشروع في نظام إدارة المعلومات للمدينة لأغراض الامتثال.', 'Archive all project documentation in the city''s information management system for compliance purposes.', false),
  (3053, 0, 'إعداد بيان رؤية يوضح أهداف المنتج وما يميزه عن العروض المنافسة.', 'Develop a vision statement that articulates the product''s objectives and what differentiates it from competing offerings.', true),
  (3053, 1, 'بناء نموذج أولي مبكر لعرض مفهوم المنتج وتوليد توافق الفريق حول التوجه التصميمي.', 'Build an early prototype to demonstrate the product concept and generate team alignment around the design direction.', false),
  (3053, 2, 'جدولة جلسات مع الفريق التنفيذي لتأكيد استراتيجية المنتج قبل مشاركتها مع الفريق الأوسع.', 'Schedule sessions with the executive team to confirm product strategy before sharing it with the broader team.', false),
  (3053, 3, 'إنشاء مجموعة عمل متعددة الوظائف لمنح جميع أعضاء الفريق مدخلات متساوية في تحديد أهداف المشروع.', 'Establish a cross-functional working group to give all team members equal input into defining project goals.', false),
  (3054, 0, 'البحث في معايير الحوكمة المنشورة من الهيئات التنظيمية الدوائية.', 'Research governance standards published by pharmaceutical regulatory bodies.', false),
  (3054, 1, 'مراجعة الأدبيات الأكاديمية عن أفضل ممارسات الحوكمة في القطاعات الخاضعة للتنظيم.', 'Review academic literature on governance best practices in regulated industries.', false),
  (3054, 2, 'مراجعة أطر الحوكمة والسياسات والقوالب المستخدمة في برامج تطوير الأدوية السابقة.', 'Review governance frameworks, policies, and templates used in previous drug development programs.', true),
  (3054, 3, 'تقييم منصات برمجيات إدارة المشاريع القادرة على دعم تتبع الحوكمة وإعداد تقاريرها.', 'Evaluate project management software platforms that can support governance tracking and reporting.', false),
  (3055, 0, 'التحقق من امتثال المواد المولَّدة بالذكاء الاصطناعي لمتطلبات حقوق النشر والترخيص والمللكية قبل استخدامها.', 'Verify that the AI-generated material complies with copyright, licensing, and ownership requirements before using it.', true),
  (3055, 1, 'استبدال معلومات من عروض الشركة السابقة بالمواد المولَّدة بالذكاء الاصطناعي.', 'Replace the AI-generated material with information from previous company proposals.', false),
  (3055, 2, 'تقديم العرض لأن الأعمال المولَّدة بالذكاء الاصطناعي غير محمية بحقوق النشر.', 'Submit the proposal because AI-generated work is not protected by copyright.', false),
  (3055, 3, 'إزالة أي إشارات تدل على استخدام الذكاء الاصطناعي في إعداد العرض.', 'Remove any references indicating AI was used to create the proposal.', false),
  (3056, 0, 'تحليل تباينات التكلفة لتحديد السبب الجذري قبل التواصل مع العميل.', 'Analyze the cost variances to identify the root cause before communicating with the client.', false),
  (3056, 1, 'تقديم طلب تغيير عبر الحوكمة لتعديل الخط المرجعي للموازنة بما يعكس الإنفاق الحالي.', 'Submit a change request through governance to revise the budget baseline to reflect current spending.', true),
  (3056, 2, 'الاجتماع بمدير العمليات لدى العميل للإقرار بالمخاوف المعلنة.', 'Meet with the client''s operations director to acknowledge the stated concerns.', false),
  (3056, 3, 'تحديث سجل المخاطر بإدراج تجاوز التكلفة وشاغل الجدول الزمني بوصفهما مخاطر محددة حديثًا.', 'Update the risk register with the cost overrun and schedule concern as newly identified risks.', false),
  (3057, 0, 'قبول التوصية لأن الوفاء بالتاريخ التعاقدي هو الأولوية القصوى للمشروع.', 'Accept the recommendation because meeting the contractual date is the project''s highest priority.', false),
  (3057, 1, 'رفع التوصية إلى الراعي لاعتمادها فورًا.', 'Submit the recommendation to the sponsor for immediate approval.', false),
  (3057, 2, 'مراجعة التوصية للتأكد من استمرار استيفاء متطلبات الجودة والسلامة قبل تغيير الجدول الزمني.', 'Review the recommendation to ensure quality and safety requirements continue to be satisfied before changing the schedule.', true),
  (3057, 3, 'الطلب من مدير الجودة تحديد ما إذا كانت عمليات الفحص لا تزال ضرورية.', 'Ask the quality manager to determine whether the inspections are still necessary.', false),
  (3058, 0, 'إعداد إطار شامل لتقييم المخاطر لتقييم جميع المخاطر المحتملة واحتماليتها.', 'Develop a comprehensive risk assessment framework to evaluate all potential risks and their likelihood.', false),
  (3058, 1, 'مقابلة أعضاء الفريق الذين عملوا في الترحيل السابق لفهم ما حدث من أخطاء.', 'Interview team members who worked on the previous migration to understand what went wrong.', false),
  (3058, 2, 'إنشاء مصفوفة مخاطر تربط متطلبات الترحيل الحالية بالتسليمات لتحديد نقاط الإخفاق المحتملة.', 'Create a risk matrix that maps current migration requirements to deliverables to identify potential failure points.', false),
  (3058, 3, 'مراجعة سجلات الترحيل السابق ووثائقه لتحديد الأنماط والأسباب الجذرية التي أدت إلى مشكلات سلامة البيانات.', 'Review records and documentation from the previous migration to identify the patterns and root causes that led to the data integrity issues.', true),
  (3059, 0, 'توثيق القائمة الكاملة لميزات أداة التسويق ومعايير القبول في مواصفات متطلبات رسمية.', 'Document the full list of marketing tool features and acceptance criteria in a formal requirements specification.', false),
  (3059, 1, 'تيسير ورشة عمل مع مالك المنتج وفريق التطوير لبناء سجل أعمال المنتج الأولي وتحديد معايير القبول.', 'Facilitate a workshop with the product owner and development team to build the initial product backlog and define acceptance criteria.', true),
  (3059, 2, 'إنشاء بوابة تعاون يستطيع فريق التسويق عبرها تقديم طلبات الميزات كلما حددها.', 'Set up a collaboration portal where the marketing team can submit feature requests as they identify them.', false),
  (3059, 3, 'جدولة جلسات استكشاف مع فريق التسويق لتحديد جميع الميزات الإلزامية قبل بدء التطوير.', 'Schedule discovery sessions with the marketing team to identify all mandatory features before development begins.', false),
  (3060, 0, 'مراجعة مصفوفة مشاركة المعنيين لمقارنة مستويات المشاركة الحالية بالمستويات المستهدفة المخططة.', 'Review the stakeholder engagement matrix to compare current engagement levels against planned targets.', false),
  (3060, 1, 'تحليل سجل المخاطر وسجل الإشكالات لتحديد الشواغل الموثقة المتعلقة بالمعنيين.', 'Analyze the risk register and issue log to identify documented stakeholder-related concerns.', false),
  (3060, 2, 'إجراء مقابلات أو لقاءات موجهة مع المعنيين الرئيسيين لفهم التزامهم الحالي وأي تحولات في أولوياتهم.', 'Conduct interviews or targeted check-ins with key stakeholders to understand their current commitment and any shifts in their priorities.', true),
  (3060, 3, 'تحديث خطة اتصالات المعنيين لضمان بقاء وتيرة التواصل وقنواته ملائمة.', 'Update the stakeholder communications plan to ensure outreach frequency and channels remain appropriate.', false),
  (3061, 0, 'استخدام بيانات أداء التكلفة والتنبؤ لتحديد ما إذا كان المشروع لا يزال ضمن حدود تفاوت الموازنة، وبدء طلب تغيير إذا كانت الاحتياطيات غير كافية.', 'Use cost performance data and forecasting to determine whether the project remains within budget tolerance and initiate a change request if reserves are insufficient.', true),
  (3061, 1, 'مراجعة هيكل تحليل المخاطر لتحديد ما إذا كان تجاوز الموازنة يؤهَّّل بوصفه مخاطرة رسمية تتطلب استجابة.', 'Review the risk breakdown structure to determine whether a budget overrun qualifies as a formal risk requiring a response.', false),
  (3061, 2, 'إجراء تحليل حساسية لتحديد أنشطة المشروع المتبقية التي تنطوي على أكبر قدر من عدم التيقن في التكلفة.', 'Conduct a sensitivity analysis to identify which remaining project activities pose the greatest cost uncertainty.', false),
  (3061, 3, 'تشغيل محاكاة مونت كارلو لنمذجة التوزيع الاحتمالي لتكاليف المشروع النهائية وكفاية الاحتياطي.', 'Run a Monte Carlo simulation to model the probability distribution of final project costs and reserve adequacy.', false),
  (3062, 0, 'وضع أهداف ذكية (SMART) مرتبطة بمستهدفات خفض العيوب لكل فريق تطوير.', 'Set SMART objectives tied to defect reduction targets for each development team.', false),
  (3062, 1, 'ترسيخ دورة «خطِّط – نفِّذ – افحص – صحِّلح» (Plan-Do-Check-Act) في مسار عمل التطوير لتشخيص تحسينات العمليات واختبارها والتحقق منها وترسيخها مؤسسيًا على نحو منهجي.', 'Embed the plan-do-check-act cycle into the development workflow to systematically diagnose, test, verify, and institutionalize process improvements.', true),
  (3062, 2, 'إجراء مقارنة معيارية لمعدلات عيوب الفريق مع معايير القطاع لتحديد مواضع تركيز جهود التحسين.', 'Benchmark the team''s defect rates against industry standards to identify where improvement efforts should be focused.', false),
  (3062, 3, 'تطبيق تحليل السبب الجذري كلما حدث ارتفاع مفاجئ في العيوب لمنع تكرار المشكلات نفسها.', 'Apply root cause analysis whenever a defect spike occurs to prevent the same problems from recurring.', false),
  (3063, 0, 'إرساء عملية رسمية للتحكم في التغيير لإدارة كيفية إدماج الاستجابات المعتمدة للمخاطر في خطة المشروع.', 'Establish a formal change control process to manage how approved risk responses are incorporated into the project plan.', false),
  (3063, 1, 'إعداد تقدير ثلاثي النقاط للجدول الزمني للمشروع لمراعاة عدم التيقن المرتبط بالمخاطر المحددة.', 'Develop a three-point estimate for the project schedule to account for uncertainty associated with the identified risks.', false),
  (3063, 2, 'إنشاء عمليات مستمرة لتحديد المخاطر وتقييمها ومراقبتها والاستجابة لها باستمرار طوال المشروع.', 'Create ongoing processes to continuously identify, assess, monitor, and respond to risks throughout the project.', true),
  (3063, 3, 'تصميم بروتوكول لاستمرارية الأعمال لضمان استمرار عمليات المشروع في حال تحقق مخاطرة كبرى.', 'Design a business continuity protocol to ensure project operations can continue if a major risk materializes.', false),
  (3064, 0, 'تحليل المنافع المتوقعة من تبنّي الأداة مقابل الإرباك المحتمل الناجم عن إدخال تغيير في منتصف المشروع.', 'Analyze the expected benefits of adopting the tool against the potential disruption of introducing a change mid-project.', true),
  (3064, 1, 'إعداد خطة تكامل لإدماج الأداة في مسار عمل التطوير لدى الفريق.', 'Develop an integration plan to incorporate the tool into the team''s development workflow.', false),
  (3064, 2, 'توجيه فريق التطوير للبدء باستخدام الأداة فورًا لاقتناص تحسينات الجودة.', 'Instruct the development team to begin using the tool immediately to capture the quality improvements.', false),
  (3064, 3, 'إضافة الأداة إلى المتطلبات الفنية للمشروع لإدراجها رسميًا في التسليم.', 'Add the tool to the project''s technical requirements to formally include it in delivery.', false),
  (3065, 0, 'الفريق يكمل العمل باستمرار أسرع مما هو مخطط، وهو على المسار الصحيح لإنهاء السبرينت قبل الموعد المقرر.', 'The team is consistently completing work faster than planned and is on track to finish the sprint ahead of schedule.', true),
  (3065, 1, 'الفريق متأخر عن الجدول الزمني، وينبغي أن يضيف موارد إضافية فورًا لإكمال العمل المتبقي.', 'The team is behind schedule and should immediately add additional resources to complete the remaining work.', false),
  (3065, 2, 'ينبغي للفريق تمديد السبرينت لأن مخطط الإنجاز التنازلي يُظهر أنه لن يكمل العمل الملتزم به.', 'The team should extend the sprint because the burndown chart shows they will not complete the committed work.', false),
  (3065, 3, 'ينبغي للفريق زيادة نطاق السبرينت لأنه أكمل العمل أسرع من المتوقع.', 'The team should increase the sprint scope because they completed work faster than expected.', false),
  (3066, 0, 'إشراك جميع المعنيين ذوي الصلة، بمن فيهم قسم الأشعة، في عملية جمع المتطلبات والتخطيط.', 'Involved all relevant stakeholders, including the radiology department, in the requirements gathering and planning process.', true),
  (3066, 1, 'إعداد خطة شاملة لإدارة التغيير لمعالجة أي متطلبات تُحدَّد بعد التخطيط.', 'Developed a comprehensive change management plan to process any requirements identified after planning.', false),
  (3066, 2, 'التماس استشارة الخبراء من مستشاري تقنية المعلومات في الرعاية الصحية خلال مرحلة تصميم النطاق.', 'Sought expert judgment from healthcare IT consultants during the scope design phase.', false),
  (3066, 3, 'إرساء خطة اتصالات للمعنيين لإبقاء جميع الأقسام على اطلاع على تقدم التخطيط.', 'Established a stakeholder communication plan to keep all departments informed of planning progress.', false),
  (3067, 0, 'تطبيق الإرشادات السلوكية المعيارية للمنظمة لوضع توقعات لسلوك الفريق.', 'Apply the organization''s standard behavioral guidelines to set expectations for team conduct.', false),
  (3067, 1, 'طلب استبدال العضو ذي النمط التصعيدي قبل بدء المشروع.', 'Request that the member with the escalation pattern be replaced before the project begins.', false),
  (3067, 2, 'تيسير جلسة للفريق لإرساء قواعد أساسية مشتركة تحكم كيفية تواصل الفريق وطرح المخاوف واتخاذ القرارات.', 'Facilitate a team session to establish shared ground rules that govern how the team will communicate, raise concerns, and make decisions.', true),
  (3067, 3, 'عقد اجتماع انطلاق للمشروع يغطي خطة المشروع والجدول الزمني ومسؤوليات الفريق.', 'Hold a project kickoff meeting covering the project plan, timeline, and team responsibilities.', false),
  (3068, 0, 'إدماج نتائج الدروس المستفادة في أطر التخطيط والعمليات المستخدمة لمشاريع البنية التحتية القادمة.', 'Integrate the lessons learned findings into the planning frameworks and processes used for upcoming infrastructure projects.', true),
  (3068, 1, 'مراجعة نظام معلومات إدارة المشروع لفحص كيفية تعامل برامج البنية التحتية السابقة مع تحديات مماثلة.', 'Review the project management information system to examine how past infrastructure programs managed similar challenges.', false),
  (3068, 2, 'عرض نتائج الدروس المستفادة على القيادة العليا لإظهار قيمة البرنامج المكتمل.', 'Present the lessons learned findings to senior leadership to demonstrate the value of the completed program.', false),
  (3068, 3, 'جدولة مقابلات مع المعنيين في البرنامج المختتم للتثبت من دقة النتائج الموثقة.', 'Schedule interviews with stakeholders from the concluded program to validate the accuracy of the documented findings.', false),
  (3069, 0, 'الطلب من قادة الأطقم التحول إلى ساعات العمل المعتادة خلال مرحلة المسار الحرج.', 'Ask crew leads to adjust to standard business hours during the critical path phase.', false),
  (3069, 1, 'جدولة اجتماعات التنسيق اليومية خلال النافذة من 1 إلى 2 ظهرًا حين تتداخل الأطقم الثلاثة جميعًا، مع إلزام كل قائد طاقم بالحضور.', 'Schedule daily coordination meetings during the 1pm to 2pm window when all three crews overlap and require each crew lead to attend.', true),
  (3069, 2, 'تطبيق سجل رقمي يوثّق فيه كل طاقم الأعمال المكتملة ويعلّم على الإشكالات للطاقم التالي.', 'Implement a digital logbook where each crew documents completed work and flags issues for the next crew.', false),
  (3069, 3, 'عقد اجتماعات تنسيق منفصلة مع كل طاقم على حدة وتوزيع ملخصات مجمّعة على الأطقم الثلاثة.', 'Hold separate coordination meetings with each crew individually and distribute combined summaries to all three crews.', false),
  (3070, 0, 'مراجعة سجل المعنيين القائم ووثائق المشروع ذات الصلة لتحديد المعنيين المعروفين والفجوات في معلومات المعنيين.', 'Review the existing stakeholder register and related project documents to identify known stakeholders and gaps in stakeholder information.', true),
  (3070, 1, 'الاجتماع بالراعي الرئيسي للاطلاع على منظوره لأهم علاقات المعنيين.', 'Meet with the primary sponsor to get their perspective on the most important stakeholder relationships.', false),
  (3070, 2, 'تقييم خطة الاتصالات الحالية لتحديد ما إذا كانت تصل على نحو كافٍ إلى جميع مجموعات المعنيين ذات الصلة.', 'Assess the current communication plan to determine whether it adequately reaches all relevant stakeholder groups.', false),
  (3070, 3, 'التشاور مع مديري العمليات الإقليميين لفهم الأولويات المحلية وديناميكيات المعنيين في كل دولة.', 'Consult with regional operations managers to understand local priorities and stakeholder dynamics in each country.', false),
  (3071, 0, 'يجب تعديل نطاق المشروع وجدوله الزمني وموازنته رسميًا لاستيعاب الميزات الإضافية.', 'The project scope, timeline, and budget must be formally revised to accommodate the additional features.', false),
  (3071, 1, 'سيحتاج الفريق إلى طلب موارد إضافية لتسليم الميزات الجديدة إلى جانب أعمال السبرينت المخططة.', 'The team will need to request additional resources to deliver the new features alongside planned sprint work.', false),
  (3071, 2, 'يكبر سجل الأعمال، وقد تُرتَّب أولويات القصص الجديدة ضمن السبرينتات القادمة.', 'The backlog grows, and the new stories may be prioritized into upcoming sprints.', true),
  (3071, 3, 'ينبغي مراجعة احتياطي الطوارئ لتحديد ما إذا كان يغطي تكلفة الميزات الإضافية.', 'The contingency reserve should be reviewed to determine whether it covers the cost of the additional features.', false),
  (3072, 0, 'إلزام المورّدين الخارجيين بحل جميع الإشكالات العالقة قبل اعتماد الانتقال بين المرحلتين.', 'Require the third-party vendors to resolve all outstanding issues before the phase transition is approved.', false),
  (3072, 1, 'توثيق مخاطر التكامل العالقة رسميًا، وإسناد ملكية واضحة لها، وضمان تحديد نهج لإدارتها قبل التصريح بالانتقال.', 'Formally document the outstanding integration risks, assign clear ownership, and ensure a management approach is defined before authorizing the transition.', true),
  (3072, 2, 'توثيق إشكالات التكامل غير المحلولة في سجل المخاطر والمضي في الانتقال.', 'Document the unresolved integration issues in the risk register and proceed with the transition.', false),
  (3072, 3, 'تصعيد الاعتماديات غير المحلولة إلى راعي المشروع قبل التصريح بالانتقال.', 'Escalate the unresolved dependencies to the project sponsor before authorizing the transition.', false),
  (3073, 0, 'التأكد من اكتمال جميع التسليمات وقبولها رسميًا وفقًا لمعايير القبول المحددة.', 'Confirm that all deliverables have been completed and formally accepted against the defined acceptance criteria.', true),
  (3073, 1, 'استطلاع آراء فريق العمليات للتأكد من رضاهم عن الأنظمة المركّبة وجاهزيتهم لتولي الملكية.', 'Survey the operations team to confirm they are satisfied with the installed systems and ready to take ownership.', false),
  (3073, 2, 'الحصول على اعتماد راعي المشروع لأداء المشروع في الجدول الزمني والتكلفة قبل التصريح بالتسليم.', 'Obtain the project sponsor''s sign-off on the project''s schedule and cost performance before authorizing the handover.', false),
  (3073, 3, 'إجراء جولة تفقدية نهائية في المنشأة مع مدير مركز التوزيع للتحقق من التركيب.', 'Conduct a final walkthrough of the facility with the distribution center manager to verify the installation.', false),
  (3074, 0, 'الطلب من الراعي تخصيص مدرب رشيق متمرس لدعم الفريق في تبنّي دورات السبرينت.', 'Request that the sponsor allocate an experienced agile coach to support the team in adopting sprint cycles.', false),
  (3074, 1, 'تحديث خطة المشروع لإدماج دورات السبرينت وجدولة أول جلسة لتخطيط السبرينت.', 'Update the project plan to incorporate sprint cycles and schedule the first sprint planning session.', false),
  (3074, 2, 'تقييم خبرة الفريق الحالية بالأساليب الرشيقة قبل تقرير ما إذا كان سيجري إدخال دورات السبرينت.', 'Assess the team''s current experience with agile methods before deciding whether to introduce sprint cycles.', true);
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (3074, 3, 'إدخال دورات السبرينت واستخدام التقييمات الرجعية لتحديد فجوات القدرة ومعالجتها كلما ظهرت.', 'Introduce sprint cycles and use retrospectives to identify and address capability gaps as they emerge.', false),
  (3075, 0, 'الرجوع إلى ميثاق المشروع لتحديد المعنيين والأطراف المتأثرة المذكورين خلال بدء المشروع.', 'Refer to the project charter to identify stakeholders and affected parties named during project initiation.', true),
  (3075, 1, 'مراجعة خطة مشاركة المعنيين لتحديد قنوات التواصل وجهات الاتصال المحتملة.', 'Review the stakeholder engagement plan to identify communication channels and potential contacts.', false),
  (3075, 2, 'استشارة راعي المشروع لتوضيح وحدات الأعمال والأفراد الواجب إشراكهم.', 'Consult the project sponsor to clarify which business units and individuals should be included.', false),
  (3075, 3, 'مراجعة وثيقة نطاق المشروع لتحديد وظائف الأعمال الواقعة ضمن حدود المشروع.', 'Review the project scope document to determine which business functions fall within the project''s boundaries.', false),
  (3076, 0, 'توثيق الانسحاب الملحوظ بوصفه مخاطرة معنيين في سجل المخاطر.', 'Document the observed disengagement as a stakeholder risk in the risk register.', false),
  (3076, 1, 'جدولة اجتماعات متابعة فردية مع المعنيين الثلاثة للتأكد من فهمهم للمشروع ومسؤولياتهم.', 'Schedule individual follow-up meetings with the three stakeholders to confirm their understanding of the project and their responsibilities.', true),
  (3076, 2, 'إخطار راعي المشروع بأن ثلاثة معنيين رئيسيين أظهروا مشاركة غير كافية خلال اجتماع الانطلاق.', 'Notify the project sponsor that three key stakeholders showed insufficient engagement during the kickoff.', false),
  (3076, 3, 'الطلب من قادة فرق المشروع الاطمئنان على المعنيين المنسحبين خلال أنشطة المشروع القادمة.', 'Ask the project team leads to check in with the disengaged stakeholders during upcoming project activities.', false),
  (3077, 0, 'التوضيح للراعي أن المتطلبات في المنهج الرشيق تتطور تكراريًا وتشاركيًا مع تقدم المشروع، بدلًا من تحديدها بالتفصيل الكامل في البداية.', 'Explain to the sponsor that agile requirements are developed iteratively and collaboratively as the project progresses, rather than defined in full detail at the start.', true),
  (3077, 1, 'دعوة الراعي إلى حضور مراجعات السبرينت القادمة لمشاهدة كيفية تطور المتطلبات تزايديًا.', 'Invite the sponsor to attend upcoming sprint reviews to observe how requirements develop incrementally.', false),
  (3077, 2, 'التحول إلى نهج تخطيط تنبؤي لمعالجة شاغل الراعي بشأن المتطلبات غير المكتملة.', 'Switch to a predictive planning approach to address the sponsor''s concern about incomplete requirements.', false),
  (3077, 3, 'الطلب من السكرم ماستر (Scrum Master) اصطحاب الراعي في جولة على سجل أعمال السبرينت الحالي لإظهار انضباط التخطيط.', 'Ask the scrum master to walk the sponsor through the current sprint backlog to demonstrate planning rigor.', false),
  (3078, 0, 'إجراء تقييمات مهارات للموظفين الجدد.', 'Conduct skills assessments for the new hires', false),
  (3078, 1, 'إسناد مهام منخفضة التعقيد إلى الموظفين الجدد حتى يُثبتوا إلمامًا كافيًا بقاعدة الشيفرة البرمجية.', 'Assign new hires to lower-complexity tasks until they have demonstrated sufficient familiarity with the codebase.', false),
  (3078, 2, 'تنظيم ورش عمل يعرض فيها المهندسون المتمرسون بنية النظام وقاعدة الشيفرة البرمجية على الموظفين الجدد.', 'Organize workshops where experienced engineers present the system architecture and codebase to the new hires.', false),
  (3078, 3, 'هيكلة تكليفات الفريق بحيث يقترن المهندسون المتمرسون بالموظفين الجدد لتنتقل المعرفة عبر العمل المشترك.', 'Structure team assignments to pair experienced engineers with new hires so knowledge transfers through shared work.', true),
  (3079, 0, 'إجراء تحليل أثر منظم وعرض خيارات الاستعادة مع مفاضلات التكلفة والجدول الزمني والمخاطر للاعتماد الرسمي.', 'Conduct a structured impact analysis and present recovery options with cost, schedule, and risk trade-offs for formal approval.', true),
  (3079, 1, 'تحليل المسار الحرج لتحديد المهام التي يمكن تنفيذها بالتتابع السريع أو تقليص نطاقها لاستعادة الجدول الزمني.', 'Analyze the critical path to identify tasks that can be fast-tracked or reduced in scope to recover the schedule.', false),
  (3079, 2, 'طلب تفويض من الراعي لتنفيذ العمل الإضافي فورًا نظرًا إلى حدّة التباين في الجدول الزمني.', 'Request authorization from the sponsor to implement overtime immediately given the severity of the schedule variance.', false),
  (3079, 3, 'ضغط زمن أنشطة المسار الحرج باستخدام احتياطيات الموازنة القائمة لاستعادة الجدول الزمني دون تجاوز الموازنة الإجمالية.', 'Crash critical path activities using existing budget reserves to recover schedule without exceeding the total budget.', false),
  (3080, 0, 'إعداد خطط طوارئ لكل مخاطرة محددة ليستطيع الفريق الاستجابة فورًا عند تحقق أي مخاطرة.', 'Develop contingency plans for each identified risk so the team can respond immediately when any risk materializes.', false),
  (3080, 1, 'استخدام التحليل النوعي والكمي لتقييم المخاطر المحددة وترتيب أولوياتها بناءً على الاحتمالية والأثر.', 'Use qualitative and quantitative analysis to assess and prioritize the identified risks based on probability and impact.', true),
  (3080, 2, 'تعيين أصحاب مخاطر لكل مخاطرة محددة وإرساء موازنات استجابة بناءً على التكلفة المقدرة.', 'Assign risk owners to each identified risk and establish response budgets based on estimated cost.', false),
  (3080, 3, 'تحديث سجل المخاطر بالقائمة الكاملة للمخاطر المحددة وتوزيعه على جميع المعنيين للمراجعة.', 'Update the risk register with the full list of identified risks and distribute it to all stakeholders for review.', false),
  (3081, 0, 'الإصغاء بعناية إلى شواغل المطوّر والإقرار بأثر المناوبة في عمله.', 'Listen carefully to the developer''s concerns and acknowledge the impact the rotation is having on their work.', true),
  (3081, 1, 'شرح الأسباب المتعلقة بالأعمال وراء مناوبة الدعم.', 'Explain the business reasons for the support rotation', false),
  (3081, 2, 'اقتراح جدول مناوبة معدّل يقلّص ساعات الدعم للمطوّر مع الحفاظ على التغطية.', 'Propose a modified rotation schedule that reduces the developer''s support hours while maintaining coverage.', false),
  (3081, 3, 'عرض إعادة إسناد بعض مهام المطوّر الأدنى أولوية لتعويض الوقت المفقود في واجبات الدعم.', 'Offer to reassign some of the developer''s lower-priority tasks to offset the time lost to support duties.', false),
  (3082, 0, 'تيسير تقييم رجعي للفريق لإتاحة المجال للأعضاء لطرح المظالم واقتراح تغييرات في العمليات.', 'Facilitate a team retrospective to allow members to surface grievances and propose process changes.', false),
  (3082, 1, 'تحديد ما إذا كانت أساليب العمل المختلفة تسبب الاحتكاك وإرساء قواعد أساسية تعالج كيفية تفاعل الفريق.', 'Determine whether different work styles are causing friction and establish ground rules to address how the team interacts.', false),
  (3082, 2, 'جدولة اجتماع جماعي مع جميع أعضاء الفريق لمناقشة مصادر التوتر صراحةً والاتفاق على حل.', 'Schedule a group meeting with all team members to openly discuss the sources of tension and agree on a resolution.', false),
  (3082, 3, 'جدولة اجتماعات فردية مع كل عضو في الفريق لفهم منظوره لديناميكية الفريق.', 'Schedule one-on-one meetings with each team member to understand their perspective on the team dynamic.', true),
  (3083, 0, 'إسناد المهام بناءً على أقوى مهارات كل عضو حاليًا لتعظيم قدرة الفريق التسليمية الفورية.', 'Assign tasks based on each team member''s current strongest skills to maximize the team''s immediate delivery capacity.', false),
  (3083, 1, 'عقد ورش عمل دورية للفريق يعرض فيها الأعضاء مجالات خبرتهم ويتعاونون على تحديات مشتركة.', 'Hold regular team workshops where members present their areas of expertise and collaborate on shared challenges.', false),
  (3083, 2, 'تنظيم اقترانات إرشاد مهني تصل الأعضاء الأقل خبرة بزملاء متمرسين لبناء المهارات والتوافق.', 'Organize mentorship pairings that connect less experienced members with seasoned colleagues to build skills and alignment.', true),
  (3083, 3, 'إنشاء خطط تطوير فردية لكل عضو في الفريق تربط أهداف نموه بأهداف المشروع.', 'Create individual development plans for each team member that map their growth goals to the project''s objectives.', false),
  (3084, 0, 'ضمان وصول الفريق إلى الوثائق القائمة لدى المنظمة عن تصميم العبوات وموادها.', 'Ensure the team has access to the organization''s existing documentation on packaging design and materials.', false),
  (3084, 1, 'عقد جلسات عصف ذهني مع فريق المشروع لإظهار معرفتهم المجتمعة بالعبوات المستدامة.', 'Conduct brainstorming sessions with the project team to surface their combined knowledge about sustainable packaging.', false),
  (3084, 2, 'توظيف أعضاء فريق ذوي خبرة راسخة في المواد القابلة للتحلل الحيوي لتقليل الحاجة إلى البحث الخارجي.', 'Hire team members with established experience in biodegradable materials to reduce the need for external research.', false),
  (3084, 3, 'العمل مع أعضاء الفريق على توضيح أدوارهم وتحديد المواضع التي لا تغطي فيها معرفتهم الحالية متطلبات المشروع.', 'Work with team members to clarify their roles and identify where their current knowledge does not cover the project''s requirements.', true),
  (3085, 0, 'إرساء عملية مراجعة دورية للمخاطر بنقاط تصعيد محددة تستدعي تقييم المجلس عند الاقتراب من الحدود الفاصلة للمخاطر.', 'Establish a regular risk review process with defined escalation points that trigger board evaluation when risk thresholds are approached.', true),
  (3085, 1, 'الاحتفاظ بسجل مخاطر مفصل وتحديثه بعد كل حدث مخاطرة لتكون لدى المجلس معلومات حديثة متاحة عند الطلب.', 'Maintain a detailed risk register and update it after each risk event so the board has current information available on request.', false),
  (3085, 2, 'إعداد خطط طوارئ لكل فئة مخاطر محددة ليستطيع الفريق الاستجابة قبل تجاوز الحدود الفاصلة.', 'Develop contingency plans for each identified risk category so the team can respond before thresholds are exceeded.', false),
  (3085, 3, 'تخصيص احتياطيات موازنة في بداية كل مرحلة لتوفير هامش مالي واقٍ من المخاطر التي قد تؤثر في القرارات الاستثمارية.', 'Allocate budget reserves at the start of each phase to provide a financial buffer against risks that could affect investment decisions.', false),
  (3086, 0, 'مقابلة المحامين المتقاعدين لتوثيق خبرتهم وجعلهم يراجعون المسودات للتأكد من دقتها قبل رحيلهم.', 'Interview the retiring attorneys to document their expertise and have them review the drafts for accuracy before they leave.', false),
  (3086, 1, 'اقتران المحامين المتقاعدين بموظفين مبتدئين في برنامج إرشاد مهني رسمي لنقل المعرفة مباشرةً.', 'Pair the retiring attorneys with junior staff in a formal mentorship program to transfer knowledge directly.', true),
  (3086, 2, 'جمع ملفات قضايا المحامين وملاحظاتهم الشخصية ومراسلاتهم وتنظيمها في أرشيف مركزي.', 'Collect and organize the attorneys'' case files, personal notes, and correspondence into a centralized archive.', false),
  (3086, 3, 'توثيق الدروس المستفادة من الارتباطات الرئيسية للشركة وتحديث مستودعات المعلومات في المنظمة.', 'Document lessons learned from the firm''s key engagements and update the organization''s information repositories.', false),
  (3087, 0, 'العمل مع مدير الهندسة والراعي على إعادة تقييم الجدول الزمني بناءً على القدرة الواقعية للفريق.', 'Work with the engineering manager and sponsor to reassess the schedule based on the team''s realistic capacity.', true),
  (3087, 1, 'قبول القدرة المنخفضة للفريق وإسناد موارد ضمان جودة إضافية لالتقاط إشكالات الجودة قبل الإطلاق.', 'Accept the reduced team capacity and assign additional QA resources to catch quality issues before launch.', false),
  (3087, 2, 'إعادة المهندسَين إلى مشروع المنصة على أساس أنه جُدول قبل الجهد الأمني.', 'Restore the two engineers to the platform project on the grounds that it was scheduled before the security effort.', false),
  (3087, 3, 'الاستعاضة عن المهندسَين المعاد تكليفهما بمتعاقدين خارجيين قادرين على الحفاظ على الجدول الزمني الأصلي للتسليم.', 'Replace the reassigned engineers with external contractors who can maintain the original delivery timeline.', false),
  (3088, 0, 'السماح لكل فريق بتطوير نظام إدارة وثائق خاص به مصمم وفق مسار عمله.', 'Allow each team to develop their own document management system tailored to their workflow.', false),
  (3088, 1, 'إلزام كل عضو في الفريق بالاحتفاظ بنسخ شخصية من جميع الوثائق ذات الصلة والتنبيه على التحديثات لقائد فريقه.', 'Require each team member to maintain personal copies of all relevant documents and flag updates to their team lead.', false),
  (3088, 2, 'تكليف راعي المشروع بالإشراف على مستودع وثائق مشترك واعتماد جميع تغييرات الإصدارات.', 'Assign the project sponsor to oversee a shared document repository and approve all version changes.', false),
  (3088, 3, 'إرساء سجل موحّد للوثائق ونظام للتحكم في التغيير يصل إليهما الفريقان ويستخدمانهما، مع الإشراف عليهما.', 'Establish and oversee a single document registry and change control system that both teams access and use.', true),
  (3089, 0, 'توثيق الحالة بوصفها مخاطرة امتثال وتقييم الإجراء التصحيحي الذي قد يلزم.', 'Document the situation as a compliance risk and assess what corrective action may be needed.', true),
  (3089, 1, 'مواصلة العمل مع المورّد ما دامت لم تقع إشكالات أداء، وإثارة الشاغل في مراجعة المشروع المجدولة التالية.', 'Continue working with the vendor since no performance issues have occurred and raise the concern at the next scheduled project review.', false),
  (3089, 2, 'تقديم طلب تغيير للاستعاضة عن المورّد بآخر من قائمة المورّدين المعتمدين.', 'Submit a change request to replace the vendor with one from the approved vendor list.', false),
